/* 布置时保留小屋视口，并把右侧空间整理成紧凑的工作台。 */
.room-editing .shell-side {
  align-self: stretch;
  height: min(82vh, calc(min(54vh, 36vw) + 116px));
  min-height: min(var(--shell-stage-min, 400px), 82vh);
  overflow: hidden;
}
.room-editor {
  container: roomEditor / inline-size;
  height: 100%;
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
  color: var(--t-text);
  border-left: 1px solid var(--t-line);
}
.room-editor-header {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  min-height: 58px;
  padding: var(--sp-2) 0 var(--sp-3);
  border-bottom: 1px solid var(--t-line);
}
.room-editor-title { min-width: 0; }
.room-editor-title small {
  display: block;
  margin-bottom: 2px;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
}
.room-editor-header h1 {
  margin: 0;
  color: var(--t-text-strong);
  font-size: var(--fs-lead);
  line-height: 1.35;
}
.room-editor-actions {
  display: flex;
  flex: none;
  gap: var(--sp-2);
  margin-left: auto;
}
.room-editor-actions .button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-1);
  min-height: 38px;
  padding: var(--sp-1) var(--sp-3);
  border-radius: var(--r-sm, var(--r-xs));
  font-size: var(--fs-tiny);
  white-space: nowrap;
}
.room-editor-actions svg { width: 15px; height: 15px; }
.room-editor-actions .primary {
  background: var(--t-accent-solid);
  color: var(--t-on-solid, #fff);
  border-color: var(--t-accent-solid);
}
.room-editor-actions .primary:hover {
  background: var(--t-accent-solid-hover);
  border-color: var(--t-accent-solid-hover);
}
.room-editor-controls {
  display: flex;
  flex-direction: column;
  align-content: start;
  gap: 0;
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--sp-3) var(--sp-2) var(--sp-3) 0;
  scrollbar-gutter: stable;
}
.room-editor-history {
  display: flex;
  align-items: center;
  gap: var(--sp-1);
  min-height: 42px;
  padding: var(--sp-2) 0;
  border-bottom: 1px solid var(--t-line);
}
.room-editor-history .button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: var(--r-xs, var(--r-2xs));
}
.room-editor-history .button svg {
  width: 16px;
  height: 16px;
}
.room-editor-defaults { margin-left: auto; }
.room-editor-group {
  display: grid;
  gap: var(--sp-3);
  min-width: 0;
  padding: var(--sp-3) 0;
  border-bottom: 1px solid var(--t-line);
}
.room-editor-group-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2);
}
.room-editor-group-head h2 {
  min-width: 0;
  margin: 0;
  color: var(--t-text-strong);
  font-size: var(--fs-body);
  font-weight: 650;
}
.room-editor-group-head > span {
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  text-align: right;
}
.room-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--sp-2);
  min-width: 0;
}
.room-choice {
  display: grid;
  grid-template-columns: 25px minmax(0, 1fr);
  align-items: center;
  gap: var(--sp-2);
  min-width: 0;
  min-height: 58px;
  padding: var(--sp-2);
  border: 1px solid var(--t-line-firm);
  border-radius: var(--r-xs, var(--r-2xs));
  background: var(--t-surface);
  color: var(--t-text-soft);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color var(--dur-fast, .16s ease), background-color var(--dur-fast, .16s ease), box-shadow var(--dur-fast, .16s ease);
}
.room-choice:hover { border-color: var(--t-accent); background: var(--t-surface-soft); }
.room-choice.active,
.room-choice[aria-pressed="true"] {
  border-color: var(--t-accent);
  background: var(--t-accent-quiet);
  color: var(--t-accent-ink);
  box-shadow: inset 0 0 0 1px var(--t-accent);
}
.room-choice-swatch {
  width: 25px;
  height: 36px;
  border: 1px solid color-mix(in srgb, var(--t-text) 14%, transparent);
  border-radius: 2px;
  background: var(--room-swatch-default);
}
.room-choice-swatch[data-swatch="house-classic"] { background: var(--room-swatch-house-classic); }
.room-choice-swatch[data-swatch="house-washitsu"] { background: var(--room-swatch-house-washitsu); }
.room-choice-swatch[data-swatch="house-loft"] { background: var(--room-swatch-house-loft); }
.room-choice-swatch[data-swatch="house-french"] { background: var(--room-swatch-house-french); }
.room-choice-swatch[data-swatch="house-coastal"] { background: var(--room-swatch-house-coastal); }
.room-choice-swatch[data-swatch="house-cabin"] { background: var(--room-swatch-house-cabin); }
.room-choice-swatch[data-swatch="finish-oak"] { background: var(--finish-swatch-oak); }
.room-choice-swatch[data-swatch="finish-cream"] { background: var(--finish-swatch-cream); }
.room-choice-swatch[data-swatch="finish-ink"] { background: var(--finish-swatch-ink); }
.room-choice-swatch[data-swatch="finish-rattan"] { background: var(--finish-swatch-rattan); }
.room-choice-swatch[data-swatch="finish-walnut"] { background: var(--finish-swatch-walnut); }
.room-choice-swatch[data-swatch="finish-loft"] { background: var(--finish-swatch-loft); }
.room-choice-swatch[data-swatch="finish-blossom"] { background: var(--finish-swatch-blossom); }
.room-choice-swatch[data-swatch="finish-nordic"] { background: var(--finish-swatch-nordic); }
.room-choice-copy { display: grid; gap: 2px; min-width: 0; }
.room-choice-copy strong { color: var(--t-text-strong); font-size: var(--fs-tiny); font-weight: 650; line-height: 1.35; }
.room-choice-copy small { color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.35; overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.room-editor-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--sp-3) var(--sp-2);
  min-width: 0;
}
.room-editor-field {
  display: flex;
  flex-direction: column;
  gap: var(--sp-1);
  min-width: 0;
}
.room-editor-field[hidden] { display: none !important; }
.room-editor-field label,
.room-editor-field-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-2);
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  font-weight: 600;
}
.room-editor-field select,
.room-editor-field input {
  display: block;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  min-height: 40px;
  padding: var(--sp-2) var(--sp-2);
  border: 1px solid var(--t-line-firm);
  border-radius: var(--r-xs, var(--r-2xs));
  background: var(--t-surface-raised);
  color: var(--t-text);
  font: inherit;
  font-size: var(--fs-body);
  cursor: pointer;
  transition: border-color var(--dur-fast, .16s ease), background-color var(--dur-fast, .16s ease), box-shadow var(--dur-fast, .16s ease);
}
.room-editor-field select:hover,
.room-editor-field input:hover { border-color: var(--t-accent); }
.room-editor-field input { font-variant-numeric: tabular-nums; }
.room-editor-field small {
  min-height: 0;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.45;
  overflow-wrap: anywhere;
}
.room-editor-furniture-fields { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.room-editor-furniture-picker { grid-column: 1 / -1; }
.room-editor-note { min-height: 1.3em; color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.4; }
.room-editor-storage { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-2); color: var(--t-text-soft); font-size: var(--fs-tiny); }
.room-editor-store {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-1);
  flex: none;
  min-height: 38px;
  padding: var(--sp-2) var(--sp-3);
  border-color: var(--t-line-firm);
  border-radius: var(--r-xs, var(--r-2xs));
  background: var(--t-surface);
  color: var(--t-accent-ink);
  font-size: var(--fs-tiny);
}
.room-editor-store svg { width: 15px; height: 15px; }
.room-coordinate-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--sp-2);
  min-width: 0;
}
.room-coordinate-grid .room-editor-field { gap: var(--sp-1); }
.room-coordinate-grid .room-editor-field span { color: var(--t-text-soft); font-size: var(--fs-micro); font-weight: 600; }
.room-coordinate-grid input { min-height: 40px; padding-inline: var(--sp-2); }
.room-editor-placement {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: var(--sp-3);
}
.room-editor-position, .room-editor-rotation { min-width: 0; }
.room-editor-nudge {
  display: grid;
  grid-template-columns: repeat(3, 38px);
  grid-template-rows: repeat(3, 38px);
  gap: 3px;
  width: max-content;
  margin-top: var(--sp-2);
}
.room-editor-nudge > button,
.room-editor-nudge > span {
  display: grid;
  place-items: center;
  min-width: 0;
  padding: 0;
  border: 1px solid var(--t-line-firm);
  border-radius: var(--r-xs, var(--r-2xs));
  background: var(--t-surface-soft);
  color: var(--t-text-soft);
  transition: transform var(--dur-fast, .16s ease), background-color var(--dur-fast, .16s ease), border-color var(--dur-fast, .16s ease), color var(--dur-fast, .16s ease);
}
.room-editor-nudge > span {
  border-color: transparent;
  background: transparent;
  color: var(--t-text-faint);
}
.room-editor-nudge svg { width: 16px; height: 16px; }
.room-editor-nudge > [data-room-nudge="up"] { grid-column: 2; }
.room-editor-nudge > [data-room-nudge="left"] { grid-column: 1; grid-row: 2; }
.room-editor-nudge > span { grid-column: 2; grid-row: 2; }
.room-editor-nudge > [data-room-nudge="right"] { grid-column: 3; grid-row: 2; }
.room-editor-nudge > [data-room-nudge="down"] { grid-column: 2; grid-row: 3; }
.room-editor-nudge > button:hover {
  border-color: var(--t-accent);
  background: var(--t-accent-quiet);
  color: var(--t-accent-ink);
}
.room-editor-nudge > button:active { transform: scale(.94); }
.room-editor-rotation > div {
  display: flex;
  gap: var(--sp-1);
  margin: var(--sp-2) 0;
}
.room-editor-rotation .button {
  display: grid;
  place-items: center;
  width: 40px;
  min-height: 40px;
  padding: 0;
}
.room-editor-rotation svg { width: 15px; height: 15px; }
.room-editor-rotation output {
  display: block;
  min-height: 1.4em;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  font-variant-numeric: tabular-nums;
}
.room-editor-hint {
  display: flex;
  align-items: center;
  min-width: 0;
  min-height: 1.5em;
  margin: var(--sp-1) 0 0;
  padding: 0;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.room-editor-hint.is-blocked {
  padding: var(--sp-2) var(--sp-3);
  border-left: 3px solid var(--t-warn);
  border-radius: var(--r-xs, var(--r-2xs));
  background: var(--t-warn-quiet);
  color: #87521f;
}
.room-editor button:focus-visible,
.room-editor select:focus-visible,
.room-editor input:focus-visible {
  outline: 2px solid var(--t-accent);
  outline-offset: 2px;
}
.room-editor button:disabled {
  cursor: not-allowed;
  opacity: .48;
}
.large-text .room-editor :is(.room-editor-note, .room-editor-field small, .room-editor-hint, .room-choice-copy small) { font-size: var(--fs-tiny); }
@container roomEditor (max-width: 620px) {
  .room-choice { min-height: 54px; }
  .room-editor-placement { grid-template-columns: minmax(0, 1fr) auto; }
}
@container roomEditor (max-width: 360px) {
  .room-editor-fields { grid-template-columns: minmax(0, 1fr); }
  .room-editor-furniture-picker { grid-column: 1; }
  .room-editor-group-head { align-items: flex-start; }
  .room-editor-group-head > span { max-width: 52%; }
  .room-choice { grid-template-columns: 22px minmax(0, 1fr); gap: var(--sp-1); padding: var(--sp-1); }
  .room-choice-swatch { width: 22px; height: 32px; }
  .room-editor-storage { align-items: flex-start; }
  .room-editor-storage > span { max-width: 55%; }
}
@media (max-width: 1120px) {
  .room-editor { min-height: 360px; }
  .room-editor-controls { max-height: 65vh; }
}
@media (max-width: 760px) {
  .room-editing .shell-side { height: auto; min-height: 0; overflow: visible; }
  .room-editor { height: auto; min-height: 0; border-left: 0; border-top: 1px solid var(--t-line); }
  .room-editor-header { min-height: 54px; padding: var(--sp-3) 0; flex-wrap: wrap; }
  .room-editor-actions .button { min-height: 40px; }
  .room-editor-controls { max-height: none; overflow: visible; padding: var(--sp-3) 0 0; }
  .room-editor-field select, .room-editor-field input { min-height: 46px; }
  .room-editor-nudge { grid-template-columns: repeat(3, 42px); grid-template-rows: repeat(3, 42px); }
  .room-editor-rotation .button { width: 42px; min-height: 42px; }
  .room-editor-store { min-height: 44px; }
}
@media (prefers-reduced-motion: reduce) {
  .room-editor :is(button, select) { transition: none; }
}

