/* 面板内边距：19px 夹在 --sp-4(16) 与 --sp-5(22) 正中，取 22 是为与右侧
   var(--sp-5) 保持上下左右对称，取 16 会让面板显得上下扁。 */
.state-schedule,.state-conditions{padding:var(--sp-5);margin:var(--sp-4) 0}
.state-schedule header h3,.state-conditions h3{font-size:var(--fs-lead);margin:0 0 var(--sp-1);color:var(--t-accent-ink)}
.state-schedule header p{font-size:var(--fs-tiny);line-height:1.7;color:var(--t-accent-ink);margin:0}
.state-schedule dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-4) var(--sp-5);margin:var(--sp-4) 0 0}
.state-schedule dl>div{min-width:0}
.state-schedule dt{font-size:var(--fs-tiny);color:var(--t-accent-ink)}
.state-schedule dd{font-size:var(--fs-body);line-height:1.7;color:var(--t-accent-ink);margin:var(--sp-1) 0 0;overflow-wrap:anywhere}
.state-conditions ul{list-style:none;padding:0;margin:var(--sp-2) 0 0}
.state-conditions li{display:grid;grid-template-columns:minmax(90px,.3fr) minmax(0,1fr) auto;gap:var(--sp-3);align-items:start;padding:var(--sp-2) 0;border-top:1px solid var(--t-text-soft);font-size:var(--fs-body);line-height:1.7}
.state-conditions li strong{font-weight:500;color:var(--t-accent-ink)}.state-conditions li small{font-size:var(--fs-micro);color:var(--t-accent-ink)}
.state-presentation .state-presentation-settings{margin:var(--sp-4) 0}
.state-presentation .state-presentation-settings dt{color:var(--t-accent-ink)}
.state-presentation .state-presentation-note{font-size:var(--fs-tiny);color:var(--t-accent-ink)}
.state-presentation .state-receipts li{grid-template-columns:minmax(95px,.25fr) minmax(0,1fr);overflow-wrap:anywhere}
.state-presentation .state-receipt-detail{display:block;font-size:var(--fs-tiny);color:var(--t-accent-ink);margin-top:3px}
.state-receipt-reference{font-size:var(--fs-tiny);color:var(--t-accent-ink);margin-top:var(--sp-1)}
.state-receipt-reference summary{cursor:pointer;width:fit-content;min-height:28px;display:list-item;padding:3px 0}
.state-receipt-reference p{margin:3px 0;overflow-wrap:anywhere}
.state-boundary{font-size:var(--fs-tiny);line-height:1.8;color:var(--t-accent-ink);margin:var(--sp-3) 2px}
/* 空态留白比常规面板厚一档，25→--sp-5(22)，与右侧同档。 */
.state-empty{padding:var(--sp-5);font-size:var(--fs-body);line-height:1.9;color:var(--t-accent-ink)}
.state-empty h3{font-size:var(--fs-lead);color:var(--t-accent-ink);margin:0 0 var(--sp-2)}
#roleStateWorkspace :is(button,select,input,textarea,summary):focus-visible,#perceptionRoleWeatherWorkspace :is(button,select,input,textarea,summary):focus-visible{outline:3px solid var(--t-accent-ink);outline-offset:3px}
/* 同上：编辑面板与只读面板同款内边距，一并收进 --sp-5。 */
.state-edit-panel{padding:var(--sp-5);margin:var(--sp-4) 0;overflow-wrap:anywhere}
.state-edit-panel h3{font-size:var(--fs-lead);margin:0 0 var(--sp-1);color:var(--t-accent-ink)}
.state-edit-panel header p,.state-plan-heading p,.state-edit-help{font-size:var(--fs-body);line-height:1.8;color:var(--t-accent-ink);margin:var(--sp-1) 0 var(--sp-3)}
.state-edit-panel fieldset{border:0;padding:0;margin:0 0 var(--sp-2);min-width:0}
.state-edit-panel legend{font-size:var(--fs-body);font-weight:600;color:var(--t-accent-ink);margin:var(--sp-2) 0 var(--sp-3)}
.state-edit-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-4) var(--sp-5);align-items:center}
.state-edit-panel label{display:grid;gap:var(--sp-2);font-size:var(--fs-body);line-height:1.6;color:var(--t-accent-ink)}
.state-edit-panel .state-checkbox{display:flex;align-items:center;gap:var(--sp-2);min-height:44px}
.state-edit-panel input:not([type=checkbox]){width:100%;min-width:0;box-sizing:border-box;border:1px solid var(--t-accent-quiet);border-radius:var(--r-xs);padding:var(--sp-2) var(--sp-3);min-height:42px;font:inherit;background:var(--t-text-invert);color:var(--t-accent-ink)}
.state-edit-panel input[type=checkbox]{width:18px;height:18px;accent-color:var(--t-accent-ink)}
.state-edit-actions{display:flex;gap:var(--sp-2);flex-wrap:wrap;margin:var(--sp-3) 0}
.state-edit-panel button{min-height:40px;white-space:normal}
.state-edit-panel :disabled{opacity:.6;cursor:not-allowed}
.state-edit-title{font-size:var(--fs-lead);color:var(--t-accent-ink);font-weight:600;line-height:1.8}
.state-plan-heading{border-top:1px solid var(--t-text-soft);margin-top:var(--sp-5);padding-top:var(--sp-4)}
.state-plan-heading h4{font-size:var(--fs-lead);color:var(--t-accent-ink);margin:0 0 var(--sp-1)}
.state-plan-list{list-style:none;padding:0;margin:0}
.state-plan-list li{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);padding:var(--sp-3) 0;border-bottom:1px solid var(--t-text-soft)}
.state-plan-list li>div{min-width:0}.state-plan-list strong{font-size:var(--fs-body);font-weight:500;color:var(--t-accent-ink)}
.state-plan-list p,.state-pending p{font-size:var(--fs-body);color:var(--t-accent-ink);line-height:1.8;margin:var(--sp-1) 0}
.state-pending{border-left:3px solid var(--t-warn-ink);background:var(--t-text-invert);padding:var(--sp-3) var(--sp-4);margin:var(--sp-3) 0;font-size:var(--fs-body);color:var(--t-warn-ink)}
.state-calendar-section{border-top:1px solid var(--t-surface-soft);margin-top:var(--sp-5);padding-top:var(--sp-4)}
.state-calendar-section .state-plan-heading{border-top:0;margin-top:0;padding-top:0}
.state-calendar-actions{display:flex;justify-content:flex-end;gap:var(--sp-2);flex-wrap:wrap;margin-top:var(--sp-2)}
.state-calendar-meta{display:block;font-size:var(--fs-tiny);line-height:1.7;color:var(--t-accent-ink);margin-top:var(--sp-1)}
/* 日历字段两列：列间距 19px 与相邻 .state-edit-fields 的 20px 同属一档，
   吸附到 --sp-4(16) 会让两张相邻表单的列宽对不齐，故取 --sp-5。 */
.state-calendar-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-3) var(--sp-5);margin:var(--sp-3) 0}
.state-calendar-fields label{display:grid;align-content:start;gap:var(--sp-2);font-size:var(--fs-body);line-height:1.6;color:var(--t-accent-ink)}
.state-calendar-fields input,.state-calendar-fields textarea,.state-calendar-fields select{width:100%;min-width:0;box-sizing:border-box;border:1px solid var(--t-accent-quiet);border-radius:var(--r-xs);padding:var(--sp-2) var(--sp-3);min-height:42px;font:inherit;line-height:1.7;color:var(--t-accent-ink);background:var(--t-text-invert)}
.state-calendar-fields textarea{resize:vertical;min-height:94px}
.state-edit-panel :is(select,textarea){width:100%;min-width:0;box-sizing:border-box;border:1px solid var(--t-accent-quiet);border-radius:var(--r-xs);padding:var(--sp-2) var(--sp-3);min-height:42px;font:inherit;line-height:1.7;color:var(--t-accent-ink);background:var(--t-text-invert)}
.state-edit-panel textarea{resize:vertical;min-height:100px}
.state-form-section{font-size:var(--fs-body);font-weight:600;color:var(--t-accent-ink);margin:var(--sp-4) 0 var(--sp-3)}
.state-contact-purposes{display:grid;gap:var(--sp-3)}.state-contact-purpose{border-top:1px solid var(--t-text-soft);padding:var(--sp-3) 0 var(--sp-1);min-width:0}
.state-contact-purpose h5{font-size:var(--fs-body);color:var(--t-accent-ink);margin:0 0 var(--sp-3)}.state-contact-status{list-style:none;padding:0;margin:var(--sp-2) 0}
.state-contact-status li{display:flex;gap:var(--sp-3);justify-content:space-between;flex-wrap:wrap;padding:var(--sp-2) 0;border-top:1px solid var(--t-text-soft);font-size:var(--fs-body);line-height:1.7}
.state-contact-diagnostic{margin-top:var(--sp-4);padding-top:var(--sp-3);border-top:1px solid var(--t-line)}
.state-contact-diagnostic h4{margin:0 0 var(--sp-2);font-size:var(--fs-body);color:var(--t-text)}
.state-contact-diagnostic dl{display:grid;gap:var(--sp-1);margin:0}
.state-contact-diagnostic dl>div{display:grid;grid-template-columns:minmax(6rem,auto) minmax(0,1fr);gap:var(--sp-2);line-height:1.6}
.state-contact-diagnostic dt{color:var(--t-text-soft)}
.state-contact-diagnostic dd{margin:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.state-contact-diagnostic p{margin:var(--sp-2) 0 0;line-height:1.6}
.state-contact-diagnostic-next{color:var(--t-text-soft)}
@media(max-width:560px){.state-contact-diagnostic dl>div{grid-template-columns:minmax(0,1fr);gap:0}}
.state-phase-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--sp-3) var(--sp-4)}
.state-phase-block{border:1px solid var(--t-surface-soft);border-radius:var(--r-sm);padding:var(--sp-3) var(--sp-4);margin:var(--sp-3) 0;background:var(--t-text-invert)}.state-phase-block legend{padding:0 var(--sp-2);font-size:var(--fs-body);font-weight:600;color:var(--t-accent-ink)}.state-phase-block .state-phase-fields{grid-template-columns:repeat(2,minmax(0,1fr));margin-bottom:var(--sp-2)}.state-phase-block>label{margin-top:var(--sp-2)}.state-phase-help{margin:0 0 var(--sp-2);font-size:var(--fs-tiny);line-height:1.6;color:var(--t-accent-ink)}
.state-maintenance-summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-4) var(--sp-5);margin:var(--sp-4) 0}
.state-maintenance-summary>div{min-width:0}.state-maintenance-summary dt{font-size:var(--fs-tiny);color:var(--t-accent-ink)}
.state-maintenance-summary dd{font-size:var(--fs-body);line-height:1.8;color:var(--t-accent-ink);margin:var(--sp-1) 0 0}
.state-maintenance-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--sp-4);padding-bottom:var(--sp-2)}
.state-maintenance-heading h3{margin:0;color:var(--t-ok-ink);font-size:var(--fs-lead);line-height:1.4}
.state-maintenance-heading p{margin:var(--sp-1) 0 0;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.6}
.state-scope-legend{display:flex;flex-wrap:wrap;gap:var(--sp-1);justify-content:flex-end}
.state-scope-legend span{display:inline-flex;align-items:center;min-height:25px;padding:3px var(--sp-2);border:1px solid var(--t-surface-soft);border-radius:var(--r-xs);color:var(--t-text-soft);background:var(--t-text-invert);font-size:var(--fs-micro);white-space:nowrap}
.state-setting-list{display:grid;min-width:0;margin:var(--sp-2) 0 0}
.state-setting-row{display:grid;grid-template-columns:36px minmax(0,1fr) auto;align-items:center;gap:var(--sp-3);min-width:0;padding:var(--sp-3) var(--sp-1);border-top:1px solid var(--t-surface-soft);transition:background .18s ease,transform .18s ease}
.state-setting-row:hover{background:var(--t-surface-raised);transform:translateX(2px)}
.state-setting-index{display:grid;place-items:center;width:30px;height:30px;border:1px solid var(--t-surface-soft);border-radius:var(--r-xs);background:var(--t-text-invert);color:var(--t-ok-ink);font-size:var(--fs-micro);font-variant-numeric:tabular-nums}
.state-setting-copy{min-width:0}
.state-setting-meta{display:flex;align-items:center;flex-wrap:wrap;gap:var(--sp-1) var(--sp-2);color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.4}
.state-setting-meta>span+span{padding-left:var(--sp-2);border-left:1px solid var(--t-text-soft);color:var(--t-ok-ink)}
.state-setting-copy h4{margin:3px 0;color:var(--t-ok-ink);font-size:var(--fs-body);line-height:1.45}
.state-setting-copy p{margin:0;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.65;overflow-wrap:anywhere}
.state-setting-action{display:inline-flex;align-items:center;justify-content:center;gap:var(--sp-2);min-width:110px;min-height:38px;padding:var(--sp-1) var(--sp-3);border:1px solid var(--t-surface-soft);border-radius:var(--r-xs);background:var(--t-text-invert);color:var(--t-ok-ink);font:inherit;font-size:var(--fs-tiny);font-weight:600;cursor:pointer;transition:background .18s ease,border-color .18s ease,color .18s ease,transform .18s ease}
.state-setting-action:hover:not(:disabled){transform:translateY(-1px);border-color:var(--t-ok-ink);background:var(--t-text-invert);color:var(--t-ok-ink)}
.state-setting-action:disabled{cursor:not-allowed;opacity:.55}
.state-cycle-setup{display:grid;gap:var(--sp-4)}
.state-cycle-general,.state-cycle-duration,.state-cycle-preference,.state-phase-editor-shell{min-width:0;padding-top:var(--sp-4);border-top:1px solid var(--t-text-soft)}
.state-cycle-general{padding-top:0;border-top:0}
.state-cycle-discomfort{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--sp-2);margin:var(--sp-3) 0 0;padding:var(--sp-2) 0 0;border:0;border-top:1px solid var(--t-text-soft)}
.state-cycle-discomfort>legend{margin:0 0 2px;color:var(--t-accent-ink);font-size:var(--fs-tiny);font-weight:600}
.state-cycle-discomfort .state-edit-fields{grid-template-columns:minmax(0,1fr)}
.state-cycle-discomfort .state-edit-help{margin:0;font-size:var(--fs-micro);line-height:1.5}
.state-range-field{gap:var(--sp-1)!important;min-width:0}
.state-range-control{display:grid;grid-template-columns:minmax(0,1fr) 48px;align-items:center;gap:var(--sp-3);min-width:0}
.state-range-control input[type=range]{min-height:20px!important;padding:0!important;border:0!important;accent-color:var(--t-ok-ink);cursor:pointer}
.state-range-control output{color:var(--t-ok-ink);font-size:var(--fs-tiny);font-variant-numeric:tabular-nums;text-align:right}
.state-checklist-field{display:grid;gap:var(--sp-1);min-width:0;margin:0!important;padding:0!important;border:0!important}
.state-checklist-field>legend{margin:0!important;color:var(--t-accent-ink);font-size:var(--fs-tiny);font-weight:600}
.state-checklist{display:flex;flex-wrap:wrap;gap:var(--sp-1)}
.state-checklist label{display:flex!important;align-items:center;gap:var(--sp-1)!important;min-height:32px;padding:var(--sp-1) var(--sp-2);border:1px solid var(--t-surface-soft);border-radius:var(--r-2xs);background:var(--t-text-invert);color:var(--t-text-soft)!important;font-size:var(--fs-micro)!important;line-height:1.3!important;cursor:pointer}
.state-checklist label:has(input:checked){border-color:var(--t-ok-ink);background:var(--t-text-invert);color:var(--t-ok-ink)!important}
.state-checklist input[type=checkbox]{width:14px;height:14px}
.state-cycle-discomfort:disabled{opacity:.58}
.state-form-section-row{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--sp-3);margin-bottom:var(--sp-2)}
.state-form-section-row>div{min-width:0}
.state-form-section{margin:0 0 var(--sp-1);color:var(--t-ok-ink);font-size:var(--fs-body);line-height:1.45}
.state-form-section-row .state-edit-help{margin:0;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.6}
.state-section-mark{color:var(--t-text-faint);font-size:var(--fs-micro);font-variant-numeric:tabular-nums}
.state-cycle-duration-overview{display:grid;grid-template-columns:auto minmax(100px,1fr);align-items:center;gap:var(--sp-3);margin:var(--sp-3) 0 var(--sp-4);color:var(--t-text-soft);font-size:var(--fs-micro)}
.state-cycle-meter{display:flex;gap:0;min-width:0;height:9px;overflow:hidden;border-radius:var(--r-xs);background:var(--t-surface-soft)}
.state-cycle-meter span{display:block;box-sizing:border-box;flex:0 0 var(--phase-share);min-width:2px;height:100%;border-right:2px solid var(--t-surface-raised);background:var(--t-ok);transition:flex-basis .22s ease}
.state-cycle-meter span:nth-child(2){background:var(--t-ok)}.state-cycle-meter span:nth-child(3){background:var(--t-warn)}.state-cycle-meter span:nth-child(4){background:var(--t-risk)}.state-cycle-meter span:nth-child(5){background:var(--t-accent)}.state-cycle-meter span:nth-child(6){background:var(--t-risk)}
.state-cycle-view-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-2);margin:0 0 var(--sp-3)}
.state-cycle-view-tab{display:grid;gap:3px;min-width:0;min-height:60px;padding:var(--sp-2) var(--sp-3);border:1px solid var(--t-surface-soft);border-radius:var(--r-xs);background:var(--t-text-invert);color:var(--t-text-soft);text-align:left;cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease}
.state-cycle-view-tab>span{font-size:var(--fs-tiny);font-weight:600;line-height:1.4}
.state-cycle-view-tab small{color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.4}
.state-cycle-view-tab:hover{transform:translateY(-1px);border-color:var(--t-ok-quiet)}
.state-cycle-view-tab.is-active{border-color:var(--t-ok-ink);background:var(--t-text-invert);color:var(--t-ok-ink);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--t-ok-ink) 14%,transparent)}
.state-cycle-view-panel{min-width:0;animation:state-cycle-view-enter .2s ease-out both}
@keyframes state-cycle-view-enter{from{opacity:.4;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
.state-phase-tabs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:var(--sp-1);margin:var(--sp-2) 0 var(--sp-3)}
.state-phase-tab{display:grid;align-content:center;gap:3px;min-width:0;min-height:55px;padding:var(--sp-2) var(--sp-2);border:1px solid var(--t-surface-soft);border-radius:var(--r-xs);background:var(--t-text-invert);color:var(--t-text-soft);text-align:left;cursor:pointer;transition:background .18s ease,border-color .18s ease,transform .18s ease,box-shadow .18s ease}
.state-phase-tab>span{font-size:var(--fs-tiny);font-weight:600;line-height:1.35;overflow-wrap:anywhere}
.state-phase-tab small{color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.3}
.state-phase-tab:hover{transform:translateY(-1px);border-color:var(--t-surface-soft)}
.state-phase-tab.is-active{border-color:var(--t-ok-ink);background:var(--t-text-invert);color:var(--t-ok-ink);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--t-ok-ink) 14%,transparent)}
.state-phase-editor{min-width:0;margin:0!important;padding:var(--sp-3) 0 0!important;border:0!important;border-top:1px solid var(--t-text-soft)!important}
.state-phase-editor legend{display:flex;align-items:baseline;justify-content:space-between;gap:var(--sp-2);width:100%;margin:0 0 var(--sp-2)!important;padding:0!important;color:var(--t-ok-ink)!important;font-size:var(--fs-body)!important}
.state-phase-editor legend small{color:var(--t-text-faint);font-size:var(--fs-micro);font-weight:400}
.state-phase-editor .state-phase-help{margin:0 0 var(--sp-3);color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.65}
.state-phase-editor .state-phase-fields{grid-template-columns:repeat(2,minmax(0,1fr));margin:0 0 var(--sp-3)}
.state-phase-editor>label{margin-top:var(--sp-2)}
@media(max-width:650px){.state-maintenance-summary{grid-template-columns:minmax(0,1fr)}.state-phase-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:650px){.state-maintenance-heading{align-items:flex-start;flex-direction:column;gap:var(--sp-2)}.state-scope-legend{justify-content:flex-start}.state-setting-row{grid-template-columns:30px minmax(0,1fr);gap:var(--sp-2);padding:var(--sp-3) 2px}.state-setting-index{width:27px;height:27px}.state-setting-action{grid-column:2;justify-self:start;min-height:36px}.state-cycle-view-tabs{gap:var(--sp-1)}.state-cycle-view-tab{min-height:46px;padding:var(--sp-2)}.state-cycle-view-tab small{display:none}.state-phase-tabs{grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--sp-1)}.state-phase-tab{min-height:51px;padding:var(--sp-1)}.state-cycle-duration-overview{grid-template-columns:1fr;gap:var(--sp-1)}}
@media(prefers-reduced-motion:reduce){.state-setting-row,.state-setting-action,.state-phase-tab,.state-cycle-view-tab,.state-cycle-meter span{transition:none}.state-cycle-view-panel{animation:none}}
