/* weather-source.css */
.weather-source-settings { padding-block: calc(var(--sp-1) * 1.5) calc(var(--sp-3) * 1.5); border-bottom: 1px solid var(--t-line); }
.weather-source-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--sp-3); margin-bottom: var(--sp-4); }
.weather-source-heading h4 { margin: 0 0 calc(var(--sp-1) * 1.5); font-size: var(--fs-lead); }
.weather-source-heading p, .weather-source-footer p { margin: 0; color: var(--t-text-soft); font-size: var(--fs-micro); line-height: 1.6; }
.weather-source-intro { max-width: 640px; }
.weather-source-state { flex-shrink: 0; color: var(--t-ok-ink); font-size: var(--fs-micro); line-height: 1.6; }
.weather-source-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: calc(var(--sp-2) * 1.75) calc(var(--sp-4) * 1.25); margin: 0; padding: 0; border: 0; }
.weather-source-grid .perception-setting { min-width: 0; }
.weather-source-grid input, .weather-source-grid select, .weather-source-grid textarea { box-sizing: border-box; width: 100%; min-width: 0; }
.weather-source-grid textarea { min-height: calc(var(--sp-5) * 4); resize: vertical; font-family: var(--font-mono, ui-monospace, monospace); }
.weather-source-wide, .weather-source-private-key { grid-column: 1 / -1; }
.weather-source-grid small { overflow-wrap: anywhere; }
.weather-source-auth-card { grid-column: 1 / -1; padding: var(--sp-4); border: 1px solid var(--t-line); border-radius: var(--r-md); background: var(--t-surface-soft); }
.weather-source-auth-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--sp-3); }
.weather-source-auth-heading h5 { margin: 0 0 var(--sp-1); font-size: var(--fs-body); }
.weather-source-auth-heading p, .weather-source-auth-summary, .weather-source-panel-note, .weather-source-inline-note { margin: 0; color: var(--t-text-soft); font-size: var(--fs-micro); line-height: 1.6; }
.weather-source-badge { flex-shrink: 0; padding: calc(var(--sp-1) * .5) calc(var(--sp-2) * 2.25); border: 1px solid var(--t-line); border-radius: var(--r-pill); color: var(--t-text-soft); background: var(--t-surface); font-size: var(--fs-micro); line-height: 1.6; white-space: nowrap; }
.weather-source-badge.is-configured { border-color: transparent; color: var(--t-ok-ink); background: var(--t-ok-quiet); }
.weather-source-auth-summary { margin-top: var(--sp-2); }
.weather-source-auth-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--sp-2); margin-top: var(--sp-3); }
.weather-source-auth-option { display: flex; gap: var(--sp-2); padding: var(--sp-3); border: 1px solid var(--t-line-firm); border-radius: var(--r-sm); background: var(--t-surface); cursor: pointer; transition: border-color .15s ease, background .15s ease; }
.weather-source-auth-option:hover { border-color: var(--t-ok); }
.weather-source-auth-option.is-selected { border-color: var(--t-ok); background: var(--t-ok-quiet); }
.weather-source-auth-option input { flex: 0 0 auto; width: auto; margin: calc(var(--sp-1) * .75) 0 0; accent-color: var(--t-ok); }
.weather-source-auth-option span { display: grid; gap: calc(var(--sp-1) * .5); min-width: 0; }
.weather-source-auth-option strong { font-size: var(--fs-body); font-weight: 600; }
.weather-source-auth-option small { color: var(--t-text-soft); font-size: var(--fs-micro); line-height: 1.5; overflow-wrap: anywhere; }
.weather-source-auth-panel { margin-top: var(--sp-3); }
.weather-source-auth-panel[hidden] { display: none; }
.weather-source-signed-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: calc(var(--sp-2) * 1.75) calc(var(--sp-4) * 1.25); margin-top: var(--sp-3); }
