.output-album-summary{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-2);margin-bottom:var(--sp-2);color:var(--t-text-faint);font-size:var(--fs-micro)}
.output-album-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:var(--sp-2)}
.output-album-card{position:relative;display:block;overflow:hidden;min-width:0;aspect-ratio:1;padding:0;border:1px solid var(--t-line);border-radius:var(--r-md);background:var(--t-surface-soft);cursor:pointer;text-align:left}
.output-album-card img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .18s ease}
.output-album-card:hover img{transform:scale(1.035)}
.output-album-card-meta{position:absolute;inset:auto 0 0;display:grid;gap:2px;padding:var(--sp-2);background:linear-gradient(transparent,rgba(20,26,22,.78));color:#fff;opacity:0;transform:translateY(4px);transition:opacity .18s ease,transform .18s ease}
.output-album-card:hover .output-album-card-meta,.output-album-card:focus-visible .output-album-card-meta{opacity:1;transform:translateY(0)}
.output-album-card-meta strong{font-size:var(--fs-micro);font-weight:600}
.output-album-card-meta small{font-size:var(--fs-micro);opacity:.82}
.output-album-state{display:grid;justify-items:start;gap:var(--sp-2);padding:var(--sp-4);border:1px dashed var(--t-line);border-radius:var(--r-md);background:var(--t-surface-soft)}
.output-album-state strong{color:var(--t-text-strong);font-size:var(--fs-body)}
.output-album-state span{color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.6}
.output-album-state.is-error{border-color:color-mix(in srgb,var(--t-danger) 35%,var(--t-line))}
.output-album-more{display:flex;justify-content:center;padding-top:var(--sp-3)}
.output-album-lightbox{position:fixed;inset:0;z-index:80;display:grid;place-items:center;padding:var(--sp-4)}
.output-album-lightbox[hidden]{display:none}
.output-album-lightbox-mask{position:absolute;inset:0;border:0;background:rgba(12,16,14,.72);cursor:zoom-out}
.output-album-lightbox-card{position:relative;z-index:1;display:grid;gap:0;width:min(92vw,920px);max-height:90vh;overflow:hidden;border:1px solid var(--t-line-firm);border-radius:var(--r-lg);background:var(--t-surface-raised);box-shadow:0 24px 70px rgba(0,0,0,.32)}
.output-album-lightbox-card>header{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);padding:var(--sp-3);border-bottom:1px solid var(--t-line)}
.output-album-lightbox-card>header>div{display:grid;gap:2px;min-width:0}
.output-album-lightbox-card>header strong{color:var(--t-text-strong);font-size:var(--fs-body)}
.output-album-lightbox-card>header small{color:var(--t-text-faint);font-size:var(--fs-micro)}
.output-album-lightbox-stage{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:var(--sp-2);padding:var(--sp-3);min-height:0}
.output-album-lightbox-stage img{display:block;width:100%;max-height:66vh;object-fit:contain;border-radius:var(--r-sm);background:var(--t-surface-soft)}
.output-album-nav{display:grid;place-items:center;width:36px;height:36px;padding:0;border:1px solid var(--t-line);border-radius:50%;background:var(--t-surface);color:var(--t-text);cursor:pointer}
.output-album-nav:disabled{opacity:.3;cursor:default}
.output-album-lightbox-card>footer{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-2);padding:0 var(--sp-3) var(--sp-3);color:var(--t-text-faint);font-size:var(--fs-micro)}
@media(max-width:760px){.output-album-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.output-album-lightbox-stage{grid-template-columns:minmax(0,1fr)}.output-album-nav{display:none}}

.output-album-toolbar{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap;margin-bottom:var(--sp-2);padding:var(--sp-2);border:1px solid var(--t-line);border-radius:var(--r-md);background:var(--t-surface-soft)}
.output-album-check{display:inline-flex;align-items:center;gap:var(--sp-1);color:var(--t-text-soft);font-size:var(--fs-micro);cursor:pointer}
.output-album-check input,.output-album-select input{accent-color:var(--t-accent);cursor:pointer}
.output-album-selected{color:var(--t-text-faint);font-size:var(--fs-micro)}
.output-album-selected b{color:var(--t-text-strong);font-variant-numeric:tabular-nums}
.output-album-actions{display:flex;align-items:center;gap:var(--sp-1);flex-wrap:wrap;margin-left:auto}
.output-album-notice{margin:0 0 var(--sp-2);padding:var(--sp-2);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface-soft);color:var(--t-text-soft);font-size:var(--fs-micro);line-height:1.55;overflow-wrap:anywhere}
.output-album-notice.is-error{border-color:color-mix(in srgb,var(--t-danger) 35%,var(--t-line));color:var(--t-danger)}
.output-album-card{position:relative;display:block;overflow:hidden;min-width:0;aspect-ratio:1;border:1px solid var(--t-line);border-radius:var(--r-md);background:var(--t-surface-soft)}
.output-album-card.is-selected{border-color:var(--t-accent);box-shadow:0 0 0 2px color-mix(in srgb,var(--t-accent) 18%,transparent)}
.output-album-open{display:block;width:100%;height:100%;padding:0;border:0;background:transparent;color:inherit;cursor:pointer;text-align:left}
.output-album-select{position:absolute;top:var(--sp-1);left:var(--sp-1);z-index:2;display:grid;place-items:center;width:26px;height:26px;border:1px solid rgba(255,255,255,.7);border-radius:8px;background:rgba(20,26,22,.5);backdrop-filter:blur(4px)}
.output-album-select input{width:15px;height:15px;margin:0}
.output-album-open img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .18s ease}
.output-album-card:hover .output-album-open img{transform:scale(1.035)}

/* decision-page.css */
.decision-page{display:grid;gap:var(--sp-4);min-width:0;color:var(--t-text)}
.decision-workspace{min-width:0}
.decision-page [hidden],
.decision-panel[hidden],
.decision-editors [hidden]{display:none!important}
.decision-tabs{display:flex;align-items:center;gap:var(--sp-1);min-width:0;padding:calc(var(--sp-1) * 1.25);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface)}
.decision-tab-list{display:flex;align-items:center;gap:var(--sp-1);min-width:0}
.decision-tab{display:inline-flex;align-items:center;justify-content:center;gap:var(--sp-2);min-width:0;min-height:38px;padding:var(--sp-2) var(--sp-3);border:1px solid transparent;border-radius:calc(var(--r-xs) * 1.2);background:transparent;color:var(--t-text-soft);font:inherit;white-space:nowrap;cursor:pointer;transition:background var(--dur-fast) ease,border-color var(--dur-fast) ease,color var(--dur-fast) ease}
.decision-tab:hover{background:var(--t-surface-soft);color:var(--t-text-strong)}
.decision-tab.is-active{border-color:var(--t-accent-solid);background:var(--t-accent-solid);color:var(--t-on-solid)}
.decision-tab:focus-visible,.decision-chain-step:focus-visible,.decision-shortcuts button:focus-visible,.decision-domain-link:focus-visible{outline:2px solid var(--t-focus);outline-offset:2px}
.decision-tab svg{width:16px;height:16px;flex:none}
.decision-current{margin-inline-start:auto;padding:var(--sp-1) var(--sp-2);border-radius:var(--r-pill);background:var(--t-ok-quiet);color:var(--t-ok-ink);font-size:var(--fs-micro);white-space:nowrap}
.decision-panels,.decision-panel,.decision-editors{display:grid;gap:var(--sp-4);min-width:0}
.decision-panel{align-content:start}
.decision-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:var(--sp-3);min-width:0}
.decision-stats-four{grid-template-columns:repeat(4,minmax(0,1fr))}
.decision-stats-three{grid-template-columns:repeat(3,minmax(0,1fr))}
.decision-stat{display:grid;align-content:start;gap:var(--sp-1);min-width:0;min-height:98px;padding:var(--sp-4);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface)}
.decision-stat>span{overflow-wrap:anywhere;color:var(--t-text-faint);font-size:var(--fs-tiny)}
.decision-stat strong{overflow-wrap:anywhere;color:var(--t-text-strong);font-size:var(--fs-head);font-weight:650;line-height:1.25}
.decision-stat small{overflow-wrap:anywhere;color:var(--t-text-soft);font-size:var(--fs-tiny);line-height:1.55}
.decision-stat.is-ok strong{color:var(--t-ok-ink)}
.decision-chain,.decision-overview-section{min-width:0;padding:var(--sp-4);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface)}
.decision-block-heading{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);margin-bottom:var(--sp-3)}
.decision-block-heading h2{margin:0;color:var(--t-text-strong);font-size:var(--fs-title);font-weight:650}
.decision-block-heading p{margin:var(--sp-1) 0 0;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.55}
.decision-chain-rule,.decision-state{flex:none;padding:var(--sp-1) var(--sp-2);border-radius:var(--r-pill);background:var(--t-ok-quiet);color:var(--t-ok-ink);font-size:var(--fs-micro)}
.decision-chain-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--sp-3)}
.decision-chain-step{display:grid;grid-template-columns:26px minmax(0,1fr) 14px;align-items:start;gap:var(--sp-2);min-width:0;min-height:116px;padding:var(--sp-3);border:0;border-radius:var(--r-sm);background:var(--t-surface-soft);color:var(--t-text);text-align:left;font:inherit;cursor:pointer}
.decision-chain-step:last-child{grid-template-columns:26px minmax(0,1fr)}
.decision-step-number{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--t-accent-quiet);color:var(--t-accent-ink);font-size:var(--fs-tiny);font-weight:700}
.decision-step-copy{display:grid;gap:var(--sp-1);min-width:0}
.decision-step-copy b{color:var(--t-text-strong);font-size:var(--fs-body)}
.decision-step-copy small,.decision-step-copy em{overflow-wrap:anywhere;color:var(--t-text-soft);font-size:var(--fs-tiny);font-style:normal;line-height:1.55}
.decision-step-copy em{color:var(--t-accent-ink)}
.decision-chain-step>svg{width:14px;height:14px;margin-top:calc(var(--sp-1) * 1.5);color:var(--t-accent)}
.decision-overview-columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--sp-4);min-width:0}
.decision-signal-groups{display:grid;gap:var(--sp-3)}
.decision-signal-groups>div{display:grid;gap:var(--sp-2);min-width:0}
.decision-signal-groups>div>strong{color:var(--t-text-strong);font-size:var(--fs-tiny);font-weight:650}
.decision-signals{display:flex;flex-wrap:wrap;gap:var(--sp-2);min-width:0}
.decision-signal{display:inline-flex;align-items:center;gap:var(--sp-2);max-width:100%;padding:var(--sp-1) var(--sp-2);border-radius:var(--r-xs);background:var(--t-accent-quiet);color:var(--t-accent-ink);font-size:var(--fs-micro)}
.decision-signal b{font-weight:650}
.decision-signal span{color:var(--t-text-soft);overflow-wrap:anywhere}
.decision-reference-list{display:grid;gap:var(--sp-2)}
.decision-reference-list>div{display:flex;justify-content:space-between;align-items:center;gap:var(--sp-3);min-width:0;padding:var(--sp-3);border-radius:calc(var(--r-xs) * 1.2);background:var(--t-surface-soft)}
.decision-reference-list b{color:var(--t-text-strong);font-size:var(--fs-tiny)}
.decision-reference-list span{overflow-wrap:anywhere;color:var(--t-text-soft);font-size:var(--fs-tiny);text-align:right}
.decision-shortcuts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--sp-3);min-width:0}
.decision-shortcuts button,.decision-domain-link{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);min-width:0;min-height:62px;padding:var(--sp-3);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface);color:var(--t-text);text-align:left;font:inherit;cursor:pointer}
.decision-shortcuts button:hover,.decision-domain-link:hover{border-color:var(--t-line-firm);background:var(--t-surface-soft)}
.decision-shortcuts button>span,.decision-domain-link>span{display:grid;gap:var(--sp-1);min-width:0}
.decision-shortcuts b,.decision-domain-link b{color:var(--t-text-strong);font-size:var(--fs-body)}
.decision-shortcuts small,.decision-domain-link small{color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.45}
.decision-shortcuts svg,.decision-domain-link svg{width:16px;height:16px;flex:none;color:var(--t-accent)}
.decision-editors{gap:var(--sp-4)}
.decision-editors .wb{gap:var(--sp-3)}
.decision-editors .wb-card-head{display:none}
.decision-editors .wb-rail-legend{display:none}
.decision-editors .wb-card-body{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:stretch;gap:var(--sp-3);min-width:0}
.decision-editors .wb-group{min-width:0;height:100%;margin:0;padding:var(--sp-4);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface)}
.decision-editors .wb-group+.wb-group{margin:0;padding:var(--sp-4);border:1px solid var(--t-line)}
.decision-editors .wb-group-head{margin:0 0 var(--sp-3);padding-bottom:var(--sp-3);border-bottom:1px solid var(--t-line);font-size:var(--fs-lead)}
.decision-editors .wb-fields{grid-template-columns:minmax(0,1fr);gap:0}
.decision-editors .wb-field{grid-template-columns:10px minmax(0,1fr);gap:var(--sp-2);padding:var(--sp-2) 0}
.decision-editors .wb-field-main{min-width:0}
.decision-editors .wb-field-side{grid-column:2;justify-content:flex-start}
.decision-editors .wb-control input[type=number],.decision-editors .wb-control input[type=text],.decision-editors .wb-control select,.decision-editors .wb-control textarea{max-width:100%;background:var(--t-surface-soft);border-color:var(--t-line-firm)}
.decision-editors .wb-actions{grid-column:1/-1;flex-wrap:wrap;margin-top:0;padding-top:var(--sp-3);border-top:1px solid var(--t-line)}
.decision-joke-heading{display:flex;align-items:baseline;gap:var(--sp-2);margin-bottom:calc(var(--sp-2) * -1)}
.decision-joke-heading>span{color:var(--t-accent-ink);font-size:var(--fs-micro);font-weight:700}
.decision-joke-heading h3{margin:0;color:var(--t-text-strong);font-size:var(--fs-lead)}
.decision-domain-link{width:100%}

@media(max-width:1180px){
  .decision-stats{grid-template-columns:repeat(3,minmax(0,1fr))}
  .decision-chain-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .decision-shortcuts{grid-template-columns:repeat(2,minmax(0,1fr))}
  .decision-editors .wb-card-body{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:760px){
  .decision-tabs{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--sp-1);overflow:visible}
  .decision-tab-list{min-width:0;overflow-x:auto;overflow-y:hidden;padding:var(--sp-1) 1px;scrollbar-width:thin}
  .decision-tab{flex:none;padding-inline:var(--sp-2)}
  .decision-current{position:static;justify-self:end;max-width:100%;margin:0;white-space:normal;text-align:right}
  .decision-stats,.decision-stats-four,.decision-stats-three{grid-template-columns:repeat(2,minmax(0,1fr))}
  .decision-stat{min-height:88px;padding:var(--sp-3)}
  .decision-overview-columns{grid-template-columns:minmax(0,1fr)}
  .decision-chain-grid{grid-template-columns:minmax(0,1fr)}
  .decision-chain-step{min-height:0}
  .decision-shortcuts{grid-template-columns:minmax(0,1fr)}
  .decision-editors .wb-card-body{grid-template-columns:minmax(0,1fr)}
  .decision-editors .wb-group{padding:var(--sp-3)}
  .decision-editors .wb-field{grid-template-columns:10px minmax(0,1fr)}
  .decision-reference-list>div{align-items:flex-start;flex-direction:column;gap:var(--sp-1)}
  .decision-reference-list span{text-align:left}
  .decision-chain-rule{max-width:45%;white-space:normal;text-align:right}
}
@media(prefers-reduced-motion:reduce){
  .decision-page *{scroll-behavior:auto;animation:none;transition:none}
}

/* action-page.css */
.action-page{
  --action-together:var(--t-risk-ink);
  --action-game:var(--t-accent-ink);
  --action-reality:var(--t-warn-ink);
  display:grid;
  gap:var(--sp-7);
  min-width:0;
  color:var(--t-text);
}
.action-overview{
  position:relative;
  display:grid;
  grid-template-columns:minmax(210px,.78fr) minmax(0,1.5fr);
  gap:clamp(var(--sp-5), 4vw, var(--sp-8));
  align-items:center;
  min-height:238px;
  overflow:hidden;
  padding:clamp(var(--sp-5), 3vw, calc(var(--sp-1) + var(--sp-6)));
  border:1px solid color-mix(in srgb,var(--t-text-strong) 72%,transparent);
  border-radius:var(--r-lg);
  background:var(--t-text-strong);
  color:var(--t-text-invert);
  isolation:isolate;
}
.action-overview::before{
  position:absolute;
  z-index:-1;
  inset:0;
  background-image:linear-gradient(color-mix(in srgb,var(--t-text-invert) 5%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--t-text-invert) 5%,transparent) 1px,transparent 1px);
  background-size:32px 32px;
  mask-image:linear-gradient(90deg,transparent,black 45%,black);
  content:"";
  pointer-events:none;
}
.action-overview-copy{min-width:0;max-width:340px}
.action-kicker{
  display:flex;
  align-items:center;
  gap:var(--sp-2);
  margin:0;
  color:color-mix(in srgb,var(--t-text-invert) 64%,transparent);
  font:700 10px/1.4 var(--numeric-font);
  letter-spacing:.08em;
}
.action-live-mark{
  width:7px;
  height:7px;
  flex:none;
  border:1px solid var(--t-ok-quiet);
  border-radius:50%;
  background:var(--t-ok);
  box-shadow:0 0 0 4px color-mix(in srgb,var(--t-ok-ink) 18%,transparent);
  animation:action-beat 2.4s ease-in-out infinite;
}
.action-overview h2{
  margin:var(--sp-3) 0 0;
  color:var(--t-text-invert);
  font-size:var(--fs-head);
  font-weight:650;
  line-height:1.25;
}
.action-overview-role{
  margin:var(--sp-2) 0 0;
  color:color-mix(in srgb,var(--t-text-invert) 70%,transparent);
  font-size:var(--fs-tiny);
}
.action-overview-role strong{color:var(--t-text-invert);font-weight:650}
.action-overview-count{
  display:flex;
  align-items:baseline;
  gap:var(--sp-2);
  margin-top:var(--sp-5);
}
.action-overview-count strong{
  color:var(--t-text-invert);
  font:650 28px/1 var(--numeric-font);
  font-variant-numeric:tabular-nums;
}
.action-overview-count strong span{color:color-mix(in srgb,var(--t-text-invert) 46%,transparent);font-size:var(--fs-lead)}
.action-overview-count>span{color:color-mix(in srgb,var(--t-text-invert) 66%,transparent);font-size:var(--fs-tiny)}
.action-meter{
  width:min(100%,210px);
  height:4px;
  margin-top:var(--sp-2);
  overflow:hidden;
  border-radius:var(--r-pill);
  background:color-mix(in srgb,var(--t-text-invert) 17%,transparent);
}
.action-meter span{
  display:block;
  width:0;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg,var(--action-together),var(--action-game) 52%,var(--t-ok-quiet));
  transition:width .7s cubic-bezier(.2,.75,.25,1);
}
.action-overview-summary{min-height:1.5em;margin:var(--sp-2) 0 0;color:color-mix(in srgb,var(--t-text-invert) 72%,transparent);font-size:var(--fs-micro)}
.action-overview-map{
  position:relative;
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:clamp(var(--sp-2), 1.4vw, var(--sp-4));
  min-width:0;
  align-items:stretch;
}
.action-map-line{
  position:absolute;
  top:22px;
  right:12%;
  left:12%;
  height:1px;
  overflow:hidden;
  background:color-mix(in srgb,var(--t-text-invert) 21%,transparent);
  pointer-events:none;
}
.action-map-line::after{
  position:absolute;
  inset:0 auto 0 -35%;
  width:34%;
  background:linear-gradient(90deg,transparent,var(--t-surface-raised),transparent);
  content:"";
  animation:action-signal 5s ease-in-out infinite;
}
.action-route-node{
  position:relative;
  z-index:1;
  display:grid;
  grid-template-rows:18px 46px auto 10px;
  justify-items:center;
  gap:var(--sp-2);
  min-width:0;
  min-height:147px;
  padding:var(--sp-2) var(--sp-2) var(--sp-2);
  border:1px solid color-mix(in srgb,var(--t-text-invert) 15%,transparent);
  border-radius:var(--r-md);
  background:color-mix(in srgb,var(--t-text-invert) 7%,transparent);
  color:var(--t-text-invert);
  text-align:center;
  cursor:pointer;
  transition:transform var(--dur-fast) ease,border-color var(--dur-fast) ease,background var(--dur-fast) ease;
}
