.action-qzone-limits span{min-width:0;overflow-wrap:anywhere}
.action-qzone-alert{display:flex;gap:var(--sp-2);align-items:flex-start;margin:0;padding:var(--sp-2) var(--sp-3);border:1px solid color-mix(in srgb,var(--t-risk) 46%,transparent);border-radius:var(--r-sm);background:var(--t-risk-quiet);color:var(--t-risk-ink);font-size:var(--fs-tiny);line-height:1.6}
