.action-qzone-block{display:grid;min-width:0;gap:var(--sp-2);padding:var(--sp-3);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface-soft)}
.action-qzone-block-head{display:flex;flex-wrap:wrap;align-items:center;gap:var(--sp-2);min-width:0}
