.action-qzone-scene{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr));gap:var(--sp-2);min-width:0}
.action-qzone-field select{width:100%;min-width:0;min-height:32px;padding:var(--sp-1) var(--sp-2);border:1px solid var(--t-line-firm);border-radius:var(--r-xs);background:var(--t-surface);color:var(--t-text);font:inherit;font-size:var(--fs-tiny);line-height:1.6;cursor:pointer;text-overflow:ellipsis}
.action-qzone-field select:focus-visible{outline:2px solid var(--t-focus);outline-offset:1px}
