.action-qzone-suggestion-list{display:grid;gap:var(--sp-2);min-width:0}
.action-qzone-suggestion{
  display:grid;
  min-width:0;
  gap:var(--sp-2);
  padding:var(--sp-3);
  border:1px solid color-mix(in srgb,var(--t-warn) 34%,transparent);
  border-radius:var(--r-sm);
  background:var(--t-surface);
