.action-qzone-suggestion-head{display:flex;flex-wrap:wrap;align-items:flex-start;gap:var(--sp-2);min-width:0}
.action-qzone-suggestion-head strong{display:flex;gap:var(--sp-1);min-width:0;margin-right:auto;color:var(--t-text-strong);font-size:var(--fs-tiny);font-weight:650;line-height:1.6}
