.action-qzone-suggestion-head strong span{min-width:0;overflow-wrap:anywhere;white-space:pre-wrap}
.action-qzone-suggestion-head time{flex:none;color:var(--t-text-faint);font-size:var(--fs-micro);white-space:nowrap}
.action-qzone-suggestion-meta{display:flex;flex-wrap:wrap;gap:var(--sp-2) var(--sp-3);margin:0;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.6}
