.action-qzone-suggestion-note{display:flex;gap:var(--sp-2);align-items:flex-start;margin:0;padding:var(--sp-2);border-radius:var(--r-xs);background:var(--t-warn-quiet);color:var(--t-warn-ink);font-size:var(--fs-micro);line-height:1.7}
.action-qzone-suggestion-note>svg{width:14px;height:14px;flex:none;margin-top:3px}
.action-qzone-suggestion-note span{min-width:0;overflow-wrap:anywhere}
.action-qzone-suggestion-form{display:grid;gap:var(--sp-2);min-width:0}
