.action-qzone-suggestion-reason{display:flex;gap:var(--sp-1);align-items:flex-start;flex:1 1 180px;min-width:0;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.6}
.action-qzone-suggestion-reason[hidden]{display:none}
.action-qzone-suggestion-reason>svg{width:13px;height:13px;flex:none;margin-top:3px}
.action-qzone-suggestion-reason span{min-width:0;overflow-wrap:anywhere}
.action-qzone-danger{display:grid;gap:var(--sp-2);padding-top:var(--sp-2);border-top:1px solid var(--t-line)}
.action-qzone-danger.is-confirming{padding:var(--sp-2);border:1px solid color-mix(in srgb,var(--t-risk) 38%,transparent);border-radius:var(--r-sm);background:var(--t-risk-quiet)}
.action-qzone-danger-text{display:flex;gap:var(--sp-2);align-items:flex-start;margin:0;color:var(--t-risk-ink);font-size:var(--fs-tiny);line-height:1.7}
.action-qzone-danger-text>svg{width:15px;height:15px;flex:none;margin-top:2px}
.action-qzone button:disabled,.action-qzone textarea:disabled,.action-qzone select:disabled,.action-qzone input:disabled{opacity:.5;cursor:not-allowed}
.action-qzone .button span{min-width:0;overflow-wrap:anywhere}
@media(max-width:700px){
