  .action-qzone-feed{grid-template-columns:minmax(0,1fr)}
  .action-qzone-status-row .button{margin-left:0}
}
@media(max-width:380px){
  .action-qzone-head{grid-template-columns:32px minmax(0,1fr)}
  .action-qzone-mark{width:32px;height:32px}
  .action-qzone-block{padding:var(--sp-2)}
  .action-qzone-post{padding:var(--sp-2)}
  .action-qzone-suggestion{padding:var(--sp-2)}
}
@keyframes action-arrive{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
@keyframes action-focus{0%,100%{filter:none}35%{filter:brightness(1.05)}}
@keyframes action-beat{0%,100%{box-shadow:0 0 0 4px color-mix(in srgb,var(--t-ok) 15%,transparent)}50%{box-shadow:0 0 0 7px color-mix(in srgb,var(--t-ok) 5%,transparent)}}
@keyframes action-signal{0%,35%{transform:translateX(0);opacity:0}55%{opacity:.9}82%,100%{transform:translateX(400%);opacity:0}}
.action-page :is(button,a):focus-visible{outline-color:var(--t-focus)}
@media(max-width:1100px){
  .action-overview{grid-template-columns:minmax(190px,.7fr) minmax(0,1.3fr);gap:var(--sp-5)}
  .action-config-grid{gap:var(--sp-2)}
  .action-config-card{padding:var(--sp-3)}
