  .action-overview{grid-template-columns:minmax(0,1fr);gap:var(--sp-5);padding:var(--sp-5)}
  .action-overview-copy{max-width:none}
  .action-overview-count{margin-top:var(--sp-4)}
  .action-overview-map{gap:var(--sp-2)}
  .action-route-node{min-height:132px;padding:var(--sp-2) var(--sp-1)}
  .action-route-copy strong{font-size:var(--fs-micro)}
  .action-route-copy small{font-size:var(--fs-micro)}
  .action-map-line{top:21px}
  .action-config-grid{grid-template-columns:minmax(0,1fr);gap:var(--sp-2)}
  .action-config-card{min-height:0;padding:var(--sp-3)}
  .action-config-card-head{grid-template-columns:38px minmax(0,1fr) auto}
  .action-config-icon{width:36px;height:36px}
  .action-card-status{grid-column:auto;justify-self:end;max-width:110px;text-align:right}
  .action-config-summary{min-height:0;margin:var(--sp-2) 0 var(--sp-3)}
  .action-config-owner{margin-bottom:var(--sp-2)}
