:root[data-motion="off"] .action-page *::before,
:root[data-motion="off"] .action-page *::after,
:root[data-motion="low"] .action-live-mark,
:root[data-motion="low"] .action-map-line::after,
:root[data-motion="low"] .action-config-card,
body.reduce-motion .action-page *,
body.reduce-motion .action-page *::before,
body.reduce-motion .action-page *::after{animation:none!important;transition-duration:.01ms!important}

/* QQ 空间作为主操作区，其余提供方收为状态清单。 */
.action-page{gap:var(--sp-6)}
.action-qzone{
  gap:var(--sp-5);
  padding:0 0 var(--sp-6);
  border:0;
  border-bottom:1px solid var(--t-line-firm);
  border-radius:0;
  background:transparent;
  box-shadow:none;
}
.action-qzone-head{grid-template-columns:44px minmax(0,1fr);align-items:center;gap:var(--sp-3)}
.action-qzone-mark{width:42px;height:42px;border:1px solid color-mix(in srgb,var(--t-accent) 28%,transparent);border-radius:var(--r-sm)}
.action-qzone-mark svg{width:19px;height:19px}
.action-qzone-copy h2{font-size:var(--fs-title);line-height:1.3}
.action-qzone-copy>p:last-child{margin-top:var(--sp-1);font-size:var(--fs-micro)}
.action-qzone-body{gap:var(--sp-3)}
.action-capabilities{display:grid;gap:var(--sp-3);min-width:0}
.action-capabilities-heading{display:flex;align-items:end;justify-content:space-between;gap:var(--sp-3)}
.action-capabilities-heading h2{margin:var(--sp-1) 0 0;color:var(--t-text-strong);font-size:var(--fs-title);font-weight:650;line-height:1.3}
.action-capabilities-count{flex:none;color:var(--t-text-faint);font:600 var(--fs-micro)/1.4 var(--numeric-font);font-variant-numeric:tabular-nums}
.action-capability-list{display:grid;min-width:0;border-top:1px solid var(--t-line-firm)}
.action-capability-row{
  display:grid;
  grid-template-columns:40px minmax(0,1fr) auto auto;
  gap:var(--sp-3);
  align-items:center;
  min-width:0;
  padding:var(--sp-3) var(--sp-1);
  border-bottom:1px solid var(--t-line);
  scroll-margin-block:24px;
  transition:background var(--dur-fast) ease;
}
.action-capability-row:hover{background:var(--t-surface-soft)}
.action-capability-icon{display:grid;width:36px;height:36px;place-items:center;border-radius:var(--r-sm);background:color-mix(in srgb,var(--action-node) 13%,var(--t-surface));color:var(--action-node)}
.action-capability-icon svg{width:18px;height:18px}
.action-capability-row h3{min-width:0;margin:0;color:var(--t-text-strong);font-size:var(--fs-body);font-weight:650;line-height:1.4;overflow-wrap:anywhere}
.action-capability-status{display:inline-flex;max-width:140px;align-items:center;gap:var(--sp-1);padding:calc(var(--sp-1) * 1.25) var(--sp-2);border:1px solid var(--t-line);border-radius:var(--r-pill);background:var(--t-surface-soft);color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.35;overflow-wrap:anywhere}
.action-capability-status i{width:6px;height:6px;flex:none;border-radius:50%;background:currentColor}
.action-capability-status.action-status--connected{border-color:color-mix(in srgb,var(--t-ok) 34%,transparent);background:var(--t-ok-quiet);color:var(--t-ok-ink)}
.action-capability-status:is(.action-status--degraded,.action-status--missing,.action-status--disabled,.action-status--waiting,.action-status--conflict,.action-status--unknown){border-color:color-mix(in srgb,var(--t-warn) 30%,transparent);background:var(--t-warn-quiet);color:var(--t-warn-ink)}
.action-capability-status.action-status--stopped{border-color:color-mix(in srgb,var(--t-risk) 30%,transparent);background:var(--t-risk-quiet);color:var(--t-risk-ink)}
.action-capability-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:var(--sp-2);min-width:0}
.action-capability-actions .button{display:flex;min-width:0;align-items:center;justify-content:center;gap:var(--sp-1);line-height:1.35;white-space:normal;text-align:center}
.action-capability-actions .button span{min-width:0;overflow-wrap:anywhere}
.action-capability-actions svg{width:14px;height:14px;flex:none}
.action-capability-actions .action-settings-button>svg:last-child{width:12px;height:12px;margin-left:auto}
.action-capability-row :is(button,a):focus-visible{outline:2px solid var(--t-focus);outline-offset:2px}
@media(max-width:900px){
  .action-capability-row{grid-template-columns:36px minmax(0,1fr) auto;gap:var(--sp-2)}
  .action-capability-actions{grid-column:2/-1;justify-content:flex-start}
}
@media(max-width:700px){
  .action-page{gap:var(--sp-5)}
  .action-qzone{padding-bottom:var(--sp-5)}
  .action-qzone-head{grid-template-columns:40px minmax(0,1fr)}
  .action-qzone-mark{width:38px;height:38px}
  .action-capabilities-heading{align-items:center}
  .action-capability-row{grid-template-columns:34px minmax(0,1fr) auto;padding-inline:0}
  .action-capability-icon{width:32px;height:32px}
  .action-capability-actions{grid-column:2/-1}
  .action-qzone-status-row .button{margin-left:0}
}
@media(max-width:380px){
  .action-qzone-head{grid-template-columns:34px minmax(0,1fr)}
  .action-qzone-mark{width:32px;height:32px}
  .action-capabilities-heading{align-items:flex-start;flex-direction:column;gap:var(--sp-1)}
  .action-capability-row{grid-template-columns:30px minmax(0,1fr);column-gap:var(--sp-2)}
  .action-capability-icon{width:28px;height:28px}
  .action-capability-status{grid-column:2;grid-row:2;justify-self:start}
  .action-capability-actions{grid-column:2;grid-row:3;justify-content:flex-start}
  .action-capability-actions .button{padding-inline:7px}
}

/* home.css */
/* 小屋首页与生活专题页组件层
 *
 * 首页此前用的是另一套语汇：右栏三张 overview-card、生活观察三张同款卡、
 * 家具目录一张等宽卡片网格。每张卡都带 radius + shadow + border（见
 * styles.css 的 .overview-card / .furniture-card），而管理页同一时期已经改成
 * 分隔线清单。结果是同一个插件里两种读法：管理页扫得动，首页要一张张看。
 *
 * 这一层把首页收到与管理页同一套结构件上：
 *   分区用 border-top 分隔线，不用卡片框
 *   层级靠字号与留白表达，不靠嵌套
 *   说明限宽 62ch，不拉通栏
 *   颜色一律取 tokens.css 的语义令牌，切主题整页跟着变
 *
 * 体素小屋不进这一层。它是首页唯一的主角，尺寸、圆角与背景渐变都留在
 * styles.css 里由 .room-stage 管——那块的视觉重量是刻意的，与清单语汇不冲突。
 */

/* === 页首 ===
 * 旧的 .home-jumpbar 是一条横贯整屏的工具栏，三个「跳到某段」按钮加一句
 * 版本号。跳转本身有用，但「当前角色的生活空间 V2.0」这句不携带信息，
 * 版本号在能力目录里已经有了。收成一行小字，不加边框。 */
.home-lede{
  display:flex;align-items:baseline;justify-content:space-between;
  gap:var(--sp-4);flex-wrap:wrap;margin:0 0 var(--sp-4);
}
.home-lede-nav{display:flex;gap:var(--sp-1);flex-wrap:wrap}
.home-lede-nav button{
  display:inline-flex;align-items:center;gap:var(--sp-1);
  padding:var(--sp-2) var(--sp-3);border-radius:var(--r-sm);
  color:var(--t-text-soft);font-size:var(--fs-body);line-height:1.5;
}
.home-lede-nav button:hover{background:var(--t-surface-soft);color:var(--t-text-strong)}
.home-lede-nav svg{width:14px;height:14px;color:var(--t-text-faint)}
.home-lede-note{color:var(--t-text-faint);font-size:var(--fs-tiny);margin:0}

/* === 小屋与右栏 ===
 * 左列是体素小屋（主角），右栏是与它同时要看的状态。右栏比原来的
 * 285px 收窄 15px：三张卡换成清单行后每行只用一行高度，不需要那么宽。 */
.home-stage{
  display:grid;grid-template-columns:minmax(0,1fr) 270px;
  gap:var(--sp-5);align-items:start;
}
.home-environment{
  display:grid;grid-template-columns:32px minmax(0,1fr) auto 36px;align-items:center;
  gap:var(--sp-3);min-width:0;min-height:74px;margin:0 0 var(--sp-4);padding:var(--sp-3) var(--sp-4);
  border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface);
}
.home-environment-icon{display:grid;place-items:center;width:32px;height:32px;color:var(--t-accent-ink);}
.home-environment-icon svg{width:23px;height:23px;}
.home-environment-copy{display:grid;gap:var(--sp-1);min-width:0;}
.home-environment-copy strong{color:var(--t-text-strong);font-size:var(--fs-body);font-weight:600;line-height:1.5;overflow-wrap:anywhere;}
.home-environment-copy small,.home-environment-clock small{color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.45;overflow-wrap:anywhere;}
.home-environment-clock{display:grid;justify-items:end;gap:2px;white-space:nowrap;}
.home-environment-clock time{color:var(--t-text-strong);font-size:var(--fs-title);font-variant-numeric:tabular-nums;line-height:1.25;}
.home-environment-refresh{display:grid;place-items:center;width:36px;height:36px;border:1px solid var(--t-line);border-radius:var(--r-sm);color:var(--t-text-soft);}
.home-environment-refresh:hover:not(:disabled){background:var(--t-surface-soft);color:var(--t-text-strong);}
.home-environment-refresh svg{width:16px;height:16px;}
.home-environment-refresh[aria-busy="true"] svg{animation:home-weather-spin 1s linear infinite;}
@keyframes home-weather-spin{to{transform:rotate(360deg);}}
.home-stage-main{min-width:0}
.home-stage-side{display:flex;flex-direction:column;gap:var(--sp-4);min-width:0}

/* 小屋工具行：标题 + 两个文字动作。 */
.room-bar{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);flex-wrap:wrap;margin:0 0 var(--sp-3)}
.room-bar h2{display:flex;align-items:center;gap:var(--sp-2);color:var(--t-text-strong);font-size:var(--fs-body);font-weight:600;margin:0}
.room-bar h2 svg{width:15px;height:15px;color:var(--t-text-faint)}
.room-bar-actions{display:flex;gap:var(--sp-1);flex-wrap:wrap}

/* 场景下方的一行说明：天气摘要 + 来源。不画框，只当底注。 */
.room-foot{
  display:flex;align-items:baseline;justify-content:space-between;
  gap:var(--sp-4);flex-wrap:wrap;margin:var(--sp-3) 0 0;
  color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.7;
}
.room-foot b{color:var(--t-text-soft);font-weight:500}

/* 常用生活入口：四格。改成分隔线格，不是四个圆角按钮块——
 * 它们指向四处不同地方，分隔线正好表达「这是四个并列的入口」。 */
.room-doors{
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));
  margin-top:var(--sp-4);border-top:1px solid var(--t-line);
}
.room-doors button{
  display:flex;align-items:center;gap:var(--sp-2);
  padding:var(--sp-3) 0;color:var(--t-text);font-size:var(--fs-body);text-align:left;min-width:0;
}
.room-doors button+button{padding-left:var(--sp-4)}
.room-doors button:hover{color:var(--t-accent)}
.room-doors svg{width:15px;height:15px;flex:none;color:var(--t-text-faint)}
.room-doors button:hover svg{color:var(--t-accent)}
.room-doors span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* === 分区 ===
 * 与管理页 .console-section 同一形状：一条分隔线，标题与说明同一行，
 * 说明靠右限宽。首页的分区比管理页少，所以说明可以直接跟在标题后面。 */
.home-band{padding-top:var(--sp-5);border-top:1px solid var(--t-line);scroll-margin-top:14px}
.home-band-head{
  display:flex;align-items:baseline;justify-content:space-between;
  gap:var(--sp-4);flex-wrap:wrap;margin:0 0 var(--sp-4);
}
.home-band-head h2{color:var(--t-text-strong);font-size:var(--fs-lead);font-weight:600;margin:0;letter-spacing:.01em}
.home-band-note{
  flex:1 1 260px;min-width:0;max-width:62ch;margin:0;
  color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.7;
}

/* === 概览行 ===
 * 右栏三张卡与生活观察三张卡共用这一套。跳转行沿用管理页的形状：
 * 单行高度、标签带说明、右侧一个动作。 */
.home-rows{display:flex;flex-direction:column}
.home-row{
  display:flex;align-items:center;gap:var(--sp-3);
  padding:var(--sp-3) 0;border-bottom:1px solid var(--t-line);min-width:0;
}
.home-row:last-child{border-bottom:0}
.home-row-icon{
  flex:none;display:grid;place-items:center;width:20px;height:20px;
  color:var(--t-text-faint);
}
.home-row-icon svg{width:16px;height:16px}
.home-row-main{flex:1;min-width:0}
.home-row-main strong{display:block;color:var(--t-text);font-size:var(--fs-body);font-weight:500}
.home-row-main small{
  display:block;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.6;
  margin-top:3px;max-width:62ch;
}
.home-row-value{flex:none;color:var(--t-text-soft);font-size:var(--fs-body);text-align:right}
.home-row-value b{display:block;color:var(--t-text-strong);font-size:var(--fs-lead);font-weight:600;line-height:1.3}
.home-row-value small{color:var(--t-text-faint);font-size:var(--fs-micro)}

/* === 生活观察 ===
 * 原来的四页签（日记与梦境 / 生活轨迹 / 状态变化 / 交互影响）改成
 * 段内切换条，样式与管理页的 section-tabs 对齐。 */
.home-tabs{display:flex;gap:var(--sp-1);flex-wrap:wrap;margin:0 0 var(--sp-4)}
.home-tabs button{
  padding:var(--sp-2) var(--sp-3);border-radius:var(--r-sm);
  color:var(--t-text-soft);font-size:var(--fs-body);line-height:1.5;
}
.home-tabs button:hover{background:var(--t-surface-soft)}
.home-tabs button.active{background:var(--t-surface-raised);color:var(--t-accent);box-shadow:var(--t-shadow)}
.home-band-body{min-width:0}
.home-band-body:empty{display:none}

/* 观察内容共用同一套行距，不再各自成卡。 */
.home-note{
  max-width:62ch;margin:0;color:var(--t-text-faint);
  font-size:var(--fs-tiny);line-height:1.85;
}
.home-empty{
  display:flex;flex-direction:column;gap:var(--sp-3);
  padding:var(--sp-4) 0;color:var(--t-text-soft);font-size:var(--fs-body);
}
.home-empty strong{color:var(--t-text-strong);font-size:var(--fs-body);font-weight:500}
.home-empty p{max-width:62ch;margin:0;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.85}
.home-empty svg{width:18px;height:18px;color:var(--t-text-faint)}

/* 心理能量：一个数字 + 一条 meter。用栅格对齐数字与量条。 */
.home-energy{
  display:grid;grid-template-columns:auto minmax(0,1fr);
  align-items:center;gap:var(--sp-3) var(--sp-4);
  padding:var(--sp-4) 0;border-bottom:1px solid var(--t-line);
}
.home-energy span{color:var(--t-text-soft);font-size:var(--fs-body)}
.home-energy strong{color:var(--t-text-strong);font-size:var(--fs-head);font-weight:600}
.home-energy strong small{color:var(--t-text-faint);font-size:var(--fs-tiny);font-weight:400}
.home-energy meter{width:100%;height:6px}

/* 状态事实：两列定义表。 */
.home-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 var(--sp-5);margin:0}
.home-facts>div{
  display:flex;align-items:baseline;justify-content:space-between;gap:var(--sp-3);
  padding:var(--sp-2) 0;border-bottom:1px solid var(--t-line);min-width:0;
}
.home-facts dt{color:var(--t-text-faint);font-size:var(--fs-tiny);margin:0}
.home-facts dd{margin:0;color:var(--t-text);font-size:var(--fs-body);text-align:right;overflow-wrap:anywhere}

/* === 家具目录 ===
 * 换成按可用性分组的清单。旧版是等宽卡片网格，每张卡重复一遍
 * 图标 + 名字 + 描述 + 归属 + 状态，扫二十张很累；而且「待处理」那个
 * 筛选页签本来就是个分组，做成分组标题后不需要用户先点一下。 */
.home-group-head{
  display:flex;align-items:baseline;gap:var(--sp-3);
  padding:var(--sp-4) 0 var(--sp-2);
}
.home-group-head h3{color:var(--t-text-strong);font-size:var(--fs-body);font-weight:600;margin:0}
.home-group-head small{color:var(--t-text-faint);font-size:var(--fs-tiny)}
.home-group-head .pill{margin-left:auto;flex:none}

.home-tools{
  display:flex;align-items:center;justify-content:space-between;
  gap:var(--sp-4);flex-wrap:wrap;margin:0 0 var(--sp-3);
}
.home-filters{display:flex;gap:var(--sp-1);flex-wrap:wrap}
.home-filters button{
  padding:var(--sp-2) var(--sp-3);border-radius:var(--r-sm);
  color:var(--t-text-soft);font-size:var(--fs-tiny);line-height:1.5;
}
.home-filters button:hover{background:var(--t-surface-soft)}
.home-filters button.active{background:var(--t-surface-raised);color:var(--t-accent);box-shadow:var(--t-shadow)}
.home-filters button span{color:var(--t-text-faint);margin-left:var(--sp-1)}
.home-filters button.active span{color:var(--t-accent)}
.home-search{
  display:flex;align-items:center;gap:var(--sp-2);min-width:180px;
  padding:0 0 0 var(--sp-2);border-radius:var(--r-sm);
  border:1px solid var(--t-line);background:var(--t-surface);
}
.home-search svg{width:14px;height:14px;flex:none;color:var(--t-text-faint)}
.home-search input{
  flex:1;min-width:0;padding:var(--sp-2) var(--sp-2) var(--sp-2) 0;border:0;background:none;
  color:var(--t-text);font-size:var(--fs-body);
}

/* 家具行：图标 + 名字与说明 + 归属 + 状态 + 一个动作。
 * 与 .home-row 的区别是它多一格图标块、且名字右侧跟状态标签。 */
.home-item{
  display:grid;grid-template-columns:28px minmax(0,1fr) auto;
  align-items:center;gap:var(--sp-3);
  padding:var(--sp-3) 0;border-bottom:1px solid var(--t-line);min-width:0;
}
.home-item:last-child{border-bottom:0}
.home-item-icon{
  display:grid;place-items:center;width:28px;height:28px;
  border-radius:var(--r-sm);background:var(--t-surface-soft);color:var(--t-text-soft);
}
.home-item-icon svg{width:15px;height:15px}
.home-item-main{min-width:0}
.home-item-title{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap;min-width:0}
.home-item-title strong{color:var(--t-text);font-size:var(--fs-body);font-weight:500}
.home-item-main small{
  display:block;margin-top:2px;color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.6;
}
.home-item-end{display:flex;align-items:center;gap:var(--sp-3);flex:none}
.home-item-owner{color:var(--t-text-faint);font-size:var(--fs-tiny);white-space:nowrap}
.home-item-end button{
  display:inline-flex;align-items:center;gap:var(--sp-1);
  padding:var(--sp-1) var(--sp-2);border-radius:var(--r-sm);
  color:var(--t-text-soft);font-size:var(--fs-tiny);white-space:nowrap;
}
.home-item-end button:hover{background:var(--t-surface-soft);color:var(--t-accent)}
.home-item-end button svg{width:13px;height:13px}
/* 不可用的家具压一档对比度，但仍可读、仍可点开看原因——
 * 旧版靠整张卡套一层透明度和「预览已移除」四个字，用户看不出为什么。 */
.home-item.unavailable .home-item-icon{background:none;color:var(--t-text-faint)}
.home-item.unavailable .home-item-title strong{color:var(--t-text-soft)}

.home-foot{
  display:flex;align-items:baseline;justify-content:space-between;
  gap:var(--sp-4);flex-wrap:wrap;
  padding-top:var(--sp-3);border-top:1px solid var(--t-line);
  color:var(--t-text-faint);font-size:var(--fs-tiny);
}

/* === 体素小屋的回退态 ===
 * .voxel-fallback-actions 此前被 app.js 渲染却没有任何样式表定义它——
 * 与管理页 console.css 那次是同一个毛病，只是范围小。补上。 */
.voxel-fallback-actions{display:flex;gap:var(--sp-2);justify-content:center;margin-top:var(--sp-3)}

@media(max-width:1100px){
  .home-stage{grid-template-columns:minmax(0,1fr)}
  .home-stage-side{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-4)}
}
@media(max-width:760px){
  /* 手机上天气栏压成两行：图标 + 地点/天气 + 刷新，时钟单独一行横排。
     原来四列挤在 390px 里，说明列只剩约 150px，一句
     「角色地点未设置 · 正在读取天气设置…」要折成三行，
     右侧「20:25 / 10月17日星期六 / Asia/Shanghai · 夜间」也各占一行。 */
  .home-environment{
    grid-template-columns:24px minmax(0,1fr) 40px;
    grid-template-areas:"icon copy refresh" "clock clock clock";
    align-items:center;gap:var(--sp-1) var(--sp-2);
    width:100%;min-width:0;min-height:0;padding:var(--sp-2) var(--sp-3);
    overflow:hidden;
  }
  .home-environment-icon{grid-area:icon;width:24px;height:28px}
  .home-environment-icon svg{width:20px;height:20px}
  .home-environment-copy{grid-area:copy;min-width:0}
  /* 窄屏不让摘要逐字竖排：最多两行，超出省略；正常手机宽度仍能完整读到。
     详情同样限两行，避免异常窄容器把整张卡撑成一屏高。 */
  .home-environment-copy strong,
  .home-environment-copy small{
    display:-webkit-box;overflow:hidden;
    -webkit-box-orient:vertical;
    word-break:break-word;overflow-wrap:anywhere;
  }
  .home-environment-copy strong{-webkit-line-clamp:2;line-clamp:2;line-height:1.45}
  /* 摘要最多两行已经足够，次要说明收成一行，避免窄屏多占一整行。 */
  .home-environment-copy small{-webkit-line-clamp:1;line-clamp:1;line-height:1.5}
  .home-environment-clock{
    grid-area:clock;justify-items:start;min-width:0;
    display:flex;flex-wrap:wrap;align-items:baseline;gap:var(--sp-1);
    padding-top:var(--sp-1);border-top:1px solid var(--t-line);
    white-space:normal;
  }
  .home-environment-clock > *{white-space:nowrap}
  .home-environment-clock time{font-size:var(--fs-lead)}
  .home-environment-refresh{grid-area:refresh;width:40px;height:40px}
  .home-stage-side{grid-template-columns:minmax(0,1fr)}
  .room-doors{grid-template-columns:repeat(2,minmax(0,1fr))}
  .room-doors button+button{padding-left:0}
  .room-doors button:nth-child(n+3){border-top:1px solid var(--t-line)}
  .room-doors button:nth-child(even){padding-left:var(--sp-4)}
  .home-facts{grid-template-columns:minmax(0,1fr)}
  .home-item{grid-template-columns:28px minmax(0,1fr)}
  .home-item-end{grid-column:2;justify-content:flex-start}
  .home-band-head{flex-direction:column;align-items:flex-start;gap:var(--sp-2)}
  .home-band-note{max-width:none}
}
@media(prefers-reduced-motion:reduce){.home-environment-refresh[aria-busy="true"] svg{animation:none}}

/* 小屋右栏。承接 V1 的状态摘要与时间线，使用当前主题的分隔线与色板。 */
.home-side-band{min-width:0;padding-top:var(--sp-4)}
.shell-side>.home-side-band:first-child{padding-top:0;border-top:0}
.home-side-band .home-band-head{
  flex-direction:row;align-items:center;flex-wrap:nowrap;gap:var(--sp-2);margin-bottom:var(--sp-3);
}
.home-side-band .home-band-head h2{font-size:var(--fs-lead);letter-spacing:0}
.home-side-action{
  flex:none;min-height:36px;padding:var(--sp-1) 0 var(--sp-1) var(--sp-2);font-size:var(--fs-tiny);
  color:var(--t-accent-ink);white-space:nowrap;
}
.home-side-action:focus-visible{outline:2px solid var(--t-accent);outline-offset:3px;border-radius:var(--r-2xs)}
.home-state-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-2);margin:var(--sp-3) 0 0}
.home-state-tile{min-width:0;min-height:58px;padding:var(--sp-2) var(--sp-3);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface)}
.home-state-tile:first-child{grid-column:1/-1}
.home-state-tile dt{margin:0 0 var(--sp-1);font-size:var(--fs-micro);color:var(--t-text-soft)}
.home-state-tile dd{margin:0;font-size:var(--fs-body);line-height:1.6;color:var(--t-text);overflow-wrap:anywhere}
.home-state-tile dd.is-unrecorded{color:var(--t-text-faint)}
.home-vitals{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--sp-1)}
.home-vital{
  position:relative;display:flex;flex-direction:column;align-items:center;gap:var(--sp-1);min-width:0;min-height:72px;
  padding:var(--sp-1) 2px;border:0;border-radius:var(--r-sm);background:transparent;color:var(--t-text-soft);cursor:help;
  transition:background-color var(--dur-fast),color var(--dur-fast);
}
.home-vital:hover{background:var(--t-surface)}
.home-vital:focus-visible{outline:2px solid var(--t-accent);outline-offset:2px}
.home-vital-glyph{
  position:relative;display:grid;place-items:center;flex:none;width:42px;height:42px;border-radius:50%;
  border:1px solid var(--t-line-firm);background:var(--t-surface-sunken);color:var(--t-text-soft);
}
.home-vital-glyph svg{width:22px;height:22px;stroke-width:1.7}
.home-vital-label{font-size:var(--fs-micro);line-height:1.5;color:var(--t-text-soft)}
.home-vital[data-tone="ok"] .home-vital-glyph{border-color:transparent;background:var(--t-ok-quiet);color:var(--t-ok-ink)}
.home-vital[data-tone="warn"] .home-vital-glyph{border-color:transparent;background:var(--t-warn-quiet);color:var(--t-warn-ink)}
.home-vital[data-tone="risk"] .home-vital-glyph{border-color:transparent;background:var(--t-risk-quiet);color:var(--t-risk-ink)}
.home-vital[data-tone="rest"] .home-vital-glyph{border-color:transparent;background:var(--t-accent-quiet);color:var(--t-accent-ink)}
.home-vital[data-visual="unknown"] .home-vital-glyph{border-style:dashed;background:transparent}
.home-vital[data-visual="disabled"] .home-vital-glyph{background:transparent;opacity:.55}
.home-vital[data-visual="disabled"] .home-vital-glyph::after{content:"";position:absolute;width:27px;height:1px;background:currentColor;transform:rotate(-45deg)}
.home-vital-mark{position:absolute;right:-3px;top:-3px;font-size:var(--fs-micro);font-weight:600;line-height:1.3;background:var(--t-canvas);padding:1px 2px;border-radius:var(--r-2xs)}
.home-vital-tooltip{
  position:absolute;z-index:60;bottom:calc(100% + 8px);left:50%;transform:translateX(-50%);
  display:block;width:max-content;min-width:140px;max-width:220px;padding:var(--sp-2) var(--sp-3);
  border:1px solid var(--t-line-firm);border-radius:var(--r-sm);background:var(--t-surface-raised);box-shadow:var(--t-shadow-lift);
  color:var(--t-text);text-align:left;white-space:normal;overflow-wrap:anywhere;
  opacity:0;visibility:hidden;pointer-events:none;transition:opacity var(--dur-fast),visibility var(--dur-fast);
}
.home-vital:first-child .home-vital-tooltip{left:0;transform:none}
.home-vital:last-child .home-vital-tooltip{left:auto;right:0;transform:none}
.home-vital:is(:hover,:focus) .home-vital-tooltip{opacity:1;visibility:visible}
.home-vital-tooltip strong{display:block;font-size:var(--fs-tiny);line-height:1.65;font-weight:600}
.home-vital-tooltip>span{display:block;margin-top:var(--sp-1);font-size:var(--fs-tiny);line-height:1.7;color:var(--t-text-soft)}
.home-vital-tooltip meter{display:block;appearance:none;width:100%;height:4px;margin-top:var(--sp-2);border:0;border-radius:var(--r-sm);background:var(--t-surface-sunken)}
.home-vital-tooltip meter::-webkit-meter-bar{height:4px;border:0;border-radius:var(--r-sm);background:var(--t-surface-sunken);box-shadow:none}
.home-vital-tooltip meter::-webkit-meter-optimum-value{border-radius:var(--r-sm);background:var(--t-accent)}
.home-vital-tooltip meter::-moz-meter-bar{border-radius:var(--r-sm);background:var(--t-accent)}
.home-side-caption{margin:var(--sp-3) 0 0;font-size:var(--fs-micro);line-height:1.65;color:var(--t-text-soft);overflow-wrap:anywhere}
.home-agenda-current{margin:0 0 var(--sp-3);font-size:var(--fs-tiny);line-height:1.7;color:var(--t-text-soft)}
.home-agenda-current time{font-variant-numeric:tabular-nums;color:var(--t-text-strong);font-weight:600}
.home-agenda-current-gap{display:flex;align-items:baseline;gap:var(--sp-2);flex-wrap:wrap;margin:-var(--sp-2) 0 var(--sp-3);font-size:var(--fs-micro);line-height:1.65;color:var(--t-text-soft)}
.home-agenda-current-gap time{font-variant-numeric:tabular-nums;color:var(--t-accent-ink);font-weight:700}
.home-agenda-current-gap strong{color:var(--t-accent-ink);font-weight:600}
.home-agenda-overview{margin:0 0 var(--sp-3);padding:0 0 var(--sp-3);border-bottom:1px solid var(--t-line)}
.home-agenda-overview-track{position:relative;display:flex;overflow:hidden;height:12px;border-radius:3px;background:var(--t-surface-sunken)}
.home-agenda-overview-segment{display:block;flex:0 0 auto;height:100%;background:var(--t-line-firm)}
.home-agenda-overview-segment[data-kind="gap"]{background:var(--t-surface-sunken)}
.home-agenda-overview-segment[data-kind="unknown"]{background:repeating-linear-gradient(135deg,var(--t-surface-sunken) 0 3px,var(--t-line) 3px 5px)}
.home-agenda-overview-segment[data-tone="planned"]{background:var(--t-ok-quiet)}
.home-agenda-overview-segment[data-tone="proposed"]{background:var(--t-warn-quiet)}
.home-agenda-overview-segment[data-tone="elapsed"]{background:var(--t-line-firm)}
.home-agenda-overview-segment[data-tone="current"]{background:var(--t-accent)}
.home-agenda-overview-point{position:absolute;top:2px;width:8px;height:8px;transform:translateX(-50%);border:1px solid var(--t-canvas);border-radius:50%;background:var(--t-text-soft)}
.home-agenda-overview-now{position:absolute;top:-2px;bottom:-2px;width:2px;transform:translateX(-1px);background:var(--t-accent);box-shadow:0 0 0 1px var(--t-canvas)}
.home-agenda-overview-labels{display:grid;grid-template-columns:1fr 1fr 1fr;margin-top:var(--sp-1);font-size:var(--fs-micro);font-variant-numeric:tabular-nums;color:var(--t-text-faint)}
.home-agenda-overview-labels span:nth-child(2){text-align:center}
.home-agenda-overview-labels span:last-child{text-align:right}
.home-agenda-overview-legend{display:flex;align-items:center;gap:var(--sp-3);flex-wrap:wrap;margin-top:var(--sp-1);font-size:var(--fs-micro);line-height:1.5;color:var(--t-text-soft)}
.home-agenda-overview-legend span{display:inline-flex;align-items:center;gap:var(--sp-1)}
.home-agenda-overview-legend span::before{content:"";width:8px;height:8px;border-radius:2px;background:var(--t-ok-quiet)}
.home-agenda-overview-legend span[data-kind="gap"]::before{border:1px solid var(--t-line-firm);background:var(--t-surface-sunken)}
.home-agenda-overview-legend span[data-kind="unknown"]::before{background:repeating-linear-gradient(135deg,var(--t-surface-sunken) 0 2px,var(--t-line) 2px 3px)}
.home-agenda-overview-legend time{margin-left:auto;font-variant-numeric:tabular-nums;color:var(--t-accent-ink);font-weight:600}
.home-agenda-overview-note{margin:var(--sp-1) 0 0;font-size:var(--fs-micro);line-height:1.55;color:var(--t-warn-ink)}
.home-agenda-scroll{max-height:420px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--t-line-firm) transparent}
.home-agenda-scroll:focus-visible{outline:2px solid var(--t-accent);outline-offset:2px}
.home-agenda-scroll::-webkit-scrollbar{width:6px}
.home-agenda-scroll::-webkit-scrollbar-thumb{border-radius:3px;background:var(--t-line-firm)}
.home-agenda{display:flex;flex-direction:column;list-style:none;margin:0;padding:0}
.home-agenda-item{position:relative;display:grid;grid-template-columns:18px minmax(0,1fr);gap:var(--sp-2);min-width:0;padding:0 0 var(--sp-3)}
.home-agenda-item:not(:last-child)::before{content:"";position:absolute;top:10px;bottom:-6px;left:5px;width:1px;background:var(--t-line-firm)}
.home-agenda-item:last-child{padding-bottom:0}
.home-agenda-dot{z-index:1;width:11px;height:11px;margin-top:var(--sp-1);border:2px solid var(--t-canvas);border-radius:50%;background:var(--t-line-firm)}
.home-agenda-body{min-width:0;padding:0 0 0 var(--sp-1)}
.home-agenda-body time{display:block;font-size:var(--fs-micro);line-height:1.8;color:var(--t-text-soft);font-variant-numeric:tabular-nums}
.home-agenda-body strong{display:block;margin:2px 0;font-size:var(--fs-body);font-weight:500;line-height:1.65;color:var(--t-text);overflow-wrap:anywhere}
.home-agenda-body small{display:block;font-size:var(--fs-micro);line-height:1.7;color:var(--t-text-soft);overflow-wrap:anywhere}
.home-agenda-body .home-agenda-detail{white-space:pre-wrap}
.home-agenda-more{margin-top:var(--sp-2);border-top:1px solid var(--t-line);padding-top:var(--sp-2)}
.home-agenda-more>summary{color:var(--t-accent-ink);font-size:var(--fs-micro);line-height:1.7;cursor:pointer}
.home-agenda-more[open]>.home-agenda{margin-top:var(--sp-3)}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-dot{background:var(--t-accent)}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body{
  padding:var(--sp-2) var(--sp-2);border-radius:var(--r-xs);background:var(--t-accent-quiet);
}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-dot{margin-top:var(--sp-3)}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body :is(time,strong,small){color:var(--t-accent-ink)}
.home-agenda-item[data-current="true"] .home-agenda-dot{width:13px;height:13px;margin-left:-1px;border-color:var(--t-accent-ink);background:var(--t-accent)}
.home-agenda-item[data-current="true"] .home-agenda-body{box-shadow:inset 3px 0 var(--t-accent)}
.home-agenda-gap{position:relative;display:grid;grid-template-columns:18px minmax(0,1fr);gap:var(--sp-2);min-width:0;padding:0 0 var(--sp-2)}
.home-agenda-gap-mark{z-index:1;width:9px;height:9px;margin:var(--sp-1) 0 0 1px;border:1px dashed var(--t-line-firm);border-radius:2px;background:var(--t-canvas)}
.home-agenda-gap-body{min-width:0;padding:0 0 var(--sp-2) var(--sp-1);border-left:1px dashed var(--t-line-firm)}
.home-agenda-gap-body time{display:block;font-size:var(--fs-micro);line-height:1.7;font-variant-numeric:tabular-nums;color:var(--t-text-soft)}
.home-agenda-gap-body strong{display:block;font-size:var(--fs-tiny);font-weight:600;line-height:1.55;color:var(--t-text-soft)}
.home-agenda-gap-body small{display:block;font-size:var(--fs-micro);line-height:1.55;color:var(--t-text-faint);overflow-wrap:anywhere}
.home-agenda-gap[data-current="true"] .home-agenda-gap-mark{border:2px solid var(--t-accent-ink);background:var(--t-accent-quiet)}
.home-agenda-gap[data-current="true"] .home-agenda-gap-body{padding-left:var(--sp-2);border-left:2px solid var(--t-accent)}
.home-agenda-gap[data-current="true"] .home-agenda-gap-body strong{color:var(--t-accent-ink)}
.home-side-warning{margin:var(--sp-2) 0 0;color:var(--t-warn-ink);font-size:var(--fs-micro);line-height:1.75;overflow-wrap:anywhere}
.home-state-board{
  position:relative;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--sp-1);width:100%;min-height:76px;
  padding:var(--sp-2);border:1px solid var(--t-line);border-radius:var(--r-xs);background:var(--t-surface);color:var(--t-text);
  text-align:left;cursor:pointer;transition:border-color var(--dur-fast),background-color var(--dur-fast),box-shadow var(--dur-fast)
}
.home-state-board:hover{border-color:var(--t-line-firm);background:var(--t-surface-raised);box-shadow:0 5px 14px color-mix(in srgb,var(--t-ok-ink) 7%,transparent)}
.home-state-board:focus-visible{outline:2px solid var(--t-accent);outline-offset:3px}
.home-state-point{position:relative;display:flex;min-width:0;min-height:70px;flex-direction:column;align-items:center;justify-content:center;gap:3px;border-radius:var(--r-xs);color:var(--t-text-soft)}
.home-state-glyph{display:grid;place-items:center;width:25px;height:25px;border-radius:50%;background:var(--t-surface-sunken);color:var(--t-accent-ink);transition:transform var(--dur-fast),background-color var(--dur-fast),color var(--dur-fast)}
.home-state-glyph svg{width:15px;height:15px;stroke-width:1.8}
.home-state-point[data-tone="ok"] .home-state-glyph{background:var(--t-ok-quiet);color:var(--t-ok-ink)}
.home-state-point[data-tone="warn"] .home-state-glyph{background:var(--t-warn-quiet);color:var(--t-warn-ink)}
.home-state-point[data-tone="risk"] .home-state-glyph{background:var(--t-risk-quiet);color:var(--t-risk-ink)}
.home-state-point[data-tone="rest"] .home-state-glyph{background:var(--t-accent-quiet);color:var(--t-accent-ink)}
.home-state-point[data-visual^="energy-"][data-tone="ok"] .home-state-glyph{background:linear-gradient(to top,var(--t-ok-quiet) var(--home-state-level),var(--t-surface-sunken) var(--home-state-level))}
.home-state-point[data-visual^="energy-"][data-tone="warn"] .home-state-glyph{background:linear-gradient(to top,var(--t-warn-quiet) var(--home-state-level),var(--t-surface-sunken) var(--home-state-level))}
.home-state-point[data-visual^="energy-"][data-tone="risk"] .home-state-glyph{background:linear-gradient(to top,var(--t-risk-quiet) var(--home-state-level),var(--t-surface-sunken) var(--home-state-level))}
.home-state-point[data-visual="unknown"] .home-state-glyph{border:1px dashed var(--t-line-firm);background:transparent}
.home-state-label{font-size:var(--fs-micro);line-height:1.25;color:var(--t-text-soft)}
.home-state-point>strong{max-width:100%;font-size:var(--fs-micro);font-weight:600;line-height:1.25;color:var(--t-text-strong);text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.home-state-point[data-tone="ok"]>strong{color:var(--t-ok-ink)}
.home-state-point[data-tone="warn"]>strong{color:var(--t-warn-ink)}
.home-state-point[data-tone="risk"]>strong{color:var(--t-risk-ink)}
.home-state-point[data-visual="unknown"]>strong{color:var(--t-text-faint);font-weight:500}
.home-state-tooltip{position:absolute;z-index:60;bottom:calc(100% + 7px);left:50%;display:grid;gap:3px;width:max-content;min-width:116px;max-width:205px;padding:var(--sp-2) var(--sp-2);transform:translateX(-50%);border:1px solid var(--t-line-firm);border-radius:var(--r-xs);background:var(--t-surface-raised);box-shadow:var(--t-shadow-lift);color:var(--t-text);text-align:left;white-space:normal;overflow-wrap:anywhere;opacity:0;visibility:hidden;pointer-events:none;transition:opacity var(--dur-fast),visibility var(--dur-fast)}
.home-state-point:nth-child(4n+1) .home-state-tooltip,.home-state-point:nth-child(4n+2) .home-state-tooltip{left:0;transform:none;max-width:min(205px,calc(300% + 8px))}
.home-state-point:nth-child(4n+3) .home-state-tooltip,.home-state-point:nth-child(4n) .home-state-tooltip{left:auto;right:0;transform:none;max-width:min(205px,calc(300% + 8px))}
.home-state-point:hover .home-state-tooltip{opacity:1;visibility:visible}
.home-state-tooltip b{font-size:var(--fs-micro);line-height:1.5}
.home-state-tooltip>span{font-size:var(--fs-micro);line-height:1.55;color:var(--t-text-soft)}
.home-state-empty{grid-column:1/-1;align-self:center;padding:0 var(--sp-1);font-size:var(--fs-tiny);color:var(--t-text-soft)}
.home-state-open{position:absolute;right:6px;top:6px;display:grid;place-items:center;width:14px;height:14px;color:var(--t-text-faint);opacity:.48;transition:opacity var(--dur-fast),transform var(--dur-fast)}
.home-state-open svg{width:13px;height:13px}
.home-state-board:hover .home-state-open,.home-state-board:focus-visible .home-state-open{opacity:1}
@media(prefers-reduced-motion:reduce){.home-state-board,.home-state-glyph,.home-state-tooltip,.home-state-open{transition:none}}
@media(min-width:761px) and (max-width:1120px){
  .shell-side{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-6);align-items:start}
  .shell-side>.home-band:not(.home-side-band){grid-column:1/-1}
  .home-side-band{padding-top:0;border-top:0}
}
@media(max-width:760px){
  .home-side-action{min-height:44px}
  /* 手机上不再把今日安排套进第二个滚动容器。原来的 420px 内层滚动区
     会截住页面的连续下滑手势，用户要在一张小卡片里再滑一次才能看完；
     日程直接跟随页面滚动，内容只多出被折叠的那一小段。 */
  .shell-side .home-agenda-scroll{max-height:none;overflow:visible;overscroll-behavior:auto}
}

/* === 今日安排 · 节目单 ===
 * 日程内容优先：标题和说明是主体，时间退到边注。
 * 这一组规则覆盖旧时间轴的行布局，但保留原 .home-agenda-* 语义供状态逻辑使用。 */
.home-side-band .home-band-head h2{letter-spacing:.06em}
.home-agenda-program-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:0 0 var(--sp-2);color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.5;letter-spacing:.02em}
.home-agenda-program-meta span:first-child{color:var(--t-accent-ink);font-weight:600}
.home-agenda-current{margin:0 0 var(--sp-1);color:var(--t-text-soft);font-size:var(--fs-micro);line-height:1.55}
.home-agenda-current.is-visually-hidden{position:absolute;width:1px;height:1px;margin:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.home-agenda-current-gap{display:flex;align-items:baseline;gap:var(--sp-1);flex-wrap:wrap;margin:0 0 var(--sp-2);color:var(--t-text-soft);font-size:var(--fs-micro);line-height:1.55}
.home-agenda-current-gap time{color:var(--t-accent-ink);font-weight:600;font-variant-numeric:tabular-nums}
.home-agenda-current-gap strong{color:var(--t-accent-ink);font-weight:600}
.home-agenda-overview{display:flex;align-items:center;gap:var(--sp-3);flex-wrap:wrap;margin:0 0 var(--sp-3);padding:0 0 var(--sp-2);border-bottom:1px solid var(--t-line);color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.5}
.home-agenda-overview-count{white-space:nowrap}
.home-agenda-overview-count b{color:var(--t-text);font-weight:600;font-variant-numeric:tabular-nums}
.home-agenda-overview-current{margin-left:auto;color:var(--t-accent-ink);font-weight:600;white-space:nowrap}
.home-agenda-overview-unknown{display:none}
.home-agenda-overview-note{flex:1 0 100%;margin:0;color:var(--t-warn-ink);font-size:var(--fs-micro);line-height:1.55}
.home-agenda-program-head{display:flex;align-items:baseline;justify-content:space-between;gap:var(--sp-2);margin:0 0 var(--sp-2);padding:0 0 var(--sp-1);border-bottom:1px solid var(--t-line)}
.home-agenda-program-head h3{margin:0;color:var(--t-text-strong);font-family:var(--skin-heading-font);font-size:var(--fs-tiny);font-weight:600;letter-spacing:.08em}
.home-agenda-program-head>span{color:var(--t-text-faint);font-size:var(--fs-micro);font-variant-numeric:tabular-nums}
.home-agenda-program-past{margin-top:var(--sp-3)}
.home-agenda-scroll{max-height:430px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--t-line-firm) transparent}
.home-agenda{counter-reset:agenda-act}
.home-agenda-item{position:relative;display:grid;grid-template-columns:25px minmax(0,1fr);column-gap:10px;align-items:start;padding:0 0 var(--sp-3);border-bottom:1px dotted var(--t-line)}
.home-agenda-item:last-child{border-bottom:0;padding-bottom:0}
.home-agenda .home-agenda-item::before{content:counter(agenda-act,decimal-leading-zero);counter-increment:agenda-act;position:static !important;grid-column:1;grid-row:1;background:transparent !important;width:auto !important;height:auto !important;top:auto !important;bottom:auto !important;left:auto !important;right:auto !important;border:0 !important;color:var(--t-text-soft);font-family:var(--skin-heading-font);font-size:16px;line-height:1.25;font-variant-numeric:tabular-nums}
.home-agenda-item[data-tone="active"]::before,.home-agenda-item[data-tone="current"]::before{color:var(--t-accent);font-size:18px;font-weight:600}
.home-agenda-dot{display:none}
.home-agenda-body{display:grid;grid-column:2;grid-row:1;grid-template-columns:88px minmax(0,1fr);column-gap:10px;min-width:0;padding:0;border:0;background:none;box-shadow:none}
.home-agenda-body time{grid-column:1;grid-row:1;display:block;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.7;font-variant-numeric:tabular-nums;white-space:nowrap}
.home-agenda-body strong{grid-column:2;grid-row:1;display:block;margin:0;color:var(--t-text);font-family:var(--skin-heading-font);font-size:var(--fs-body);font-weight:600;line-height:1.4;letter-spacing:.02em;overflow-wrap:anywhere}
.home-agenda-body small{grid-column:2;display:block;margin:2px 0 0;color:var(--t-text-soft);font-size:var(--fs-micro);line-height:1.55;overflow-wrap:anywhere}
.home-agenda-body .home-agenda-detail{grid-column:2;margin-top:3px;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.65;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]){padding:12px 12px 12px 11px;margin:0 0 var(--sp-3);border:1px solid rgba(74,124,80,.18);border-left:3px solid var(--t-accent);border-radius:var(--r-xs);background:linear-gradient(100deg,var(--t-accent-quiet),color-mix(in srgb,var(--t-accent-quiet) 40%,var(--t-surface)))}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body{grid-template-columns:88px minmax(0,1fr);padding:0;border:0;border-radius:0;background:none;box-shadow:none}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body strong{font-size:20px;line-height:1.28;color:var(--t-accent-ink)}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body time{color:var(--t-accent-ink);font-weight:600}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body small{color:var(--t-text-soft)}
.home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-detail{-webkit-line-clamp:unset;color:var(--t-text-soft)}
.home-agenda-item[data-current="true"]{box-shadow:none}
.home-agenda-item[data-current="true"] .home-agenda-body{box-shadow:none !important}
.home-agenda-gap{display:grid;grid-template-columns:25px minmax(0,1fr);column-gap:10px;padding:0 0 var(--sp-2);border-bottom:1px dotted var(--t-line)}
.home-agenda-gap-mark{display:none}
.home-agenda-gap-body{grid-column:2;display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;padding:0;border:0}
.home-agenda-gap-body time{color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.65;font-variant-numeric:tabular-nums;white-space:nowrap}
.home-agenda-gap-body strong{color:var(--t-text-soft);font-size:var(--fs-tiny);font-weight:500;line-height:1.5}
.home-agenda-gap-body small{flex:1 0 100%;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.5}
.home-agenda-gap[data-current="true"]{padding:9px 10px;margin:0 0 var(--sp-3);border:1px dashed var(--t-line-firm);border-radius:var(--r-xs);background:color-mix(in srgb,var(--t-surface-soft) 65%,transparent)}
.home-agenda-gap[data-current="true"] .home-agenda-gap-body strong{color:var(--t-accent-ink)}
.home-agenda-more>summary{color:var(--t-accent-ink);font-size:var(--fs-micro)}
.home-agenda-more>ol{margin-top:var(--sp-2)}


/* 桌面右栏只有约 270px 宽：把时间收到标题上方，避免 88px 时间列把标题挤成竖排。 */
@media(min-width:761px){
  .home-agenda-item{grid-template-columns:20px minmax(0,1fr);column-gap:8px}
  .home-agenda .home-agenda-item::before{font-size:13px;line-height:1.3}
  .home-agenda-item[data-tone="active"]::before,.home-agenda-item[data-tone="current"]::before{font-size:15px}
  .home-agenda-body{display:block;padding:0}
  .home-agenda-body time{display:block;white-space:normal;line-height:1.55;font-size:var(--fs-micro)}
  .home-agenda-body strong{margin-top:2px;font-size:var(--fs-tiny);line-height:1.4}
  .home-agenda-item:is([data-tone="active"],[data-tone="current"]) .home-agenda-body strong{font-size:17px}
  .home-agenda-body small{margin-top:2px}
  .home-agenda-body .home-agenda-detail{-webkit-line-clamp:3}
  .home-agenda-gap{grid-template-columns:20px minmax(0,1fr);column-gap:8px}
  .home-agenda-gap-body{display:block}
  .home-agenda-gap-body time{display:block;white-space:normal}
  .home-agenda-gap-body small{margin-top:2px}
  .home-agenda-program-meta{flex-wrap:wrap;gap:2px 8px}
  .home-agenda-program-meta span:last-child{color:var(--t-text-faint)}
  .home-agenda-program-head h3{font-size:var(--fs-tiny)}
  .home-agenda-program-head>span{font-size:var(--fs-micro)}
  .home-agenda-item:is([data-tone="active"],[data-tone="current"]){padding:10px}
}

/* models-page.css */
#modelWorkspace{padding:var(--pad-lg,var(--sp-5))}
/* ===== 模型与连接 · 设计令牌（对齐 MODEL_CONFIG_UI_UX_DESIGN_20260926） ===== */
.model-workspace,.perception-scope{
  --m-card:var(--t-surface); --m-card2:var(--t-surface-soft);
  --m-ink:var(--t-text); --m-ink2:var(--t-text-soft); --m-ink3:var(--t-text-faint);
  --m-line:var(--t-line); --m-line2:var(--t-line-firm);
  --m-sel:var(--t-accent-quiet); --m-sel2:var(--t-surface-sunken);
  --m-accent:var(--t-accent-ink); --m-accent2:var(--t-accent-solid); --m-accent3:var(--t-accent);
  --m-green:var(--t-ok-ink); --m-green-bg:var(--t-ok-quiet);
  --m-amber:var(--t-warn-ink); --m-amber-bg:var(--t-warn-quiet);
  --m-red:var(--t-risk-ink);  --m-red-bg:var(--t-risk-quiet);
  --m-r:var(--r-md); --m-rs:var(--r-sm);
  --m-shadow:var(--t-shadow);
  min-width:0;color:var(--m-ink);display:grid;gap:var(--sp-3);font-size:var(--fs-body);line-height:1.6}
.model-workspace .model-hint{margin:var(--sp-2) 2px 0;font-size:var(--fs-tiny);color:var(--m-amber)}
.model-workspace .model-mono{font-family:ui-monospace,Consolas,monospace;font-size:var(--fs-tiny);color:var(--m-ink2);overflow-wrap:anywhere}
.model-workspace .model-grow{flex:1}
/* ---- 顶栏 / 主页签 / 二级页签 ---- */
.model-topbar{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.model-topbar-t{font-size:var(--fs-body);color:var(--m-ink3)}
.model-tabs{display:flex;gap:var(--sp-1);background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);padding:var(--sp-1);box-shadow:var(--m-shadow)}
.model-tabs button{flex:1;display:flex;align-items:center;justify-content:center;gap:var(--sp-2);border:0;background:transparent;border-radius:var(--m-rs);padding:var(--sp-2) var(--sp-2);font-size:var(--fs-lead);color:var(--m-ink2);cursor:pointer;transition:.15s}
.model-tabs button:hover{background:var(--m-card2);color:var(--m-ink)}
.model-tabs button.on{background:var(--m-sel);color:var(--m-accent);font-weight:600}
.model-tabs .ic{width:16px;height:16px;flex:none;opacity:.85}
.model-tabs .c{font-size:var(--fs-tiny);color:var(--m-ink3);background:var(--m-card2);border-radius:var(--r-pill);padding:0 var(--sp-2);margin-left:2px}
.model-tabs button.on .c{background:var(--m-sel2);color:var(--m-accent)}
.model-subtabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--sp-2);border:0;margin:var(--sp-2) 0 var(--sp-3);padding:0}
.model-subtabs button{display:grid;grid-template-columns:34px minmax(0,1fr);align-items:center;gap:10px;min-width:0;padding:10px 12px;border:1px solid var(--m-line);border-radius:var(--r-md);background:var(--m-card);color:var(--m-ink2);font:inherit;text-align:left;cursor:pointer;transition:background-color .16s ease,border-color .16s ease,box-shadow .16s ease}
.model-subtabs button:hover{border-color:color-mix(in srgb,var(--m-accent) 38%,var(--m-line));background:color-mix(in srgb,var(--m-accent) 5%,var(--m-card))}
.model-subtabs button.on{border-color:color-mix(in srgb,var(--m-accent) 58%,var(--m-line));background:linear-gradient(135deg,color-mix(in srgb,var(--m-accent) 10%,var(--m-card)),var(--m-card));color:var(--m-ink);box-shadow:inset 3px 0 0 var(--m-accent),var(--m-shadow)}
.model-subtab-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:color-mix(in srgb,var(--m-accent) 10%,var(--m-card2));color:var(--m-accent)}
.model-subtab-icon svg{width:17px;height:17px}
.model-subtab-copy{display:grid;gap:2px;min-width:0}
.model-subtab-copy b{color:var(--m-ink);font-size:var(--fs-tiny);font-weight:650;line-height:1.25}
.model-subtab-copy small{overflow:hidden;color:var(--m-ink3);font-size:var(--fs-micro);font-weight:400;line-height:1.35;text-overflow:ellipsis;white-space:nowrap}
.model-subtabs button.on .model-subtab-icon{background:var(--m-accent);color:var(--t-on-solid)}
@media(max-width:760px){.model-subtabs{grid-template-columns:minmax(0,1fr)}.model-subtab-copy small{white-space:normal}}
.model-subpane{display:grid;gap:var(--sp-3);min-width:0}
/* ---- 通用件 ---- */
.model-workspace .model-seg{display:inline-flex;background:var(--m-card2);border:1px solid var(--m-line);border-radius:var(--r-sm);padding:3px;gap:2px}
.model-workspace .model-seg button{border:0;background:transparent;border-radius:var(--r-xs);padding:var(--sp-1) var(--sp-3);font-size:var(--fs-body);color:var(--m-ink2);cursor:pointer}
.model-workspace .model-seg button.on{background:var(--m-card);color:var(--m-accent);font-weight:600;box-shadow:var(--t-shadow)}
.model-filters{display:inline-flex;background:var(--m-card2);border:1px solid var(--m-line);border-radius:var(--r-sm);padding:3px;gap:2px;flex-wrap:wrap}
.model-filters button{border:0;background:transparent;border-radius:var(--r-xs);padding:var(--sp-1) var(--sp-3);font-size:var(--fs-body);color:var(--m-ink2);cursor:pointer}
.model-filters button.active{background:var(--m-card);color:var(--m-accent);font-weight:600;box-shadow:var(--t-shadow)}
.model-pill{display:inline-flex;align-items:center;gap:var(--sp-1);border:1px solid var(--m-line2);background:var(--m-card);border-radius:var(--r-pill);padding:2px var(--sp-2);font-size:var(--fs-tiny);white-space:nowrap;color:var(--m-ink2)}
.model-pill.ok{border-color:transparent;background:var(--m-green-bg);color:var(--m-green)}
.model-pill.warn{border-color:transparent;background:var(--m-amber-bg);color:var(--m-amber)}
.model-pill.m{--mc:var(--m-accent2);border-color:color-mix(in srgb,var(--mc) 34%,transparent);background:color-mix(in srgb,var(--mc) 11%,var(--m-card));color:var(--mc);cursor:pointer;transition:.14s;max-width:100%;min-width:0;overflow:hidden}
.model-pill.m::before,.model-pill.m i{content:"";width:6px;height:6px;border-radius:50%;background:var(--mc);flex:none}
.model-pill.m:hover{background:var(--mc);color:var(--t-on-solid);box-shadow:0 0 0 3px color-mix(in srgb,var(--mc) 22%,transparent)}
.model-pill.m.is-hovered{border-color:var(--mc);background:color-mix(in srgb,var(--mc) 20%,var(--m-card));color:var(--m-ink);box-shadow:0 0 0 3px color-mix(in srgb,var(--mc) 22%,transparent)}
.model-pill.m.none{background:transparent;border:1px dashed var(--m-line2);color:var(--m-amber);cursor:default}
.model-pill.m.none::before,.model-pill.m.none i{display:none}
.model-tag{display:inline-flex;align-items:center;border-radius:var(--r-xs);padding:1px var(--sp-2);font-size:var(--fs-micro);background:var(--m-sel);color:var(--m-accent);white-space:nowrap}
.model-tag.g{background:var(--m-green-bg);color:var(--m-green)}
.model-tag.a{background:var(--m-amber-bg);color:var(--m-amber)}
.model-tag.r{background:var(--m-red-bg);color:var(--m-red)}
.model-tag.n{background:var(--m-card2);color:var(--m-ink3)}
.model-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:var(--sp-2)}
.model-kpi{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-3);box-shadow:var(--m-shadow)}
.model-kpi b{display:block;font-size:var(--fs-head);line-height:1.3;font-weight:600;overflow-wrap:anywhere}
.model-kpi span{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-kpi.g b{color:var(--m-green)} .model-kpi.a b{color:var(--m-amber)} .model-kpi.r b{color:var(--m-red)}
.model-overview{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:var(--sp-2)}
.model-overview>div{display:flex;align-items:baseline;gap:var(--sp-2);background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-3);box-shadow:var(--m-shadow);min-width:0}
.model-overview strong{font-size:var(--fs-head);font-weight:600;color:var(--m-accent);overflow-wrap:anywhere}
.model-overview span{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-note{display:flex;align-items:center;gap:var(--sp-2);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-body);border:1px solid var(--m-line);background:var(--m-card2);color:var(--m-ink2);flex-wrap:wrap}
.model-note.cfg{justify-content:space-between}
.model-notice{min-height:38px;display:flex;align-items:center;padding:var(--sp-2) var(--sp-3);border:1px solid var(--m-line);background:var(--m-card2);border-radius:var(--r-sm);color:var(--m-ink2);font-size:var(--fs-body);line-height:1.55;overflow-wrap:anywhere}
.model-notice.error{background:var(--m-red-bg);border-color:transparent;color:var(--m-red)}
.model-alert{border:1px solid transparent;background:var(--m-amber-bg);color:var(--m-amber);border-radius:var(--r-sm);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-tiny);line-height:1.6}
.model-laya-cmd{display:block;margin-top:var(--sp-2);padding:var(--sp-2);border-radius:var(--r-xs);background:var(--m-card);white-space:pre-wrap;overflow-wrap:anywhere;font-size:var(--fs-micro)}
.model-alert small{display:block;margin-top:var(--sp-1);color:var(--m-ink3)}
.model-card{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);box-shadow:var(--m-shadow);padding:var(--sp-4) var(--sp-4);display:grid;gap:var(--sp-3)}
.model-phead{display:flex;align-items:flex-start;gap:var(--sp-3);flex-wrap:wrap}
.model-phead .model-grow{flex:1;min-width:0}
.model-phead h3{margin:var(--sp-1) 0 0;font-size:var(--fs-lead);font-weight:600}
.model-phead .model-st2{display:flex;align-items:center;gap:var(--sp-2);flex:none;flex-wrap:wrap}
.model-eb{display:flex;align-items:center;font-size:var(--fs-micro);color:var(--m-ink3);letter-spacing:.05em}
.model-eb .st{margin-left:auto;letter-spacing:0}
.model-editor-actions{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.model-laya-pane{grid-template-columns:repeat(auto-fit,minmax(min(440px,100%),1fr));align-items:start}
.model-laya-pane>.model-card:first-child{grid-column:1/-1}
.model-laya-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(280px,100%),1fr));gap:var(--sp-3)}
.model-laya-result{display:grid;gap:var(--sp-2);border:1px solid var(--m-line);background:var(--m-card2);border-radius:var(--r-sm);padding:var(--sp-3);min-width:0}
.model-laya-result b{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-laya-result code{white-space:pre-wrap;overflow-wrap:anywhere;font:var(--fs-tiny)/1.55 ui-monospace,Consolas,monospace;color:var(--m-ink)}
.model-laya-install{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:var(--sp-2);min-width:0}
.model-laya-install code,.model-laya-pane .model-state code{font:var(--fs-tiny)/1.5 ui-monospace,Consolas,monospace;overflow-wrap:anywhere;white-space:normal}
.model-laya-install code{padding:var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-sm);background:var(--m-card2);color:var(--m-ink)}
.model-laya-pane .model-state{white-space:normal;line-height:1.6;overflow-wrap:anywhere;margin-top:var(--sp-2)}
.model-laya-pane .model-state a{color:var(--m-accent3)}
.model-laya-decisions{display:grid;gap:var(--sp-2);margin-top:var(--sp-3);padding-top:var(--sp-3);border-top:1px solid var(--m-line)}
.model-laya-decisions>div:first-child{display:grid;gap:2px}
.model-laya-decisions>div:first-child strong{font-size:var(--fs-body);font-weight:600;color:var(--m-ink)}
.model-laya-decisions>div:first-child span{font-size:var(--fs-micro);line-height:1.5;color:var(--m-ink3)}
.model-laya-decision-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(260px,100%),1fr));gap:1px;background:var(--m-line);border:1px solid var(--m-line)}
.model-laya-option{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);min-width:0;min-height:62px;padding:var(--sp-2) var(--sp-3);background:var(--m-card)}
.model-laya-option>span:first-child{display:grid;gap:2px;min-width:0}
.model-laya-option strong{font-size:var(--fs-tiny);font-weight:600;color:var(--m-ink);overflow-wrap:anywhere}
.model-laya-option small{font-size:var(--fs-micro);line-height:1.45;color:var(--m-ink3);overflow-wrap:anywhere}
.model-laya-option:focus-within{outline:2px solid var(--m-accent3);outline-offset:-2px}
.model-laya-history{display:grid;gap:0;max-height:520px;overflow:auto;margin:0;padding:0;list-style:none}
.model-laya-history>li{border-top:1px solid var(--m-line)}
.model-laya-history details>summary{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);min-height:54px;cursor:pointer;list-style:none}
.model-laya-history details>summary::-webkit-details-marker{display:none}
.model-laya-history details>summary>span{display:grid;gap:2px;min-width:0}
.model-laya-history details>summary strong{font-size:var(--fs-tiny);color:var(--m-ink)}
.model-laya-history details>summary small,.model-laya-history details>div>small{font-size:var(--fs-micro);color:var(--m-ink3);overflow-wrap:anywhere}
.model-laya-history details>summary>b{flex:none;font:600 var(--fs-micro)/1 var(--numeric-font);color:var(--m-ink2)}
.model-laya-history details>div{display:grid;gap:var(--sp-1);padding:0 0 var(--sp-3)}
.model-laya-history code{max-height:220px;overflow:auto;padding:var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2);font:var(--fs-micro)/1.5 ui-monospace,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--m-ink)}
.model-laya-diagnostics{display:grid;gap:var(--sp-2);min-width:0}
.model-laya-history>li[data-state="failed"] details>summary strong{color:var(--m-red)}
.model-laya-history>li[data-state="skipped"] details>summary strong{color:var(--m-ink3)}
.model-laya-history-empty{margin:0;padding:var(--sp-3) 0;color:var(--m-ink3);font-size:var(--fs-tiny)}
/* ---- 表单 ---- */
.model-workspace .model-fd{display:flex;flex-direction:column;gap:var(--sp-1);min-width:0}
.model-workspace .model-cap{font-size:var(--fs-tiny);color:var(--m-ink3);display:flex;align-items:baseline;gap:var(--sp-1);flex-wrap:wrap}
.model-workspace .model-cap em{font-style:normal;font-size:var(--fs-micro);opacity:.82}
.model-workspace select,.model-workspace input,.model-workspace textarea{border:1px solid var(--m-line2);background:var(--m-card);border-radius:var(--r-sm);padding:var(--sp-1) var(--sp-2);font-size:var(--fs-body);outline:none;min-width:0;color:var(--m-ink)}
.model-workspace select:focus,.model-workspace input:focus,.model-workspace textarea:focus{border-color:var(--m-accent3)}
.model-workspace textarea{resize:vertical;line-height:1.6}
.model-duo{display:grid;grid-template-columns:1fr 1fr;gap:var(--sp-2)}
.model-unit{display:flex;border:1px solid var(--m-line2);border-radius:var(--r-sm);overflow:hidden;background:var(--m-card)}
.model-unit:focus-within{border-color:var(--m-accent2)}
.model-unit input{flex:1;min-width:0;border:0;border-radius:0;background:transparent;padding:var(--sp-1) var(--sp-2)}
.model-unit i{font-style:normal;display:flex;align-items:center;padding:0 var(--sp-2);font-size:var(--fs-tiny);color:var(--m-ink3);background:var(--m-card2);border-left:1px solid var(--m-line2);white-space:nowrap}
.model-msel{display:flex;align-items:center;gap:var(--sp-2);min-width:0}
.model-msel i{width:7px;height:7px;border-radius:50%;flex:none;background:var(--m-line2);transition:background .2s}
.model-msel select{flex:1;min-width:0}
.model-cur{border:1px solid var(--m-line);background:var(--m-card2);border-radius:var(--r-sm);padding:var(--sp-2) var(--sp-3);font-family:ui-monospace,Consolas,monospace;font-size:var(--fs-tiny);color:var(--m-ink);word-break:break-all}
.model-cur.miss{font-family:inherit;color:var(--m-amber);background:var(--m-amber-bg);border-color:transparent}
.model-inh{display:flex;align-items:center;gap:var(--sp-3);flex-wrap:wrap;border-top:1px dashed var(--m-line2);padding-top:var(--sp-3)}
.model-inh .lab{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-inh label{display:flex;gap:var(--sp-1);align-items:center;font-size:var(--fs-body);color:var(--m-ink2);cursor:pointer}
.model-switch{position:relative;width:34px;height:19px;flex:none;display:inline-block;vertical-align:middle}
.model-switch input{opacity:0;width:0;height:0;position:absolute}
.model-switch i{position:absolute;inset:0;background:var(--m-line2);border-radius:var(--r-pill);transition:.18s;cursor:pointer}
.model-switch i::after{content:"";position:absolute;width:14px;height:14px;border-radius:50%;background:var(--t-surface-raised);top:2.5px;left:3px;transition:transform .18s}
.model-switch input:checked+i{background:var(--m-green)}
.model-switch input:checked+i::after{transform:translateX(14px)}
.model-source{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-state{font-size:var(--fs-tiny);color:var(--m-ink3);white-space:nowrap}
.model-state.warn{color:var(--m-amber)}
/* ---- 态势图 ---- */
.model-mlgd.legend{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-mlgd.legend span{display:inline-flex;align-items:center;gap:var(--sp-1)}
.model-mlgd.legend i{width:7px;height:7px;border-radius:50%;display:inline-block}
.model-mlgd.legend em{font-style:normal;color:var(--m-ink2)}
.model-rgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(392px,100%),1fr));gap:var(--sp-3)}
.model-grp{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);box-shadow:var(--m-shadow);overflow:hidden}
.model-grp>header{display:flex;align-items:center;gap:var(--sp-2);padding:var(--sp-2) var(--sp-4);border-bottom:1px solid var(--m-line)}
.model-grp>header .ic{width:16px;height:16px;color:var(--m-accent2);flex:none}
.model-grp>header b{font-size:var(--fs-body);font-weight:600;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.model-grp>header .cnt{margin-left:auto;font-size:var(--fs-tiny);color:var(--m-ink3);white-space:nowrap;flex:none}
.model-grp .model-gck{width:14px;height:14px;accent-color:var(--m-accent2);cursor:pointer;flex:none}
.model-item{display:flex;gap:var(--sp-2);padding:var(--sp-2) var(--sp-4);border-bottom:1px solid var(--m-line);cursor:pointer;align-items:flex-start}
.model-item:last-child{border-bottom:0}
.model-item:hover{background:var(--m-card2)}
.model-item.seled{background:var(--m-sel)}
.model-item.seled:hover{background:var(--m-sel2)}
.model-item-sel{flex:none;padding-top:2px}
.model-item-sel input{width:14px;height:14px;accent-color:var(--m-accent2);cursor:pointer;display:block}
.model-item-nm{flex:0 1 118px;min-width:0}
.model-item-nm b{display:block;font-size:var(--fs-body);font-weight:500}
.model-item-nm small{font-size:var(--fs-micro);color:var(--m-ink3)}
.model-map-open{border:0;background:transparent;padding:0;text-align:left;cursor:pointer;font:inherit;color:inherit;min-width:0}
.model-map-open:hover b{color:var(--m-accent)}
.model-item-ch{flex:1;min-width:0;display:flex;flex-direction:column;gap:var(--sp-1)}
.model-ln{display:grid;grid-template-columns:50px minmax(0,1fr);align-items:center;gap:var(--sp-2)}
.model-ln i{font-style:normal;font-size:var(--fs-micro);color:var(--m-ink3);white-space:nowrap}
.model-ps{display:flex;align-items:center;gap:var(--sp-1);flex-wrap:wrap;min-width:0}
/* ---- 批量测试停靠栏 ---- */
.model-dock{position:sticky;bottom:12px;z-index:20;display:flex;flex-direction:column;gap:var(--sp-2);pointer-events:none}
.model-dock>*{pointer-events:auto}
.model-selbar{display:flex;align-items:center;gap:var(--sp-3);flex-wrap:wrap;background:var(--m-card);border:1px solid var(--m-sel2);border-radius:var(--m-r);box-shadow:var(--t-shadow-lift);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-body);color:var(--m-ink2)}
.model-selbar b{color:var(--m-accent);font-weight:600}
.model-bar{width:132px;height:5px;border-radius:var(--r-2xs);background:var(--m-line2);overflow:hidden;flex:none}
.model-bar i{display:block;height:100%;border-radius:var(--r-2xs);background:var(--m-accent2);transition:width .32s ease}
.model-bar.full i{background:var(--m-green)}
.model-tres{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);box-shadow:var(--t-shadow-lift);overflow:hidden}
.model-tres .th{display:flex;align-items:center;gap:var(--sp-2);padding:var(--sp-2) var(--sp-3);border-bottom:1px solid var(--m-line);font-size:var(--fs-body)}
.model-tres .th .s{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-tres .tbody{max-height:238px;overflow:auto}
.model-trow{display:flex;align-items:center;gap:var(--sp-2);padding:var(--sp-2) var(--sp-3);border-bottom:1px solid var(--m-line);font-size:var(--fs-body)}
.model-trow:last-child{border-bottom:0}
.model-trow .dotm{width:7px;height:7px;border-radius:50%;flex:none;background:var(--m-line2)}
.model-trow .mno{font-family:ui-monospace,Consolas,monospace;font-size:var(--fs-tiny);flex:none}
.model-trow .u{font-size:var(--fs-tiny);color:var(--m-ink3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;min-width:0}
.model-trow .tr{margin-left:auto;display:flex;align-items:center;gap:var(--sp-1);font-size:var(--fs-tiny);color:var(--m-ink3);white-space:nowrap;flex:none}
.model-trow.ok .tr{color:var(--m-green)}
.model-trow.bad .tr{color:var(--m-red)}
.model-trow.run .tr{color:var(--m-ink3)}
.model-sp{width:12px;height:12px;border-radius:50%;border:2px solid var(--m-line2);border-top-color:var(--m-accent2);animation:modelspin .7s linear infinite;display:inline-block}
@keyframes modelspin{to{transform:rotate(360deg)}}
/* ---- 卡片（快速配置 / 精准配置） ---- */
.model-qgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(438px,100%),1fr));gap:var(--sp-3)}
.model-sc,.model-fncard{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);box-shadow:var(--m-shadow);display:flex;flex-direction:column;overflow:hidden;min-width:0}
.model-fncard.open{border-color:var(--m-accent3);box-shadow:0 0 0 2px var(--m-sel2),var(--m-shadow);scroll-margin-top:var(--sp-3)}
.model-fncard.dirty .model-ti b::after{content:"";display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--m-amber);margin-left:var(--sp-1);vertical-align:middle}
.model-fncard.picked{background:color-mix(in srgb,var(--m-sel) 40%,var(--m-card))}
.model-sc-tp{padding:var(--sp-3) var(--sp-4) var(--sp-3)}
.model-ti{display:flex;align-items:center;gap:var(--sp-2);margin-top:var(--sp-2);flex-wrap:wrap}
.model-ti .ic{width:17px;height:17px;color:var(--m-accent2);flex:none}
.model-ti b{font-size:var(--fs-title);font-weight:600}
.model-pick{margin-left:auto;display:inline-flex;align-items:center}
.model-pick input{width:14px;height:14px;accent-color:var(--m-accent2);cursor:pointer}
.model-ds{font-size:var(--fs-tiny);color:var(--m-ink2);margin-top:var(--sp-2);line-height:1.68}
.model-rl{display:flex;gap:var(--sp-1);flex-wrap:wrap;margin-top:var(--sp-2)}
.model-rl span{border-radius:var(--r-xs);padding:2px var(--sp-2);font-size:var(--fs-micro);background:var(--m-sel);color:var(--m-accent2)}
.model-sc-bd{padding:var(--sp-3) var(--sp-4) var(--sp-3);display:flex;flex-direction:column;gap:var(--sp-3);border-top:1px solid var(--m-line)}
.model-fd.dash{border-top:1px dashed var(--m-line2);padding-top:var(--sp-3)}
.model-sc-rf{border-top:1px solid var(--m-line);background:var(--m-card2);padding:var(--sp-3) var(--sp-4);display:flex;flex-direction:column;gap:var(--sp-2)}
.model-sc-rf .r{display:grid;grid-template-columns:34px 1fr;gap:var(--sp-2);font-size:var(--fs-tiny);line-height:1.62;align-items:baseline}
.model-sc-rf .r b{font-weight:500;color:var(--m-ink3)}
.model-sc-rf .r span{color:var(--m-ink2);min-width:0;overflow-wrap:anywhere}
.model-sc-ft{display:flex;align-items:center;gap:var(--sp-2);padding:var(--sp-3) var(--sp-4);border-top:1px solid var(--m-line);flex-wrap:wrap}
.model-sc-ft code{font-family:ui-monospace,Consolas,monospace;font-size:var(--fs-micro);color:var(--m-ink3);letter-spacing:.02em;overflow-wrap:anywhere}
.model-res{display:flex;align-items:center;gap:var(--sp-1);font-size:var(--fs-tiny);white-space:nowrap;color:var(--m-ink3)}
.model-resk{width:18px;height:18px;border-radius:50%;display:grid;place-items:center;flex:none;font-size:var(--fs-micro)}
.model-resk.ok{background:var(--m-green-bg);color:var(--m-green)}
.model-resk.bad{background:var(--m-red-bg);color:var(--m-red)}
.model-lk{border:0;background:transparent;color:var(--m-accent);font-size:var(--fs-tiny);cursor:pointer;padding:2px 0;white-space:nowrap}
.model-exp ul{list-style:none;margin:0;padding:var(--sp-2) var(--sp-4) var(--sp-3);border-top:1px solid var(--m-line);background:var(--m-card2);display:grid;gap:var(--sp-1);font-size:var(--fs-tiny);color:var(--m-ink2)}
.model-exp li{display:flex;justify-content:space-between;gap:var(--sp-2)}
.model-exp li span{color:var(--m-ink3)}
/* ---- 工具条 / 队列 / 选择 ---- */
.model-toolbar{display:flex;align-items:flex-end;gap:var(--sp-3);flex-wrap:wrap}
.model-search{display:grid;gap:var(--sp-1);flex:1 1 220px;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-search input{height:36px;width:100%;border:1px solid var(--m-line2);border-radius:var(--r-sm);background:var(--m-card);color:var(--m-ink);padding:var(--sp-1) var(--sp-2);font-size:var(--fs-body)}
.model-provider-filter{display:grid;gap:var(--sp-1);flex:0 1 220px;min-width:160px;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-provider-filter select{height:36px;width:100%;min-width:0;max-width:260px;border:1px solid var(--m-line2);border-radius:var(--r-sm);background:var(--m-card);color:var(--m-ink);padding:var(--sp-1) var(--sp-2);font-size:var(--fs-body)}
.model-selection{display:flex;align-items:center;gap:var(--sp-3);flex-wrap:wrap;background:var(--m-card);border:1px solid var(--m-sel2);border-radius:var(--r-md);box-shadow:var(--m-shadow);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-body);color:var(--m-ink2)}
.model-selection strong{color:var(--m-accent)}
.model-selection select{height:32px;padding:var(--sp-1) var(--sp-2)}
.model-queue{display:flex;align-items:center;gap:var(--sp-2);background:var(--m-amber-bg);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-body);color:var(--m-amber);margin-bottom:var(--sp-3);flex-wrap:wrap}
.model-queue.busy{opacity:.7}
/* ---- 替换策略 ---- */
.model-polbar{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.model-polbar .model-cap{font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-pol-card{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);box-shadow:var(--m-shadow);padding:var(--sp-4) var(--sp-4);display:grid;gap:var(--sp-3)}
.model-pol-body{display:flex;flex-direction:column;gap:var(--sp-3);border-top:1px dashed var(--m-line2);padding-top:var(--sp-3)}
.model-pol-actions{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.model-kw{list-style:none;background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-3);display:grid;gap:var(--sp-2)}
.model-kw.off{opacity:.55}
.model-kwh{display:flex;align-items:center;gap:var(--sp-2)}
.model-kwh .model-ix{font-size:var(--fs-micro);color:var(--m-ink3);font-family:ui-monospace,Consolas,monospace;flex:none}
.model-kn{flex:1;min-width:110px;border:1px solid transparent;background:transparent;border-radius:var(--r-sm);padding:var(--sp-1) var(--sp-2);font-size:var(--fs-body);font-weight:600}
.model-kn:hover{border-color:var(--m-line2);background:var(--m-card2)}
.model-kn:focus{border-color:var(--m-accent3);background:var(--m-card)}
.model-kwc{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.model-kwc .model-cap{flex:none}
.model-kwc .model-arw{color:var(--m-ink3);font-size:var(--fs-body);flex:none}
.model-kk{flex:1;min-width:186px;max-width:300px;padding:var(--sp-1) var(--sp-2);font-size:var(--fs-tiny)}
.model-num{width:86px}
.model-mo{flex:1;min-width:140px}
.model-kchip{display:inline-flex;align-items:center;border:1px solid var(--m-line2);background:var(--m-card2);border-radius:var(--r-xs);padding:1px var(--sp-2);font-size:var(--fs-micro);color:var(--m-ink2);margin:2px var(--sp-1) 0 0}
.model-kchip.muted{opacity:.75}
.model-chips{display:flex;flex-wrap:wrap}
.model-rule-time{display:grid;gap:var(--sp-2);padding-top:var(--sp-2);border-top:1px dashed var(--m-line2)}
.model-rule-time>.model-cap{display:flex;align-items:center;gap:var(--sp-2);cursor:pointer}
.model-rule-src{margin:0;font-size:var(--fs-micro);color:var(--m-ink3);font-family:ui-monospace,Consolas,monospace}
.model-rule-json{margin:0}
.model-rule-json summary{cursor:pointer;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-rule-json textarea{width:100%;margin-top:var(--sp-2);font-family:ui-monospace,Consolas,monospace;font-size:var(--fs-tiny);line-height:1.6}
.model-rules{list-style:none;margin:0;padding:0;display:grid;gap:var(--sp-2)}
.model-runstat{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--sp-2);border-top:1px dashed var(--m-line2);padding-top:var(--sp-3)}
.model-runstat .rs{background:var(--m-card2);border:1px solid var(--m-line);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-3);min-width:0}
.model-runstat .rs span{display:block;font-size:var(--fs-micro);color:var(--m-ink3)}
.model-runstat .rs b{font-size:var(--fs-body);font-weight:600;color:var(--m-ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}
.model-rf2{display:grid;grid-template-columns:1.42fr 1fr;gap:var(--sp-4);align-items:start}
.model-rfchips{display:flex;flex-wrap:wrap;gap:2px;border:1px dashed var(--m-line2);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-2);max-height:198px;overflow:auto;align-content:flex-start;min-height:66px}
.model-rf2 textarea{width:100%;min-width:0;min-height:132px;resize:vertical;border:1px solid var(--m-line2);border-radius:var(--r-xs);background:var(--m-card2);color:var(--m-ink);padding:var(--sp-2);font:inherit;font-size:var(--fs-tiny);line-height:1.5}
.model-rf2 textarea:focus-visible{outline:2px solid var(--m-accent3);outline-offset:1px}
.model-rf2 textarea:disabled{opacity:.65;cursor:not-allowed}
.model-rf2 [data-refusal-count]{color:var(--m-accent);font-variant-numeric:tabular-nums}
.model-rfchips .model-empty{align-self:center;padding:var(--sp-2);font-size:var(--fs-micro);color:var(--m-ink3)}
/* ---- 时段带 ---- */
.model-band{display:flex;gap:2px}
.model-band-cell{flex:1;height:42px;border-radius:var(--r-2xs);background:var(--m-card2);border:1px solid transparent;cursor:pointer;position:relative;transition:.12s;padding:0;font-size:var(--fs-micro);color:transparent;font-family:inherit}
.model-band-cell.on{background:color-mix(in srgb,var(--m-red) 30%,var(--m-card));border-color:color-mix(in srgb,var(--m-red) 34%,transparent)}
.model-band-cell:hover{z-index:2;border-color:var(--m-accent3)}
.model-band-cell.tick{color:var(--m-ink3)}
.model-hrs{display:flex;gap:2px;margin-top:var(--sp-1)}
.model-hrs span{flex:1;text-align:center;font-size:var(--fs-micro);color:var(--m-ink3)}
.model-hrl{display:flex;align-items:center;gap:var(--sp-3);margin-top:var(--sp-1);flex-wrap:wrap}
.model-hrl .lg{display:flex;align-items:center;gap:var(--sp-1);font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-hrl .lg i{display:inline-block;width:12px;height:12px;border-radius:var(--r-2xs);flex:none}
.model-hrl .lg i.hi{background:color-mix(in srgb,var(--m-red) 30%,var(--m-card));border:1px solid color-mix(in srgb,var(--m-red) 34%,transparent)}
.model-hrl .lg i.lo{background:var(--m-card2);box-shadow:inset 0 0 0 1px var(--m-line2)}
/* ---- 语音 / 生图 ---- */
.model-voice,.model-image{display:grid;gap:var(--sp-3);min-width:0}
.model-voice{grid-template-columns:minmax(0,1fr)}
.model-voice>.model-card{min-width:0;grid-template-columns:minmax(0,1fr)}
.model-voice select{max-width:100%}
/* 长 Provider 名称按标签列宽省略，避免 min-content 撑宽整个配置页。 */
.model-vtabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--sp-2)}
.model-vtabs button{display:flex;flex-direction:column;align-items:flex-start;gap:3px;min-width:0;border:1px solid var(--m-line);background:var(--m-card);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-3);cursor:pointer;transition:.14s;text-align:left;font:inherit;color:inherit}
.model-vtabs button:hover{border-color:var(--m-accent3)}
.model-vtabs button.on{border-color:var(--m-accent3);background:var(--m-sel)}
.model-vtabs b{font-size:var(--fs-body);font-weight:600;display:flex;align-items:center;gap:var(--sp-2)}
.model-vtabs .d{width:8px;height:8px;border-radius:50%;flex:none;display:inline-block}
.model-vtabs small{display:block;width:100%;font-size:var(--fs-micro);color:var(--m-ink3);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.model-vbar{display:flex;gap:var(--sp-2);align-items:flex-end;flex-wrap:wrap;min-width:0}
.model-vbar .model-fd{flex:1;min-width:min(250px,100%);max-width:100%}
.model-vmatrix{display:grid;border:1px solid var(--m-line);border-radius:var(--r-md);overflow:hidden;background:var(--m-card)}
.model-vmatrix-head,.model-vmatrix-row{display:grid;grid-template-columns:minmax(72px,.55fr) repeat(var(--voice-channels,2),minmax(0,1fr));gap:var(--sp-2);align-items:center;padding:var(--sp-2) var(--sp-3)}
.model-vmatrix-head{background:var(--m-card2);color:var(--m-ink3);font-size:var(--fs-micro)}
.model-vmatrix-head>span{display:flex;align-items:center;gap:var(--sp-2);min-width:0;font-weight:600}
.model-vmatrix-row{border-top:1px solid var(--m-line)}
.model-vmatrix-row>b{font-size:var(--fs-body);font-weight:600}
.model-vmatrix-cell{display:flex;flex-direction:column;gap:var(--sp-1);min-width:0}
.model-vmatrix-cell select{width:100%;min-width:0}
.model-vmatrix-cell small{color:var(--m-ink3);font-size:var(--fs-micro);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.model-vmatrix-channel{display:none;color:var(--m-ink3);font-size:var(--fs-micro);font-style:normal;font-weight:600}
.model-vmatrix-clear{margin-left:auto;border:1px solid var(--m-line);border-radius:var(--r-2xs);background:var(--m-card);color:var(--m-ink3);padding:0 var(--sp-1);font:inherit;font-size:var(--fs-micro);cursor:pointer}
.model-vmatrix-clear:hover:not(:disabled){border-color:var(--m-accent3);color:var(--m-ink)}
.model-vmatrix-clear:disabled{opacity:.45;cursor:not-allowed}
.model-vfoot{display:flex;align-items:center;gap:var(--sp-2);border-top:1px solid var(--m-line);padding-top:var(--sp-3);flex-wrap:wrap}
.model-vfoot .model-note{border:0;background:transparent;padding:0}
.model-pvl{list-style:none;margin:0;padding:0;display:grid;gap:var(--sp-2)}
.model-pv{display:grid;grid-template-columns:22px 1fr auto;gap:var(--sp-2);align-items:center;border:1px solid var(--m-line);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-3);background:var(--m-card)}
.model-pv.main{border-color:var(--m-accent3);background:var(--m-sel)}
.model-pv.off{opacity:.55}
.model-pv .ix{font-size:var(--fs-tiny);color:var(--m-ink3);text-align:center}
.model-pv .nm strong{font-size:var(--fs-body);font-weight:600}
.model-pv .nm small{display:block;color:var(--m-ink3);font-size:var(--fs-tiny);overflow-wrap:anywhere}
.model-pv .caps{display:flex;gap:var(--sp-1);flex-wrap:wrap;margin-top:var(--sp-1)}
.model-pv .mt{display:flex;align-items:center;gap:var(--sp-2);white-space:nowrap;flex-wrap:wrap;justify-content:flex-end}
/* ---- 抽屉 ---- */
.model-mask{position:fixed;inset:0;background:var(--scrim);opacity:0;pointer-events:none;transition:.2s;z-index:40}
.model-mask.on{opacity:1;pointer-events:auto}
.model-drawer{position:fixed;top:0;right:0;height:100vh;width:376px;max-width:92vw;background:var(--m-card);box-shadow:var(--t-shadow-lift);transform:translateX(102%);transition:transform .24s cubic-bezier(.4,0,.2,1);z-index:41;padding:var(--sp-4) var(--sp-5);overflow:auto;display:grid;gap:var(--sp-3);align-content:start;color:var(--m-ink);font-size:var(--fs-body)}
.model-drawer.on{transform:none}
.model-drawer .dh{display:flex;gap:var(--sp-2);align-items:flex-start}
.model-drawer .dh h3{margin:0;font-size:var(--fs-title);overflow-wrap:anywhere}
.model-drawer .dh p{margin:var(--sp-1) 0 0;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-drawer .x{margin-left:auto;border:0;background:transparent;color:var(--m-ink3);font-size:var(--fs-head);cursor:pointer;line-height:1}
.model-kv{display:grid;grid-template-columns:86px 1fr;gap:var(--sp-2) var(--sp-2);font-size:var(--fs-body);margin:0}
.model-kv dt{color:var(--m-ink3)}
.model-kv dd{margin:0;overflow-wrap:anywhere}
.model-sec{border-top:1px solid var(--m-line);padding-top:var(--sp-2)}
.model-sec h4{margin:0 0 var(--sp-2);font-size:var(--fs-tiny);color:var(--m-ink3);font-weight:400}
.model-sec .li{display:flex;justify-content:space-between;gap:var(--sp-2);font-size:var(--fs-body);padding:var(--sp-1) 0;border-bottom:1px dashed var(--m-line)}
.model-sec .li span{color:var(--m-ink3);font-size:var(--fs-tiny)}
/* ---- 响应式 ---- */
@media(max-width:960px){
  .model-rgrid,.model-qgrid{grid-template-columns:1fr}
  .model-duo{grid-template-columns:1fr}
  .model-vtabs{grid-template-columns:1fr}
  .model-vmatrix-head{display:none}
  .model-vmatrix-row{grid-template-columns:1fr;gap:var(--sp-2)}
  .model-vmatrix-channel{display:block}
  .model-item-nm{flex:1 1 auto}
  .model-runstat,.model-rf2{grid-template-columns:1fr}
  .model-item{flex-wrap:wrap}
  .model-item-ch{flex-basis:100%}
  .model-tabs button{padding:var(--sp-2) var(--sp-1);font-size:var(--fs-body)}
}
@media(max-width:520px){
  .model-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}
  .model-tabs button{min-width:0;white-space:nowrap}
  .model-provider-filter{flex:1 1 160px}
  .model-provider-filter select{max-width:none}
}
@media(prefers-reduced-motion:reduce){
  .model-sp,.model-drawer,.model-mask,.model-bar i,.model-pill.m,.model-vtabs button{transition:none;animation:none}
}
/* ---- 补充：Provider 视图 / 策略任务选择 / 工具条分组 ---- */
.model-workspace .model-field{display:flex;flex-direction:column;gap:var(--sp-1);min-width:0}
.model-map-filters{display:flex;align-items:flex-end;gap:var(--sp-3);flex-wrap:wrap}
.model-switches{display:inline-flex;background:var(--m-card2);border:1px solid var(--m-line);border-radius:var(--r-sm);padding:3px;gap:2px}
.model-switches button{border:0;background:transparent;border-radius:var(--r-xs);padding:var(--sp-1) var(--sp-3);font-size:var(--fs-body);color:var(--m-ink2);cursor:pointer}
.model-switches button.active{background:var(--m-card);color:var(--m-accent);font-weight:600;box-shadow:var(--t-shadow)}
.model-card-head{display:flex;align-items:flex-start;gap:var(--sp-3);flex-wrap:wrap}
.model-card-head h3{margin:0;font-size:var(--fs-lead);font-weight:600}
.model-card-sub{margin-left:auto;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-providers{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(392px,100%),1fr));gap:var(--sp-3)}
.model-provider-panel{background:var(--m-card);border:1px solid var(--m-line);border-radius:var(--m-r);box-shadow:var(--m-shadow);padding:var(--sp-3) var(--sp-4);display:grid;gap:var(--sp-2)}
.model-provider-panel header{display:flex;align-items:baseline;gap:var(--sp-2);flex-wrap:wrap}
.model-provider-panel header strong{font-size:var(--fs-lead);font-weight:600}
.model-provider-panel header em{font-style:normal;font-size:var(--fs-tiny);color:var(--m-ink3)}
/* 模型名单独一行，等宽字形。
   这一页有大量 id、上限、耗时，等宽能让整列扫读而不是逐行读；
   模型名里混着连字符和版本号（deepseek-v4-flash），比例字形下更难分辨。 */
.model-provider-model{margin:0;font-family:var(--numeric-font);font-size:var(--fs-tiny);color:var(--m-ink2);overflow-wrap:anywhere}
.model-provider-caps{display:flex;flex-wrap:wrap;gap:var(--sp-1);margin:0}
.model-provider-caps small{font-size:var(--fs-micro);padding:2px var(--sp-1);border-radius:var(--r-pill);background:var(--m-sel);color:var(--m-accent2)}
.model-provider-tasks{list-style:none;margin:0;padding:0;display:grid;gap:var(--sp-1)}
.model-provider-tasks button{width:100%;display:flex;flex-direction:column;gap:2px;text-align:left;border:1px solid var(--m-line);background:var(--m-card2);border-radius:var(--r-sm);padding:var(--sp-2) var(--sp-3);font:inherit;color:inherit;cursor:pointer}
.model-provider-tasks button:hover{border-color:var(--m-accent3);background:var(--m-sel)}
.model-provider-tasks small{font-size:var(--fs-micro);color:var(--m-ink3)}
.model-provider-note{margin:0;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-rule-title{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--sp-3);flex-wrap:wrap}
.model-rule-title h3{margin:0 0 var(--sp-1);font-size:var(--fs-lead);font-weight:600}
.model-rule-actions{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
/* ---- V1 参考补强：语音共享警示 / 试听样句 / 测试结果；生图逐项诊断 ---- */
.model-sharewarn{display:flex;gap:var(--sp-2);align-items:flex-start;background:var(--m-amber-bg);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-tiny);color:var(--m-amber);line-height:1.6;flex-wrap:wrap}
.model-vfoot .model-sample{font-size:var(--fs-tiny);color:var(--m-ink3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:280px}
.model-vfoot .model-audio-label{font-size:var(--fs-tiny);color:var(--m-ink2);white-space:nowrap}
.model-vfoot .model-test-audio{width:min(320px,100%);height:34px;flex:0 1 280px}
.model-vfoot .model-res{min-width:0;white-space:normal}
.model-vfoot .model-note{border:0;background:transparent;padding:0;flex:none}
.model-voice-diagnostic{display:flex;align-items:baseline;gap:var(--sp-2);flex:1 1 100%;min-width:0;flex-wrap:wrap;padding:var(--sp-2) var(--sp-3);border:1px solid var(--m-red-bg);border-radius:var(--r-sm);background:var(--m-red-bg);color:var(--m-red);font-size:var(--fs-tiny);line-height:1.55;overflow-wrap:anywhere}
.model-voice-diagnostic b{font-weight:600;white-space:nowrap}
.model-voice-diagnostic span{min-width:0}
.model-diag{display:inline-flex;align-items:center;gap:3px;font-size:var(--fs-micro);color:var(--m-ink3);white-space:nowrap}
.model-diag i{font-style:normal;width:14px;height:14px;border-radius:50%;display:grid;place-items:center;font-size:var(--fs-micro);flex:none}
.model-diag.ok i{background:var(--m-green-bg);color:var(--m-green)}
.model-diag.no i{background:var(--m-card2);color:var(--m-ink3);box-shadow:inset 0 0 0 1px var(--m-line2)}
.model-pv .rt{display:block;margin-top:var(--sp-1);font-size:var(--fs-micro);color:var(--m-ink3)}
/* ---- TTS Provider 管理 / 生图路线与连接 ---- */
.model-tts-group{display:grid;grid-column:1/-1;min-width:0;gap:var(--sp-2);margin-top:var(--sp-3);padding-top:var(--sp-3);border-top:1px solid var(--m-line)}
.model-tts-group:first-child{margin-top:0;padding-top:0;border-top:0}
.model-tts-group h4{margin:0;color:var(--m-ink);font-size:.83rem;letter-spacing:0}
.model-tts-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-3)}
.model-tts-fields textarea{min-height:8rem;resize:vertical;font-family:var(--font-mono,ui-monospace,monospace);line-height:1.45}
.model-tts-test-result{display:grid;gap:.2rem;margin-top:var(--sp-3);padding:var(--sp-3);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2)}
.model-tts-test-result.ok{border-color:color-mix(in srgb,var(--m-green) 45%,var(--m-line))}
.model-tts-test-result.error{border-color:color-mix(in srgb,var(--m-red) 45%,var(--m-line))}
.model-tts-test-result b{font-size:.82rem}.model-tts-test-result span,.model-tts-test-result small{color:var(--m-muted);line-height:1.45}
.model-tts-fields>.model-fd:has(.model-switch){grid-column:1/-1}
.model-vcreate{display:grid;gap:var(--sp-2);border:1px dashed var(--m-line2);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-3)}
.model-imgrs{list-style:none;margin:0;padding:0;display:grid;gap:var(--sp-2)}
.model-imgr{display:grid;grid-template-columns:1.15fr .75fr .75fr 1fr .9fr auto;gap:var(--sp-2);align-items:center}
/* 一条路线 = 队列行 + 收起着的预置字段块。两者是兄弟而不是同一栅格：
   预置块里的控件按列排，塞进 .model-imgr 的六列栅格会被挤成一条。 */
.model-imgr-item{display:grid;gap:var(--sp-2);border:1px solid var(--m-line2);border-radius:var(--r-md);padding:var(--sp-2) var(--sp-3)}
.model-imgr-ext>summary{cursor:pointer;font-size:var(--fs-tiny);color:var(--m-ink3)}
.model-imgr-ext[open]>summary{color:var(--m-ink2);margin-bottom:var(--sp-2)}
.model-imgr-body{display:grid;gap:var(--sp-3)}
.model-imgr-ps{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:var(--sp-2)}
.model-imgr-p{display:flex;flex-direction:column;gap:2px;min-width:0}
.model-imgr-p em{font-style:normal;font-size:var(--fs-micro);color:var(--m-ink3)}
.model-imgr-p input{width:100%}
.model-imgr-gs{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:var(--sp-2)}
.model-imgr-g{display:flex;flex-direction:column;gap:2px;min-width:0}
.model-imgr-g textarea{width:100%;resize:vertical}
.model-imgr-ro{display:grid;gap:var(--sp-1);border-top:1px dashed var(--m-line2);padding-top:var(--sp-2)}
.model-imgr-ro p{margin:0;font-size:var(--fs-tiny);color:var(--m-ink2);overflow-wrap:anywhere}
.model-quad{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--sp-2)}
@media(max-width:960px){
  .model-tts-fields,.model-quad{grid-template-columns:1fr}
  .model-imgr{grid-template-columns:1fr 1fr}
}
.model-cfgrs{list-style:none;margin:0;padding:0;display:grid;gap:var(--sp-2)}
.model-cfgr{display:grid;grid-template-columns:auto 1fr 1.2fr auto;gap:var(--sp-2);align-items:center}
/* 目录条上的三个 --m-* 名字从来没有声明过：这一页的词表是 --m-card / --m-ink /
   --m-ink2（见文件头的令牌定义），没有 --m-panel / --m-muted / --m-text。
   var() 引用不存在的令牌属于"计算值无效"：background 退回透明、color 退回继承，
   所以这一条一直是废的——看上去只是"这行字颜色有点淡"，实际是声明整条没生效。
   audit_page_scale.py 的【二之三】只查 --fs-/--sp-/--r- 三个命名空间，看不见这一类，
   于是它安静地留在这里。按本页已有的角色名接上：面板底 → --m-card，
   次级文字 → --m-ink2，正文 → --m-ink。 */

/* ---- 替换策略：沿用设计稿的分段栏 + 单一内容面板 ---- */
.model-policy{gap:var(--sp-3)}
.model-policy-bar{display:flex;align-items:center;gap:var(--sp-2);min-width:0;flex-wrap:wrap;padding-bottom:var(--sp-3);border-bottom:1px solid var(--m-line)}
.model-policy-modes{flex:none;max-width:100%;flex-wrap:wrap}
.model-policy-modes button,.model-policy-scope button{white-space:nowrap}
.model-policy-task{display:flex;align-items:center;gap:var(--sp-2);min-width:0;color:var(--m-ink3);font-size:var(--fs-tiny)}
.model-policy-task select{width:min(320px,28vw);min-width:180px;height:36px;padding:var(--sp-1) var(--sp-2);border:1px solid var(--m-line2);border-radius:var(--r-sm);background:var(--m-card);color:var(--m-ink);font:inherit}
.model-policy-scope-label{flex:none;color:var(--m-ink3);font-size:var(--fs-tiny)}
.model-policy-scope{flex:none;max-width:100%;flex-wrap:wrap}
.model-policy-scope button{min-height:30px}
.model-policy-bar>.model-pol-actions{flex:none}
.model-policy-editor{min-width:0}
.model-policy-editor>.model-empty{min-height:140px;display:grid;place-items:center;border:1px dashed var(--m-line2);border-radius:var(--r-sm)}
.model-policy-foot{margin:0;border:1px solid var(--m-line);border-radius:var(--r-sm);background:var(--m-card2);padding:var(--sp-2) var(--sp-3);font-size:var(--fs-tiny);color:var(--m-ink2)}
.model-refusal-provider{grid-column:1/-1}
.model-refusal-provider select{width:100%;min-height:36px;padding:var(--sp-1) var(--sp-2);border:1px solid var(--m-line2);border-radius:var(--r-sm);background:var(--m-card2);color:var(--m-ink);font:inherit}

/* ---- 生图配置分区 ---- */
.model-imgconfig{min-width:0;overflow:hidden;border:1px solid var(--m-line);border-radius:var(--r-sm);background:var(--m-card);box-shadow:var(--m-shadow);animation:model-panel-in .22s ease both}
.model-imgconfig-head{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);padding:var(--sp-4);border-bottom:1px solid var(--m-line);flex-wrap:wrap}
.model-imgconfig-head h3{margin:var(--sp-1) 0 0;font-size:var(--fs-title);font-weight:600}
.model-imgconfig-head p{margin:2px 0 0;color:var(--m-ink3);font-size:var(--fs-tiny)}
.model-img-workbench{display:grid;grid-template-columns:204px minmax(0,1fr);min-width:0;min-height:330px}
.model-img-nav{display:grid;align-content:start;gap:var(--sp-1);padding:var(--sp-3);border-right:1px solid var(--m-line);background:var(--m-card2)}
.model-img-nav button{position:relative;display:grid;grid-template-columns:24px minmax(0,1fr) 12px;align-items:center;gap:var(--sp-2);min-width:0;min-height:56px;padding:var(--sp-2);border:1px solid transparent;border-radius:var(--r-xs);background:transparent;color:var(--m-ink2);text-align:left;cursor:pointer;transition:background .16s ease,color .16s ease,border-color .16s ease,transform .16s ease}
.model-img-nav button:hover{background:var(--m-card);color:var(--m-ink);transform:translateX(1px)}
.model-img-nav button.on{border-color:var(--m-line);background:var(--m-card);color:var(--m-accent);box-shadow:var(--t-shadow)}
.model-img-nav-no{align-self:start;padding-top:2px;color:var(--m-ink3);font-family:var(--numeric-font);font-size:var(--fs-micro)}
.model-img-nav button.on .model-img-nav-no{color:var(--m-accent2)}
.model-img-nav button b,.model-img-nav button small{display:block;min-width:0;overflow-wrap:anywhere}
.model-img-nav button b{font-size:var(--fs-tiny);font-weight:600}
.model-img-nav button small{margin-top:2px;color:var(--m-ink3);font-size:var(--fs-micro)}
.model-img-nav button>i{font-style:normal;font-size:var(--fs-lead);color:var(--m-ink3);transition:transform .16s ease}
.model-img-nav button.on>i{transform:translateX(2px);color:var(--m-accent2)}
.model-img-main{min-width:0;padding:var(--sp-4);animation:model-panel-in .2s ease both}
.model-img-view{display:grid;gap:var(--sp-3);min-width:0}
.model-img-sectionhead{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-2);flex-wrap:wrap}
.model-img-sectionhead>div{display:grid;gap:2px}
.model-img-sectionhead b{font-size:var(--fs-lead);font-weight:600}
.model-img-sectionhead span{color:var(--m-ink3);font-size:var(--fs-tiny)}
.model-img-sectionhead .model-tag{color:var(--m-accent)}
.model-img-limits{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-3)}
.model-img-limits>.model-fd{padding:var(--sp-3);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2)}
.model-img-limits input{width:100%;min-height:38px}
.model-img-connection{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(128px,.55fr);align-items:start;gap:var(--sp-3)}
.model-img-connection>header{grid-column:1/-1;display:flex;align-items:baseline;justify-content:space-between;gap:var(--sp-2);padding-bottom:var(--sp-2);border-bottom:1px solid var(--m-line)}
.model-img-connection>header b{font-size:var(--fs-body);font-weight:600}
.model-img-connection>header span{font-size:var(--fs-micro);color:var(--m-ink3)}
.model-img-connection input{width:100%;min-height:38px}
.model-img-savebar{position:sticky;bottom:0;z-index:3;display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);padding:var(--sp-2) var(--sp-4);border-top:1px solid var(--m-line);background:color-mix(in srgb,var(--m-card) 94%,transparent);backdrop-filter:blur(12px);flex-wrap:wrap}
.model-img-savebar>span{color:var(--m-ink3);font-size:var(--fs-tiny)}
.model-img-savebar>div{display:flex;gap:var(--sp-2);flex-wrap:wrap}
.model-imgconfig>.model-note{margin:0 var(--sp-4) var(--sp-3);font-size:var(--fs-micro)}
.model-img-route-editor{display:grid;gap:var(--sp-3);min-width:0;padding-top:var(--sp-4);border-top:1px solid var(--m-line)}
.model-img-migration{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap;padding:var(--sp-2) var(--sp-3);border:1px solid var(--m-line2);border-radius:var(--r-xs);background:var(--m-card2);color:var(--m-ink2);font-size:var(--fs-tiny)}
.model-img-migration strong{color:var(--m-ink);font-weight:600}
.model-img-route-editor>.model-imgconfig-head{padding:0 0 var(--sp-3);border-bottom:1px solid var(--m-line)}
.model-img-route-editor>.model-img-main{padding:0}
.model-img-route-editor>.model-note{margin:0;font-size:var(--fs-micro)}
.model-img-enable{display:flex;align-items:center;gap:var(--sp-2);color:var(--m-ink2);font-size:var(--fs-tiny)}
.model-img-enable input{width:18px;height:18px;accent-color:var(--m-accent)}
.model-img-main>.model-img-view{gap:var(--sp-3)}
.model-img-routes{display:grid;gap:var(--sp-2);min-width:0}
.model-img-route{display:grid;gap:var(--sp-3);min-width:0;padding:var(--sp-3);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card)}
.model-img-route>header{display:flex;align-items:center;gap:var(--sp-2);min-width:0}
.model-img-priority{display:grid;place-items:center;flex:0 0 30px;aspect-ratio:1;border-radius:var(--r-xs);background:var(--m-sel);color:var(--m-accent);font-family:var(--numeric-font);font-weight:600}
.model-img-route-title{display:grid;gap:2px;flex:1;min-width:0}
.model-img-route-title strong{overflow-wrap:anywhere;color:var(--m-ink);font-size:var(--fs-body);font-weight:600}
.model-img-route-name-wrap{display:flex;align-items:center;gap:2px;min-width:0}
.model-img-route-name{flex:1;min-width:0;width:100%;margin-left:calc(-1 * var(--sp-1));padding:1px var(--sp-1);border:1px solid transparent;border-radius:var(--r-xs);background:transparent;color:var(--m-ink);font:inherit;font-size:var(--fs-body);font-weight:600;line-height:1.35}
.model-img-route-name::placeholder{color:var(--m-ink);opacity:.72}
.model-img-route-name:hover{border-color:var(--m-line);background:var(--m-card2)}
.model-img-route-name:focus{outline:none;border-color:var(--m-accent);background:var(--m-card);box-shadow:0 0 0 2px var(--m-sel)}
.model-img-route-name:disabled{opacity:.72;cursor:not-allowed}
.model-img-route-name:disabled:hover{border-color:transparent;background:transparent}
.model-img-route-name-wrap>i{flex:0 0 13px;width:13px;height:13px;color:var(--m-ink3);pointer-events:none}
.model-img-route-title small,.model-img-route-support{overflow-wrap:anywhere;color:var(--m-ink3);font-size:var(--fs-micro)}
.model-img-route-support{max-width:220px;text-align:right}
.model-img-route-details{min-width:0;border-top:1px solid var(--m-line)}
.model-img-route-details>summary{padding:var(--sp-2) 0 0;color:var(--m-accent);font-size:var(--fs-tiny);font-weight:600;cursor:pointer;list-style:none}
.model-img-route-details>summary::-webkit-details-marker{display:none}
.model-img-route-details>summary::after{content:"⌄";display:inline-block;margin-left:var(--sp-1);transition:transform .16s ease}
.model-img-route-details[open]>summary::after{transform:rotate(180deg)}
.model-img-route-details>.model-schema-group,.model-img-route-details>.model-img-endpoint-test,.model-img-route-details>.model-img-route-delete,.model-img-route-details>.model-img-field{margin-top:var(--sp-3)}
.model-img-route-delete{display:flex;justify-content:flex-end;padding-top:var(--sp-2);border-top:1px solid var(--m-line)}
.model-img-route-tools{display:flex;gap:2px}
.model-img-route-tools .output-icon-button{width:30px;height:30px}
.model-img-route-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-2);min-width:0;padding-top:var(--sp-2);border-top:1px solid var(--m-line)}
.model-img-field{display:grid;align-content:start;gap:var(--sp-1);min-width:0;color:var(--m-ink3);font-size:var(--fs-micro)}
.model-img-field input:not([type=checkbox]),.model-img-field select,.model-img-field textarea{width:100%;min-width:0;min-height:36px;padding:var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2);color:var(--m-ink);font:inherit}
.model-img-field textarea{min-height:128px;resize:vertical;font-family:var(--numeric-font);font-size:var(--fs-micro);line-height:1.5}
.model-img-field small{color:var(--m-ink3);font-size:var(--fs-micro);line-height:1.45}
.model-img-field.model-img-inline{display:flex;align-items:center;justify-content:space-between;min-height:36px;padding:var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2)}
.model-img-field.model-img-inline>span:last-child{display:flex;align-items:center;gap:var(--sp-1)}
.model-img-field.model-img-inline input[type=checkbox]{width:18px;height:18px;accent-color:var(--m-accent)}
.model-img-field.model-img-json{grid-column:1/-1}
.model-img-workflow{grid-column:1/-1;min-width:0;border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2)}
.model-img-workflow>summary{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-2);padding:var(--sp-2) var(--sp-3);color:var(--m-ink);font-size:var(--fs-tiny);font-weight:600;cursor:pointer;list-style:none}
.model-img-workflow>summary::-webkit-details-marker{display:none}
.model-img-workflow>summary small{color:var(--m-ink3);font-size:var(--fs-micro);font-weight:400;white-space:nowrap}
.model-img-workflow>summary:focus-visible{outline:2px solid var(--m-accent);outline-offset:2px}
.model-img-workflow>.model-img-field{padding:0 var(--sp-3) var(--sp-3)}
.model-img-workflow textarea{min-height:180px}
.model-img-legacy-list{display:flex;gap:var(--sp-2);flex-wrap:wrap;padding:var(--sp-2) 0}
.model-img-legacy-list>span{display:inline-flex;gap:var(--sp-1);max-width:100%;padding:var(--sp-1) var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-xs);color:var(--m-ink2);font-size:var(--fs-micro);overflow-wrap:anywhere}
.model-img-legacy-list b{color:var(--m-ink);font-weight:600}
.model-img-legacy-raw{margin-top:var(--sp-2)}
.model-img-legacy-raw pre{max-height:240px;overflow:auto;margin:0;padding:var(--sp-3);border-top:1px solid var(--m-line);color:var(--m-ink2);font-size:var(--fs-micro);white-space:pre-wrap;overflow-wrap:anywhere}
.model-img-addbar{display:flex;align-items:flex-end;gap:var(--sp-2);flex-wrap:wrap;padding-top:var(--sp-3);border-top:1px solid var(--m-line)}
.model-img-addbar>label{display:grid;gap:var(--sp-1);flex:1 1 220px;min-width:0;color:var(--m-ink3);font-size:var(--fs-micro)}
.model-img-addbar select{width:100%;min-height:34px;padding:var(--sp-1) var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card);color:var(--m-ink)}
.model-img-empty,.model-img-loading{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);min-height:76px;padding:var(--sp-3);border:1px dashed var(--m-line2);border-radius:var(--r-xs);color:var(--m-ink3);font-size:var(--fs-tiny);line-height:1.55}
.model-img-savebar [role=status].is-error{color:var(--t-risk-ink)}
.model-imgconfig .model-cfgrs{max-height:310px;overflow:auto;padding-right:var(--sp-1)}
.model-imgconfig .model-cfgr{grid-template-columns:auto minmax(110px,.7fr) minmax(180px,1.3fr) auto;padding:var(--sp-2);border:1px solid var(--m-line);border-radius:var(--r-xs);background:var(--m-card2)}
.model-imgconfig .model-imgrs{max-height:min(62vh,680px);overflow:auto;padding:1px var(--sp-1) 1px 1px}
.model-imgconfig .model-imgr-item{border-radius:var(--r-xs);transition:border-color .16s ease,background .16s ease}
.model-imgconfig .model-imgr-item:focus-within{border-color:var(--m-accent3);background:color-mix(in srgb,var(--m-sel) 20%,var(--m-card))}
.model-imgconfig .model-imgr-ext[open] .model-imgr-body{animation:model-panel-in .18s ease both}
.model-img-module-note{margin:var(--sp-2) var(--sp-4) 0;color:var(--t-risk-ink);font-size:var(--fs-tiny);line-height:1.5;overflow-wrap:anywhere}
.model-img-endpoint-test{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.model-img-endpoint-test>[role=status]{color:var(--m-ink3);font-size:var(--fs-micro);line-height:1.45;overflow-wrap:anywhere}
.model-img-endpoint-test>[data-state=succeeded]{color:var(--m-green)}
.model-img-endpoint-test>[data-state=failed],.model-img-endpoint-test>[data-state=error]{color:var(--t-risk-ink)}
.model-img-endpoint-test>[data-state=unknown],.model-img-endpoint-test>[data-state=pending]{color:var(--m-amber)}
.model-image>.model-img-status .model-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}
.model-image .model-pvl{gap:var(--sp-2)}
@keyframes model-panel-in{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:960px){
  .model-img-workbench{grid-template-columns:1fr}
  .model-img-nav{display:flex;overflow-x:auto;border-right:0;border-bottom:1px solid var(--m-line);scroll-snap-type:x proximity}
  .model-img-nav button{flex:1 0 154px;scroll-snap-align:start}
  .model-img-nav button:hover{transform:translateY(-1px)}
}
@media(max-width:640px){
  .model-policy-bar{align-items:stretch}
  .model-policy-modes{width:100%;display:flex}
  .model-policy-modes button{flex:1;white-space:normal}
  .model-policy-task{width:100%;justify-content:space-between}
  .model-policy-task select{width:auto;min-width:0;flex:1}
  .model-policy-bar>.model-grow{display:none}
  .model-policy-scope-label{width:100%}
  .model-policy-scope{width:100%;display:flex}
  .model-policy-scope button{flex:1;white-space:normal}
  .model-policy-bar>.model-pol-actions{width:100%}
  .model-policy-bar>.model-pol-actions>*{flex:1}
  .model-imgconfig-head,.model-img-main{padding:var(--sp-3)}
  .model-img-nav{padding:var(--sp-2)}
  .model-img-nav button{min-height:52px;flex-basis:144px}
  .model-img-limits,.model-img-connection{grid-template-columns:1fr}
  .model-img-route>header{align-items:flex-start;flex-wrap:wrap}
  .model-img-route-support{order:4;flex-basis:100%;max-width:none;text-align:left}
  .model-img-route-grid{grid-template-columns:1fr}
  .model-img-connection>header{grid-column:auto;align-items:flex-start;flex-direction:column}
  .model-imgconfig .model-cfgr{grid-template-columns:auto minmax(0,1fr) auto}
  .model-imgconfig .model-cfgr .model-mono,.model-imgconfig .model-cfgr input[data-cfgr$=path]{grid-column:2/4}
  .model-img-savebar{align-items:flex-start;padding:var(--sp-2) var(--sp-3)}
  .model-img-savebar>div{width:100%}
  .model-img-savebar>div button{flex:1}
  .model-image>.model-img-status .model-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(prefers-reduced-motion:reduce){
  .model-img-nav button,.model-img-nav button>i{transition:none}
  .model-imgconfig,.model-img-main,.model-imgconfig .model-imgr-ext[open] .model-imgr-body{animation:none}
}

/* 生图服务字段速查：只读说明，沿用模型页既有卡片视觉。 */
.model-schema { margin-top:var(--sp-3); border:1px solid var(--line); border-radius:var(--r-sm, var(--r-xs)); padding:var(--sp-3); background:var(--surface-soft); }
.model-schema header h4 { margin:var(--sp-1) 0; color:var(--ink); font-size:var(--fs-body); }
.model-schema header p { margin:0 0 var(--sp-2); color:var(--muted); font-size:var(--fs-micro); }
.model-schema-group { min-width:0; border:0; border-top:1px solid var(--line); padding:var(--sp-2) 0; }
.model-schema-group legend { padding:0 var(--sp-1); color:var(--muted); font-size:var(--fs-tiny); }
.model-schema-provider h4 { margin:var(--sp-1) 0; color:var(--ink); font-size:var(--fs-body); }
.model-schema-group summary { cursor:pointer; color:var(--accent); font-size:var(--fs-tiny); }
.model-schema-fields { margin:var(--sp-2) 0 0; padding-left:var(--sp-4); color:var(--ink); font-size:var(--fs-micro); line-height:1.7; }
.model-schema-fields code { font-family:var(--font-mono, monospace); }
.model-schema-fields small { display:block; color:var(--muted); }
.model-schema-fields li.model-schema-editable { list-style:none; margin-left:calc(var(--sp-4) * -1); }
.model-schema-editable label { display:flex; align-items:center; gap:var(--sp-2); }
.model-schema-editable input { width:96px; }
.model-schema-editable code { color:var(--muted); }

/* 生图模型页：概览 + 横向功能切换 */
.model-img-overview{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:var(--sp-4);align-items:center;padding:var(--sp-4);border:1px solid var(--m-line);border-radius:var(--r-md);background:linear-gradient(135deg,color-mix(in srgb,var(--m-accent) 6%,var(--m-card)),var(--m-card));box-shadow:var(--m-shadow)}
.model-img-overview-copy{display:grid;gap:2px;min-width:0}
.model-img-overview-title{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap;margin-top:var(--sp-1)}
.model-img-overview-title h3{margin:0;color:var(--m-ink);font-size:var(--fs-title);font-weight:650;line-height:1.25}
.model-img-overview-copy p{max-width:680px;margin:3px 0 0;color:var(--m-ink3);font-size:var(--fs-tiny);line-height:1.6}
.model-img-backend-state{display:inline-flex;align-items:center;gap:5px;padding:2px var(--sp-2);border-radius:var(--r-pill);background:var(--m-card2);color:var(--m-ink3);font-size:var(--fs-micro);white-space:nowrap}
.model-img-backend-state::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.65}
.model-img-backend-state.is-ready{background:var(--m-green-bg);color:var(--m-green)}
.model-img-backend-state.is-off{background:var(--m-card2);color:var(--m-ink3)}
.model-img-overview-side{display:flex;align-items:flex-end;flex-direction:column;gap:var(--sp-2);min-width:0}
.model-img-statusline{display:flex;align-items:center;justify-content:flex-end;gap:var(--sp-1);flex-wrap:wrap}
