t;display:block;text-align:left;width:100%;padding:var(--sp-2) 0}.product-journals small{color:#748195}.product-journals strong{display:block;margin-top:var(--sp-2);font-size:var(--fs-lead)}.product-journals p{line-height:1.8;color:#58687d;font-size:var(--fs-body);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.product-workspace{min-width:0;background:#f6f8fc;border:1px solid #e1e6ee;border-radius:var(--r-lg);overflow:hidden}.product-workspace-frame{width:100%;height:900px;min-height:620px;border:0;display:block;background:#f6f8fc}.product-domain-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 var(--sp-5);margin-bottom:var(--sp-6)}.product-domain-grid article{padding:var(--sp-4) 0;border-bottom:1px solid #dfe5ed;font-size:var(--fs-lead)}.product-domain-grid p{font-size:var(--fs-body);line-height:1.7;color:#607089;margin:var(--sp-2) 0}.product-domain-grid span{font-size:var(--fs-tiny);color:#477366}.product-section-title{margin:var(--sp-5) 0 var(--sp-4);font-size:var(--fs-title)}.product-growth-list{display:grid;gap:var(--sp-4)}.product-growth-form{padding:var(--sp-6)}.product-growth-form label{display:flex;flex-direction:column;gap:var(--sp-2);margin:var(--sp-4) 0;font-size:var(--fs-body)}.product-growth-form input,.product-growth-form textarea{padding:var(--sp-2);border:1px solid #cdd7e5;border-radius:var(--r-xs);font:inherit;width:100%;box-sizing:border-box}.product-growth-form h2{font-size:var(--fs-head)}.product-growth-form p{line-height:1.8}.product-card strong,.product-card p,.definition-list dd,.product-domain-grid p{overflow-wrap:anywhere}.product-scope select:focus-visible,.product-record-list button:focus-visible,.product-journals button:focus-visible{outline:2px solid #6585af;outline-offset:3px}.settings-content:has(.product-workspace){min-width:0}.product-heading{margin-bottom:var(--sp-5)}.product-heading h2{font-size:var(--fs-display);margin-bottom:var(--sp-2)}.product-heading p{font-size:var(--fs-lead);color:#65758b}.product-workspace button{scroll-margin:var(--sp-5)}
@media(max-width:1100px){.product-scope{flex-direction:column;align-items:stretch}.product-scope-actions{justify-content:flex-end}.product-scope-fields label{flex:1}.product-scope-actions>span{max-width:none;flex:1}}
