@media(max-width:380px){.home-jumpbar>div{flex-wrap:wrap;gap:0}.home-jumpbar button{padding:var(--sp-2) var(--sp-1);font-size:var(--fs-micro)}.room-toolbar{gap:var(--sp-1)}.room-toolbar h2{font-size:var(--fs-lead)}.room-quick-access{grid-template-columns:repeat(2,minmax(0,1fr))}.global-tools{gap:var(--sp-1)}.product-scope{margin-left:0;margin-right:0}}

/* 工作区还没法挂载时的说明块（取代一块 900px 高的空 iframe）。
   排版与 .product-workspace 一致，所以它出现时不会让版式跳一下——
   差别只是里面写着发生了什么、以及两个出口，而不是一片空白。 */
.product-workspace-blank {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap:var(--sp-3) var(--sp-5);
  min-height: 96px;
  padding:var(--sp-5) var(--sp-5);
  background: #f6f8fc;
  border: 1px solid #e1e6ee;
  border-radius:var(--r-lg);
}
.product-workspace-blank > div:first-child {
  flex: 1 1 260px;
  min-width: 0;
}
.product-workspace-blank strong {
  display: block;
  font-size:var(--fs-lead);
  color: #26384b;
}
.product-workspace-blank p {
  margin:var(--sp-1) 0 0;
  font-size:var(--fs-body);
  line-height: 1.7;
  color: #637187;
}
.product-workspace-blank-actions {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-2);
}

/* native-extension-panel.css */
.detail-dialog.detail-dialog-native-extension {
  width: min(860px, calc(100vw - 40px));
}
.native-extension-panel {
  color: var(--ink);
  min-width: 0;
  font-size: var(--fs-body);
}
.native-extension-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-4);
}
.native-extension-kicker {
  font-size: var(--fs-micro);
  color: var(--muted);
}
.native-extension-head h3 {
  margin: var(--sp-2) 0;
  font-size: var(--fs-title);
}
.native-extension-head p, .native-extension-lifecycle p {
  margin: 0;
  color: var(--secondary);
  font-size: var(--fs-tiny);
  line-height: 1.8;
}
.native-extension-status {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-3);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  font-size: var(--fs-micro);
  white-space: nowrap;
}
.native-extension-status::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--muted);
}
.native-extension-status.ready::before { background: var(--t-status-success); }
.native-extension-status.pending::before { background: var(--t-status-warning); }
.native-extension-status.error::before { background: var(--t-status-error); }
.native-extension-lifecycle {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--sp-3);
  padding: var(--sp-4) 0;
  margin-bottom: var(--sp-3);
  border-bottom: 1px solid var(--line);
}
.native-extension-lifecycle > div {
  display: flex;
  gap: var(--sp-2);
  flex-shrink: 0;
}
.native-extension-search { display: block; margin-bottom: var(--sp-4); }
.native-extension-search input {
  width: 100%;
  min-width: 0;
  padding: var(--sp-3);
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  background: var(--t-surface, var(--bg));
  color: var(--ink);
  font: inherit;
}
.native-extension-workspace {
  display: grid;
  grid-template-columns: 172px minmax(0, 1fr);
  gap: var(--sp-5);
  align-items: start;
}
/* 只挂一组时不画分组栏：设置项占满整行，避免同一页出现两条导航。 */
.native-extension-workspace.is-single { grid-template-columns: minmax(0, 1fr); }
.mobile-connection-page { display: grid; gap: var(--sp-4); min-width: 0; }
.mobile-connection-guide { border: 1px solid var(--t-line); border-radius: var(--r-sm); background: var(--t-surface-soft); }
.mobile-connection-guide summary { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); cursor: pointer; padding: var(--sp-4); list-style: none; }
.mobile-connection-guide summary::-webkit-details-marker { display: none; }
.mobile-connection-guide summary h2 { margin: 0; font-size: var(--fs-title); }
.mobile-connection-guide summary small { display: block; margin-top: var(--sp-1); color: var(--t-text-soft); font-size: var(--fs-micro); font-weight: 400; }
.mobile-connection-guide summary::after { content: "+"; color: var(--muted); font-size: var(--fs-title); line-height: 1; }
.mobile-connection-guide[open] summary::after { content: "−"; }
.mobile-connection-guide-body { padding: 0 var(--sp-4) var(--sp-4); }
.mobile-connection-guide ol { margin: 0; padding-left: 1.25rem; color: var(--t-text); line-height: 1.9; }
.mobile-connection-guide p { margin: var(--sp-2) 0 0; color: var(--t-text-soft); font-size: var(--fs-body); line-height: 1.8; }
.mobile-connection-settings { min-width: 0; }
.mobile-gateway-card { display: grid; gap: var(--sp-4); padding: var(--sp-4); margin-bottom: var(--sp-4); border: 1px solid var(--line); border-radius: var(--r-sm); background: var(--t-surface-soft); }
.mobile-gateway-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--sp-3); flex-wrap: wrap; }
.mobile-gateway-head h3 { margin: var(--sp-2) 0; font-size: var(--fs-title); }
.mobile-gateway-card p { margin: 0; color: var(--secondary); line-height: 1.8; }
.mobile-gateway-status { min-width: 0; }
.mobile-gateway-facts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--sp-3) var(--sp-4); margin: 0; }
.mobile-gateway-facts > div { min-width: 0; padding-top: var(--sp-2); border-top: 1px solid var(--line); }
.mobile-gateway-facts dt { color: var(--muted); font-size: var(--fs-micro); }
.mobile-gateway-facts dd { margin: var(--sp-1) 0 0; color: var(--ink); font-size: var(--fs-tiny); overflow-wrap: anywhere; }
.mobile-gateway-actionbar { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); flex-wrap: wrap; }
.mobile-gateway-actions { display: flex; flex-wrap: wrap; gap: var(--sp-2); }
.mobile-gateway-actionbar [data-mobile-token-result] { flex: 1 1 16rem; }
.mobile-pairing-token { display: flex; align-items: center; gap: var(--sp-2); min-width: 0; }
.mobile-pairing-token input { flex: 1; min-width: 0; padding: var(--sp-3); border: 1px solid var(--line); border-radius: var(--r-sm); color: var(--ink); background: var(--t-surface, var(--bg)); font: 12px ui-monospace, SFMono-Regular, Consolas, monospace; user-select: all; }
.mobile-gateway-card [data-mobile-token-result] { overflow-wrap: anywhere; }
.mobile-connection-overview { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(260px, .85fr); gap: var(--sp-4); margin-bottom: var(--sp-5); align-items: stretch; }
.mobile-gateway-card, .mobile-recent-card { display: grid; align-content: start; gap: var(--sp-4); min-width: 0; padding: var(--sp-4); margin: 0; border: 1px solid var(--line); border-radius: var(--r-sm); background: var(--t-surface, var(--bg)); }
.mobile-gateway-head h3, .mobile-recent-head h3, .mobile-config-heading h3 { margin: var(--sp-1) 0 0; color: var(--ink); font-size: var(--fs-title); }
.mobile-gateway-card p, .mobile-recent-card p { margin: 0; color: var(--secondary); line-height: 1.7; }
.mobile-gateway-lifecycle { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--sp-3); padding-top: var(--sp-3); border-top: 1px solid var(--line); }
.mobile-gateway-lifecycle p { margin: 0; color: var(--muted); font-size: var(--fs-micro); }
.mobile-gateway-lifecycle > div { display: flex; flex-wrap: wrap; gap: var(--sp-2); justify-content: flex-end; }
.mobile-recent-head { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); }
.mobile-recent-list { display: grid; gap: 0; margin: 0; padding: 0; list-style: none; }
.mobile-recent-list li { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--sp-3); padding: var(--sp-3) 0; border-top: 1px solid var(--line); }
.mobile-recent-list li > div { min-width: 0; }
.mobile-recent-list strong { display: block; color: var(--ink); font-size: var(--fs-tiny); }
.mobile-recent-list p { margin-top: 3px; color: var(--secondary); font-size: var(--fs-micro); overflow-wrap: anywhere; }
.mobile-recent-list time { flex: 0 0 auto; color: var(--muted); font-size: var(--fs-micro); }
.mobile-recent-empty { padding: var(--sp-4) 0; border-top: 1px solid var(--line); color: var(--muted) !important; font-size: var(--fs-tiny); }
.mobile-config-heading { margin: var(--sp-5) 0 var(--sp-3); padding-top: var(--sp-4); border-top: 1px solid var(--line); }
.mobile-config-heading p { margin: var(--sp-1) 0 0; color: var(--muted); font-size: var(--fs-micro); }
.is-mobile-connection .native-extension-search { margin-bottom: var(--sp-3); }
.is-mobile-connection .native-extension-group > h3 { display: none; }
.mobile-config-sections { display: grid; gap: var(--sp-3); }
.mobile-config-section { border: 1px solid var(--line); border-radius: var(--r-sm); background: var(--t-surface); }
.mobile-config-section > summary { display: flex; align-items: center; justify-content: space-between; gap: var(--sp-3); cursor: pointer; padding: var(--sp-3) var(--sp-4); list-style: none; }
.mobile-config-section > summary::-webkit-details-marker { display: none; }
.mobile-config-section > summary strong { display: block; color: var(--ink); font-size: var(--fs-body); font-weight: 600; }
.mobile-config-section > summary small { display: block; margin-top: 2px; color: var(--muted); font-size: var(--fs-micro); font-weight: 400; line-height: 1.6; }
.mobile-config-chevron { flex: none; width: .55rem; height: .55rem; margin: 0 .25rem .25rem 0; border-right: 2px solid var(--muted); border-bottom: 2px solid var(--muted); transform: rotate(45deg); transition: transform .16s ease; }
.mobile-config-section[open] .mobile-config-chevron { transform: rotate(-135deg); margin-bottom: 0; margin-top: .25rem; }
.mobile-config-section-body { display: grid; gap: var(--sp-4); padding: 0 var(--sp-4) var(--sp-4); }
.native-extension-nav {
  display: flex;
  flex-direction: column;
  gap: var(--sp-1);
  position: sticky;
  top: 100px;
  max-height: min(60dvh, 600px);
  overflow: auto;
}
.native-extension-nav button {
  color: var(--secondary);
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  padding: var(--sp-3);
  text-align: left;
  font: inherit;
  font-size: var(--fs-tiny);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.native-extension-nav button:hover { background: var(--t-surface-hover); }
.native-extension-nav button[aria-pressed="true"] {
  color: var(--accent-dark);
  background: var(--t-accent-soft);
  border-color: var(--line);
}
