.native-mihome-state::before { content: ""; width: .45rem; height: .45rem; border-radius: 50%; background: var(--muted); }
.native-mihome-state.state-online::before { background: var(--t-status-success); }
.native-mihome-state.state-offline::before { background: var(--t-status-error); }
.native-mihome-policy { display: flex; align-items: center; flex-wrap: wrap; gap: var(--sp-2); margin: calc(var(--sp-2) * -1) 0 var(--sp-4); color: var(--muted); font-size: var(--fs-micro); line-height: 1.8; }
.native-mihome-feedback { margin: var(--sp-3) 0; padding: var(--sp-3); border: 1px solid var(--line); border-radius: var(--r-sm); background: var(--t-surface-soft); font-size: var(--fs-tiny); line-height: 1.8; overflow-wrap: anywhere; }
.native-mihome-feedback strong { display: block; color: var(--ink); }
.native-mihome-feedback p { margin: var(--sp-1) 0 0; color: var(--secondary); }
.native-mihome-feedback.is-error { border-color: var(--t-status-error); }
.native-management-field { display: flex; flex-direction: column; gap: var(--sp-2); margin: var(--sp-4) 0; font-size: var(--fs-tiny); }
