.native-management-field small { color: var(--muted); font-size: var(--fs-micro); }
.native-management-consent { display: flex; gap: var(--sp-2); align-items: flex-start; line-height: 1.8; font-size: var(--fs-tiny); margin: var(--sp-3) 0; }
.native-management-consent input { flex-shrink: 0; margin-top: var(--sp-1); accent-color: var(--accent); }
.native-management-policy { border: 0; border-top: 1px solid var(--line); padding: var(--sp-4) 0 0; margin-top: var(--sp-4); min-width: 0; }
.native-management-policy legend { font-size: var(--fs-tiny); color: var(--muted); padding: 0 var(--sp-2) 0 0; }
.native-management-camera-state { font-size: var(--fs-micro); color: var(--secondary); }
.native-management-camera-devices { padding: 0; margin: var(--sp-3) 0; list-style: none; font-size: var(--fs-tiny); line-height: 1.8; }
.native-management-camera-devices li { padding: var(--sp-2) 0; }
.native-management-camera-devices span { color: var(--muted); margin-left: var(--sp-2); }
.native-management-camera-test { margin-top: 1rem; padding-top: .75rem; border-top: 1px solid var(--line); font-size: var(--fs-micro); line-height: 1.8; overflow-wrap: anywhere; }
