  .native-extension-workspace { grid-template-columns: 1fr; gap: var(--sp-4); }
  .native-extension-nav {
    position: sticky;
    top: calc(57px + max(var(--sp-4), env(safe-area-inset-top)));
    z-index: 2;
    width: 100%;
    min-width: 0;
    flex-direction: row;
    flex-wrap: nowrap;
    max-height: none;
    gap: var(--sp-1);
    margin: calc(var(--sp-4) * -1) calc(var(--sp-4) * -1) var(--sp-3);
    padding: var(--sp-2) var(--sp-4);
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    background: color-mix(in srgb, var(--t-surface, var(--bg)) 92%, transparent);
    border-bottom: 1px solid var(--line);
