  .native-extension-lifecycle > div { width: 100%; flex-wrap: wrap; }
  .native-extension-lifecycle .button,
  .native-extension-savebar .button,
  .native-extension-template-actions .button,
  .native-management-actions .button { min-height: 44px; }
  .native-extension-search { margin-bottom: var(--sp-3); }
  .native-extension-search input,
  .native-extension-field input:not([type="checkbox"]),
  .native-extension-field textarea,
  .native-extension-field select,
  .native-extension-template-actions select,
  .native-management-field input,
  .native-management-field select { min-height: 44px; font-size: max(1rem, calc(var(--fs-body) + 2px)); }
  .native-extension-switch { width: 44px; height: 28px; }
  .native-extension-switch-track { height: 28px; }
  .native-extension-switch-track::after { width: 20px; height: 20px; margin: 3px; }
  .native-extension-switch input:checked + span::after { transform: translateX(16px); }
  .native-extension-field { padding: var(--sp-3) 0; }
  .native-extension-savebar {
