    flex-direction: column;
    margin: var(--sp-4) calc(var(--sp-4) * -1) calc(var(--sp-4) * -1);
    padding: var(--sp-3) var(--sp-4) max(var(--sp-3), env(safe-area-inset-bottom));
  }
  .native-extension-savebar p { max-height: 4.8em; overflow: auto; }
  .native-extension-savebar > div { justify-content: stretch; flex-wrap: nowrap; }
  .native-extension-savebar > div .button { flex: 1 1 0; }
  .native-management-qr { flex-direction: column; align-items: flex-start; }
  .native-management-bottom { flex-direction: column; align-items: flex-start; }
  .mobile-gateway-facts { grid-template-columns: minmax(0, 1fr); }
  .mobile-gateway-actionbar { align-items: stretch; flex-direction: column; }
