/* semantic-page.css */
.semantic-section{border-top:1px solid var(--t-text-soft);padding:var(--sp-5) 0;margin-top:var(--sp-4)}
.semantic-heading,.semantic-toolbar,.semantic-actions{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);flex-wrap:wrap}
.semantic-heading h3{margin:0;font-size:var(--fs-title)}.semantic-heading span,.semantic-meta,.semantic-import span,.semantic-row small{color:var(--t-text-soft);font-size:var(--fs-body)}
.semantic-feedback{min-height:20px;color:var(--t-ok-ink);font-size:var(--fs-body)}.semantic-state{font-size:var(--fs-body);background:var(--t-surface-soft);color:var(--t-ok-ink);padding:var(--sp-1) var(--sp-2);border-radius:var(--r-2xs)}.semantic-state.lexical_fallback{background:var(--t-warn-quiet);color:var(--t-warn-ink)}.semantic-state.disabled{background:var(--t-surface-soft);color:var(--t-text-soft)}
.semantic-flags{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-1) var(--sp-4);margin:var(--sp-4) 0}
.semantic-toggle{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);padding:var(--sp-2) 0;font-size:var(--fs-body)}.semantic-toggle input{width:17px;height:17px;accent-color:var(--t-ok-ink)}
.semantic-providers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-3)}.semantic-providers label,.semantic-editor label,.semantic-import label{display:grid;gap:var(--sp-1);font-size:var(--fs-body);font-weight:600;color:var(--t-accent-ink)}
.semantic-providers input,.semantic-providers select,.semantic-toolbar input,.semantic-editor textarea{width:100%;min-width:0;box-sizing:border-box;border:1px solid var(--t-surface-soft);background:var(--t-text-invert);border-radius:var(--r-2xs);padding:var(--sp-2);color:var(--t-text-soft);font:inherit}
.semantic-actions{justify-content:flex-start;margin-top:var(--sp-4)}.semantic-toolbar{margin:var(--sp-4) 0}.semantic-tabs{display:flex;gap:var(--sp-1)}.semantic-tabs button{background:transparent;border:0;border-bottom:2px solid transparent;padding:var(--sp-2) var(--sp-3);cursor:pointer}.semantic-tabs button[aria-selected=true]{border-color:var(--t-ok-ink);color:var(--t-ok-ink);font-weight:700}
.semantic-session{display:flex;align-items:center;gap:var(--sp-2);margin-top:var(--sp-3);color:var(--t-accent-ink);font-size:var(--fs-body);font-weight:600}.semantic-session select{min-width:180px;max-width:100%;border:1px solid var(--t-surface-soft);background:var(--t-text-invert);border-radius:var(--r-2xs);padding:var(--sp-2);color:var(--t-text-soft);font:inherit}
.semantic-toolbar form{display:flex;gap:var(--sp-2);flex:1;justify-content:flex-end;min-width:220px}.semantic-toolbar input{max-width:290px}.semantic-import{display:flex;align-items:center;gap:var(--sp-3);flex-wrap:wrap;padding:var(--sp-2) 0 var(--sp-4)}
.semantic-list{border-top:1px solid var(--t-text-soft)}.semantic-row{display:flex;justify-content:space-between;align-items:center;gap:var(--sp-3);padding:var(--sp-3) 0;border-bottom:1px solid var(--t-text-soft)}.semantic-row p{margin:var(--sp-1) 0;font-size:var(--fs-body);color:var(--t-accent-ink);overflow-wrap:anywhere}.semantic-row strong{font-size:var(--fs-lead)}
.semantic-results{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap;padding:var(--sp-2) 0;color:var(--t-accent-ink);font-size:var(--fs-body)}.semantic-results button{border:1px solid var(--t-surface-soft);border-radius:var(--r-2xs);background:var(--t-text-invert);padding:var(--sp-1) var(--sp-2);cursor:pointer}
