/* === 感知页新设计：网格卡片拼接布局 === */
.perception-page{min-width:0;max-width:1200px;display:grid;gap:var(--sp-4);--perception-ink:var(--t-ok);--perception-accent:var(--t-ok);--perception-line:color-mix(in srgb,var(--t-ok) 16%,transparent)}

/* 感知概览容器 - 采用网格布局 */
.perception-overview{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:var(--sp-3);padding:0}

/* 感知分组 - 大卡片容器。
   必须单列：分组内只有「标题 + 卡片网格」两个子元素，若用 auto-fit 多列，
   .perception-group-items 只会落进第一列，右侧留出大片空白。 */
.perception-group{grid-column:1 / -1;display:grid;grid-template-columns:minmax(0,1fr);gap:var(--sp-3);
  padding:var(--sp-4);border-radius:var(--r-md);
  background:linear-gradient(135deg,
    color-mix(in srgb,var(--t-surface) 95%,var(--t-ok-quiet)),
    var(--t-surface) 70%);
  border:1px solid color-mix(in srgb,var(--t-ok) 12%,transparent);
  box-shadow:0 2px 12px color-mix(in srgb,var(--t-accent) 4%,transparent)}

.perception-group-header{grid-column:1 / -1;display:flex;align-items:center;gap:var(--sp-2);
  padding-bottom:var(--sp-3);margin-bottom:var(--sp-2);
  border-bottom:2px solid color-mix(in srgb,var(--t-ok) 18%,transparent)}

.perception-group-header svg{width:20px;height:20px;color:var(--t-ok-ink);flex:none}

