.perception-balance-config{position:relative;z-index:1;grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-2);min-width:0;margin:0 calc(var(--sp-3) * -1);padding:var(--sp-3);border-top:1px solid var(--t-line);background:color-mix(in srgb,var(--t-surface-soft) 62%,transparent)}
