.perception-subpanel>summary span{display:block}
.perception-subpanel>summary strong{font-size:var(--fs-lead);font-weight:650}
.perception-subpanel>summary small{display:none}
.perception-subpanel[open]>summary{background:var(--t-surface-soft)}
.perception-subpanel-body{padding:var(--sp-3) var(--sp-4) var(--sp-4);animation:none}
.perception-config-grid-environment #perception-detail-place{grid-column:1;grid-row:1 / span 2}
.perception-config-grid-environment #perception-detail-calendar{grid-column:2;grid-row:1}
.perception-config-grid-environment #perception-detail-important-days{grid-column:2;grid-row:2}
.perception-config-grid-models #perception-detail-context{grid-column:1;grid-row:1}
.perception-config-grid-models #perception-detail-model-route{grid-column:2;grid-row:1 / span 2}
.perception-config-grid-models #perception-detail-injection{grid-column:1 / -1;grid-row:2}
.perception-config-grid-reality #perception-detail-device-access{grid-column:1;grid-row:1}
.perception-config-grid-reality #perception-detail-providers{grid-column:2;grid-row:1}
.perception-config-grid-external #perception-detail-external{grid-column:1;grid-row:1}
