.perception-config-grid .perception-scope{margin-top:var(--sp-2)}
.perception-config-grid .perception-settings-heading{margin-bottom:var(--sp-2)}
.perception-config-grid .perception-settings-disclosure{margin:0;border:0;border-radius:0;background:transparent}
.perception-config-grid .perception-settings-disclosure>summary{display:none}
.perception-config-grid .perception-settings-disclosure[open]>summary{border:0}
.perception-config-grid .perception-settings-disclosure .perception-settings-form{padding:0}
.perception-config-grid .perception-model-route-note{justify-content:flex-end}
.perception-config-grid .perception-access-block{margin-block:var(--sp-3);padding-block:var(--sp-3)}
.perception-config-grid .perception-access-heading{margin-bottom:var(--sp-2)}
.perception-config-grid .perception-access-heading .perception-section-index{display:none}
.perception-config-grid .perception-mihome-subpanel{margin-top:var(--sp-3);box-shadow:none}
.perception-config-grid-environment{--perception-page-accent:var(--t-ok)}
.perception-config-grid-models{--perception-page-accent:var(--t-accent)}
.perception-config-grid-reality{--perception-page-accent:var(--t-warn-ink)}
.perception-config-grid-external{--perception-page-accent:var(--t-text-soft)}
