  .perception-config-grid-environment #perception-detail-calendar,
  .perception-config-grid-environment #perception-detail-important-days,
  .perception-config-grid-models #perception-detail-context,
  .perception-config-grid-models #perception-detail-model-route,
  .perception-config-grid-models #perception-detail-injection,
  .perception-config-grid-reality #perception-detail-device-access,
  .perception-config-grid-reality #perception-detail-providers,
