.hw-health-login{display:grid;gap:9px;padding-top:4px}
.hw-health-login-state{display:flex;gap:10px;align-items:baseline;font-size:var(--fs-tiny);color:var(--t-text-strong)}
.hw-health-login-state small{color:var(--t-text-faint)}
.hw-health-inline{display:flex;gap:8px;align-items:center;max-width:310px}
.hw-health-summary{border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface-soft);padding:var(--sp-3);display:grid;gap:9px}
.hw-health-summary-head{display:flex;justify-content:space-between;gap:10px;align-items:baseline;color:var(--t-text-strong)}
.hw-health-summary-head span{font-size:var(--fs-micro);color:var(--t-text-faint)}
.hw-health-summary pre{margin:0;max-height:260px;overflow:auto;white-space:pre-wrap;word-break:break-word;border-radius:var(--r-xs);border:1px solid var(--t-line);background:var(--t-surface);color:var(--t-text);padding:10px;font:12px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}
.hw-health-note{font-size:var(--fs-tiny);color:var(--t-text-soft);line-height:1.65}
.hw-health-switches{display:flex;flex-wrap:wrap;gap:12px 18px;align-items:center;padding:12px 14px;border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface-soft)}
