.understanding-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:var(--sp-3);min-width:0}
.understanding-panel:not([data-understanding-panel=overview]) .understanding-stats{grid-template-columns:repeat(3,minmax(0,1fr))}
.understanding-stat{display:grid;align-content:start;gap:var(--sp-1);min-width:0;min-height:104px;padding:var(--sp-3);border:1px solid var(--t-line);border-radius:var(--r-xs);background:var(--t-surface)}
.understanding-stat>span{overflow-wrap:anywhere;color:var(--t-text-faint);font-size:var(--fs-tiny)}
.understanding-stat>strong{overflow-wrap:anywhere;color:var(--t-text-strong);font-size:var(--fs-lead);line-height:1.25;font-weight:700}
.understanding-stat>small{overflow-wrap:anywhere;color:var(--t-text-soft);font-size:var(--fs-tiny)}
.understanding-shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--sp-3);min-width:0}
.understanding-shortcuts-two{grid-template-columns:repeat(2,minmax(0,1fr))}
.understanding-shortcuts-one{grid-template-columns:minmax(0,1fr)}
.understanding-shortcut{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);min-width:0;min-height:64px;padding:var(--sp-3);border:1px solid var(--t-line);border-radius:var(--r-xs);background:var(--t-surface);color:var(--t-text-strong);font:inherit;text-align:left;cursor:pointer}
.understanding-shortcut:hover{border-color:var(--t-line-firm);background:var(--t-surface-soft)}
.understanding-shortcut span{display:grid;min-width:0;overflow-wrap:anywhere}
.understanding-shortcut strong{font-size:var(--fs-body);font-weight:650}
.understanding-shortcut>svg{width:17px;height:17px;flex:none;color:var(--t-accent-ink)}
.understanding-permissions{display:grid;gap:var(--sp-3);min-width:0;padding:var(--sp-4);border:1px solid var(--t-line);border-radius:var(--r-xs);background:var(--t-surface)}
.understanding-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);min-width:0}
.understanding-panel-heading>div{display:grid;gap:2px;min-width:0}
.understanding-panel-heading>div>span{color:var(--t-accent-ink);font-size:var(--fs-micro);font-weight:650}
.understanding-panel-heading h3{margin:0;color:var(--t-text-strong);font-size:var(--fs-title)}
.understanding-scope-badge{flex:none;padding:var(--sp-1) var(--sp-2);border-radius:var(--r-2xs);background:var(--t-surface-soft);color:var(--t-text-soft);font-size:var(--fs-tiny)}
.understanding-editor-workspace{min-width:0}
.understanding-editor-workspace .wb-card{border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}
.understanding-editor-workspace .wb-card-copy h3,.understanding-editor-workspace .wb-card-copy p{display:none}
.understanding-page[data-understanding-active=overview] .understanding-editor-workspace .wb-scope{display:none}
.understanding-editor-workspace .wb-section-layout{display:block}
.understanding-editor-workspace .wb-section-sidebar{display:none}
.understanding-editor-workspace .wb-section-panel{padding:0}
.understanding-forward-workspace,.understanding-panel>[data-understanding-editor-slot]{min-width:0}
.understanding-forward-workspace .host-options-panel{border:1px solid var(--t-line);border-radius:var(--r-xs);background:var(--t-surface);box-shadow:none}
.understanding-forward-workspace .host-options-heading p,.understanding-forward-workspace .host-options-copy small{color:var(--t-text-faint)}
@media(max-width:900px){.understanding-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.understanding-shortcuts{grid-template-columns:repeat(2,minmax(0,1fr))}.understanding-shortcuts>*:last-child:nth-child(odd){grid-column:1/-1}}
@media(max-width:560px){.understanding-page{gap:var(--sp-3)}.understanding-tabs{position:static}.understanding-tabs-scope{display:none}.understanding-stats,.understanding-panel:not([data-understanding-panel=overview]) .understanding-stats{grid-template-columns:minmax(0,1fr)}.understanding-stat{min-height:80px}.understanding-shortcuts,.understanding-shortcuts-two{grid-template-columns:minmax(0,1fr)}.understanding-shortcuts>*:last-child:nth-child(odd){grid-column:auto}.understanding-permissions{padding:var(--sp-3)}.understanding-panel-heading{align-items:flex-start}.understanding-scope-badge{white-space:normal;text-align:right}}
@media(prefers-reduced-motion:reduce){.understanding-tabs button,.understanding-shortcut{scroll-behavior:auto;transition:none}}

/* setup-guide.css */
