.setup-migration-context-editor { border-bottom:1px solid var(--line); }
.setup-migration-context-editor > summary { display:flex; justify-content:space-between; align-items:center; gap:var(--sp-3); min-height:66px; padding:var(--sp-3) 0; color:var(--muted); font-size:var(--fs-tiny); cursor:pointer; list-style:none; }
.setup-migration-context-editor > summary::-webkit-details-marker { display:none; }
.setup-migration-context-editor > summary > span:first-child { display:grid; gap:var(--sp-1); min-width:0; }
.setup-migration-context-editor > summary strong { color:var(--ink); font-weight:600; overflow-wrap:anywhere; }
.setup-migration-context-editor > summary small { font-size:var(--fs-micro); line-height:1.5; overflow-wrap:anywhere; }
.setup-migration-context-editor > summary > span:last-child { display:flex; align-items:center; gap:var(--sp-2); flex-shrink:0; color:var(--accent); }
.setup-migration-context-editor > summary > span:last-child::after { content:""; width:6px; height:6px; border-right:1px solid currentColor; border-bottom:1px solid currentColor; transform:rotate(45deg); }
.setup-migration-context-editor[open] > summary > span:last-child::after { transform:rotate(225deg); }
.setup-migration-context-editor .setup-migration-context { min-width:0; margin:0; border:0; border-top:1px solid var(--line); }
.setup-migration-body .setup-legacy-data-controls { min-width:0; border-right:0; border-left:0; border-bottom:0; }
.setup-migration-overview { padding:var(--sp-4) 0 0; }
.setup-migration-outcomes { display:grid; grid-template-columns:minmax(0,1.2fr) minmax(0,1.2fr) minmax(0,1fr); gap:var(--sp-4); padding:0 0 var(--sp-4); border-bottom:1px solid var(--line); }
.setup-migration-outcomes > article { display:flex; flex-direction:column; align-items:flex-start; min-width:0; padding-left:var(--sp-4); border-left:1px solid var(--line); }
.setup-migration-outcomes > article:first-child { padding-left:0; border-left:0; }
.setup-migration-outcomes > article > span { color:var(--muted); font-size:var(--fs-tiny); }
.setup-migration-outcomes > article > strong { margin-top:var(--sp-2); color:var(--ink); font-size:var(--fs-title); line-height:1.4; overflow-wrap:anywhere; }
.setup-migration-outcomes > article > p { margin:var(--sp-1) 0 var(--sp-3); color:var(--muted); font-size:var(--fs-tiny); line-height:1.5; overflow-wrap:anywhere; }
.setup-migration-outcomes .setup-actions { margin-top:auto; gap:var(--sp-2); }
.setup-migration-outcomes .button { font-size:var(--fs-tiny); }
.setup-migration-text-action { display:inline-flex; align-items:center; justify-content:center; flex:0 0 auto; min-height:36px; padding:var(--sp-1) var(--sp-2); border:0; border-radius:var(--r-xs); background:transparent; color:var(--accent); font:inherit; font-size:var(--fs-tiny); line-height:1.4; cursor:pointer; }
.setup-migration-text-action:hover { background:var(--surface-soft); text-decoration:underline; }
.setup-migration-tasks, .setup-migration-details { margin:var(--sp-4) 0 0; }
.setup-migration-tasks h4, .setup-migration-details h4 { margin:0 0 var(--sp-2); color:var(--ink); font-size:var(--fs-body); line-height:1.5; }
.setup-migration-tasks ul { margin:0; padding:0; list-style:none; border-top:1px solid var(--line); }
.setup-migration-tasks li { display:flex; justify-content:space-between; align-items:center; gap:var(--sp-3); padding:var(--sp-3) 0; border-bottom:1px solid var(--line); }
.setup-migration-tasks li > div { min-width:0; }
.setup-migration-tasks li strong { color:var(--ink); font-size:var(--fs-tiny); font-weight:600; }
.setup-migration-tasks li p, .setup-migration-detail-note { margin:var(--sp-1) 0 0; color:var(--muted); font-size:var(--fs-tiny); line-height:1.5; overflow-wrap:anywhere; }
.setup-migration-detail-note { margin:0 0 var(--sp-3); }
.setup-migration-details > .setup-migration-detail:last-child { border-bottom:0; }
.setup-migration-pending p { margin:0; }
.setup-migration-pending p + p { margin-top:var(--sp-1); }
.setup-migration-refresh { padding:var(--sp-2) 0; color:var(--accent) !important; }
@media (max-width:700px) {
  .setup-migration-wizard ol { grid-template-columns:repeat(4,minmax(72px,1fr)); overflow-x:auto; padding-bottom:var(--sp-1); }
  .setup-migration-wizard li:not(:last-child)::after { left:calc(50% + 18px); right:calc(-50% + 18px); }
  .setup-migration-wizard button { display:grid; justify-items:center; gap:var(--sp-1); padding:0 2px; text-align:center; }
  .setup-migration-wizard button > span:last-child { width:100%; }
  .setup-migration-wizard small { display:none; }
  .setup-migration-wizard-note { margin-left:0; }
  .setup-migration-wizard-actions { align-items:stretch; }
  .setup-migration-wizard-actions > span { flex-basis:100%; }
  .setup-migration-wizard-actions .button { flex:1 1 auto; }
  .setup-migration-final-action > header { display:grid; gap:var(--sp-2); }
  .setup-migration-role-topology > ul { grid-template-columns:minmax(0,1fr); }
  .setup-migration-role-topology-account { grid-template-columns:minmax(0,1fr); }
  .setup-migration-role-topology-account span { grid-column:auto; grid-row:auto; text-align:left; }
  .setup-migration-role-topology-roles li { align-items:flex-start; flex-direction:column; gap:0; }
  .setup-migration-role-topology-roles li small { text-align:left; }
  .setup-migration-outcomes { grid-template-columns:minmax(0,1fr); gap:0; padding-bottom:0; }
  .setup-migration-outcomes > article, .setup-migration-outcomes > article:first-child { padding:var(--sp-3) 0; border-left:0; border-top:1px solid var(--line); }
  .setup-migration-outcomes > article:first-child { border-top:0; padding-top:0; }
  .setup-migration-outcomes .setup-actions { margin-top:0; }
  .setup-migration-context-editor > summary { align-items:flex-start; }
  .setup-migration-context-editor > summary > span:last-child { font-size:var(--fs-micro); }
  .setup-migration-tasks li { align-items:flex-start; }
  .setup-migration-tabs button { flex:1 1 auto; padding:var(--sp-2); font-size:var(--fs-tiny); }
  .setup-migration-metrics { grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--sp-3) 0; }
  .setup-migration-metrics > div:nth-child(3) { padding-left:0; border-left:0; }
  .setup-migration-table { font-size:var(--fs-micro); }
  .setup-migration-table th, .setup-migration-table td { padding:var(--sp-2) var(--sp-1); }
  .setup-migration-table th[scope="row"] { width:26%; }
  .setup-migration-source-list li { grid-template-columns:minmax(0,1fr); }
  .setup-migration-section-head > .button { width:100%; }
}

/* ==========================================================================
   旧版资料迁入 · 页面级整理（2026-10-24）
   目标不是换一套皮，而是让「现在在哪一步、这一步要做什么、做完去哪」在同一
   屏里成立：左侧一条竖向步骤轨道，右侧一张舞台卡，抬头固定说明这一步的边界，
   底部动作条吸附在视口边缘。步骤内容仍由 setup-guide.js 生成，这里只重排。
   ========================================================================== */

.setup-migration-workspace {
  display: grid;
  grid-template-columns: 248px minmax(0, 1fr);
  grid-template-areas:
    "hero hero"
    "rail stage";
  align-items: start;
  gap: var(--sp-4) var(--sp-5);
  min-width: 0;
}

/* ── 页面抬头 ─────────────────────────────── */
.setup-migration-workspace .setup-migration-header {
  grid-area: hero;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-5);
  padding: var(--sp-4) var(--sp-5);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background:
    linear-gradient(118deg, color-mix(in srgb, var(--t-accent-quiet) 62%, var(--t-surface)) 0%, var(--t-surface) 58%);
  box-shadow: var(--shadow-1, 0 1px 2px rgba(20, 32, 42, .04));
}
.setup-migration-hero-copy { min-width: 0; }
.setup-migration-hero h3 {
  margin: 2px 0 0;
  color: var(--t-text-strong);
  font-size: var(--fs-head);
  line-height: 1.3;
  letter-spacing: -.01em;
}
.setup-migration-hero-lead {
  max-width: 68ch;
  margin: var(--sp-2) 0 0;
  color: var(--t-text-soft);
  font-size: var(--fs-body);
  line-height: 1.65;
}
.setup-migration-safety {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-1) var(--sp-2);
  margin: var(--sp-3) 0 0;
  padding: 0;
  list-style: none;
}
.setup-migration-safety li {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  padding: var(--sp-1) var(--sp-2);
  border: 1px solid var(--t-line);
  border-radius: var(--r-pill);
  background: var(--t-surface);
  color: var(--t-text-soft);
  font-size: var(--fs-micro);
  white-space: nowrap;
}
.setup-migration-safety li::before {
  content: "";
  width: 5px;
  height: 5px;
  flex: 0 0 5px;
  border-radius: 50%;
  background: var(--t-ok);
  box-shadow: 0 0 0 3px var(--t-ok-quiet);
}
.setup-migration-meter {
  display: grid;
  flex: 0 0 186px;
  gap: var(--sp-1);
  min-width: 0;
  padding: var(--sp-2) var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-migration-meter-label {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2);
  margin: 0;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
}
.setup-migration-meter-label b {
  color: var(--t-accent);
  font-size: var(--fs-title);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.setup-migration-meter-track {
  display: block;
  height: 6px;
  border-radius: var(--r-pill);
  background: var(--t-surface-sunken);
  overflow: hidden;
}
.setup-migration-meter-track i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--t-accent), var(--t-accent-hover));
  transition: width var(--dur-slow) var(--ease-control, cubic-bezier(.22, .72, .24, 1));
}
.setup-migration-meter-current {
  margin: 0;
  color: var(--t-text-strong);
  font-size: var(--fs-tiny);
  font-weight: 600;
  line-height: 1.4;
}

/* ── 步骤轨道 ─────────────────────────────── */
.setup-migration-workspace .setup-migration-wizard {
  grid-area: rail;
  position: sticky;
  top: var(--sp-2);
  min-width: 0;
  max-height: calc(100dvh - var(--sp-5));
  margin: 0;
  padding: var(--sp-3);
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--t-surface-soft);
  overflow: auto;
}
.setup-migration-wizard-title {
  margin: 0;
  padding: 0 var(--sp-1);
  color: var(--t-text-strong);
  font-size: var(--fs-tiny);
  font-weight: 700;
  letter-spacing: .01em;
}
.setup-migration-workspace .setup-migration-wizard ol {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 2px;
  margin: var(--sp-2) 0 0;
  padding: 0;
  list-style: none;
}
.setup-migration-workspace .setup-migration-wizard li { position: relative; min-width: 0; }
.setup-migration-workspace .setup-migration-wizard li:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 36px;
  bottom: -4px;
  left: 19px;
  width: 1px;
  background: var(--t-line);
}
.setup-migration-workspace .setup-migration-wizard li.is-done:not(:last-child)::after { background: var(--t-ok); opacity: .55; }
.setup-migration-workspace .setup-migration-wizard li.is-current:not(:last-child)::after {
  background: linear-gradient(180deg, var(--t-accent), var(--t-line));
}
.setup-migration-workspace .setup-migration-wizard button {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  align-items: center;
  gap: var(--sp-2);
  width: 100%;
  min-width: 0;
  padding: var(--sp-1);
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  background: transparent;
  color: var(--t-text-soft);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease-control, ease), border-color var(--dur-fast) var(--ease-control, ease),
    color var(--dur-fast) var(--ease-control, ease), box-shadow var(--dur-fast) var(--ease-control, ease);
}
.setup-migration-workspace .setup-migration-wizard button:disabled { cursor: not-allowed; opacity: .48; }
.setup-migration-workspace .setup-migration-wizard li.is-ready button:hover:not(:disabled),
.setup-migration-workspace .setup-migration-wizard li.is-done button:hover:not(:disabled) {
  background: var(--t-surface);
  color: var(--t-text-strong);
}
.setup-migration-workspace .setup-migration-wizard li.is-current button {
  border-color: color-mix(in srgb, var(--t-accent) 34%, var(--t-line));
  background: var(--t-surface);
  color: var(--t-text-strong);
  box-shadow: inset 3px 0 var(--t-accent), 0 1px 2px rgba(20, 32, 42, .04);
}
.setup-migration-wizard-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  border: 1px solid var(--t-line-firm);
  border-radius: 50%;
  background: var(--t-surface);
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  font-variant-numeric: tabular-nums;
  transition: background var(--dur-fast), border-color var(--dur-fast), color var(--dur-fast), box-shadow var(--dur);
}
.setup-migration-wizard-index svg { width: 13px; height: 13px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
.setup-migration-wizard li.is-current .setup-migration-wizard-index {
  border-color: var(--t-accent-solid);
  background: var(--t-accent-solid);
  color: var(--t-on-solid);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--t-accent) 14%, transparent);
  font-weight: 700;
}
.setup-migration-wizard li.is-done .setup-migration-wizard-index {
  border-color: var(--t-ok);
  background: var(--t-ok-quiet);
  color: var(--t-ok-ink);
}
.setup-migration-wizard li.is-ready .setup-migration-wizard-index {
  border-color: color-mix(in srgb, var(--t-accent) 58%, var(--t-line-firm));
  color: var(--t-accent-ink);
}
.setup-migration-workspace .setup-migration-wizard button > span:last-child { display: grid; gap: 1px; min-width: 0; }
.setup-migration-workspace .setup-migration-wizard strong { color: inherit; font-size: var(--fs-tiny); font-weight: 600; line-height: 1.3; }
.setup-migration-workspace .setup-migration-wizard small {
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.35;
  white-space: normal;
  overflow-wrap: anywhere;
}
.setup-migration-wizard li.is-current strong { color: var(--t-accent-ink); }
.setup-migration-wizard li.is-current small { color: var(--t-text-soft); }
.setup-migration-wizard-note {
  margin: var(--sp-3) 0 0;
  padding: var(--sp-2) var(--sp-1) 0;
  border-top: 1px solid var(--t-line);
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.55;
}

/* ── 舞台 ─────────────────────────────────── */
.setup-migration-main {
  grid-area: stage;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: var(--r-md);
  background: var(--t-surface);
  box-shadow: var(--t-shadow);
}
.setup-migration-stage-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-4);
  padding: var(--sp-4) var(--sp-5) var(--sp-3);
  border-bottom: 1px solid var(--t-line);
  border-radius: var(--r-md) var(--r-md) 0 0;
  background: linear-gradient(180deg, var(--t-surface) 0%, var(--t-surface-soft) 100%);
  outline: none;
}
.setup-migration-stage-head:focus-visible { outline: 2px solid var(--t-focus, var(--t-accent)); outline-offset: -2px; }
.setup-migration-stage-copy { min-width: 0; }
.setup-migration-stage-eyebrow {
  margin: 0;
  color: var(--t-accent);
  font-size: var(--fs-micro);
  font-weight: 700;
  letter-spacing: .06em;
  font-variant-numeric: tabular-nums;
}
.setup-migration-stage-head h4 {
  margin: 3px 0 0;
  color: var(--t-text-strong);
  font-size: var(--fs-title);
  line-height: 1.35;
}
.setup-migration-stage-head p:last-child {
  max-width: 72ch;
  margin: var(--sp-1) 0 0;
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  line-height: 1.6;
}
.setup-migration-stage-tags { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: var(--sp-1); flex: 0 0 auto; }
.setup-migration-tag {
  padding: var(--sp-1) var(--sp-2);
  border: 1px solid var(--t-line);
  border-radius: var(--r-pill);
  background: var(--t-surface);
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  white-space: nowrap;
}
.setup-migration-tag.is-strong {
  border-color: color-mix(in srgb, var(--t-accent) 30%, var(--t-line));
  background: var(--t-accent-quiet);
  color: var(--t-accent-ink);
}
.setup-migration-main > .setup-migration-body {
  min-width: 0;
  margin: 0;
  padding: var(--sp-4) var(--sp-5) 0;
  border: 0;
}

.setup-migration-body > .setup-migration-role-setup,
.setup-migration-body > .setup-migration-source-panel,
.setup-migration-body > .setup-legacy-data,
.setup-migration-body > .setup-migration-review,
.setup-migration-body > .setup-migration-wizard-panel { margin: 0; padding: 0; border: 0; }
.setup-migration-body > .setup-migration-role-form { margin: var(--sp-4) 0 0; }
.setup-migration-body > .setup-migration-mapping-panel { margin: 0; padding: var(--sp-3) 0; border: 0; }

/* 第一个区块不再自带顶边，避免和舞台抬头之间出现双线。 */
.setup-migration-body .setup-migration-source-panel > header,
.setup-migration-body .setup-migration-section-head { margin-bottom: var(--sp-3); }
.setup-migration-body .setup-migration-source-panel > header h4,
.setup-migration-body .setup-migration-section-head h4 { font-size: var(--fs-lead); }
.setup-migration-body .setup-migration-source-panel > header p,
.setup-migration-body .setup-migration-section-head p { max-width: 68ch; }
.setup-migration-body .setup-migration-section-head > .button { flex: 0 0 auto; }

/* ── 来源检查：左侧表单 + 右侧边界说明 ───────── */
.setup-migration-source-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(210px, .6fr);
  gap: var(--sp-3) var(--sp-4);
  align-items: start;
  margin: var(--sp-3) 0 0;
}
.setup-migration-source-main { min-width: 0; }
.setup-migration-source-main .setup-legacy-path { max-width: none; margin-top: 0; }
.setup-migration-source-main .setup-legacy-path input { min-height: 44px; font-size: var(--fs-body); }
.setup-migration-source-aside {
  min-width: 0;
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-source-aside h5 { margin: 0; color: var(--t-text-strong); font-size: var(--fs-tiny); }
.setup-migration-source-aside ul { display: grid; gap: var(--sp-2); margin: var(--sp-2) 0 0; padding: 0; list-style: none; }
.setup-migration-source-aside li { display: grid; grid-template-columns: 22px minmax(0, 1fr); gap: var(--sp-2); align-items: start; }
.setup-migration-source-aside li > span {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid var(--t-line-firm);
  border-radius: 50%;
  color: var(--t-accent);
  font-size: var(--fs-micro);
  font-variant-numeric: tabular-nums;
}
.setup-migration-source-aside p { margin: 0; color: var(--t-text-soft); font-size: var(--fs-micro); line-height: 1.55; }
.setup-migration-source-aside-note {
  margin: var(--sp-3) 0 0 !important;
  padding-top: var(--sp-2);
  border-top: 1px dashed var(--t-line);
  color: var(--t-text-faint) !important;
}
.setup-migration-source-status { margin-top: var(--sp-3); border-radius: 0 var(--r-xs) var(--r-xs) 0; }

/* ── 资料范围：卡片式选择 ─────────────────── */
.setup-migration-body .setup-legacy-option-groups { margin: 0; padding: 0; border: 0; }
.setup-migration-body .setup-legacy-option-group { margin: 0 0 var(--sp-4); }
.setup-migration-body .setup-legacy-option-group > header { align-items: baseline; }
.setup-migration-body .setup-legacy-option-group > header strong { font-size: var(--fs-lead); }
.setup-migration-body .setup-legacy-data-checks { gap: var(--sp-2); margin: var(--sp-2) 0 0; }
.setup-legacy-data-checks label {
  position: relative;
  padding: var(--sp-3);
  border-radius: var(--r-sm);
  background: var(--t-surface);
  transition: border-color var(--dur-fast) var(--ease-control, ease), background var(--dur-fast),
    box-shadow var(--dur-fast) var(--ease-control, ease), transform var(--dur-fast) var(--ease-control, ease);
}
@media (hover: hover) and (pointer: fine) {
  .setup-legacy-data-checks label:hover:not(:has(input:disabled)) {
    border-color: color-mix(in srgb, var(--t-accent) 42%, var(--t-line));
    box-shadow: var(--t-shadow);
    transform: translateY(-1px);
  }
}
.setup-legacy-data-checks label:has(input:checked) {
  border-color: color-mix(in srgb, var(--t-accent) 55%, var(--t-line));
  background: color-mix(in srgb, var(--t-accent-quiet) 46%, var(--t-surface));
  box-shadow: inset 3px 0 var(--t-accent);
}
.setup-legacy-data-checks label:has(input:disabled) { opacity: .58; transform: none; box-shadow: none; }
.setup-legacy-data-choice strong { font-size: var(--fs-tiny); }
.setup-legacy-data-choice small { margin-top: 2px; }
.setup-legacy-data-choice input { width: 16px; height: 16px; accent-color: var(--t-accent); }
.setup-legacy-confirm { padding: var(--sp-2); border: 1px solid var(--t-line); border-radius: var(--r-xs); background: var(--t-surface); }
.setup-legacy-confirm:has(input:checked) {
  border-color: color-mix(in srgb, var(--t-ok) 42%, var(--t-line));
  background: color-mix(in srgb, var(--t-ok-quiet) 55%, var(--t-surface));
}

/* ── 映射：抽屉与目的地 ───────────────────── */
.setup-migration-drawer {
  margin: var(--sp-4) 0 0;
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-drawer > summary {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-3);
  min-height: 48px;
  padding: var(--sp-2) var(--sp-3);
  color: var(--t-text-strong);
  font-size: var(--fs-tiny);
  font-weight: 600;
  cursor: pointer;
  list-style: none;
}
.setup-migration-drawer > summary::-webkit-details-marker { display: none; }
.setup-migration-drawer > summary::after {
  content: "";
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-right: 1px solid var(--t-text-faint);
  border-bottom: 1px solid var(--t-text-faint);
  transform: rotate(45deg);
  transition: transform var(--dur-fast) var(--ease-control, ease);
}
.setup-migration-drawer[open] > summary::after { transform: rotate(225deg); }
.setup-migration-drawer > summary small { color: var(--t-text-faint); font-size: var(--fs-micro); font-weight: 400; }
.setup-migration-drawer[open] > summary { border-bottom: 1px solid var(--t-line); }
.setup-migration-drawer .setup-legacy-persona-batch { margin: 0; padding: var(--sp-3); border: 0; }
.setup-migration-drawer .setup-legacy-persona-batch > h5 { font-size: var(--fs-body); }
.setup-legacy-persona-row {
  gap: var(--sp-2);
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-legacy-persona-source strong { font-size: var(--fs-tiny); }
.setup-legacy-persona-destination { border-top-color: var(--t-line); }
.setup-legacy-persona-destinations > .button[data-setup-legacy-batch-add] {
  width: 100%;
  min-height: 42px;
  border-style: dashed;
  border-color: color-mix(in srgb, var(--t-accent) 42%, var(--t-line-firm));
  background: var(--t-surface-soft);
  color: var(--t-accent-ink);
  font-size: var(--fs-tiny);
}
.setup-legacy-persona-destinations > .button[data-setup-legacy-batch-add]:hover:not(:disabled) {
  background: var(--t-accent-quiet);
  border-style: solid;
}

/* ── 分区标签改为分段控件 ─────────────────── */
.setup-migration-body .setup-migration-tabs {
  gap: 3px;
  margin: var(--sp-3) 0 var(--sp-2);
  padding: 3px;
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-body .setup-migration-tabs button {
  min-height: 38px;
  margin: 0;
  padding: var(--sp-2) var(--sp-3);
  border: 0;
  border-radius: calc(var(--r-sm) - 3px);
  background: transparent;
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  transition: background var(--dur-fast), color var(--dur-fast), box-shadow var(--dur-fast);
}
.setup-migration-body .setup-migration-tabs button[aria-pressed="true"] {
  background: var(--t-surface);
  color: var(--t-accent-ink);
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(20, 32, 42, .06);
}

/* ── 预览概况：三张卡片 ───────────────────── */
.setup-migration-overview { padding-top: var(--sp-2); }
.setup-migration-outcomes {
  gap: var(--sp-3);
  padding: 0 0 var(--sp-4);
  border-bottom: 1px solid var(--t-line);
}
.setup-migration-outcomes > article,
.setup-migration-outcomes > article:first-child {
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-outcomes > article > strong { margin-top: var(--sp-1); font-size: var(--fs-lead); }
.setup-migration-outcomes > article > p { margin-bottom: var(--sp-3); }
.setup-migration-tasks { margin-top: var(--sp-4); }
.setup-migration-tasks ul { border-top: 1px solid var(--t-line); }
.setup-migration-tasks li { padding: var(--sp-3) 0; }
.setup-migration-details { margin-top: var(--sp-4); }

/* ── 导入与完成：结果表与回执 ─────────────── */
.setup-migration-table-wrap {
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-migration-table thead th { background: var(--t-surface-soft); }
.setup-migration-table tbody tr:hover > * { background: color-mix(in srgb, var(--t-accent-quiet) 30%, transparent); }
.setup-migration-table th[scope="row"] { width: 24%; }
.setup-migration-import-step > header { margin-bottom: var(--sp-3); }
.setup-migration-finish-step > header { margin-bottom: var(--sp-3); }
.setup-migration-run-step,
.setup-migration-finish-step { min-width: 0; }
.setup-migration-main .setup-migration-final-action { margin-top: var(--sp-4); }

/* ── 空状态与提示 ─────────────────────────── */
.setup-migration-empty {
  padding: var(--sp-4);
  border: 1px dashed var(--t-line-firm);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
  text-align: center;
}
.setup-migration-refresh {
  padding: var(--sp-2) var(--sp-3);
  border-left: 2px solid var(--t-accent);
  background: var(--t-accent-quiet);
  color: var(--t-accent-ink) !important;
  font-size: var(--fs-tiny);
}
.setup-migration-status { background: var(--t-surface); }
.setup-migration-detail { border-bottom-color: var(--t-line); }
.setup-migration-detail > summary { border-radius: var(--r-xs); }
.setup-migration-detail > summary:hover { color: var(--t-accent-ink); background: var(--t-surface-soft); }

/* ── 吸底动作条 ───────────────────────────── */
.setup-migration-main > .setup-migration-body > .setup-migration-wizard-actions {
  position: sticky;
  bottom: 0;
  z-index: 3;
  gap: var(--sp-2);
  margin: var(--sp-5) calc(var(--sp-5) * -1) 0;
  /* 小屋画中画固定占用右下角 176×104；主按钮必须让开它，否则会被盖住。 */
  padding: var(--sp-3) calc(var(--sp-5) + var(--shell-pip-w, 0px) + var(--sp-2)) var(--sp-3) var(--sp-5);
  border-top: 1px solid var(--t-line);
  border-radius: 0 0 var(--r-md) var(--r-md);
  background: color-mix(in srgb, var(--t-surface) 92%, transparent);
  backdrop-filter: blur(10px);
  box-shadow: 0 -10px 26px -22px rgba(20, 32, 42, .45);
}
.setup-migration-wizard-actions > span { color: var(--t-text-soft); }
.setup-migration-wizard-actions .button { min-height: 40px; }
.setup-migration-wizard-actions .button.primary { box-shadow: 0 4px 12px -6px color-mix(in srgb, var(--t-accent) 60%, transparent); }

/* ── 步骤切换动效 ─────────────────────────────
   过渡挂在迁移页的宿主节点上（setup-guide.js 的 legacyCommitStep），
   因为步骤内容每次都会整体替换；挂在宿主上才不会被异步刷新打断。 */

/* ── 窄屏：轨道折成横向条，舞台占满 ───────── */
@media (max-width: 1120px) {
  .setup-migration-workspace {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "hero" "rail" "stage";
    gap: var(--sp-3);
  }
  .setup-migration-workspace .setup-migration-wizard {
    position: static;
    max-height: none;
    padding: var(--sp-2);
    overflow: visible;
  }
  .setup-migration-wizard-title,
  .setup-migration-wizard-note { display: none; }
  .setup-migration-workspace .setup-migration-wizard ol {
    display: grid;
    grid-template-columns: repeat(4, minmax(88px, 1fr));
    gap: 0;
    margin: 0;
    overflow-x: auto;
    padding-bottom: 2px;
    scrollbar-width: thin;
    scrollbar-color: var(--t-line-firm) transparent;
  }
  .setup-migration-workspace .setup-migration-wizard ol::-webkit-scrollbar { height: 4px; }
  .setup-migration-workspace .setup-migration-wizard ol::-webkit-scrollbar-thumb {
    border-radius: var(--r-pill);
    background: var(--t-line-firm);
  }
  .setup-migration-workspace .setup-migration-wizard ol::-webkit-scrollbar-track { background: transparent; }
  .setup-migration-workspace .setup-migration-wizard li:not(:last-child)::after {
    top: 17px;
    left: calc(50% + 17px);
    right: calc(-50% + 17px);
    bottom: auto;
    width: auto;
    height: 1px;
  }
  .setup-migration-workspace .setup-migration-wizard button {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    gap: var(--sp-1);
    padding: var(--sp-1) 0;
    text-align: center;
  }
  .setup-migration-workspace .setup-migration-wizard small { display: none; }
  .setup-migration-wizard-index { width: 26px; height: 26px; flex-basis: 26px; }
  .setup-migration-workspace .setup-migration-wizard li.is-current button { box-shadow: none; }
}

@media (max-width: 760px) {
  .setup-migration-workspace .setup-migration-header {
    display: grid;
    gap: var(--sp-3);
    padding: var(--sp-3);
  }
  .setup-migration-meter { width: 100%; }
  .setup-migration-stage-head { display: grid; gap: var(--sp-2); padding: var(--sp-3); }
  .setup-migration-stage-tags { justify-content: flex-start; }
  .setup-migration-main > .setup-migration-body { padding: var(--sp-3) var(--sp-3) 0; }
  .setup-migration-source-grid { grid-template-columns: minmax(0, 1fr); }
  .setup-migration-main > .setup-migration-body > .setup-migration-wizard-actions {
    margin-inline: calc(var(--sp-3) * -1);
    padding-inline: var(--sp-3);
    flex-direction: column;
    align-items: stretch;
  }
  .setup-migration-wizard-actions > span { flex-basis: auto; }
  .setup-migration-wizard-actions .button { width: 100%; }
  .setup-migration-outcomes > article,
  .setup-migration-outcomes > article:first-child { padding: var(--sp-3); }
  .setup-migration-body .setup-migration-tabs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .setup-migration-body .setup-migration-tabs button { min-height: 42px; }
}

/* 舞台内的小标题比舞台抬头低一级，避免同屏两个等大的标题。 */
.setup-migration-body .setup-migration-role-lead h4,
.setup-migration-body .setup-migration-source-panel > header h4,
.setup-migration-body .setup-migration-section-head h4 { font-size: var(--fs-lead); }

/* 角色选择独占整行：以前它被旧的三列上下文网格压成 1/3 宽。 */
.setup-migration-body .setup-migration-context { grid-template-columns: minmax(0, 1fr); }
.setup-migration-role-form { padding-top: var(--sp-2); border-bottom: 0; }
.setup-migration-role-form .setup-migration-step { padding: 0; border-left: 0; }
.setup-migration-role-form .setup-migration-step h4 { font-size: var(--fs-tiny); }
.setup-migration-role-form .setup-legacy-scope {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--sp-3);
  max-width: none;
  margin: var(--sp-2) 0 0;
}
.setup-migration-role-form .setup-legacy-scope label { font-size: var(--fs-tiny); }
.setup-migration-role-form .setup-legacy-scope select,
.setup-migration-role-form .setup-legacy-scope input { min-height: 44px; font-size: var(--fs-body); }
.setup-migration-role-form .setup-migration-step-note { max-width: 72ch; margin-top: var(--sp-2); }

/* 导入前先给一张「本批会写什么」的清单，而不是让用户直接按一个按钮。 */
.setup-migration-batch {
  margin: 0 0 var(--sp-4);
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-batch-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2);
  flex-wrap: wrap;
  margin-bottom: var(--sp-2);
}
.setup-migration-batch-head h5 { margin: 0; color: var(--t-text-strong); font-size: var(--fs-tiny); }
.setup-migration-batch-head span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-batch ul {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(142px, 1fr));
  gap: var(--sp-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.setup-migration-batch li {
  display: grid;
  gap: 2px;
  min-width: 0;
  padding: var(--sp-2) var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-xs);
  background: var(--t-surface);
}
.setup-migration-batch li span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-batch li strong { color: var(--t-text-strong); font-size: var(--fs-tiny); font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }

/* 配置表不再自己截断：整页滚动比「表内滚动条被吸底动作条盖住」更可预期。
   分页仍把单页限制在 40 行。 */
.setup-migration-body .migration-config-table-wrap {
  max-height: none;
  overscroll-behavior: contain;
}

@media (max-width: 760px) {
  .setup-migration-role-form .setup-legacy-scope { grid-template-columns: minmax(0, 1fr); }
  .setup-migration-batch ul { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* 小屏上动作条保持一行按钮：144px 的两行提示条会吃掉可见内容。 */
@media (max-width: 600px) {
  .setup-migration-main > .setup-migration-body > .setup-migration-wizard-actions {
    flex-direction: row;
    align-items: center;
    gap: var(--sp-2);
  }
  .setup-migration-wizard-actions > span { display: none; }
  .setup-migration-wizard-actions .button { width: auto; flex: 1 1 auto; }
  .setup-migration-wizard-actions .button:first-child { flex: 0 0 auto; }
}

/* 动效偏好为「减弱」时宿主过渡由 JS 跳过；「关闭」连过渡一起提交最终状态。 */
:root[data-motion="off"] .setup-migration-workspace *,
.setup-migration-workspace.reduce-motion * {
  animation: none !important;
  transition: none !important;
}
:root[data-motion="off"] .setup-migration-workspace .setup-migration-meter-track i { transition: none; }
@media (prefers-reduced-motion: reduce) {
  .setup-migration-workspace * { transition: none !important; }
}

/* ── 一键迁移：先看清范围，再一键执行 ───────────────────────────── */
.setup-oneclick { display:grid; gap:var(--sp-3); padding:var(--sp-4); border:1px solid var(--line);
  border-radius:var(--r-sm); background:linear-gradient(180deg, var(--surface) 0%, var(--surface-soft) 100%); }
.setup-oneclick-head { display:flex; align-items:flex-start; justify-content:space-between; gap:var(--sp-3); }
.setup-oneclick-head h5 { margin:0 0 var(--sp-1); font-size:var(--fs-title); color:var(--ink); }
.setup-oneclick-head p { margin:0; max-width:60ch; color:var(--muted); font-size:var(--fs-body); line-height:1.6; }
.setup-oneclick-state { flex:0 0 auto; padding:var(--sp-1) var(--sp-2); border-radius:999px; border:1px solid var(--line);
  font-size:var(--fs-micro); color:var(--muted); background:var(--surface); transition:background .2s ease, color .2s ease; }
.setup-oneclick-state.is-ready { color:var(--accent); border-color:color-mix(in srgb, var(--accent) 35%, var(--line)); }
.setup-oneclick-state.is-running { color:var(--accent); background:color-mix(in srgb, var(--accent) 10%, var(--surface)); }
.setup-oneclick-state.is-done { color:var(--accent); background:color-mix(in srgb, var(--accent) 14%, var(--surface)); }
.setup-oneclick-state.is-error { color:var(--danger); border-color:color-mix(in srgb, var(--danger) 35%, var(--line)); }
.setup-oneclick-progress { position:relative; height:4px; overflow:hidden; border-radius:999px; background:var(--surface-soft); }
.setup-oneclick-progress span { position:absolute; inset:0 auto 0 0; width:36%; border-radius:999px; background:var(--accent);
  animation:setup-oneclick-run 1.1s ease-in-out infinite; }
@keyframes setup-oneclick-run { 0% { transform:translateX(-100%); } 100% { transform:translateX(320%); } }
.setup-oneclick-stats { display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:var(--sp-2); }
.setup-oneclick-stat { display:grid; gap:0; padding:var(--sp-3); border:1px solid var(--line); border-radius:var(--r-xs); background:var(--surface); }
.setup-oneclick-stat strong { font-size:calc(var(--fs-title) * 1.35); line-height:1.1; color:var(--ink); font-variant-numeric:tabular-nums; }
.setup-oneclick-stat span { color:var(--ink); font-size:var(--fs-body); }
.setup-oneclick-stat small { color:var(--muted); font-size:var(--fs-micro); }
.setup-oneclick-columns { display:grid; grid-template-columns:repeat(2, minmax(0, 1fr)); gap:var(--sp-3); }
.setup-oneclick-column { min-width:0; border:1px solid var(--line); border-radius:var(--r-xs); background:var(--surface); overflow:hidden; }
.setup-oneclick-column h6 { display:flex; align-items:center; justify-content:space-between; gap:var(--sp-2); margin:0; padding:var(--sp-2) var(--sp-3);
  font-size:var(--fs-micro); color:var(--muted); background:var(--surface-soft); border-bottom:1px solid var(--line); }
.setup-oneclick-column.is-auto h6 { color:var(--accent); }
.setup-oneclick-column ul { list-style:none; margin:0; padding:0; max-height:260px; overflow:auto; }
.setup-oneclick-column li { display:grid; grid-template-columns:auto minmax(0, 1fr); align-items:center; gap:var(--sp-2);
  padding:var(--sp-2) var(--sp-3); border-bottom:1px solid var(--line); font-size:var(--fs-body); color:var(--ink); }
.setup-oneclick-column li:last-child { border-bottom:0; }
.setup-oneclick-column li small { grid-column:2; color:var(--muted); font-size:var(--fs-micro); }
.setup-oneclick-column li.is-auto { border-left:2px solid var(--accent); }
.setup-oneclick-column li.is-review { border-left:2px solid color-mix(in srgb, var(--danger) 55%, var(--line)); }
.setup-oneclick-column li.is-empty { grid-template-columns:1fr; color:var(--muted); font-size:var(--fs-micro); border-left:0; }
.setup-oneclick-chip { padding:0 var(--sp-2); border-radius:999px; font-style:normal; font-size:var(--fs-micro); white-space:nowrap; }
.setup-oneclick-chip.is-auto { color:var(--accent); background:color-mix(in srgb, var(--accent) 12%, transparent); }
.setup-oneclick-chip.is-review { color:var(--danger); background:color-mix(in srgb, var(--danger) 10%, transparent); }
.setup-oneclick-chip.is-error { color:var(--danger); background:color-mix(in srgb, var(--danger) 16%, transparent); }
.setup-oneclick-empty, .setup-oneclick-notice { margin:0; padding:var(--sp-3); border:1px dashed var(--line); border-radius:var(--r-xs);
  color:var(--muted); font-size:var(--fs-body); }
.setup-oneclick-notice.is-error { color:var(--danger); border-style:solid; }
.setup-oneclick-result { display:grid; gap:var(--sp-2); }
.setup-oneclick-result > strong { font-size:var(--fs-micro); color:var(--muted); }
.setup-oneclick-result ul { list-style:none; margin:0; padding:0; display:grid; gap:0; }
.setup-oneclick-result li { display:grid; grid-template-columns:auto minmax(0, 1fr); align-items:center; gap:var(--sp-2);
  padding:var(--sp-2) var(--sp-3); border-radius:var(--r-xs); background:var(--surface); font-size:var(--fs-body);
  animation:setup-oneclick-rise .28s ease both; }
.setup-oneclick-result li:nth-child(2) { animation-delay:.05s; }
.setup-oneclick-result li:nth-child(3) { animation-delay:.1s; }
.setup-oneclick-result li:nth-child(4) { animation-delay:.15s; }
.setup-oneclick-result li small { grid-column:2; color:var(--muted); font-size:var(--fs-micro); }
@keyframes setup-oneclick-rise { from { opacity:0; transform:translateY(4px); } to { opacity:1; transform:none; } }
.setup-oneclick-actions { display:flex; flex-wrap:wrap; gap:var(--sp-2); justify-content:flex-end; }
.setup-oneclick-actions .button { transition:transform .15s ease, box-shadow .15s ease; }
.setup-oneclick-actions .button:not(:disabled):hover { transform:translateY(-1px); }
.setup-oneclick-actions .button:not(:disabled):active { transform:translateY(0); }
.setup-oneclick-actions .button:focus-visible { outline:2px solid var(--accent); outline-offset:2px; }
@media (max-width: 720px) {
  .setup-oneclick-stats { grid-template-columns:repeat(2, minmax(0, 1fr)); }
  .setup-oneclick-columns { grid-template-columns:1fr; }
}
@media (prefers-reduced-motion: reduce) {
  .setup-oneclick-progress span, .setup-oneclick-result li { animation:none; }
  .setup-oneclick-actions .button { transition:none; }
  .setup-oneclick-actions .button:not(:disabled):hover { transform:none; }
}

.setup-legacy-advanced { margin: var(--sp-3) 0; border: 1px solid var(--line); border-radius: var(--r-xs); background: var(--surface); }
.setup-legacy-advanced > summary { padding: var(--sp-3); cursor: pointer; color: var(--muted); font-size: var(--fs-body); }
.setup-legacy-advanced[open] > summary { border-bottom: 1px solid var(--line); }
.setup-legacy-advanced-note { margin: 0; padding: var(--sp-2) var(--sp-3) 0; color: var(--muted); font-size: var(--fs-micro); }
.setup-legacy-advanced .setup-legacy-data-controls { border: 0; margin: 0; }
.setup-migration-oneclick-panel { padding-top: 0; }

/* ==========================================================================
   旧版迁移 · 四步角色驱动流程（2026-10-25）
   角色与来源 → 核对 → 一键迁移 → 完成。默认路径不要求先挑旧版人格或群，
   逐项能力收在第 2 步的「高级：逐项迁移」里。所有尺寸走 tokens。
   ========================================================================== */

.setup-migration-step-panel { min-width: 0; }
.setup-migration-step-panel[hidden] { display: none !important; }

/* ── 第 1 步：角色概述 + 来源 ───────────────── */
.setup-migration-entry-panel { display: grid; gap: var(--sp-4); min-width: 0; }
.setup-migration-role-summary {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-3);
  min-width: 0;
  padding: var(--sp-4);
  border: 1px solid var(--t-line);
  border-radius: var(--r-md);
  background:
    linear-gradient(118deg, color-mix(in srgb, var(--t-accent-quiet) 55%, var(--t-surface)) 0%, var(--t-surface) 70%);
  box-shadow: var(--t-shadow);
}
.setup-migration-role-summary.is-empty { border-style: dashed; background: var(--t-surface-soft); }
.setup-migration-role-mark {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border: 1px solid color-mix(in srgb, var(--t-accent) 45%, var(--t-line));
  border-radius: 50%;
  background: var(--t-surface);
  color: var(--t-accent-ink);
  font-size: var(--fs-micro);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.setup-migration-role-copy { display: grid; gap: var(--sp-1); min-width: 0; }
.setup-migration-role-copy > span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-role-copy strong {
  color: var(--t-text-strong);
  font-size: var(--fs-lead);
  line-height: 1.35;
  overflow-wrap: anywhere;
}
.setup-migration-role-copy small {
  color: var(--t-text-soft);
  font-size: var(--fs-micro);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.setup-migration-role-details { margin: 0; }
.setup-migration-role-details > summary,
.setup-migration-advanced > summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: baseline;
  gap: var(--sp-2);
  list-style: none;
  color: var(--t-text-strong);
  font-size: var(--fs-tiny);
  font-weight: 600;
}
.setup-migration-role-details > summary::-webkit-details-marker,
.setup-migration-advanced > summary::-webkit-details-marker { display: none; }
.setup-migration-role-details > summary small,
.setup-migration-advanced > summary small {
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  font-weight: 400;
  text-align: right;
}
.setup-migration-role-details > summary::after,
.setup-migration-advanced > summary::after {
  content: "";
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  margin-left: auto;
  border-right: 1px solid var(--t-text-faint);
  border-bottom: 1px solid var(--t-text-faint);
  transform: rotate(45deg);
  transition: transform var(--dur-fast) var(--ease-control, ease);
}
.setup-migration-role-details[open] > summary::after,
.setup-migration-advanced[open] > summary::after { transform: rotate(225deg); }
.setup-migration-role-details[open] > summary,
.setup-migration-advanced[open] > summary { border-bottom: 1px solid var(--t-line); }
.setup-migration-role-details .setup-migration-role-setup { padding: var(--sp-3); }

/* ── 第 2 步：范围概况 + 配置对照 ────────────── */
.setup-migration-review-step,
.setup-migration-run-panel,
.setup-migration-finish-panel { display: grid; gap: var(--sp-4); min-width: 0; }
.setup-migration-scope {
  display: grid;
  gap: var(--sp-3);
  min-width: 0;
  padding: var(--sp-4);
  border: 1px solid var(--t-line);
  border-radius: var(--r-md);
  background: var(--t-surface-soft);
}
.setup-migration-scope-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-3);
}
.setup-migration-scope-head h4 { margin: 0; color: var(--t-text-strong); font-size: var(--fs-lead); }
.setup-migration-scope-head p {
  max-width: 68ch;
  margin: var(--sp-1) 0 0;
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  line-height: 1.55;
}
.setup-migration-scope-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--sp-2);
}
.setup-migration-scope-stat {
  display: grid;
  gap: var(--sp-1);
  min-width: 0;
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-migration-scope-stat strong {
  color: var(--t-text-strong);
  font-size: var(--fs-head);
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}
.setup-migration-scope-stat span { color: var(--t-text); font-size: var(--fs-tiny); }
.setup-migration-scope-stat small { color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.45; }
.setup-migration-scope-stat.is-warn {
  border-color: color-mix(in srgb, var(--t-warn) 46%, var(--t-line));
  background: color-mix(in srgb, var(--t-warn-quiet) 62%, var(--t-surface));
}
.setup-migration-scope-stat.is-warn strong { color: var(--t-warn-ink); }
.setup-migration-scope-empty {
  display: grid;
  gap: var(--sp-2);
  justify-items: start;
  padding: var(--sp-3);
  border: 1px dashed var(--t-line-firm);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-migration-scope-empty p { margin: 0; color: var(--t-text-soft); font-size: var(--fs-tiny); }
.setup-migration-scope-note {
  margin: 0;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.55;
}
.setup-migration-source-path {
  margin: 0 !important;
  color: var(--t-text-soft) !important;
  font-size: var(--fs-micro) !important;
}
.setup-migration-source-path code { color: var(--t-text-strong); }
.setup-migration-review-list {
  border: 1px solid color-mix(in srgb, var(--t-warn) 36%, var(--t-line));
  border-radius: var(--r-sm);
  background: color-mix(in srgb, var(--t-warn-quiet) 48%, var(--t-surface));
}
.setup-migration-review-list > summary {
  padding: var(--sp-2) var(--sp-3);
  color: var(--t-warn-ink);
  font-size: var(--fs-tiny);
  font-weight: 600;
  cursor: pointer;
}
.setup-migration-review-list ul { display: grid; gap: var(--sp-1); margin: 0; padding: 0 var(--sp-3) var(--sp-3); list-style: none; }
.setup-migration-review-list li {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--sp-1);
  padding-top: var(--sp-1);
  border-top: 1px solid var(--t-line);
}
.setup-migration-review-list li span { color: var(--t-text); font-size: var(--fs-tiny); }
.setup-migration-review-list li small { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-config-summary {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-2);
  min-width: 0;
}
.setup-migration-chip {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  padding: var(--sp-1) var(--sp-2);
  border: 1px solid var(--t-line);
  border-radius: var(--r-pill);
  background: var(--t-surface);
  color: var(--t-text-soft);
  font-size: var(--fs-micro);
  white-space: nowrap;
}
.setup-migration-chip.is-ok {
  border-color: color-mix(in srgb, var(--t-ok) 40%, var(--t-line));
  background: var(--t-ok-quiet);
  color: var(--t-ok-ink);
}
.setup-migration-chip.is-warn {
  border-color: color-mix(in srgb, var(--t-warn) 44%, var(--t-line));
  background: var(--t-warn-quiet);
  color: var(--t-warn-ink);
}

/* 状态徽标：成功用强调型绿，危险/需确认用警示色。 */
.setup-migration-tag.is-ok {
  border-color: color-mix(in srgb, var(--t-ok) 34%, var(--t-line));
  background: var(--t-ok-quiet);
  color: var(--t-ok-ink);
}
.setup-migration-tag.is-warn {
  border-color: color-mix(in srgb, var(--t-warn) 40%, var(--t-line));
  background: var(--t-warn-quiet);
  color: var(--t-warn-ink);
}
.setup-migration-tag.is-kept { color: var(--t-text-faint); }

/* 高级折叠区：默认不展示逐项控件，打开后与核对主表同一视觉层级。 */
.setup-migration-advanced { margin: var(--sp-4) 0 0; }
.setup-migration-advanced > summary { padding: var(--sp-3) var(--sp-4); }
.setup-migration-advanced[open] > summary { border-bottom: 1px solid var(--t-line); }
.setup-migration-advanced .setup-migration-manual { padding: 0 var(--sp-4) var(--sp-4); }
.setup-migration-manual { display: grid; gap: var(--sp-4); min-width: 0; }
.setup-migration-manual-controls { min-width: 0; }
.setup-migration-manual-personas,
.setup-migration-manual-import { padding-top: var(--sp-3); border-top: 1px solid var(--t-line); }
.setup-migration-manual-import .setup-migration-import-step { margin: 0; }

/* ── 第 3 步：一键迁移 ─────────────────────── */
.setup-migration-run-intro {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-3);
  padding: var(--sp-4);
  border: 1px solid var(--t-line);
  border-radius: var(--r-md);
  background: linear-gradient(118deg, color-mix(in srgb, var(--t-accent-quiet) 60%, var(--t-surface)) 0%, var(--t-surface) 72%);
}
.setup-migration-run-lead {
  max-width: 72ch;
  margin: 0;
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  line-height: 1.6;
}
.setup-migration-run-safety {
  margin: 0;
  padding: var(--sp-2) var(--sp-3);
  border-left: 2px solid var(--t-ok);
  background: var(--t-ok-quiet);
  color: var(--t-ok-ink);
  font-size: var(--fs-micro);
  line-height: 1.55;
}
.setup-oneclick-config {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: baseline;
  gap: var(--sp-1) var(--sp-3);
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-oneclick-config > span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-oneclick-config > strong { color: var(--t-text-strong); font-size: var(--fs-tiny); }
.setup-oneclick-config > small { grid-column: 2; color: var(--t-text-soft); font-size: var(--fs-micro); line-height: 1.5; }
.setup-oneclick-config.is-ready { border-color: color-mix(in srgb, var(--t-ok) 34%, var(--t-line)); background: var(--t-ok-quiet); }
.setup-oneclick-config.is-warn { border-color: color-mix(in srgb, var(--t-warn) 42%, var(--t-line)); background: var(--t-warn-quiet); }
.setup-oneclick-config.is-error { border-color: color-mix(in srgb, var(--t-risk) 42%, var(--t-line)); background: var(--t-risk-quiet); }
.setup-oneclick-config.is-kept { background: var(--t-surface-soft); }

/* ── 逐项回执：逐条出现，弱动效偏好下静态呈现 ── */
.setup-migration-receipts { display: grid; gap: var(--sp-2); }
.setup-migration-receipt-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2);
  flex-wrap: wrap;
}
.setup-migration-receipt-head strong { color: var(--t-text-strong); font-size: var(--fs-micro); }
.setup-migration-receipt-head span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-receipt-list { display: grid; gap: var(--sp-1); margin: 0; padding: 0; list-style: none; }
.setup-migration-receipt-list li {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: baseline;
  gap: var(--sp-1) var(--sp-2);
  padding: var(--sp-2) var(--sp-3);
  border: 1px solid var(--t-line);
  border-left-width: 3px;
  border-radius: var(--r-xs);
  background: var(--t-surface);
  animation: setup-migration-receipt-in var(--dur-slow) var(--ease-control, ease) both;
}
.setup-migration-receipt-list li:nth-child(2) { animation-delay: 40ms; }
.setup-migration-receipt-list li:nth-child(3) { animation-delay: 80ms; }
.setup-migration-receipt-list li:nth-child(4) { animation-delay: 120ms; }
.setup-migration-receipt-list li:nth-child(5) { animation-delay: 160ms; }
.setup-migration-receipt-list li:nth-child(6) { animation-delay: 200ms; }
.setup-migration-receipt-list li:nth-child(7) { animation-delay: 240ms; }
.setup-migration-receipt-list li:nth-child(8) { animation-delay: 280ms; }
.setup-migration-receipt-list li:nth-child(n+9) { animation-delay: 320ms; }
.setup-migration-receipt-list li em {
  padding: 0 var(--sp-2);
  border-radius: var(--r-pill);
  font-style: normal;
  font-size: var(--fs-micro);
  white-space: nowrap;
  background: var(--t-surface-soft);
  color: var(--t-text-soft);
}
.setup-migration-receipt-list li span { color: var(--t-text); font-size: var(--fs-tiny); }
.setup-migration-receipt-list li small { grid-column: 2; color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.45; }
.setup-migration-receipt-list li.is-imported { border-left-color: var(--t-ok); }
.setup-migration-receipt-list li.is-imported em { color: var(--t-ok-ink); background: var(--t-ok-quiet); }
.setup-migration-receipt-list li.is-review { border-left-color: var(--t-warn); }
.setup-migration-receipt-list li.is-review em { color: var(--t-warn-ink); background: var(--t-warn-quiet); }
.setup-migration-receipt-list li.is-failed { border-left-color: var(--t-risk); }
.setup-migration-receipt-list li.is-failed em { color: var(--t-risk-ink); background: var(--t-risk-quiet); }
.setup-migration-receipt-list li.is-kept { border-left-color: var(--t-line-firm); }
@keyframes setup-migration-receipt-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}

/* ── 第 4 步：结果汇总 ─────────────────────── */
.setup-migration-finish-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-3);
}
.setup-migration-finish-head h4 { margin: 0; color: var(--t-text-strong); font-size: var(--fs-title); }
.setup-migration-finish-head p {
  max-width: 72ch;
  margin: var(--sp-1) 0 0;
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  line-height: 1.6;
}
.setup-migration-finish-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--sp-2);
}
.setup-migration-finish-stats > div {
  display: grid;
  gap: var(--sp-1);
  min-width: 0;
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-finish-stats strong {
  color: var(--t-text-strong);
  font-size: var(--fs-lead);
  line-height: 1.25;
  overflow-wrap: anywhere;
}
.setup-migration-finish-stats span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-finish-stats > div.is-warn { border-color: color-mix(in srgb, var(--t-warn) 42%, var(--t-line)); background: var(--t-warn-quiet); }
.setup-migration-finish-stats > div.is-warn strong { color: var(--t-warn-ink); }
.setup-migration-finish-stats > div.is-danger { border-color: color-mix(in srgb, var(--t-risk) 42%, var(--t-line)); background: var(--t-risk-quiet); }
.setup-migration-finish-stats > div.is-danger strong { color: var(--t-risk-ink); }
.setup-migration-finish-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-3);
  flex-wrap: wrap;
  padding: var(--sp-4);
  border: 1px solid color-mix(in srgb, var(--t-ok) 34%, var(--t-line));
  border-radius: var(--r-md);
  background: linear-gradient(118deg, var(--t-ok-quiet) 0%, var(--t-surface) 78%);
}
.setup-migration-finish-cta strong { color: var(--t-text-strong); font-size: var(--fs-lead); }
.setup-migration-finish-cta p { margin: var(--sp-1) 0 0; color: var(--t-text-soft); font-size: var(--fs-micro); line-height: 1.5; }

/* ── 按钮：加载态、焦点环与按压反馈 ─────────── */
.setup-migration-workspace button:focus-visible,
.setup-migration-workspace .button:focus-visible {
  outline: 2px solid var(--t-focus, var(--t-accent));
  outline-offset: 2px;
}
.setup-migration-workspace .button[aria-busy="true"] {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-2);
}
.setup-migration-workspace .button[aria-busy="true"]::before {
  content: "";
  width: 12px;
  height: 12px;
  flex: 0 0 12px;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: setup-migration-spin .8s linear infinite;
}
.setup-migration-workspace .button:not(:disabled) { transition: transform var(--dur-fast) var(--ease-control, ease), box-shadow var(--dur-fast) var(--ease-control, ease); }
.setup-migration-workspace .button:not(:disabled):active { transform: translateY(1px); }
@keyframes setup-migration-spin { to { transform: rotate(360deg); } }

/* ── 窄屏 ──────────────────────────────────── */
@media (max-width: 1120px) {
  .setup-migration-scope-grid,
  .setup-migration-finish-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 760px) {
  .setup-migration-role-summary { grid-template-columns: auto minmax(0, 1fr); }
  .setup-migration-role-summary > .button,
  .setup-migration-role-summary > .setup-migration-chip { grid-column: 1 / -1; justify-self: start; }
  .setup-migration-scope-head,
  .setup-migration-run-intro,
  .setup-migration-finish-head { display: grid; gap: var(--sp-2); }
  .setup-migration-role-details > summary,
  .setup-migration-advanced > summary { display: grid; grid-template-columns: minmax(0, 1fr) auto; }
  .setup-migration-role-details > summary small,
  .setup-migration-advanced > summary small { display: none; }
  .setup-migration-advanced .setup-migration-manual { padding: 0 var(--sp-3) var(--sp-3); }
  .setup-migration-scope { padding: var(--sp-3); }
  .setup-migration-scope-grid,
  .setup-migration-finish-stats { grid-template-columns: minmax(0, 1fr); }
  .setup-migration-finish-cta { align-items: stretch; }
  .setup-migration-finish-cta .setup-actions { width: 100%; }
  .setup-migration-finish-cta .button { flex: 1 1 auto; }
}

/* 动效偏好：减弱或关闭时不播放逐条出现与加载旋转。 */
@media (prefers-reduced-motion: reduce) {
  .setup-migration-receipt-list li,
  .setup-migration-workspace .button[aria-busy="true"]::before { animation: none !important; }
  .setup-migration-workspace .button:not(:disabled) { transition: none !important; }
}
:root[data-motion="off"] .setup-migration-receipt-list li,
:root[data-motion="off"] .setup-migration-workspace .button[aria-busy="true"]::before { animation: none !important; }

/* ==========================================================================
   旧版迁移 · 第二轮：引导设置角色 / 只读核对 / 显式迁移 / 完成（2026-10-25）
   一张主卡最多三个区块；正文 72ch；主操作唯一且在动作条右侧。
   ========================================================================== */

/* ── 卡片、区块与标题层级 ─────────────────── */
.setup-migration-main > .setup-migration-body {
  display: grid;
  gap: 0;
  padding: 0 var(--sp-5) var(--sp-4);
}
.setup-migration-step-panel { display: grid; gap: 0; min-width: 0; }
.setup-migration-block {
  display: grid;
  gap: var(--sp-3);
  min-width: 0;
  padding: var(--sp-4) 0;
  border-top: 1px solid var(--t-line);
}
.setup-migration-block:first-child { padding-top: var(--sp-2); border-top: 0; }
.setup-migration-block > h3 {
  margin: 0;
  color: var(--t-text-strong);
  font-size: var(--fs-title);
  line-height: 1.3;
}
.setup-migration-stage-head h2 {
  margin: var(--sp-1) 0 0;
  color: var(--t-text-strong);
  font-size: var(--fs-head);
  line-height: 1.25;
  letter-spacing: -.01em;
}
.setup-migration-hero-title {
  margin: var(--sp-1) 0 0;
  color: var(--t-text-strong);
  font-size: var(--fs-head);
  font-weight: 700;
  line-height: 1.3;
}
.setup-migration-lead {
  max-width: 72ch;
  margin: 0;
  color: var(--t-text-soft);
  font-size: var(--fs-body);
  line-height: 1.6;
}
.setup-migration-micro {
  max-width: 72ch;
  margin: 0;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.5;
}
.setup-migration-summary-line {
  max-width: 72ch;
  margin: 0;
  color: var(--t-text);
  font-size: var(--fs-body);
  line-height: 1.6;
}
.setup-migration-summary-line strong {
  color: var(--t-text-strong);
  font-variant-numeric: tabular-nums;
}

/* ── 只读状态行 ────────────────────────────── */
.setup-migration-statusline {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--sp-2) var(--sp-3);
  min-width: 0;
  margin: var(--sp-3) 0 0;
  padding: var(--sp-2) var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-statusline.is-warn {
  border-color: color-mix(in srgb, var(--t-warn) 40%, var(--t-line));
  background: color-mix(in srgb, var(--t-warn-quiet) 55%, var(--t-surface));
}
.setup-migration-statusline-item {
  display: flex;
  align-items: baseline;
  gap: var(--sp-1);
  min-width: 0;
}
.setup-migration-statusline-item > span { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-statusline-item > strong,
.setup-migration-statusline-item > code {
  color: var(--t-text-strong);
  font-size: var(--fs-micro);
  font-weight: 600;
  overflow-wrap: anywhere;
}
.setup-migration-statusline-item > small { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-statusline-alert {
  flex: 1 0 100%;
  color: var(--t-warn-ink);
  font-size: var(--fs-micro);
  line-height: 1.45;
}
.setup-migration-statusline-actions {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  margin-left: auto;
}
.setup-migration-source-manual { position: relative; }
.setup-migration-source-manual > summary {
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  cursor: pointer;
  white-space: nowrap;
}
.setup-migration-source-manual[open] {
  position: absolute;
  top: calc(100% + var(--sp-2));
  right: 0;
  z-index: 3;
  width: min(420px, 80vw);
  padding: var(--sp-3);
  border: 1px solid var(--t-line-firm);
  border-radius: var(--r-sm);
  background: var(--t-surface);
  box-shadow: var(--t-shadow);
}
.setup-migration-source-manual .setup-legacy-path { margin: 0; }
.setup-migration-source-manual .setup-migration-micro { margin-top: var(--sp-1); }

/* ── 第 1 步：角色引导 ─────────────────────── */
.setup-migration-role-empty {
  display: grid;
  gap: var(--sp-2);
  justify-items: start;
  padding: var(--sp-3);
  border: 1px dashed var(--t-line-firm);
  border-radius: var(--r-sm);
  background: var(--t-surface-soft);
}
.setup-migration-role-empty p { margin: 0; color: var(--t-text); font-size: var(--fs-body); line-height: 1.6; }
.setup-migration-role-empty .setup-migration-micro { color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-role-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-3);
  min-width: 0;
  padding: var(--sp-3) var(--sp-4);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: linear-gradient(118deg, color-mix(in srgb, var(--t-accent-quiet) 58%, var(--t-surface)) 0%, var(--t-surface) 74%);
}
.setup-migration-role-card-main { display: grid; gap: var(--sp-1); min-width: 0; }
.setup-migration-role-card-name {
  margin: 0;
  color: var(--t-text-strong);
  font-size: var(--fs-lead);
  font-weight: 700;
  line-height: 1.3;
  overflow-wrap: anywhere;
}
.setup-migration-role-card-account,
.setup-migration-role-card-personas {
  margin: 0;
  color: var(--t-text-soft);
  font-size: var(--fs-tiny);
  line-height: 1.5;
  overflow-wrap: anywhere;
}
.setup-migration-role-card-personas { color: var(--t-text-faint); }
.setup-migration-role-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: var(--sp-2);
  margin-top: var(--sp-3);
}
.setup-migration-role-editor .setup-actions { justify-content: flex-end; }
.setup-migration-role-message {
  margin: 0;
  color: var(--t-ok-ink);
  font-size: var(--fs-micro);
  line-height: 1.5;
}
.setup-migration-role-manager {
  margin-top: var(--sp-3);
  padding-top: var(--sp-3);
  border-top: 1px solid var(--t-line);
}
.setup-migration-manager-title {
  margin: 0;
  color: var(--t-text-strong);
  font-size: var(--fs-body);
  font-weight: 700;
}
.setup-migration-manager-label {
  margin: 0;
  color: var(--t-text);
  font-size: var(--fs-tiny);
  font-weight: 600;
}
.setup-migration-field-note {
  max-width: 72ch;
  margin: 0;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.5;
}
.setup-migration-role-editor { display: grid; gap: var(--sp-2); margin-top: var(--sp-3); padding-top: var(--sp-3); border-top: 1px solid var(--t-line); }
.setup-migration-role-editor .setup-legacy-scope { margin: 0; }
.setup-migration-persona-fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.setup-migration-persona-fieldset legend { padding: 0; color: var(--t-text); font-size: var(--fs-tiny); font-weight: 600; }
.setup-migration-persona-options { display: flex; flex-wrap: wrap; gap: var(--sp-2); margin-top: var(--sp-1); }
.setup-migration-persona-option {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  padding: var(--sp-1) var(--sp-2);
  border: 1px solid var(--t-line);
  border-radius: var(--r-pill);
  background: var(--t-surface);
  color: var(--t-text);
  font-size: var(--fs-micro);
  cursor: pointer;
}
.setup-migration-persona-option input { accent-color: var(--t-accent); }
.setup-migration-persona-count { margin: 0; color: var(--t-text-faint); font-size: var(--fs-micro); }

/* ── 第 2 步：紧凑表 ───────────────────────── */
.setup-migration-table-scroll {
  min-width: 0;
  overflow-x: auto;
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-migration-compact-table {
  width: 100%;
  min-width: 660px;
  border-collapse: collapse;
  table-layout: fixed;
}
.setup-migration-compact-table col.col-item { width: 24%; }
.setup-migration-compact-table col.col-now { width: 22%; }
.setup-migration-compact-table col.col-after { width: 22%; }
.setup-migration-compact-table col.col-reason { width: 32%; }
.setup-migration-compact-table th,
.setup-migration-compact-table td {
  padding: var(--sp-2) var(--sp-3);
  border-bottom: 1px solid var(--t-line);
  font-size: var(--fs-tiny);
  line-height: 1.5;
  text-align: left;
  vertical-align: top;
}
.setup-migration-compact-table thead th {
  background: var(--t-surface-soft);
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  font-weight: 600;
  white-space: nowrap;
}
.setup-migration-compact-table tbody th {
  border-left: 2px solid var(--t-line-firm);
  color: var(--t-text-strong);
  font-weight: 600;
  overflow-wrap: anywhere;
}
.setup-migration-compact-table tbody tr.is-changed th { border-left-color: var(--t-accent); }
.setup-migration-compact-table tbody tr.is-lost th { border-left-color: var(--t-warn); }
.setup-migration-compact-table tbody td {
  overflow: hidden;
  color: var(--t-text-soft);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.setup-migration-compact-table tbody th code {
  display: block;
  margin-top: var(--sp-1);
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  font-weight: 400;
  overflow-wrap: anywhere;
}
.setup-migration-table-badge {
  display: inline-flex;
  align-items: center;
  margin-right: var(--sp-1);
  padding: 0 var(--sp-2);
  border-radius: var(--r-pill);
  font-size: var(--fs-micro);
  font-weight: 600;
  white-space: nowrap;
}
.setup-migration-table-badge.is-changed { background: var(--t-accent-quiet); color: var(--t-accent-ink); }
.setup-migration-table-badge.is-lost { background: var(--t-warn-quiet); color: var(--t-warn-ink); }
.setup-migration-compact-table tfoot td { padding: 0; border-bottom: 0; background: var(--t-surface-soft); }
.setup-migration-unchanged > summary {
  padding: var(--sp-2) var(--sp-3);
  color: var(--t-text-soft);
  font-size: var(--fs-micro);
  cursor: pointer;
}
.setup-migration-unchanged p { margin: 0; padding: 0 var(--sp-3) var(--sp-2); color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.5; }

/* ── 第 2 步：范围双列 ─────────────────────── */
.setup-migration-scope-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--sp-3);
}
.setup-migration-scope-column {
  min-width: 0;
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
}
.setup-migration-scope-column.is-warn {
  border-color: color-mix(in srgb, var(--t-warn) 42%, var(--t-line));
  background: color-mix(in srgb, var(--t-warn-quiet) 54%, var(--t-surface));
}
.setup-migration-column-title {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2);
  margin: 0 0 var(--sp-2);
  color: var(--t-text-strong);
  font-size: var(--fs-tiny);
  font-weight: 600;
}
.setup-migration-column-title span { color: var(--t-text-faint); font-size: var(--fs-micro); font-weight: 400; }
.setup-migration-scope-column ul { display: grid; gap: var(--sp-1); margin: 0; padding: 0; list-style: none; }
.setup-migration-scope-column li {
  display: grid;
  gap: var(--sp-1);
  padding-top: var(--sp-1);
  border-top: 1px solid var(--t-line);
  min-width: 0;
}
.setup-migration-scope-column li span { color: var(--t-text); font-size: var(--fs-tiny); overflow-wrap: anywhere; }
.setup-migration-scope-column li small { color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.45; }
.setup-migration-scope-column li.is-empty { border-top: 0; color: var(--t-text-faint); font-size: var(--fs-micro); }
.setup-migration-scope { padding: 0; border: 0; background: transparent; }

/* ── 第 3 步：迁移方式与进度 ───────────────── */
.setup-migration-method {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--sp-2);
}
.setup-migration-method-option {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2);
  min-width: 0;
  padding: var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-sm);
  background: var(--t-surface);
  cursor: pointer;
}
.setup-migration-method-option.is-selected {
  border-color: color-mix(in srgb, var(--t-accent) 52%, var(--t-line));
  background: color-mix(in srgb, var(--t-accent-quiet) 58%, var(--t-surface));
}
.setup-migration-method-option input { margin: 2px 0 0; accent-color: var(--t-accent); flex: 0 0 auto; }
.setup-migration-method-option > span { display: grid; gap: var(--sp-1); min-width: 0; }
.setup-migration-method-option strong { color: var(--t-text-strong); font-size: var(--fs-tiny); }
.setup-migration-method-option small { color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.45; }
.setup-migration-confirm-line {
  margin: 0;
  padding: var(--sp-3);
  border-left: 2px solid var(--t-accent);
  background: var(--t-accent-quiet);
  color: var(--t-accent-ink);
  font-size: var(--fs-body);
  line-height: 1.6;
}
.setup-migration-progress {
  height: 4px;
  overflow: hidden;
  border-radius: var(--r-pill);
  background: var(--t-surface-sunken);
}
.setup-migration-progress span {
  display: block;
  width: 38%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--t-accent), var(--t-accent-hover));
  animation: setup-migration-indeterminate 1.1s var(--ease-control, ease-in-out) infinite;
}
@keyframes setup-migration-indeterminate {
  from { transform: translateX(-100%); }
  to { transform: translateX(300%); }
}
.setup-migration-receipt-actions { display: flex; justify-content: flex-start; }

/* ── 第 4 步：结果与待办 ───────────────────── */
.setup-migration-remaining { display: grid; gap: var(--sp-1); margin: 0; padding: 0; list-style: none; }
.setup-migration-remaining li {
  display: grid;
  gap: var(--sp-1);
  padding: var(--sp-2) 0;
  border-top: 1px solid var(--t-line);
}
.setup-migration-remaining li:first-child { padding-top: 0; border-top: 0; }
.setup-migration-remaining strong { color: var(--t-text); font-size: var(--fs-tiny); }
.setup-migration-remaining small { color: var(--t-text-faint); font-size: var(--fs-micro); line-height: 1.5; }
.setup-migration-manual-result > summary { color: var(--t-text-soft); font-size: var(--fs-micro); cursor: pointer; }

/* ── 动作条：左侧返回/次要，右侧唯一 primary ── */
.setup-migration-actionbar {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--sp-3);
  flex-wrap: wrap;
  min-width: 0;
  margin-top: var(--sp-4);
  padding-top: var(--sp-3);
  border-top: 1px solid var(--t-line);
}
.setup-migration-actionbar-left { display: flex; align-items: center; flex-wrap: wrap; gap: var(--sp-2); }
.setup-migration-actionbar-right { display: grid; justify-items: end; gap: var(--sp-1); margin-left: auto; }
.setup-migration-primary-reason {
  max-width: 46ch;
  color: var(--t-text-faint);
  font-size: var(--fs-micro);
  line-height: 1.45;
  text-align: right;
}

/* ── 独立的逐项迁移页面 ───────────────────── */
.setup-migration-manual-page { display: grid; gap: var(--sp-4); min-width: 0; }
.setup-migration-manual-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--sp-4);
  padding: var(--sp-4) var(--sp-5);
  border: 1px solid var(--t-line);
  border-radius: var(--r-md);
  background: linear-gradient(118deg, color-mix(in srgb, var(--t-accent-quiet) 58%, var(--t-surface)) 0%, var(--t-surface) 76%);
}
.setup-migration-manual-head h2 { margin: var(--sp-1) 0 0; color: var(--t-text-strong); font-size: var(--fs-head); line-height: 1.3; }
.setup-migration-manual-head .button { flex: 0 0 auto; }
.setup-migration-manual-page > .setup-legacy-install-note,
.setup-migration-manual-page > .setup-migration-check,
.setup-migration-manual-page > .setup-legacy-data { margin: 0; }
.setup-migration-manual-foot { display: flex; justify-content: flex-end; }
.setup-migration-manual-page .setup-legacy-data { padding-top: var(--sp-3); }

/* ── 窄屏：单列、按钮占满 ──────────────────── */
@media (max-width: 1120px) {
  .setup-migration-scope-columns { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 760px) {
  .setup-migration-main > .setup-migration-body { padding: 0 var(--sp-3) var(--sp-3); }
  .setup-migration-statusline { align-items: flex-start; }
  .setup-migration-statusline-actions { width: 100%; margin-left: 0; justify-content: space-between; }
  .setup-migration-statusline-item { flex-wrap: wrap; }
  .setup-migration-source-manual[open] { right: auto; left: 0; width: min(420px, 88vw); }
  .setup-migration-role-card { grid-template-columns: minmax(0, 1fr); }
  .setup-migration-role-actions .button,
  .setup-migration-role-empty .button { width: 100%; }
  .setup-migration-method { grid-template-columns: minmax(0, 1fr); }
  .setup-migration-actionbar { align-items: stretch; }
  .setup-migration-actionbar-left,
  .setup-migration-actionbar-right { width: 100%; margin-left: 0; justify-items: stretch; }
  .setup-migration-actionbar-left .button,
  .setup-migration-actionbar-right .button { width: 100%; }
  .setup-migration-primary-reason { max-width: none; text-align: left; }
  .setup-migration-manual-head { display: grid; gap: var(--sp-2); padding: var(--sp-3); }
  .setup-migration-manual-head .button { width: 100%; }
  .setup-migration-manual-foot .button { width: 100%; }
  .setup-migration-compact-table { min-width: 0; table-layout: auto; }
  .setup-migration-compact-table thead { display: none; }
  .setup-migration-compact-table,
  .setup-migration-compact-table tbody,
  .setup-migration-compact-table tr,
  .setup-migration-compact-table th,
  .setup-migration-compact-table td { display: block; width: auto; }
  .setup-migration-compact-table tbody tr {
    padding: var(--sp-2) var(--sp-3);
    border-bottom: 1px solid var(--t-line);
    border-left: 2px solid var(--t-line-firm);
  }
  .setup-migration-compact-table tbody tr.is-changed { border-left-color: var(--t-accent); }
  .setup-migration-compact-table tbody tr.is-lost { border-left-color: var(--t-warn); }
  .setup-migration-compact-table tbody th,
  .setup-migration-compact-table tbody td {
    border: 0;
    padding: var(--sp-1) 0;
    white-space: normal;
    overflow: visible;
  }
  .setup-migration-compact-table tbody td::before {
    content: attr(data-label) "：";
    color: var(--t-text-faint);
    font-size: var(--fs-micro);
  }
  .setup-migration-compact-table tfoot,
  .setup-migration-compact-table tfoot tr,
  .setup-migration-compact-table tfoot td { display: block; }
}

/* 动效偏好：关闭不确定进度与回执出现动画。 */
@media (prefers-reduced-motion: reduce) {
  .setup-migration-progress span { animation: none; width: 100%; opacity: .55; }
}
:root[data-motion="off"] .setup-migration-progress span { animation: none; width: 100%; opacity: .55; }

/* 开始使用 = 旧版配置引导的一页式清单：编号分区 + 一句说明 + 就地点开编辑。 */
.setup-guide-status { margin:0 0 var(--sp-3); color: var(--muted); font-size:var(--fs-body); line-height: 1.6; }
.setup-guide-list { display: grid; gap:var(--sp-2); margin:0 0 var(--sp-4); padding:0; list-style: none; }
.setup-guide-item { display: grid; grid-template-columns: 36px minmax(0, 1fr) auto; align-items: center;
  gap:var(--sp-3); padding:var(--sp-3); border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); }
.setup-guide-number { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%;
  border: 1px solid var(--line-strong); color: var(--muted); font-size:var(--fs-micro); font-variant-numeric: tabular-nums; }
.setup-guide-copy h3 { margin:0 0 var(--sp-1); color: var(--ink); font-size:var(--fs-head); line-height: 1.35; }
.setup-guide-copy p { margin:0; color: var(--muted); font-size:var(--fs-tiny); line-height: 1.6; }
@media (max-width: 720px) {
  .setup-guide-item { grid-template-columns: 36px minmax(0, 1fr); }
  .setup-guide-item > .button { grid-column: 2; justify-self: start; }
}

/* 旧版引导的分组步骤树 + 每步说明与要点清单。 */
.setup-progress > .setup-progress-group { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--sp-1); margin: 0 0 var(--sp-3); min-height: 0; }
.setup-progress > .setup-progress-group > strong, .setup-progress > .setup-progress-group > .setup-progress-steps { grid-column: 1; }
.setup-progress-group > strong { color: var(--muted); font-size: var(--fs-micro); font-weight: 700; letter-spacing: .04em; line-height:1.45; overflow-wrap:normal; word-break:keep-all; }
.setup-progress-group.complete > strong { color: var(--ink); }
.setup-progress-group.current > strong { color: var(--accent); }
.setup-progress-group.current .setup-progress-step:not(.current) { color:var(--muted); }
.setup-progress-steps { display: grid; gap: var(--sp-1); margin: 0; padding: 0; list-style: none; }
.setup-progress-step { display: grid; grid-template-columns: 30px minmax(0, 1fr); align-items: center;
  gap: var(--sp-2); min-height: 38px; color: var(--muted); font-size: var(--fs-body); line-height: 1.35; }
.setup-progress-step > span:last-child { min-width:0; overflow-wrap:anywhere; }
.setup-progress-step.current { color: var(--ink); font-weight: 700; }
.setup-progress-step.complete .setup-progress-marker { border-color: var(--line-strong); color: var(--ink); }
.setup-stage-banner { display: grid; gap: var(--sp-2); margin: 0 0 var(--sp-4); padding: var(--sp-3);
  border: 1px solid var(--line); border-radius: var(--radius-md); background: var(--surface); }
.setup-stage-body { margin: 0; max-width: 72ch; color: var(--muted); font-size: var(--fs-body); line-height: 1.7; }
.setup-checklist { display: grid; gap: var(--sp-1); margin: 0; padding: 0; list-style: none; }
.setup-checklist li { position: relative; padding-left: var(--sp-4); color: var(--ink); font-size: var(--fs-tiny); line-height: 1.6; }
.setup-checklist li::before { content: ""; position: absolute; left: 4px; top: .62em; width: 6px; height: 6px;
  border-radius: 50%; background: var(--line-strong); }
@media (max-width: 960px) {
  .setup-stage-banner { padding: var(--sp-2); }
}

/* migration-config-table.css */
/* Migration configuration comparison, shared with the reviewed guide design. */
.migration-config-review { min-width:0; color:var(--ink); font-size:var(--fs-tiny); }
.migration-config-heading { display:flex; align-items:center; justify-content:space-between; gap:var(--sp-3); padding:0 0 var(--sp-3); border-bottom:1px solid var(--line); }
.migration-config-heading h4 { margin:0; font-size:var(--fs-body); font-weight:600; }
.migration-config-heading > span { color:var(--muted); font-size:var(--fs-micro); }
.migration-config-toolbar { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:var(--sp-3); padding:var(--sp-3) 0 var(--sp-4); }
.migration-config-toolbar nav, .migration-config-tools { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-1); min-width:0; }
.migration-config-toolbar nav button { padding:var(--sp-2) var(--sp-3); min-height:32px; border:1px solid var(--line); border-radius:var(--r-pill); background:var(--surface); color:var(--muted); font:inherit; cursor:pointer; }
.migration-config-toolbar nav button[aria-pressed="true"] { border-color:var(--accent); background:var(--surface-soft); color:var(--accent); font-weight:600; }
.migration-config-search { display:flex; align-items:center; gap:var(--sp-2); width:220px; min-width:0; min-height:34px; padding:0 var(--sp-2); border:1px solid var(--line-strong); border-radius:var(--r-xs); background:var(--surface); }
.migration-config-search svg { flex:0 0 14px; width:14px; height:14px; fill:none; stroke:currentColor; stroke-width:1.5; }
.migration-config-search input { width:100%; min-width:0; padding:var(--sp-2) 0; border:0; background:transparent; color:var(--ink); font:inherit; outline-offset:3px; }
.migration-config-reset { min-height:34px; padding:var(--sp-2) var(--sp-3); border:0; background:transparent; color:var(--accent); font:inherit; cursor:pointer; }
.migration-config-table-wrap { max-height:58vh; min-height:160px; overflow:auto; border:1px solid var(--line-strong); border-radius:var(--r-xs); }
.migration-config-table { width:100%; border-collapse:separate; border-spacing:0; table-layout:fixed; font-size:inherit; line-height:1.45; text-align:left; }
.migration-config-table col.field { width:29%; }
.migration-config-table col.values { width:26%; }
.migration-config-table col.status { width:15%; }
.migration-config-table col.actions { width:30%; }
.migration-config-table th, .migration-config-table td { min-width:0; padding:var(--sp-3); border-bottom:1px solid var(--line); vertical-align:middle; overflow-wrap:anywhere; }
.migration-config-table thead { position:sticky; top:0; z-index:1; background:var(--surface-soft); }
.migration-config-table thead th { color:var(--muted); font-weight:600; font-size:var(--fs-micro); }
.migration-config-table tbody tr:last-child > * { border-bottom:0; }
.migration-config-table .migration-config-group th { padding:var(--sp-2) var(--sp-3); background:var(--surface-soft); color:var(--accent); }
.migration-config-group th > div { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-1) var(--sp-2); }
.migration-config-group small { color:var(--muted); font-size:var(--fs-micro); font-weight:400; }
.migration-config-group th > div > span { display:flex; flex-wrap:wrap; gap:var(--sp-1); margin-left:auto; }
.migration-config-field > strong { display:block; font-weight:600; }
.migration-config-field .migration-config-key { display:block; margin-top:2px; color:var(--muted); font-size:var(--fs-micro); font-weight:400; word-break:break-all; }
.migration-config-field small { display:block; margin-top:3px; color:var(--muted); font-size:var(--fs-micro); font-weight:400; line-height:1.45; }
.migration-config-diff { display:flex; align-items:baseline; flex-wrap:wrap; gap:var(--sp-1); min-width:0; font-variant-numeric:tabular-nums; }
.migration-config-diff .old { color:var(--muted); }
.migration-config-diff .arrow { color:var(--line-strong); }
.migration-config-diff strong { font-weight:600; }
.migration-config-badge { display:inline-flex; align-items:center; gap:var(--sp-1); padding:var(--sp-1) var(--sp-2); border-radius:var(--r-2xs); font-size:var(--fs-micro); white-space:nowrap; }
.migration-config-badge.pending { background:var(--t-warn-soft, #fff4df); color:var(--t-warn-ink, #946020); }
.migration-config-badge.pending::before { content:""; width:5px; height:5px; border-radius:50%; background:currentColor; }
.migration-config-badge.ready { color:var(--accent); background:var(--surface-soft); }
.migration-config-badge.muted, .migration-config-locked { color:var(--muted); font-size:var(--fs-micro); }
.migration-config-segment { display:inline-flex; max-width:100%; border:1px solid var(--line-strong); border-radius:var(--r-xs); overflow:hidden; }
.migration-config-segment button, .migration-config-mini { min-height:28px; padding:var(--sp-1) var(--sp-2); border:0; background:var(--surface); color:var(--muted); font:inherit; font-size:var(--fs-micro); cursor:pointer; }
.migration-config-segment button + button { border-left:1px solid var(--line); }
.migration-config-segment button[aria-pressed="true"] { color:var(--accent); background:var(--surface-soft); font-weight:600; }
.migration-config-mini { border:1px solid var(--line-strong); border-radius:var(--r-2xs); }
.migration-config-manual { display:flex; flex-wrap:wrap; gap:var(--sp-1); }
.migration-config-review button:hover:not(:disabled) { color:var(--accent); background:var(--surface-soft); }
.migration-config-review button:disabled { opacity:.5; cursor:not-allowed; }
.migration-config-pagination { display:flex; align-items:center; justify-content:flex-end; gap:var(--sp-2); padding:var(--sp-2) 0 0; color:var(--muted); font-size:var(--fs-micro); }
.migration-config-pagination span { margin-right:auto; }
.migration-config-summary { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:var(--sp-1) var(--sp-4); margin-top:var(--sp-3); padding:var(--sp-2) var(--sp-3); border:1px dashed var(--line-strong); border-radius:var(--r-xs); color:var(--muted); font-size:var(--fs-tiny); }
.migration-config-summary strong { color:var(--ink); font-weight:600; }
.migration-config-summary .pending { color:var(--t-warn-ink, #946020); }
.migration-config-summary .ready { color:var(--accent); }
.migration-config-hint { margin:var(--sp-2) 0 0; color:var(--muted); font-size:var(--fs-micro); line-height:1.55; }
.migration-config-empty { padding:var(--sp-6) var(--sp-4); border:1px solid var(--line); border-radius:var(--r-xs); color:var(--muted); text-align:center; }
.setup-migration-config-options { margin:var(--sp-4) 0 0; color:var(--muted); font-size:var(--fs-micro); }
.setup-migration-config-options summary { cursor:pointer; }
.setup-migration-config-options .setup-actions { margin-top:var(--sp-3); }
@media (max-width:700px) {
  .migration-config-tools { width:100%; justify-content:space-between; }
  .migration-config-search { flex:1 1 160px; }
  .migration-config-table { min-width:640px; }
  .migration-config-table-wrap { max-height:62vh; }
  .migration-config-group small { display:none; }
  .migration-config-table th, .migration-config-table td { padding:var(--sp-2); }
  .migration-config-summary { align-items:flex-start; }
}

/* backup-page.css */
/* 备份与还原工作区。
 *
 * 这一页此前没有独立样式表——模块写完却从未被加载，所以也就没人发现
 * 它引用的类名一个都没有定义。下面这些类名是从 backup-page.js 里逐个
 * 抄出来的实际渲染产物，不是照命名习惯猜的。
 *
 * 样式全部用 tokens.css 已有的变量，不新增色值：备份页在「资料与维护」
 * 下，和相邻分区视觉上必须是同一层。
 */

.backup-workspace {
  display: flex;
  flex-direction: column;
  gap:var(--sp-3);
}

.backup-notice {
  margin:0;
  padding:var(--sp-2) var(--sp-3);
  border-radius: var(--r-md);
  border: 1px solid var(--t-line);
  background: var(--t-surface-sunken);
  color: var(--t-text-soft);
  font-size:var(--fs-body);
  line-height: 1.6;
}

/* 失败与成功共用一套壳，只换边框与文字色——备份页的操作不可逆，
   大面积饱和色块会喧宾夺主。 */
.backup-notice.is-error {
  border-color: var(--t-risk);
  color: var(--t-danger);
  background: var(--t-risk-quiet);
}

.backup-loading {
  margin:0;
  padding:var(--sp-3);
  color: var(--t-text-soft);
  font-size:var(--fs-body);
}

/* ── 创建区 ───────────────────────────────────────────────────── */
.backup-create {
  display: flex;
  flex-direction: column;
  gap:var(--sp-2);
  padding:var(--sp-4);
  border:1px solid var(--t-line);
  border-radius:var(--r-sm);
  background:var(--t-surface);
}

.backup-create-title { color:var(--t-text-strong);font-size:var(--fs-body);font-weight:600; }
.backup-create label { color:var(--t-text-soft);font-size:var(--fs-tiny); }

.backup-create-row {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-2);
  align-items: center;
}

.backup-create-row input[type="text"] {
  flex: 1 1 220px;
  min-width: 0;
}

/* ── 快照列表 ─────────────────────────────────────────────────── */
.backup-list-block {
  display: flex;
  flex-direction: column;
  gap:var(--sp-2);
  padding:var(--sp-4);
  border:1px solid var(--t-line);
  border-radius:var(--r-sm);
  background:var(--t-surface);
}

.backup-list-block > header { display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);color:var(--t-text-strong); }
.backup-list-block > header small { color:var(--t-text-faint);font-size:var(--fs-micro); }

.backup-counts {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-3);
  margin:0;
  font-size:var(--fs-body);
  color: var(--t-text-soft);
}

.backup-count {
  font-variant-numeric: tabular-nums;
}

.backup-snapshot-list {
  list-style: none;
  margin:0;
  padding:0;
  display: flex;
  flex-direction: column;
  gap:var(--sp-2);
}

.backup-snapshot-row {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-2) var(--sp-3);
  align-items: center;
  padding:var(--sp-3);
  border: 1px solid var(--t-line);
  border-radius: var(--r-md);
  background: var(--t-surface);
}

.backup-snapshot-main {
  flex: 1 1 260px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap:2px;
}

.backup-snapshot-title {
  font-size:var(--fs-lead);
  font-weight: 600;
  color: var(--t-text);
}

/* 时间、字节数与哈希都要竖排对齐才好比对——哈希是拿来逐字核对的，
   比例字体下很难看出两串的差别。 */
.backup-snapshot-meta {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-2) var(--sp-3);
  font-size:var(--fs-body);
  color: var(--t-text-soft);
  font-variant-numeric: tabular-nums;
}

.backup-snapshot-note {
  font-size:var(--fs-body);
  color: var(--t-text-soft);
  overflow-wrap: anywhere;
}

.backup-snapshot-actions {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-2);
  align-items: center;
}

.backup-tag {
  display: inline-flex;
  align-items: center;
  padding:1px var(--sp-1);
  border-radius: 999px;
  border: 1px solid var(--t-line);
  font-size:var(--fs-tiny);
  color: var(--t-text-soft);
}

.backup-empty {
  padding:var(--sp-4);
  border: 1px dashed var(--t-line);
  border-radius: var(--r-md);
  color: var(--t-text-soft);
  font-size:var(--fs-body);
  text-align: center;
}

/* ── 还原 ─────────────────────────────────────────────────────── */

/* 有还原在等重启时提示条常驻：这条信息决定「现在重启会不会退回旧数据」，
   不该藏在列表里。 */
.backup-pending {
  padding:var(--sp-3);
  border: 1px solid var(--t-warn);
  border-radius: var(--r-md);
  background: var(--t-warn-quiet);
  font-size:var(--fs-body);
  line-height: 1.6;
}

.backup-preview {
  display: flex;
  flex-direction: column;
  gap:var(--sp-2);
  padding:var(--sp-3);
  border: 1px solid var(--t-risk);
  border-radius: var(--r-md);
  background: var(--t-surface);
}

.backup-preview-head {
  display:grid;
  gap:var(--sp-1);
  padding:var(--sp-2) var(--sp-3);
  border-radius:var(--r-sm);
  background:var(--t-risk);
  color:var(--t-text-invert);
  font-size:var(--fs-lead);
  font-weight: 600;
}
.backup-preview-head small { color:var(--t-text-invert);font-size:var(--fs-micro);font-weight:400;line-height:1.5; }

.backup-preview-lead {
  margin:0;
  font-size:var(--fs-body);
  line-height: 1.7;
  color: var(--t-text);
}

.backup-preview-hash {
  font-family: var(--numeric-font);
  font-size:var(--fs-body);
  overflow-wrap: anywhere;
}

/* 影响范围：还原是整根替换，多目标下不止当前角色。
   语气与 warn 同族但更轻——它是范围说明，不是风险警告。 */
.backup-preview-scope {
  margin:0;
  padding:var(--sp-2) var(--sp-3);
  border-left: 3px solid var(--m-line2);
  font-size: var(--fs-tiny);
  line-height: 1.7;
  color: var(--m-ink2);
}

/* 会替换掉什么：这是整个页面唯一需要用户读全的一段。 */
.backup-preview-warn {
  margin:0;
  padding:var(--sp-2) var(--sp-3);
  border-left: 3px solid var(--t-risk);
  font-size:var(--fs-body);
  line-height: 1.7;
  color: var(--t-danger);
}

.backup-preview-actions {
  display: flex;
  flex-wrap: wrap;
  gap:var(--sp-2);
  align-items: center;
}

/* ── 窄屏 ─────────────────────────────────────────────────────── */
@media (max-width: 640px) {
  .backup-snapshot-row {
    flex-direction: column;
    align-items: stretch;
  }

  .backup-snapshot-actions .button,
  .backup-preview-actions .button {
    flex: 1 1 auto;
  }
}

/* 读不到列表时的说明块。跟工作区容器同一套底色与边框，避免出现时跳版；
   中间给一句原因加一个出口，而不是留一块空框。 */
.backup-workspace .backup-unavailable {
  display: flex;
  flex-direction: column;
  gap:var(--sp-3);
  align-items: flex-start;
  padding:var(--sp-5);
  min-height: 96px;
  border: 1px solid var(--t-line-firm);
  border-radius: var(--r-md);
  background: var(--t-surface-sunken);
}
.backup-workspace .backup-unavailable p { margin:0; line-height: 1.6; }
.backup-workspace .backup-unavailable-actions { display: flex; gap:var(--sp-2); flex-wrap: wrap; }

/* storage-page.css */
.storage-dashboard{display:grid;gap:var(--sp-3);min-width:0;color:var(--t-text)}
.storage-usage-card,.storage-panel{min-width:0;padding:var(--sp-4);border:1px solid var(--t-line);border-radius:var(--r-sm);background:var(--t-surface)}
.storage-usage-header{display:flex;align-items:flex-end;justify-content:space-between;gap:var(--sp-4)}
.storage-usage-header>div{display:grid;gap:var(--sp-1);min-width:0}
.storage-usage-header>div:last-child{text-align:right}
.storage-usage-header span,.storage-usage-item small{color:var(--t-text-soft);font-size:var(--fs-micro)}
.storage-usage-header strong{color:var(--t-text-strong);font-size:var(--fs-title);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.storage-usage-header>div:first-child strong{font-size:var(--fs-head)}
.storage-usage-bar{display:flex;height:12px;overflow:hidden;border-radius:var(--r-pill);background:var(--t-surface-sunken)}
.storage-usage-segment{height:100%;min-width:0}
.storage-usage-segment.is-database,.storage-usage-mark.is-database{background:var(--t-ok)}
.storage-usage-segment.is-backups,.storage-usage-mark.is-backups{background:var(--t-accent-solid)}
.storage-usage-segment.is-other,.storage-usage-mark.is-other{background:var(--t-warn)}
.storage-usage-legend{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--sp-3);margin-top:var(--sp-3)}
.storage-usage-item{display:grid;grid-template-columns:10px minmax(0,1fr) auto;align-items:center;gap:var(--sp-1) var(--sp-2);min-width:0}
.storage-usage-mark{width:9px;height:9px;border-radius:50%}
.storage-usage-item>span:nth-child(2){color:var(--t-text-soft);font-size:var(--fs-tiny)}
.storage-usage-item strong{color:var(--t-text-strong);font-size:var(--fs-tiny);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
.storage-usage-item small{grid-column:2/4}
.storage-settings{display:grid;gap:var(--sp-3);min-width:0}
.storage-panel{display:grid;gap:var(--sp-3)}
.storage-panel h4{margin:0;color:var(--t-text-strong);font-size:var(--fs-body);font-weight:650}
.storage-location-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-4)}
.storage-path-field{display:grid;align-content:start;gap:var(--sp-2);min-width:0}
.storage-path-field>span{color:var(--t-text-strong);font-size:var(--fs-tiny);font-weight:600}
.storage-field-label{display:flex;align-items:center;flex-wrap:wrap;gap:var(--sp-2)}
.storage-field-label em{padding:2px var(--sp-2);border-radius:var(--r-pill);background:var(--t-ok-quiet);color:var(--t-ok-ink);font-size:var(--fs-micro);font-style:normal;font-weight:500}
.storage-path-field input,.storage-retention input{min-width:0;border:1px solid var(--t-line-firm);border-radius:var(--r-sm);background:var(--t-surface-soft);color:var(--t-text);padding:var(--sp-2) var(--sp-3);font:inherit}
.storage-path-field small,.storage-retention small{color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.55;overflow-wrap:anywhere}
.storage-location-note{margin:0;color:var(--t-text-faint);font-size:var(--fs-micro);overflow-wrap:anywhere}
.storage-location-note.is-pending{color:var(--t-warn-ink)}
.storage-retention{display:flex;flex-wrap:wrap;align-items:center;gap:var(--sp-2) var(--sp-4);margin:0;padding:0;border:0;min-width:0}
.storage-retention label{display:flex;align-items:center;gap:var(--sp-2);color:var(--t-text);font-size:var(--fs-tiny);white-space:nowrap}
.storage-retention input{width:76px;padding:var(--sp-2)}
.storage-retention small{flex-basis:100%}
.storage-cleanup-preview{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--sp-3);padding-top:var(--sp-3);border-top:1px solid var(--t-line)}
.storage-cleanup-preview>div{display:grid;gap:var(--sp-1);min-width:0}
.storage-cleanup-preview>div strong{color:var(--t-text-strong);font-size:var(--fs-tiny)}
.storage-cleanup-preview>div span,.storage-cleanup-empty{color:var(--t-text-faint);font-size:var(--fs-micro)}
.storage-cleanup-preview button.danger{color:var(--t-risk-ink)}
.storage-cleanup-empty{margin:0}
.storage-actions{display:flex;flex-wrap:wrap;gap:var(--sp-2);padding-top:var(--sp-2)}
.storage-message{margin:0;padding:var(--sp-2) var(--sp-3);border-radius:var(--r-sm);background:var(--t-ok-quiet);color:var(--t-ok-ink);font-size:var(--fs-tiny);overflow-wrap:anywhere}
.storage-message.is-error{background:var(--t-risk-quiet);color:var(--t-risk-ink)}
@media(max-width:760px){.storage-usage-legend{grid-template-columns:1fr}.storage-location-grid{grid-template-columns:minmax(0,1fr);gap:var(--sp-3)}}
@media(max-width:420px){.storage-usage-header{align-items:flex-start}.storage-usage-header strong,.storage-usage-header>div:first-child strong{font-size:var(--fs-title)}.storage-retention{align-items:flex-start;flex-direction:column}.storage-retention small{flex-basis:auto}}

/* maintenance-page.css */
.maintenance-page {
  display: grid;
  gap:var(--sp-6);
  min-width: 0;
}

.maint-board {
  display: grid;
  gap:var(--sp-3);
  min-width: 0;
  color: var(--t-text);
}

.maint-board-head {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap:var(--sp-5);
  min-height: 146px;
  overflow: hidden;
  padding:var(--sp-5) var(--sp-6);
  border: 1px solid var(--t-line-firm);
  border-radius:var(--r-sm);
  color: var(--t-text-invert);
  background-color: var(--t-text-strong);
  background-image: linear-gradient(120deg, var(--t-text-strong), var(--t-accent-ink));
  isolation: isolate;
}

.maint-board-head::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background-image: linear-gradient(to right, color-mix(in srgb, var(--t-text-invert) 7%, transparent) 1px, transparent 1px),
    linear-gradient(to bottom, color-mix(in srgb, var(--t-text-invert) 7%, transparent) 1px, transparent 1px);
  background-size: 28px 28px;
  content: "";
  mask-image: linear-gradient(90deg, black 0%, transparent 85%);
}

.maint-board-head::after {
  position: absolute;
  z-index: -1;
  right: 25%;
  bottom: -45px;
  width: 190px;
  height: 92px;
  border: 1px solid color-mix(in srgb, var(--t-text-invert) 24%, transparent);
  border-radius: 50%;
  content: "";
  transform: rotate(-18deg);
  box-shadow: 0 -10px 0 -9px color-mix(in srgb, var(--t-text-invert) 36%, transparent),
    0 -20px 0 -19px color-mix(in srgb, var(--t-text-invert) 25%, transparent);
  animation: maint-signal-drift 8s ease-in-out infinite alternate;
}

.maint-board-copy,
.maint-board-actions,
.maint-panel-heading,
.maint-usage-feature,
.maint-usage-kpis,
.maint-cache-overview,
.maint-call-row summary,
.maint-call-detail,
.maint-probe-line,
.maint-check-row,
.maint-cache-event,
.maint-board-footer,
.maintenance-config-title,
.maintenance-config-section-title {
  min-width: 0;
}

.maint-board-copy h2 {
  margin:var(--sp-2) 0 var(--sp-1);
  color: inherit;
  font-size:var(--fs-display);
  font-weight: 720;
  line-height: 1.2;
}

.maint-board-copy p {
  margin:0;
  color: color-mix(in srgb, var(--t-text-invert) 74%, transparent);
  font-size:var(--fs-body);
  line-height: 1.6;
}

.maint-eyebrow {
  display: inline-flex;
  align-items: center;
  gap:var(--sp-2);
  color: var(--t-text-faint);
  font-size:var(--fs-micro);
  font-weight: 700;
  line-height: 1.3;
  text-transform: uppercase;
}

.maint-board-copy .maint-eyebrow {
  color: color-mix(in srgb, var(--t-text-invert) 64%, transparent);
}

.maint-board-actions {
  display: grid;
  grid-template-columns: auto auto;
  align-items: center;
  justify-items: end;
  gap:var(--sp-2) var(--sp-2);
  flex: 0 0 auto;
}
.maint-board-actions .maint-live { grid-column: 1; }
.maint-board-actions .maint-updated { grid-column: 1; grid-row: 2; }
.maint-board-actions .maint-export { grid-column: 2; grid-row: 1; }
.maint-board-actions .maint-refresh { grid-column: 2; grid-row: 2; }

.maint-live {
  display: inline-flex;
  align-items: center;
  gap:var(--sp-2);
  min-height: 27px;
  padding:var(--sp-1) var(--sp-2);
  border: 1px solid color-mix(in srgb, var(--t-text-invert) 24%, transparent);
  border-radius:var(--r-pill);
  color: var(--t-text-invert);
  font-size:var(--fs-tiny);
  line-height: 1;
  white-space: nowrap;
}

.maint-live i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--t-ok);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--t-ok) 24%, transparent);
  animation: maint-pulse 2.2s ease-in-out infinite;
}

.maint-live[data-state="warn"] i { background: var(--t-warn); }
.maint-updated { color: color-mix(in srgb, var(--t-text-invert) 72%, transparent); font-size:var(--fs-tiny); }

.maint-refresh,
.maint-probe-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap:var(--sp-2);
  min-height: 34px;
  padding:0 var(--sp-3);
  border: 1px solid var(--t-line-firm);
  border-radius:var(--r-xs);
  color: var(--t-text-strong);
  background: var(--t-surface-raised);
  font: inherit;
  font-size:var(--fs-body);
  font-weight: 650;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease, transform 160ms ease;
}

.maint-refresh { color: var(--t-text-invert); border-color: color-mix(in srgb, var(--t-text-invert) 34%, transparent); background: transparent; }
.maint-refresh:hover:not(:disabled) { background: color-mix(in srgb, var(--t-text-invert) 10%, transparent); }
.maint-probe-button:hover:not(:disabled) { border-color: var(--t-accent); background: var(--t-accent-quiet); transform: translateY(-1px); }
.maint-refresh:focus-visible,
.maint-probe-button:focus-visible,
.maint-periods button:focus-visible,
.maint-probe-line select:focus-visible { outline: 2px solid var(--t-focus); outline-offset: 2px; }
.maint-refresh:disabled,
.maint-probe-button:disabled { opacity: .55; cursor: wait; }
.maint-refresh svg,
.maint-probe-button svg { width: 14px; height: 14px; }

.maint-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(290px, .9fr);
  align-items: stretch;
  gap:var(--sp-3);
}

.maint-usage-panel,
.maint-check-panel,
.maint-cache-panel,
.maint-recent-panel {
  min-width: 0;
  border: 1px solid var(--t-line);
  border-radius:var(--r-sm);
  background: var(--t-surface);
  box-shadow: var(--t-shadow);
}

.maint-usage-panel { padding:var(--sp-4) var(--sp-5) var(--sp-4); overflow: hidden; }
.maint-check-panel { display: flex; flex-direction: column; padding:var(--sp-4) var(--sp-4) var(--sp-4); }
.maint-cache-panel { padding:var(--sp-4) var(--sp-5); }
.maint-recent-panel { padding:var(--sp-4) var(--sp-5) var(--sp-3); }

.maint-panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap:var(--sp-3);
}

.maint-panel-heading h3 {
  margin:var(--sp-1) 0 0;
  color: var(--t-text-strong);
  font-size:var(--fs-title);
  font-weight: 700;
  line-height: 1.35;
}

.maint-periods {
  display: inline-flex;
  align-items: center;
  gap:2px;
  padding:3px;
  border: 1px solid var(--t-line);
  border-radius:var(--r-xs);
  background: var(--t-surface-soft);
}

.maint-periods button {
  min-width: 38px;
  min-height: 27px;
  padding:0 var(--sp-2);
  border: 0;
  border-radius:var(--r-2xs);
  color: var(--t-text-soft);
  background: transparent;
  font: inherit;
  font-size:var(--fs-tiny);
  cursor: pointer;
  transition: background-color 160ms ease, color 160ms ease, box-shadow 160ms ease;
}

.maint-periods button:hover { color: var(--t-text-strong); }
.maint-periods button.is-active { color: var(--t-accent-ink); background: var(--t-surface-raised); box-shadow: 0 1px 4px color-mix(in srgb, var(--t-text) 13%, transparent); }

.maint-usage-feature {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 136px;
  align-items: center;
  gap:var(--sp-4);
  padding:var(--sp-4) 0 var(--sp-3);
}

.maint-usage-total { display: grid; grid-template-columns: auto auto; align-items: baseline; justify-content: start; gap:3px var(--sp-2); }
.maint-usage-total > span { grid-column: 1 / -1; color: var(--t-text-soft); font-size:var(--fs-tiny); }
.maint-usage-total strong { max-width: 100%; overflow: hidden; color: var(--t-text-strong); font-size:var(--fs-hero); font-variant-numeric: tabular-nums; line-height: 1.15; text-overflow: ellipsis; }
.maint-usage-total > small { color: var(--t-text-faint); font-size:var(--fs-body); }
.maint-usage-subline { display: flex; grid-column: 1 / -1; align-items: center; gap:var(--sp-2); margin-top:2px; color: var(--t-text-faint); font-size:var(--fs-tiny); }
.maint-usage-subline i { width: 3px; height: 3px; border-radius: 50%; background: var(--t-text-faint); }

.maint-budget-meter {
  display: grid;
  justify-items: center;
  gap:var(--sp-2);
  width: 136px;
  height: 136px;
  padding-top:var(--sp-3);
  border-radius: 50%;
  background: conic-gradient(from -90deg, var(--t-accent) var(--budget-progress, 0%), var(--t-surface-sunken) 0);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--t-text) 5%, transparent);
  transition: background 600ms cubic-bezier(.2,.7,.2,1);
}

.maint-budget-meter-center {
  display: grid;
  align-content: center;
  justify-items: center;
  gap:1px;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  background: var(--t-surface);
}

.maint-budget-meter-center strong { color: var(--t-text-strong); font-size:var(--fs-display); font-variant-numeric: tabular-nums; line-height: 1.2; }
.maint-budget-meter-center span { color: var(--t-text-faint); font-size:var(--fs-micro); }
.maint-budget-caption { display: flex; align-items: center; justify-content: center; gap:var(--sp-1); width: 100%; margin-top:-var(--sp-1); color: var(--t-text-invert); font-size:var(--fs-micro); line-height: 1; white-space: nowrap; }
.maint-budget-caption b { font-weight: 700; }

.maint-chart {
  display: grid;
  grid-template-columns: repeat(var(--day-count, 7), minmax(0, 1fr));
  align-items: end;
  gap:var(--sp-1);
  min-height: 105px;
  padding:var(--sp-2) 1px 0;
  border-top: 1px solid var(--t-line);
}

.maint-chart-day { display: grid; grid-template-rows: 76px 16px; align-items: end; justify-items: center; min-width: 0; gap:var(--sp-1); }
.maint-chart-column { align-self: end; width: min(100%, 17px); height: var(--bar-height); border-radius:var(--r-2xs) 3px 1px 1px; background: linear-gradient(to top, var(--t-brand), var(--t-accent)); transform-origin: bottom; animation: maint-bar-in 540ms cubic-bezier(.18,.67,.3,1) both; }
.maint-chart-day:nth-child(even) .maint-chart-column { animation-delay: 35ms; }
.maint-chart-day small { overflow: hidden; max-width: 100%; color: var(--t-text-faint); font-size:var(--fs-micro); line-height: 1; text-align: center; text-overflow: clip; white-space: nowrap; }
.maint-chart[data-count="30"] .maint-chart-day:nth-child(3n + 2) small { visibility: hidden; }

.maint-usage-foot { display: flex; justify-content: space-between; gap:var(--sp-2); padding:var(--sp-1) 0 var(--sp-3); color: var(--t-text-faint); font-size:var(--fs-micro); }
.maint-usage-foot > span:first-child { display: inline-flex; align-items: center; gap:var(--sp-1); }
.maint-legend-token { display: inline-block; width: 7px; height: 7px; border-radius:var(--r-2xs); background: var(--t-brand); }
.maint-usage-kpis { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid var(--t-line); }
.maint-usage-kpis > div { display: grid; gap:3px; min-width: 0; padding:var(--sp-3) var(--sp-2) 0 0; }
.maint-usage-kpis > div + div { padding-left:var(--sp-2); border-left: 1px solid var(--t-line); }
.maint-usage-kpis span { overflow: hidden; color: var(--t-text-faint); font-size:var(--fs-micro); text-overflow: ellipsis; white-space: nowrap; }
.maint-usage-kpis strong { overflow: hidden; color: var(--t-text-strong); font-size:var(--fs-body); font-variant-numeric: tabular-nums; text-overflow: ellipsis; }

.maint-check-state,
.maint-cache-chip,
.maint-recent-count {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding:0 var(--sp-2);
  border-radius:var(--r-xs);
  color: var(--t-ok-ink);
  background: var(--t-ok-quiet);
  font-size:var(--fs-micro);
  font-weight: 650;
  white-space: nowrap;
}

.maint-check-state[data-state="warn"], .maint-cache-chip[data-state="warn"] { color: var(--t-warn-ink); background: var(--t-warn-quiet); }
.maint-cache-chip[data-state="unknown"] { color: var(--t-text-soft); background: var(--t-surface-sunken); }
.maint-check-list { display: grid; gap:0; margin:var(--sp-3) 0; }
.maint-check-row { display: grid; grid-template-columns: 29px minmax(0, 1fr) 25px; align-items: center; gap:var(--sp-2); min-height: 52px; border-bottom: 1px solid var(--t-line); }
.maint-check-icon { display: grid; place-items: center; width: 27px; height: 27px; border-radius:var(--r-xs); color: var(--t-accent-ink); background: var(--t-accent-quiet); }
.maint-check-icon svg { width: 14px; height: 14px; }
.maint-check-row strong { display: block; color: var(--t-text-strong); font-size:var(--fs-tiny); font-weight: 680; }
.maint-check-row small { display: block; overflow: hidden; margin-top:2px; color: var(--t-text-faint); font-size:var(--fs-micro); line-height: 1.4; text-overflow: ellipsis; white-space: nowrap; }
.maint-check-mark { display: grid; place-items: center; width: 21px; height: 21px; border-radius: 50%; color: var(--t-ok-ink); background: var(--t-ok-quiet); font-size:var(--fs-micro); font-weight: 800; }
.maint-check-row[data-state="warn"] .maint-check-mark { color: var(--t-warn-ink); background: var(--t-warn-quiet); }

.maint-probe-controls { display: grid; gap:var(--sp-1); margin-top:auto; }
.maint-probe-controls label { color: var(--t-text-soft); font-size:var(--fs-micro); font-weight: 650; }
.maint-probe-line { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap:var(--sp-2); }
.maint-probe-line select { min-width: 0; min-height: 34px; padding:0 var(--sp-2); border: 1px solid var(--t-line-firm); border-radius:var(--r-xs); color: var(--t-text); background: var(--t-surface-raised); font: inherit; font-size:var(--fs-tiny); }
.maint-probe-controls > small { color: var(--t-text-faint); font-size:var(--fs-micro); line-height: 1.4; }
.maint-test-result { display: flex; justify-content: space-between; gap:var(--sp-2); margin-top:var(--sp-3); padding:var(--sp-2) var(--sp-2); border-left: 3px solid var(--t-ok); color: var(--t-ok-ink); background: var(--t-ok-quiet); font-size:var(--fs-micro); }
.maint-test-result[data-state="unknown"], .maint-test-result[data-state="failed"] { border-color: var(--t-warn); color: var(--t-warn-ink); background: var(--t-warn-quiet); }
.maint-test-result small { color: inherit; text-align: right; }

.maint-cache-overview { display: grid; grid-template-columns: minmax(170px, .65fr) minmax(0, 1.35fr); align-items: center; gap:var(--sp-5); padding:var(--sp-4) 0 var(--sp-2); }
.maint-cache-rate { display: grid; gap:3px; }
.maint-cache-rate strong { color: var(--t-text-strong); font-size:var(--fs-hero); font-variant-numeric: tabular-nums; line-height: 1.15; }
.maint-cache-rate > span { color: var(--t-text-soft); font-size:var(--fs-micro); }
.maint-cache-meter { overflow: hidden; width: 100%; height: 5px; margin-top:var(--sp-2); border-radius:var(--r-2xs); background: var(--t-surface-sunken); }
.maint-cache-meter > span { display: block; width: var(--cache-rate); height: 100%; border-radius: inherit; background: linear-gradient(90deg, #A17BFF, #3EE0D0); transition: width 500ms cubic-bezier(.2,.7,.2,1); }
.maint-cache-measures { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap:var(--sp-2); }
.maint-cache-measures > div { display: grid; gap:var(--sp-1); min-width: 0; padding:var(--sp-2) var(--sp-2); border-left: 2px solid var(--t-line-firm); }
.maint-cache-measures > div:first-child { border-color: var(--t-ok); }
.maint-cache-measures > div:nth-child(2) { border-color: var(--t-warn); }
.maint-cache-measures > div:nth-child(3) { border-color: var(--t-accent); }
.maint-cache-measures span { color: var(--t-text-faint); font-size:var(--fs-micro); }
.maint-cache-measures strong { overflow: hidden; color: var(--t-text-strong); font-size:var(--fs-body); font-variant-numeric: tabular-nums; text-overflow: ellipsis; }
.maint-cache-note { margin:3px 0 var(--sp-4); padding:var(--sp-2) var(--sp-3); border-left: 2px solid var(--t-accent); color: var(--t-text-soft); background: var(--t-surface-soft); font-size:var(--fs-micro); line-height: 1.55; }
.maint-cache-events { border-top: 1px solid var(--t-line); padding-top:var(--sp-3); }
.maint-subhead { display: flex; justify-content: space-between; gap:var(--sp-3); color: var(--t-text-strong); font-size:var(--fs-tiny); }
.maint-subhead span { color: var(--t-text-faint); font-size:var(--fs-micro); }
.maint-cache-event-list { display: grid; margin-top:var(--sp-2); }
.maint-cache-event { display: grid; grid-template-columns: 27px minmax(0, 1fr) auto; align-items: center; gap:var(--sp-2); min-height: 50px; border-bottom: 1px solid var(--t-line); }
.maint-event-mark { display: grid; place-items: center; width: 24px; height: 24px; border-radius:var(--r-xs); color: var(--t-warn-ink); background: var(--t-warn-quiet); }
.maint-event-mark svg { width: 13px; height: 13px; }
.maint-cache-event strong { display: block; overflow: hidden; color: var(--t-text-strong); font-size:var(--fs-micro); text-overflow: ellipsis; white-space: nowrap; }
.maint-cache-event small { display: block; margin-top:3px; color: var(--t-text-faint); font-size:var(--fs-micro); }
.maint-event-next { color: var(--t-text-soft); font-size:var(--fs-micro); }

.maint-empty { display: flex; align-items: center; gap:var(--sp-2); min-height: 55px; color: var(--t-text-faint); }
.maint-empty p { margin:0; font-size:var(--fs-micro); line-height: 1.5; }
.maint-empty-mark { display: grid; place-items: center; width: 25px; height: 25px; border: 1px solid var(--t-line-firm); border-radius: 50%; color: var(--t-accent-ink); font-size:var(--fs-body); }
.maint-ranking-empty-copy { display:flex; align-items:baseline; flex-wrap:wrap; gap:0 var(--sp-2); min-width:0; }
.maint-ranking-empty-copy .maint-text-action { padding:0; white-space:nowrap; }

.maint-recent-count { color: var(--t-text-soft); background: var(--t-surface-sunken); }
.maint-call-list { display: grid; margin-top:var(--sp-2); }
.maint-call-row { border-bottom: 1px solid var(--t-line); }
.maint-call-row summary { position: relative; display: grid; grid-template-columns: 92px minmax(90px, .8fr) minmax(100px, 1fr) 105px 67px; align-items: center; gap:var(--sp-2); min-height: 40px; padding-right:var(--sp-4); list-style: none; cursor: pointer; }
.maint-call-row summary::-webkit-details-marker { display: none; }
.maint-call-row summary::after { position: absolute; right: 0; content: "＋"; color: var(--t-text-faint); }
.maint-call-row[open] summary::after { content: "−"; }
.maint-call-time, .maint-call-provider, .maint-call-total { overflow: hidden; color: var(--t-text-soft); font-size:var(--fs-micro); text-overflow: ellipsis; white-space: nowrap; }
.maint-call-task { overflow: hidden; color: var(--t-text-strong); font-size:var(--fs-micro); font-weight: 650; text-overflow: ellipsis; white-space: nowrap; }
.maint-call-total { color: var(--t-text-strong); font-variant-numeric: tabular-nums; }
.maint-call-state { color: var(--t-ok-ink); font-size:var(--fs-micro); text-align: right; white-space: nowrap; }
.maint-call-state[data-state="unknown"], .maint-call-state[data-state="dispatched"] { color: var(--t-warn-ink); }
.maint-call-detail { display:grid; gap:var(--sp-2); padding:0 0 var(--sp-3) 102px; color: var(--t-text-faint); font-size:var(--fs-micro); }
.maint-call-facts { display:flex; flex-wrap:wrap; gap:var(--sp-1) var(--sp-3); min-width:0; }
