.maint-prompt-list-state,
.maint-prompt-editor-empty { display: grid; place-items: center; gap:var(--sp-2); min-height: 160px; padding:var(--sp-5); color: var(--t-text-faint); font-size:var(--fs-tiny); text-align: center; }
.maint-prompt-editor-empty svg { width: 24px; height: 24px; color: var(--t-accent-ink); }
