.maint-prompt-editor { display: grid; align-content: start; gap:var(--sp-3); padding:var(--sp-4); background: var(--t-surface); }
.maint-prompt-editor-head { display:flex; align-items:flex-start; justify-content:space-between; gap:var(--sp-3); }
.maint-prompt-task-identity { min-width:0; }
