.maint-prompt-badge { display:flex; flex:0 0 auto; align-items:center; gap:var(--sp-1); min-height:28px; padding:0 var(--sp-2); border:1px solid var(--t-line); border-radius:var(--r-xs); color:var(--t-text-soft); background:var(--t-surface-soft); font-size:var(--fs-micro); white-space:nowrap; }
.maint-prompt-badge svg { width:14px; height:14px; }
.maint-prompt-badge[data-state="custom"] { border-color:color-mix(in srgb,var(--t-accent) 36%,var(--t-line)); color:var(--t-accent-ink); background:var(--t-accent-quiet); }
.maint-prompt-tabs { display:flex; gap:3px; padding:3px; border:1px solid var(--t-line); border-radius:var(--r-xs); background:var(--t-surface-sunken); }
.maint-prompt-tabs button { display:inline-flex; flex:1 1 0; align-items:center; justify-content:center; gap:var(--sp-1); min-width:0; min-height:36px; padding:0 var(--sp-2); border:1px solid transparent; border-radius:var(--r-2xs); color:var(--t-text-soft); background:transparent; font:inherit; font-size:var(--fs-micro); cursor:pointer; }
