.maint-prompt-boundary { display: flex; align-items: flex-start; gap:var(--sp-2); padding:var(--sp-2) var(--sp-2); border-left: 2px solid var(--t-accent); color: var(--t-text-faint); background: var(--t-accent-quiet); font-size:var(--fs-micro); line-height: 1.5; }
.maint-prompt-boundary svg { flex: 0 0 auto; width: 13px; height: 13px; color: var(--t-accent-ink); }
.maint-prompt-preview,
.maint-prompt-dynamics { min-width: 0; padding:var(--sp-2) 0; }
.maint-prompt-composition { min-width: 0; padding-top:var(--sp-2); border-top:1px solid var(--t-line); }
.maint-prompt-layers { display:grid; gap:0; margin:0; padding:0; list-style:none; }
.maint-prompt-layers li { display:grid; grid-template-columns:minmax(105px, .38fr) minmax(88px, auto) minmax(0, 1.6fr); align-items:start; gap:var(--sp-2); padding:var(--sp-2) 0; border-bottom:1px solid var(--t-line); }
