.maint-prompt-subhead { display: flex; align-items: baseline; justify-content: space-between; gap:var(--sp-2); margin-bottom:var(--sp-2); }
.maint-prompt-subhead strong { color: var(--t-text-strong); font-size:var(--fs-micro); }
