.maint-prompt-field textarea { width: 100%; min-height: 320px; resize: vertical; padding:var(--sp-3); border: 1px solid var(--t-line-firm); border-radius:var(--r-xs); outline: 0; color: var(--t-text-strong); background: var(--t-surface-raised); font: inherit; font-size:var(--fs-tiny); line-height: 1.75; }
