.sr-only { position: absolute; width: 1px; height: 1px; padding:0; margin:-1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

.maint-proactive-test { display:grid; gap:var(--sp-2); padding:var(--sp-3) 0; border-top:1px solid var(--t-line); border-bottom:1px solid var(--t-line); }
