.maint-proactive-test-controls label { display:grid; gap:var(--sp-1); min-width:min(100%, 240px); color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-proactive-test-controls select,
.maint-proactive-test-controls button { min-height:34px; padding:0 var(--sp-2); border:1px solid var(--t-line-firm); border-radius:var(--r-xs); color:var(--t-text-strong); background:var(--t-surface-raised); font:inherit; font-size:var(--fs-tiny); }
.maint-proactive-test-controls button { border-color:var(--t-accent); color:var(--t-text-invert); background:var(--t-accent-ink); cursor:pointer; }
.maint-proactive-test-controls button:disabled { opacity:.55; cursor:wait; }
.maint-proactive-test-note { margin:0; color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1.5; }
.maint-proactive-confirm,
.maint-proactive-running { display:grid; gap:var(--sp-1); padding:var(--sp-2); border-left:2px solid var(--t-warn-ink); background:var(--t-surface-soft); }
.maint-proactive-confirm > strong,
.maint-proactive-running > strong { color:var(--t-text-strong); font-size:var(--fs-tiny); }
.maint-proactive-confirm p,
.maint-proactive-running p,
.maint-proactive-notice { margin:0; color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1.5; }
.maint-proactive-confirm-actions { display:flex; flex-wrap:wrap; gap:var(--sp-1); }
.maint-proactive-confirm-actions button { min-height:34px; padding:0 var(--sp-2); border:1px solid var(--t-accent); border-radius:var(--r-xs); color:var(--t-text-invert); background:var(--t-accent-ink); font:inherit; font-size:var(--fs-tiny); cursor:pointer; }
.maint-proactive-confirm-actions button:focus-visible { outline:2px solid var(--t-focus); outline-offset:2px; }
.maint-proactive-confirm-actions .maint-proactive-confirm-cancel { border-color:var(--t-line-firm); color:var(--t-text-strong); background:var(--t-surface-raised); }
.maint-proactive-notice { padding:var(--sp-1) var(--sp-2); border-left:2px solid var(--t-line-firm); }
.maint-proactive-result { display:grid; gap:var(--sp-2); padding:var(--sp-2); border-left:2px solid var(--t-line-firm); background:var(--t-surface-soft); }
.maint-proactive-result[data-state="failed"] { border-color:var(--t-risk); }
.maint-proactive-result[data-state="passed"] { border-color:var(--t-ok); }
.maint-proactive-result > strong { color:var(--t-text-strong); font-size:var(--fs-tiny); }
.maint-proactive-result .maint-proactive-skip-reason { color:var(--t-text-soft); }
.maint-proactive-result code { overflow-wrap:anywhere; color:var(--t-warn-ink); font-size:var(--fs-micro); }
.maint-proactive-result pre { max-height:220px; overflow:auto; margin:0; white-space:pre-wrap; overflow-wrap:anywhere; color:var(--t-text-soft); font:inherit; font-size:var(--fs-micro); }
.maint-proactive-technical { display:grid; gap:var(--sp-1); border-top:1px solid var(--t-line); padding-top:var(--sp-1); }
.maint-proactive-technical summary { width:fit-content; color:var(--t-text-faint); font-size:var(--fs-micro); cursor:pointer; }
.maint-proactive-result p { margin:0; color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1.5; }
.maint-proactive-result ol { display:grid; gap:3px; margin:0; padding-left:calc(var(--sp-4) + var(--sp-1)); color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-proactive-result li { display:flex; justify-content:space-between; gap:var(--sp-2); }
.maint-proactive-result li strong { color:var(--t-text-soft); font-weight:600; }

@media (max-width: 920px) {
  .maint-prompt-workspace { grid-template-columns:minmax(0, 1fr); }
  .maint-prompt-catalog { position:static; }
  .maint-prompt-task-list { max-height:240px; }
  .maint-prompt-meta { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .maint-prompt-section { gap:var(--sp-3); }
  .maint-prompt-selector { grid-template-columns:minmax(0, 1fr); gap:var(--sp-1); }
  .maint-prompt-section > .maint-panel-heading { align-items: flex-start; flex-direction: column; }
  .maint-prompt-summary { flex-wrap:wrap; gap:var(--sp-2); }
  .maint-prompt-workspace { grid-template-columns:minmax(0, 1fr); }
  .maint-prompt-catalog,
  .maint-prompt-editor { padding:var(--sp-3); }
  .maint-prompt-catalog-tools { grid-template-columns:minmax(0, 1fr) auto; align-items:center; }
  .maint-prompt-groups { display:flex; overflow-x:auto; padding-bottom:var(--sp-2); scrollbar-width:thin; }
  .maint-prompt-group { flex:0 0 auto; gap:var(--sp-2); }
  .maint-prompt-task-list { max-height:190px; }
  .maint-prompt-task { min-height:66px; }
  .maint-prompt-field textarea { height:220px; min-height:180px; }
  .maint-prompt-editor-foot { position:static; align-items:flex-start; flex-direction:column; }
  .maint-prompt-status { width:100%; }
  .maint-prompt-actions { width:100%; justify-content:flex-start; }
}
@media (max-width: 420px) {
  .maint-prompt-meta { grid-template-columns: minmax(0, 1fr); }
  .maint-prompt-editor-head { flex-direction: column; }
  .maint-prompt-tabs button { gap:var(--sp-1); padding:0 var(--sp-1); font-size:var(--fs-micro); }
  .maint-prompt-tabs button svg { width:12px; height:12px; }
  .maint-prompt-catalog-tools { grid-template-columns:minmax(0, 1fr); }
  .maint-prompt-mode { width:100%; }
  .maint-prompt-dynamic-list > div { grid-template-columns: minmax(0, 1fr); gap:3px; }
  .maint-prompt-provenance { align-items:flex-start; }
  .maint-prompt-provenance > i { align-self:center; }
  .maint-prompt-status { align-items:flex-start; flex-direction:column; gap:2px; }
  .maint-prompt-actions button { flex:1 1 auto; }
  .maint-prompt-layers li { grid-template-columns:minmax(0, 1fr) auto; gap:var(--sp-1) var(--sp-2); }
  .maint-prompt-layers p { grid-column:1 / -1; }
}

/* Keep the diagnostics view responsive to its embedded panel width. */
.maint-diagnostics-panel {
  display:grid;
  gap:var(--sp-3);
  container-name:maint-diagnostics;
  container-type:inline-size;
}
.maint-diagnostics-panel > .maint-panel-heading { align-items:flex-start; }
.maint-diagnostic-overview,
.maint-diagnostic-signals,
