.data-page-view-head h3 { margin:0; color:var(--t-text-strong); font-size:var(--fs-lead); font-weight:600; }
.data-record-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:var(--sp-3); }
.data-record-card {
