/* ===== 动效强化（Token 统计页）===== */
@keyframes maint-meter-in { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes maint-ring-in { from { opacity:0; transform: scale(.9) rotate(-10deg); } to { opacity:1; transform: scale(1) rotate(0deg); } }
@keyframes maint-chart-line-in { from { stroke-dashoffset:100; } to { stroke-dashoffset:0; } }
@keyframes maint-chart-dot-in { from { opacity:0; transform:scale(.2); } to { opacity:1; transform:scale(1); } }
@keyframes maint-chart-day-point-in { from { opacity:0; } to { opacity:1; } }

/* 预算横条 / 软限额条 / 构成排行条：入场从左生长 */
.maint-budget-track > i,
.maint-soft-meter i,
.maint-ranking-track i { transform-origin: left center; animation: maint-meter-in 520ms cubic-bezier(.2,.7,.2,1) both; }

/* 构成排行逐行接力生长 */
.maint-ranking-row:nth-child(2) .maint-ranking-track i { animation-delay: 45ms; }
.maint-ranking-row:nth-child(3) .maint-ranking-track i { animation-delay: 90ms; }
.maint-ranking-row:nth-child(4) .maint-ranking-track i { animation-delay: 135ms; }
.maint-ranking-row:nth-child(5) .maint-ranking-track i { animation-delay: 180ms; }
.maint-ranking-row:nth-child(6) .maint-ranking-track i { animation-delay: 225ms; }
.maint-ranking-row:nth-child(7) .maint-ranking-track i { animation-delay: 270ms; }
.maint-ranking-row:nth-child(n + 8) .maint-ranking-track i { animation-delay: 300ms; }

/* 构成环：缩放微旋入场 */
.maint-composition-ring { animation: maint-ring-in 460ms cubic-bezier(.2,.7,.2,1) both; }

/* 趋势柱逐列生长，折线随后绘出，点位逐个浮现。 */
.maint-token-trend-panel .maint-chart-column > i { transform-origin: bottom; animation: maint-bar-in 520ms cubic-bezier(.18,.67,.3,1) both; animation-delay: var(--trend-delay, 0ms); }
.maint-token-trend-panel .maint-chart-column > i:nth-of-type(2) { animation-delay: calc(var(--trend-delay, 0ms) + 70ms); }
.maint-token-trend-panel .maint-chart-column > i:nth-of-type(3) { animation-delay: calc(var(--trend-delay, 0ms) + 140ms); }

/* 明细 / 趋势 / 构成 面板切换：内容淡入上浮（复用 maint-focus-enter） */
.maint-token-detail-panel:not([hidden]),
.maint-token-trend-panel:not([hidden]),
.maint-token-breakdown-panel:not([hidden]) { animation: maint-focus-enter 220ms ease both; }

/* 页签与分段控件：状态切换过渡 */
.maint-token-detail-tabs button,
.maint-trend-tabs button,
.maint-breakdown-tabs button { transition: color 160ms ease, border-color 160ms ease, background-color 160ms ease; }

/* 弱动效偏好：入场动画全部关闭 */
@media (prefers-reduced-motion: reduce) {
  .maint-budget-track > i,
  .maint-soft-meter i,
  .maint-ranking-track i,
  .maint-composition-ring,
  .maint-token-detail-panel:not([hidden]),
  .maint-token-trend-panel:not([hidden]),
  .maint-token-breakdown-panel:not([hidden]),
  .maint-token-trend-panel .maint-chart-column > i,
  .maint-token-trend-panel .maint-chart-total-line,
  .maint-token-trend-panel .maint-chart-total-dot,
  .maint-token-trend-panel .maint-chart-day-point { animation:none; }
  .maint-token-trend-panel .maint-chart-total-line { animation:none; opacity:1; stroke-dashoffset:0; }
  .maint-token-trend-panel .maint-chart-total-dot { animation:none; opacity:1; transform:none; }
  .maint-token-trend-panel .maint-chart-day-point { opacity:1; transform:translateX(-50%); }
}
:root[data-motion="off"] .maint-budget-track > i,
:root[data-motion="off"] .maint-soft-meter i,
:root[data-motion="off"] .maint-ranking-track i,
:root[data-motion="off"] .maint-composition-ring,
:root[data-motion="off"] .maint-token-detail-panel:not([hidden]),
:root[data-motion="off"] .maint-token-trend-panel:not([hidden]),
:root[data-motion="off"] .maint-token-breakdown-panel:not([hidden]),
:root[data-motion="off"] .maint-token-trend-panel .maint-chart-column > i,
:root[data-motion="off"] .maint-token-trend-panel .maint-chart-day-point { animation:none; }
:root[data-motion="off"] .maint-token-trend-panel .maint-chart-total-line { animation:none; opacity:1; stroke-dashoffset:0; }
:root[data-motion="off"] .maint-token-trend-panel .maint-chart-total-dot { animation:none; opacity:1; transform:none; }
:root[data-motion="off"] .maint-token-trend-panel .maint-chart-day-point { opacity:1; transform:translateX(-50%); }

/* ===== 鼠标交互层（hover / active / focus）===== */
/* 页签：hover 变强调色，键盘焦点圈 */
.maint-token-detail-tabs button:hover,
.maint-trend-tabs button:hover,
.maint-breakdown-tabs button:hover { color: var(--t-text-strong); }
.maint-breakdown-tabs button:hover { background: var(--t-surface-soft); }
.maint-trend-tabs button:focus-visible,
.maint-breakdown-tabs button:focus-visible { outline: 2px solid var(--t-focus); outline-offset: -2px; }

/* 趋势柱 / 小时柱：滤镜平滑过渡；日柱 hover 点亮日期标签；按压微暗 */
.maint-chart-column,
.maint-hour-bar > span { transition: filter 140ms ease; }
.maint-token-trend-panel .maint-chart-day:hover small:not([aria-hidden="true"]) { color: var(--t-text-strong); }
.maint-token-trend-panel .maint-chart-day:active .maint-chart-column { filter: brightness(.9); }

/* 排行行：背景过渡 + hover 点亮名称（行本身是筛选按钮） */
.maint-ranking-row { transition: background-color 140ms ease; }
button.maint-ranking-row:hover .maint-ranking-label { color: var(--t-text-strong); }

/* 折叠摘要（统计口径 / 来源对照 / 更多指标）hover */
.maint-token-drill > summary,
.maint-source-details > summary,
.maint-token-source-comparison > summary { transition: color 140ms ease; }
.maint-token-drill > summary:hover,
.maint-source-details > summary:hover,
.maint-token-source-comparison > summary:hover { color: var(--t-text-strong); }

/* 构成环：hover 轻微提亮 */
.maint-composition-ring { transition: filter 200ms ease; }
.maint-composition-ring:hover { filter: saturate(1.08) brightness(1.03); }

/* 按压反馈：操作按钮与可选行 */
.maint-refresh:active:not(:disabled),
.maint-probe-button:active:not(:disabled),
.maint-export:active,
.maint-balance-query:active:not(:disabled),
.maint-open-recent:active,
.maint-source-compare-row:active,
.maint-periods button:active { transform: translateY(0) scale(.97); }

/* 日期输入 hover */
.maint-date-control input:hover:not(:disabled) { border-color: var(--t-line-firm); }

.maint-efficiency-page { display:grid; gap:var(--sp-3); min-width:0; }
.maint-efficiency-panel { min-width:0; padding:var(--sp-4) var(--sp-5); border:1px solid var(--t-line); border-radius:var(--r-sm); background:var(--t-surface); box-shadow:var(--t-shadow); }
.maint-efficiency-panel > .maint-panel-heading { align-items:flex-end; margin-bottom:var(--sp-3); }
.maint-efficiency-count { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-efficiency-metrics { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); border-top:1px solid var(--t-line); border-left:1px solid var(--t-line); }
.maint-efficiency-metric { display:grid; align-content:start; gap:var(--sp-2); min-width:0; min-height:82px; padding:var(--sp-3); border-right:1px solid var(--t-line); border-bottom:1px solid var(--t-line); }
.maint-efficiency-metric span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-efficiency-metric strong { color:var(--t-text-strong); font-size:var(--fs-title); font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
.maint-efficiency-analysis { display:grid; grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr); gap:var(--sp-3); min-width:0; }
.maint-efficiency-coverage { display:grid; gap:var(--sp-3); }
.maint-efficiency-coverage-row { display:grid; grid-template-columns:minmax(0,1fr) auto; align-items:center; gap:var(--sp-1) var(--sp-3); min-width:0; }
.maint-efficiency-coverage-row span { color:var(--t-text-soft); font-size:var(--fs-tiny); }
.maint-efficiency-coverage-row strong { color:var(--t-text-strong); font-size:var(--fs-tiny); font-variant-numeric:tabular-nums; }
.maint-efficiency-coverage-row > i { grid-column:1 / -1; display:block; height:5px; overflow:hidden; border-radius:var(--r-pill); background:var(--t-surface-sunken); }
.maint-efficiency-coverage-row > i::after { display:block; width:var(--coverage-width,0%); height:100%; border-radius:inherit; background:var(--t-accent); content:""; }
.maint-efficiency-trend-panel { display:flex; flex-direction:column; }
.maint-efficiency-daily { --trend-labels:44px; display:flex; flex:1; flex-direction:column; gap:var(--sp-3); min-width:0; }
.maint-efficiency-legend { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-2) var(--sp-4); }
.maint-efficiency-legend-item { display:inline-flex; align-items:center; gap:var(--sp-2); color:var(--t-text-soft); font-size:var(--fs-micro); }
.maint-efficiency-legend-item > i,.maint-efficiency-day-readout i { flex:none; width:10px; height:10px; border-radius:2px; }
.maint-efficiency-daily [data-series="core"] { background:var(--t-accent); }
.maint-efficiency-daily [data-series="legacy"] { background:repeating-linear-gradient(135deg,transparent 0 3px,color-mix(in srgb,var(--t-surface) 45%,transparent) 3px 5px),var(--t-warn); }
.maint-efficiency-trend-meta { display:flex; align-items:center; justify-content:space-between; gap:var(--sp-2); color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1; }
.maint-efficiency-trend-chart { display:grid; flex:1; grid-template-columns:34px minmax(0,1fr); gap:var(--sp-2); min-width:0; min-height:248px; padding-top:var(--sp-1); }
.maint-efficiency-trend-axis { position:relative; margin-bottom:var(--trend-labels); color:var(--t-text-faint); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; text-align:right; }
.maint-efficiency-trend-axis > span { position:absolute; top:var(--tick-position); right:0; translate:0 -50%; white-space:nowrap; }
.maint-efficiency-trend-plot { position:relative; min-width:0; }
.maint-efficiency-trend-guides { position:absolute; inset:0 0 var(--trend-labels); display:flex; flex-direction:column; justify-content:space-between; pointer-events:none; }
.maint-efficiency-trend-guides > i { width:100%; border-top:1px dashed var(--t-line); }
.maint-efficiency-trend-guides > i:last-child { border-top-style:solid; border-color:var(--t-line-firm); }
.maint-efficiency-trend-columns { position:absolute; inset:0; display:grid; grid-template-columns:repeat(var(--day-count,7),minmax(0,1fr)); min-width:0; }
.maint-efficiency-day { position:relative; display:grid; grid-template-rows:minmax(0,1fr) 18px 16px; gap:var(--sp-1); min-width:0; border-radius:var(--r-xs); text-align:center; outline-offset:3px; }
.maint-efficiency-day:focus-visible { outline:2px solid var(--t-accent); }
.maint-efficiency-day-bars { display:flex; align-items:flex-end; justify-content:center; gap:var(--sp-1); min-height:0; padding:0 3px; }
.maint-efficiency-trend-bar,.maint-efficiency-trend-gap { display:block; flex:0 1 16px; width:16px; max-width:20px; min-height:2px; border-radius:var(--r-xs) var(--r-xs) 0 0; }
.maint-efficiency-trend-bar { height:var(--bar-height,0%); transform-origin:center bottom; animation:maint-bar-in 540ms cubic-bezier(.18,.67,.3,1) both; transition:filter 160ms ease,translate 160ms ease; }
.maint-efficiency-trend-gap { height:1px; visibility:hidden; }
.maint-efficiency-day:hover .maint-efficiency-trend-bar,.maint-efficiency-day:focus-visible .maint-efficiency-trend-bar { filter:brightness(1.1); }
.maint-efficiency-day:hover time,.maint-efficiency-day:focus-visible time { color:var(--t-text-strong); }
.maint-efficiency-day > time,.maint-efficiency-day > small { color:var(--t-text-soft); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; line-height:1.4; white-space:nowrap; }
.maint-efficiency-day > small { color:var(--t-text-faint); }
.maint-efficiency-date-compact { display:none; }
.maint-efficiency-day-detail { position:absolute; z-index:4; bottom:calc(var(--trend-labels) + var(--sp-2)); left:50%; display:none; gap:var(--sp-3); width:max-content; min-width:185px; padding:var(--sp-3); border:1px solid var(--t-line-firm); border-radius:var(--r-sm); color:var(--t-text-soft); background:var(--t-surface-raised); box-shadow:var(--t-shadow-lift); translate:-50% 0; text-align:left; pointer-events:none; }
.maint-efficiency-day:hover .maint-efficiency-day-detail,.maint-efficiency-day:focus-visible .maint-efficiency-day-detail { display:grid; }
.maint-efficiency-day:last-child .maint-efficiency-day-detail { left:auto; right:0; translate:0 0; }
.maint-efficiency-day:first-child .maint-efficiency-day-detail { left:0; right:auto; translate:0 0; }
.maint-efficiency-day-detail > strong { color:var(--t-text-strong); font-size:var(--fs-micro); font-weight:600; white-space:nowrap; }
.maint-efficiency-day-readout { display:grid; gap:var(--sp-1); font-size:var(--fs-micro); }
.maint-efficiency-day-readout > span { display:flex; align-items:center; gap:var(--sp-2); }
.maint-efficiency-day-readout > b { color:var(--t-text-strong); font-weight:600; }
.maint-efficiency-day-readout > small { color:var(--t-text-faint); font-size:inherit; }
.maint-efficiency-recent { display:grid; gap:0; }
.maint-efficiency-recent > .maint-panel-heading { margin-bottom:var(--sp-2); }
.maint-efficiency-sample { min-width:0; border-top:1px solid var(--t-line); }
.maint-efficiency-sample > summary { display:grid; grid-template-columns:minmax(0,1.4fr) minmax(240px,.8fr); align-items:center; gap:var(--sp-3); min-height:76px; padding:var(--sp-3) 0; color:var(--t-text-soft); cursor:pointer; }
.maint-efficiency-sample-overview { display:grid; gap:var(--sp-2); min-width:0; }
.maint-efficiency-sample-overview-head { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-2) var(--sp-3); min-width:0; }
.maint-efficiency-sample-overview-head time { color:var(--t-text-strong); font-size:var(--fs-tiny); font-variant-numeric:tabular-nums; }
.maint-efficiency-sample-facts { color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1.5; overflow-wrap:anywhere; }
.maint-efficiency-sample-timings { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--sp-1); min-width:0; }
.maint-efficiency-sample-timings > div { display:grid; gap:var(--sp-1); min-width:0; padding:var(--sp-2) var(--sp-3); background:var(--t-surface-soft); }
.maint-efficiency-sample-timings span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-efficiency-sample-timings strong { color:var(--t-text-strong); font-size:var(--fs-tiny); font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
.maint-efficiency-status { justify-self:start; padding:3px var(--sp-2); border-radius:var(--r-2xs); font-size:var(--fs-micro); white-space:nowrap; }
.maint-efficiency-status[data-state="ok"] { color:var(--t-ok-ink); background:var(--t-ok-quiet); }
.maint-efficiency-status[data-state="warn"] { color:var(--t-warn-ink); background:var(--t-warn-quiet); }
.maint-efficiency-status[data-state="unknown"],.maint-efficiency-status[data-state="pending"] { color:var(--t-text-soft); background:var(--t-surface-soft); }
.maint-efficiency-detail { display:grid; gap:var(--sp-3); padding:0 0 var(--sp-3) var(--sp-4); }
.maint-efficiency-cumulative,.maint-efficiency-flow { min-width:0; }
.maint-efficiency-cumulative-head,.maint-efficiency-flow-head { display:flex; align-items:baseline; flex-wrap:wrap; gap:var(--sp-1) var(--sp-2); margin-bottom:var(--sp-2); }
.maint-efficiency-cumulative-head strong,.maint-efficiency-flow-head strong { color:var(--t-text-soft); font-size:var(--fs-micro); font-weight:650; }
.maint-efficiency-cumulative-head span,.maint-efficiency-flow-head span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-efficiency-cumulative-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); border:1px solid var(--t-line); background:var(--t-line); gap:1px; }
.maint-efficiency-cumulative-item { display:grid; align-content:start; gap:var(--sp-1); min-width:0; padding:var(--sp-2) var(--sp-3); background:var(--t-surface-soft); }
.maint-efficiency-cumulative-item span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-efficiency-cumulative-item strong { color:var(--t-accent-ink); font-size:var(--fs-body); font-variant-numeric:tabular-nums; overflow-wrap:anywhere; }
.maint-efficiency-timeline { position:relative; display:grid; gap:0; margin:0; padding:var(--sp-1) 0; list-style:none; }
.maint-efficiency-timeline::before { position:absolute; top:9px; bottom:9px; left:6px; width:1px; background:var(--t-line-firm); content:""; }
.maint-efficiency-timeline-event,.maint-efficiency-timeline-stage { position:relative; display:grid; grid-template-columns:14px minmax(0,1fr); align-items:start; gap:var(--sp-2); min-width:0; }
.maint-efficiency-timeline-event { min-height:34px; }
.maint-efficiency-timeline-pin { position:relative; z-index:1; display:block; width:12px; height:12px; margin-top:2px; border:2px solid var(--t-accent-ink); border-radius:50%; background:var(--t-surface); }
.maint-efficiency-timeline-event[data-observed="false"] .maint-efficiency-timeline-pin { border-color:var(--t-line-firm); background:var(--t-surface-soft); }
.maint-efficiency-event-copy { display:flex; align-items:baseline; justify-content:space-between; flex-wrap:wrap; gap:2px var(--sp-3); min-width:0; padding:0 0 var(--sp-2); }
.maint-efficiency-event-copy > span { color:var(--t-text-soft); font-size:var(--fs-tiny); }
.maint-efficiency-event-copy > time { color:var(--t-text-strong); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; }
.maint-efficiency-timeline-event[data-observed="false"] .maint-efficiency-event-copy > time { color:var(--t-text-faint); }
.maint-efficiency-timeline-stage { min-height:35px; }
.maint-efficiency-timeline-rail { display:block; justify-self:center; width:1px; min-height:23px; background:var(--t-line-firm); }
.maint-efficiency-stage-copy { display:flex; align-items:baseline; justify-content:space-between; flex-wrap:wrap; gap:2px var(--sp-3); min-width:0; margin:0 0 var(--sp-2); padding:var(--sp-1) var(--sp-2); border-left:2px solid var(--t-accent); background:var(--t-accent-quiet); }
.maint-efficiency-stage-copy > span { color:var(--t-accent-ink); font-size:var(--fs-micro); }
.maint-efficiency-stage-copy > strong { color:var(--t-accent-ink); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; }
.maint-efficiency-timeline-stage[data-observed="false"] .maint-efficiency-stage-copy { border-left-color:var(--t-line-firm); background:var(--t-surface-soft); }
.maint-efficiency-timeline-stage[data-observed="false"] .maint-efficiency-stage-copy > span,
.maint-efficiency-timeline-stage[data-observed="false"] .maint-efficiency-stage-copy > strong { color:var(--t-text-faint); }
.maint-efficiency-trace-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--sp-4); margin-top:var(--sp-3); padding-top:var(--sp-3); border-top:1px solid var(--t-line); }
.maint-efficiency-trace-section { min-width:0; }
.maint-efficiency-trace-head { display:flex; align-items:baseline; justify-content:space-between; flex-wrap:wrap; gap:var(--sp-1) var(--sp-3); margin-bottom:var(--sp-2); }
.maint-efficiency-trace-head > strong { color:var(--t-text-soft); font-size:var(--fs-micro); font-weight:650; }
.maint-efficiency-trace-head > span,.maint-efficiency-trace-empty,.maint-efficiency-trace-note { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-efficiency-injection-list,.maint-efficiency-call-list { display:grid; gap:var(--sp-1); margin:0; padding:0; list-style:none; }
.maint-efficiency-material,.maint-efficiency-offered-tool,.maint-efficiency-call { display:grid; grid-template-columns:minmax(0,1fr) auto; align-items:baseline; gap:var(--sp-1) var(--sp-3); min-width:0; padding:var(--sp-2); background:var(--t-surface-soft); }
.maint-efficiency-material > span,.maint-efficiency-offered-tool > span { min-width:0; color:var(--t-text-soft); font-size:var(--fs-micro); overflow-wrap:anywhere; }
.maint-efficiency-material > small,.maint-efficiency-offered-tool > small { color:var(--t-text-faint); font-size:var(--fs-micro); white-space:nowrap; }
.maint-efficiency-material > small { white-space:normal; text-align:right; }
.maint-efficiency-material[data-state="ready"] > small { color:var(--t-ok-ink); }
.maint-efficiency-material[data-state="deferred"] > small { color:var(--t-warn-ink); }
.maint-efficiency-call { align-items:center; border-left:2px solid var(--t-accent); }
.maint-efficiency-call[data-state="unknown"] { border-left-color:var(--t-warn); }
.maint-efficiency-call[data-state="not_started"],.maint-efficiency-call[data-state="failed"] { border-left-color:var(--t-risk); }
.maint-efficiency-call > div { display:grid; gap:3px; min-width:0; }
.maint-efficiency-call > div > strong { color:var(--t-text-strong); font-size:var(--fs-micro); overflow-wrap:anywhere; }
.maint-efficiency-call > div > small { color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1.45; overflow-wrap:anywhere; }
.maint-efficiency-call > div > small em { color:var(--t-risk-ink); font-style:normal; }
.maint-efficiency-call > div > .maint-efficiency-call-diagnostic { color:var(--t-text-soft); }
.maint-efficiency-call > b { align-self:start; padding:2px var(--sp-1); color:var(--t-text-strong); background:var(--t-surface); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; white-space:nowrap; }
.maint-efficiency-call[data-kind="extension"] { border-left-color:var(--t-warn-ink); }
.maint-efficiency-call > div { display:grid; gap:2px; min-width:0; }
.maint-efficiency-call strong { color:var(--t-text-soft); font-size:var(--fs-micro); font-weight:600; overflow-wrap:anywhere; }
.maint-efficiency-call small { color:var(--t-text-faint); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; }
.maint-efficiency-call > b { color:var(--t-text-strong); font-size:var(--fs-micro); font-variant-numeric:tabular-nums; white-space:nowrap; }
.maint-efficiency-trace-empty,.maint-efficiency-trace-note { margin:var(--sp-2) 0 0; }

@media (max-width:900px) {
  .maint-efficiency-analysis { grid-template-columns:minmax(0,1fr); }
  .maint-efficiency-trace-grid { grid-template-columns:minmax(0,1fr); }
}
@media (max-width:640px) {
  .maint-efficiency-panel { padding:var(--sp-3); }
  .maint-efficiency-metrics { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .maint-efficiency-metric { min-height:72px; padding:var(--sp-2); }
  .maint-efficiency-metric strong { font-size:var(--fs-body); }
  .maint-efficiency-trend-chart { grid-template-columns:28px minmax(0,1fr); gap:var(--sp-1); min-height:224px; }
  .maint-efficiency-legend { gap:var(--sp-2) var(--sp-3); }
  .maint-efficiency-day-bars { gap:2px; padding:0 2px; }
  .maint-efficiency-date-full { display:none; }
  .maint-efficiency-date-compact { display:inline; }
  .maint-efficiency-sample > summary { grid-template-columns:minmax(0,1fr); gap:var(--sp-2); padding:var(--sp-3) 0; }
  .maint-efficiency-sample-timings > div { padding:var(--sp-2); }
  .maint-efficiency-detail { padding-left:0; }
  .maint-efficiency-detail { gap:var(--sp-3); }
  .maint-efficiency-cumulative-item { padding:var(--sp-2); }
  .maint-efficiency-cumulative-item strong { font-size:var(--fs-micro); }
  .maint-efficiency-event-copy { display:grid; gap:2px; }
}

@media (prefers-reduced-motion:reduce) {
  .maint-efficiency-coverage-row > i::after,.maint-efficiency-trend-bar { animation:none; transition:none; }
}

/* Cache diagnostics: the design's charts use live receipts and request profiles. */
.maint-cache-panel {
  display:grid; gap:var(--sp-3); min-width:0; padding:0;
  border:0; background:transparent; box-shadow:none;
}
.maint-cache-panel > .maint-panel-heading { padding:0 2px; }
.maint-cache-panel > .maint-panel-heading .maint-scope-note { margin:var(--sp-1) 0 0; }
.maint-cache-filters { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-3) var(--sp-4); min-width:0; padding:var(--sp-2) var(--sp-3); border:1px solid var(--t-line); border-radius:var(--r-xs); background:var(--t-surface); }
.maint-cache-source-control { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-2); min-width:0; }
.maint-cache-source-control > span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-cache-filters .maint-token-range { display:flex; align-items:center; flex-wrap:wrap; gap:var(--sp-2); flex:1; min-width:0; }
.maint-cache-filters .maint-token-controls { flex-wrap:wrap; }
.maint-cache-filters .maint-date-control { margin-left:auto; }
.maint-cache-top { display:grid; grid-template-columns:minmax(310px,.9fr) minmax(0,1.3fr); gap:var(--sp-3); min-width:0; }
.maint-cache-top > .maint-cache-section { display:flex; flex-direction:column; }
.maint-cache-split { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--sp-3); min-width:0; }
.maint-cache-section { min-width:0; padding:var(--sp-3) var(--sp-4); border:1px solid var(--t-line); border-radius:var(--r-xs); background:var(--t-surface); }
.maint-cache-section .maint-subhead { align-items:center; flex-wrap:wrap; gap:var(--sp-1) var(--sp-2); margin-bottom:var(--sp-3); }
.maint-cache-section .maint-subhead > strong,
.maint-cache-signature-head > span { display:inline-flex; align-items:center; gap:var(--sp-2); }
.maint-cache-section .maint-subhead svg,
.maint-cache-signature-head > span svg { flex:0 0 15px; width:15px; height:15px; color:var(--t-accent-ink); }
.maint-cache-section .maint-subhead > span { line-height:1.5; }
.maint-cache-rate-body { display:grid; grid-template-columns:132px minmax(0,1fr); align-items:center; gap:var(--sp-3); }
.maint-cache-donut { position:relative; width:132px; height:132px; }
.maint-cache-donut > svg { display:block; width:100%; height:100%; transform-origin:center; transition:transform 220ms cubic-bezier(.2,.7,.2,1),filter 220ms ease; }
.maint-cache-donut circle { fill:none; stroke-width:11; }
.maint-cache-ring-track { stroke:var(--t-surface-sunken); }
.maint-cache-ring-fill { stroke-linecap:round; animation:maint-cache-ring-enter 680ms cubic-bezier(.2,.7,.2,1) both; }
.maint-cache-panel #maint-cache-rate-gradient stop:nth-of-type(1) { stop-color:#A17BFF; }
.maint-cache-panel #maint-cache-rate-gradient stop:nth-of-type(2) { stop-color:#6FA2FF; }
.maint-cache-panel #maint-cache-rate-gradient stop:nth-of-type(3) { stop-color:#3EE0D0; }
.maint-cache-donut > div { position:absolute; inset:0; display:grid; align-content:center; justify-items:center; gap:var(--sp-1); }
.maint-cache-donut strong { color:#3FE0A6; font-size:var(--fs-display); font-variant-numeric:tabular-nums; line-height:1.2; }
.maint-cache-donut span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-cache-rate-copy { display:grid; gap:var(--sp-2); min-width:0; }
.maint-cache-rate-copy > span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-cache-rate-copy > div { display:flex; align-items:baseline; flex-wrap:wrap; gap:3px; font-variant-numeric:tabular-nums; }
.maint-cache-rate-copy > div > strong { color:var(--t-text-strong); font-size:var(--fs-title); overflow-wrap:anywhere; }
.maint-cache-rate-copy > div > span { color:var(--t-text-faint); font-size:var(--fs-tiny); overflow-wrap:anywhere; }
.maint-cache-rate-copy small { color:var(--t-text-faint); font-size:var(--fs-micro); line-height:1.5; }
.maint-cache-rate-copy .maint-cache-period-comparison[data-direction="up"] { color:#3FE0A6; }
.maint-cache-rate-copy .maint-cache-period-comparison[data-direction="down"] { color:var(--t-risk-ink); }
.maint-cache-mini-meter { display:block; height:3px; overflow:hidden; border-radius:var(--r-pill); background:var(--t-surface-sunken); }
.maint-cache-mini-meter > i { display:block; width:var(--cache-share,0%); height:100%; border-radius:inherit; background:linear-gradient(90deg,color-mix(in srgb,var(--cache-part,var(--t-ok-ink)) 68%,var(--t-surface)),var(--cache-part,var(--t-ok-ink))); transition:width 500ms cubic-bezier(.2,.7,.2,1),filter 180ms ease; }
