.maint-diagnostic-nav-heading strong { color:var(--t-text-strong); font-size:var(--fs-tiny); }
.maint-diagnostic-nav-heading span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-diagnostic-categories {
  display:grid;
  grid-template-columns:minmax(0, 1fr);
  gap:2px;
  max-height:min(68vh, 620px);
  overflow:auto;
  padding:0 3px 0 0;
  border:0;
  scrollbar-width:thin;
}
.maint-diagnostic-categories button {
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  grid-template-rows:auto auto;
  align-items:center;
  gap:2px var(--sp-2);
  min-width:0;
  min-height:43px;
  padding:var(--sp-1) var(--sp-2);
  border:0;
  border-left:2px solid transparent;
  border-radius:var(--r-2xs);
  color:var(--t-text-soft);
  background:transparent;
  text-align:left;
  transition:background-color 150ms ease, border-color 150ms ease;
}
.maint-diagnostic-categories button:hover { background:var(--t-surface-raised); transform:none; }
.maint-diagnostic-categories button span { min-width:0; font-size:var(--fs-micro); }
.maint-diagnostic-categories button b { grid-column:2; grid-row:1 / span 2; min-width:20px; height:20px; }
.maint-diagnostic-categories button small {
  grid-column:1;
  min-width:0;
  overflow:hidden;
  color:var(--t-text-faint);
  font-size:var(--fs-micro);
  text-overflow:ellipsis;
  white-space:nowrap;
}
.maint-diagnostic-categories button.is-active {
  border-left-color:var(--t-accent);
  color:var(--t-accent-ink);
  background:var(--t-accent-quiet);
  box-shadow:none;
}
.maint-diagnostic-categories button:focus-visible { outline:2px solid var(--t-focus); outline-offset:1px; }
.maint-diagnostic-main { display:grid; align-content:start; gap:var(--sp-4); min-width:0; }
.maint-diagnostic-focus {
  grid-template-columns:minmax(0, .85fr) minmax(0, 1.15fr);
  align-items:start;
  gap:var(--sp-2) var(--sp-3);
  margin:0;
  padding:var(--sp-3);
}
.maint-diagnostic-focus-copy h4 { font-size:var(--fs-body); }
.maint-diagnostic-focus-facts { grid-template-columns:repeat(3, minmax(0, 1fr)); }
.maint-diagnostic-focus-facts > div:first-child { border-left:0; }
.maint-diagnostic-focus-actions { grid-column:1 / -1; justify-content:flex-start; }
.maint-diagnostic-inspection {
  display:grid;
  grid-template-columns:minmax(0, 1.05fr) minmax(260px, .95fr);
  align-items:start;
  gap:var(--sp-4);
  min-width:0;
}
.maint-diagnostic-signals,
.maint-diagnostic-activity { display:grid; align-content:start; gap:var(--sp-2); min-width:0; }
.maint-diagnostic-signals { margin:0; padding:0; border:0; }
.maint-diagnostic-signals .maint-diagnostic-section-heading { align-items:flex-start; }
.maint-diagnostic-section-heading h4 { font-size:var(--fs-body); }
.maint-diagnostic-section-heading p { max-width:55ch; }
.maint-diagnostic-filter { flex:0 0 auto; }
.maint-diagnostic-activity {
  padding-left:var(--sp-3);
  border-left:1px solid var(--t-line);
}
.maint-event-lane,
.maint-runtime-lane { min-width:0; }
.maint-event-lane > .maint-subhead,
.maint-runtime-lane > .maint-subhead { align-items:baseline; }
.maint-runtime-grid { grid-template-columns:minmax(0, 1fr); }
.maint-runtime-lane > p { margin-top:var(--sp-1); }
.maint-task-audit {
  margin-top:var(--sp-2);
  padding-top:var(--sp-2);
  border-top:1px solid var(--t-line);
}
.maint-task-audit > summary {
  display:flex;
  align-items:center;
  gap:var(--sp-2);
  color:var(--t-text-strong);
  font-size:var(--fs-micro);
  cursor:pointer;
  list-style:none;
}
.maint-task-audit > summary::-webkit-details-marker { display:none; }
.maint-task-audit > summary::after {
  width:6px;
  height:6px;
  margin-left:auto;
  border-right:1px solid var(--t-text-faint);
  border-bottom:1px solid var(--t-text-faint);
  content:"";
  transform:rotate(45deg);
}
.maint-task-audit[open] > summary::after { transform:rotate(225deg); }
.maint-task-audit > summary span { color:var(--t-text-faint); font-size:var(--fs-micro); }
.maint-diagnostic-checks {
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:var(--sp-3);
  margin:0;
  padding-top:var(--sp-3);
}
.maint-diagnostic-checks > .maint-diagnostic-section-heading,
.maint-diagnostic-checks > .maint-test-zone { grid-column:1 / -1; }
.maint-diagnostic-checks > .maint-proactive-test,
.maint-diagnostic-checks > .maint-memory-diagnostic {
  min-width:0;
  margin:0;
  padding:var(--sp-3);
  border:1px solid var(--t-line);
  border-radius:var(--r-xs);
  background:var(--t-surface-soft);
}
.maint-diagnostic-checks > .maint-proactive-test { border-top:2px solid var(--t-warn); }
.maint-diagnostic-checks > .maint-memory-diagnostic { align-self:stretch; }
.maint-diagnostic-checks > .maint-test-zone {
  min-width:0;
  padding-top:var(--sp-3);
  border-top:1px solid var(--t-line);
}
.maint-diagnostic-checks .maint-test-head { align-items:flex-end; }
.maint-diagnostic-checks .maint-test-head h4 { font-size:var(--fs-body); }
.maint-diagnostic-checks .maint-test-row { gap:var(--sp-3); }
.maint-diagnostic-evidence { margin:0; }
.maint-diagnostic-workspace .maint-faq { margin:0; }

@container maint-diagnostics (max-width: 1000px) {
  .maint-diagnostic-inspection { grid-template-columns:minmax(0, 1fr); }
  .maint-diagnostic-activity { padding:var(--sp-3) 0 0; border-top:1px solid var(--t-line); border-left:0; }
  .maint-runtime-grid { grid-template-columns:repeat(auto-fit, minmax(150px, 1fr)); }
}
@container maint-diagnostics (max-width: 920px) {
  .maint-diagnostic-workspace { grid-template-columns:minmax(0, 1fr); gap:var(--sp-3); }
  .maint-diagnostic-rail { gap:var(--sp-2); padding:0 0 var(--sp-3); border-right:0; border-bottom:1px solid var(--t-line); }
  .maint-diagnostic-categories {
    display:flex;
    flex-wrap:nowrap;
    max-height:none;
    overflow-x:auto;
    overflow-y:hidden;
    padding:0 0 var(--sp-1);
  }
  .maint-diagnostic-categories button { flex:0 0 156px; }
  .maint-diagnostic-checks { grid-template-columns:repeat(2, minmax(0, 1fr)); }
}
@container maint-diagnostics (max-width: 640px) {
  .maint-diagnostic-workspace { gap:var(--sp-3); }
  .maint-diagnostic-rail { padding-bottom:var(--sp-2); }
  .maint-diagnostic-summary { padding:var(--sp-2); }
  .maint-diagnostic-main { gap:var(--sp-3); }
  .maint-diagnostic-focus { grid-template-columns:minmax(0, 1fr); padding:var(--sp-2); }
  .maint-diagnostic-focus-copy,
  .maint-diagnostic-focus-actions { grid-column:auto; }
  .maint-diagnostic-focus-facts { grid-template-columns:repeat(3, minmax(0, 1fr)); }
  .maint-diagnostic-focus-facts > div { padding:var(--sp-1); }
  .maint-diagnostic-inspection { gap:var(--sp-3); }
  .maint-diagnostic-section-heading { align-items:flex-start; flex-direction:column; }
  .maint-diagnostic-filter { justify-content:flex-start; }
  .maint-diagnostic-checks { grid-template-columns:minmax(0, 1fr); gap:var(--sp-2); }
  .maint-diagnostic-checks > .maint-diagnostic-section-heading,
  .maint-diagnostic-checks > .maint-test-zone { grid-column:1; }
  .maint-diagnostic-checks > .maint-proactive-test,
  .maint-diagnostic-checks > .maint-memory-diagnostic { padding:var(--sp-2); }
  .maint-diagnostic-checks .maint-test-head { align-items:flex-start; flex-direction:column; }
  .maint-diagnostic-checks .maint-test-row { grid-template-columns:minmax(0, 1fr); gap:var(--sp-2); }
  .maint-diagnostic-checks .maint-test-controls { display:grid; min-width:0; }
  .maint-diagnostic-checks .maint-test-controls select { width:100%; max-width:none; }
  .maint-diagnostic-checks .maint-test-row--provider .maint-test-controls,
  .maint-diagnostic-checks .maint-test-row--image .maint-test-controls { grid-template-columns:minmax(0, 1fr) auto; }
  .maint-diagnostic-checks .maint-test-row--voice .maint-test-controls { grid-template-columns:minmax(0, 1fr) minmax(76px, .65fr) auto; }
  .maint-diagnostic-item { grid-template-columns:21px minmax(0, 1fr); }
  .maint-diagnostic-item > button { grid-column:2; justify-self:start; }
}
@media (prefers-reduced-motion: reduce) {
  .maint-diagnostic-categories button,
  .maint-diagnostic-focus { animation:none; transition:none; }
}

/* navigation.css */
/* 左栏宽度由 shell.css 的栅格列决定（--shell-rail: 220px）。
   这里曾写 width:158px，而栅格列仍是 220px：栅格项的宽度一旦确定，
   justify-self:stretch 就退化成 start，于是 >1120px 时左栏只涂 158px，
   右侧留一条 62px 的画布色竖条（1440px 下实测 158 vs 220）。
   宽度交还给栅格，这里只保留内边距与对齐。 */
.rail{padding:var(--sp-5) var(--sp-3) var(--sp-4);align-items:stretch}
.brand{margin-bottom:var(--sp-3)}
.rail-links{flex:1;min-height:0;overflow-y:auto;gap:1px;scrollbar-width:thin;scrollbar-color:#cbd2de transparent}
.nav-group{display:grid;gap:2px;padding:var(--sp-1) 0 var(--sp-2);border-bottom:1px solid #e5e9f1}
.nav-group:last-child{border-bottom:0}
.nav-group-title{padding:var(--sp-1) var(--sp-3) 3px;color:#8a94a3;font-size:var(--fs-micro);line-height:1.3}
.rail-link{min-height:37px;padding:var(--sp-1) var(--sp-2);justify-content:flex-start;flex-direction:row;gap:var(--sp-2);border-radius:var(--r-xs);font-size:var(--fs-body);text-align:left;white-space:nowrap}
.rail-link:last-child{margin-top:0}
.rail-link svg{width:17px;height:17px;flex:none}
.rail-bottom{padding-top:var(--sp-2);gap:var(--sp-1)}
.shell{margin-left:calc(var(--sp-6) + var(--sp-8) + var(--sp-8) + var(--sp-5))}
/* 手机上左栏是顶部横条（shell.css 的 ≤760 规则），不是 76px 贴底栏。
   这里原先把浮层抬到 bottom:84px 给底栏让位，于是手机上「全部功能」
   无故悬空 84px；改成贴底的常规间距。 */
.navigation-dialog{position:fixed;inset:auto 12px var(--sp-4);z-index:40;width:min(460px,calc(100% - 24px));max-height:min(74vh,690px);margin:0 auto;padding:0;border:1px solid #dce4ed;border-radius:var(--r-sm);background:#f8fafc;color:#354253;box-shadow:0 16px 48px #283b5360;overflow:auto}
.navigation-dialog::backdrop{background:#1c2d4070}
.navigation-dialog-head{position:sticky;top:0;z-index:1;display:flex;align-items:center;justify-content:space-between;padding:var(--sp-3) var(--sp-4);background:#f8fafcf2;border-bottom:1px solid #e0e6ee}
.navigation-dialog-head h1{font-size:var(--fs-head);line-height:1.4;font-weight:600}
.navigation-list{padding:var(--sp-2) var(--sp-4) var(--sp-5)}
.navigation-group{padding:var(--sp-2) 0 var(--sp-3);border-bottom:1px solid #e2e8ee}
.navigation-group:last-child{border:0}
.navigation-group h2{padding:0 3px var(--sp-1);color:#7c8997;font-size:var(--fs-tiny);font-weight:500}
.navigation-group .navigation-link{display:inline-flex;align-items:center;gap:var(--sp-2);width:calc(50% - 4px);min-height:42px;padding:var(--sp-2) var(--sp-2);margin:2px;text-align:left;color:#45556a;border-radius:var(--r-xs);font-size:var(--fs-body)}
.navigation-link svg{width:17px;height:17px;flex:none}
.navigation-link.active{background:#e7ecf8;color:#526499;font-weight:600}
.navigation-link:hover{background:#ecf1f5}
.rail-link:focus-visible,.mobile-nav-link:focus-visible,.navigation-link:focus-visible{outline:2px solid #5c78a5;outline-offset:2px}
/* 配置页外壳已迁到 console.css（.console / .console-section / .boundary）。
   原有的 .config-page / .config-jump / .config-section* / .config-provider-* 已无引用，删除。 */
/* 手机断点统一到 760（外壳栅格的实际切换点）。此前这里是 650，
   于是 651–760 区间两套手机布局都不生效：外壳已经按窄屏排，
   左栏却还是 220px 的竖栏。真正的手机导航是 shell.js 的 #shellNav，
   这里的 .mobile-nav / #mainNav 在 DOM 里从来不存在，已删除。 */
@media(min-width:1740px){.shell{margin-left:auto}}

/* appearance-page.css */
/* Appearance workspace: preview and controls stay visible together. */
.ap-page{display:grid;gap:var(--sp-6);min-width:0}
.ap-intro{margin:0 0 calc(var(--sp-2) * -1);color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.7}
.ap-section{display:grid;gap:var(--sp-4);min-width:0}
.ap-section-head{display:grid;grid-template-columns:30px minmax(0,1fr) auto;align-items:center;gap:var(--sp-3);min-width:0}
.ap-section-number{display:grid;place-items:center;width:28px;height:28px;border-radius:calc(var(--r-xs) * 1.2);background:var(--t-ok);color:var(--t-text-invert);font-size:var(--fs-tiny);font-weight:700}
.ap-section-number.amber{background:var(--t-warn);color:var(--t-text-invert)}
.ap-section-copy{display:grid;gap:var(--sp-1);min-width:0}
.ap-section-copy h2{margin:0;color:var(--t-text-strong);font-family:var(--skin-heading-font,inherit);font-size:var(--fs-head);font-weight:600;line-height:1.35}
.ap-section-copy small{color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.65}
.ap-section-badge,.ap-count-badge,.ap-preview-badge{justify-self:end;padding:var(--sp-1) var(--sp-3);border-radius:var(--r-pill);background:var(--t-ok-quiet);color:var(--t-ok-ink);font-size:var(--fs-micro);font-weight:600;white-space:nowrap}
.ap-section-badge.amber{background:var(--t-warn-quiet);color:var(--t-warn-ink)}

.ap-reset-row{display:flex;align-items:center;gap:var(--sp-4);flex-wrap:wrap;padding:var(--sp-3) var(--sp-4);border:1px solid var(--t-line-firm);border-radius:var(--r-sm);background:var(--t-surface)}
.ap-reset-row>span{flex:1;min-width:min(100%,260px);display:grid;gap:var(--sp-1)}
.ap-reset-row b{color:var(--t-text);font-size:var(--fs-body);font-weight:600}
.ap-reset-row small{color:var(--t-text-faint);font-size:var(--fs-tiny);line-height:1.6}

.ap-top-grid{display:grid;grid-template-columns:minmax(0,2.05fr) minmax(330px,1fr);align-items:stretch;gap:var(--sp-4);min-width:0}
.ap-surface{display:grid;align-content:start;gap:var(--sp-3);min-width:0;padding:var(--sp-4);border:1px solid var(--t-line-firm);border-radius:var(--r-sm);background:var(--t-surface)}
.ap-panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:var(--sp-3);min-width:0}
.ap-panel-title{display:grid;gap:var(--sp-1);min-width:0}
.ap-panel-title h2{margin:0;color:var(--t-text-strong);font-family:var(--skin-heading-font,inherit);font-size:var(--fs-title);font-weight:600;line-height:1.35}
.ap-panel-title p{margin:0;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.6}
.ap-preview-badge{flex:none}

/* The preview carries the same shell, cards, status and input patterns as the real page. */
.ap-preview{overflow:hidden;border:1px solid var(--t-line-firm);border-radius:calc(var(--r-xs) * 1.2);background-color:var(--t-canvas);background-image:var(--skin-canvas-pattern,none);background-size:var(--skin-canvas-size,auto);color:var(--t-text);transition:background-color var(--dur-theme) ease}
.apv-shell{display:grid;grid-template-columns:172px minmax(0,1fr);min-height:420px;color:var(--t-text)}
.apv-rail{display:flex;flex-direction:column;gap:var(--sp-1);padding:var(--sp-4) var(--sp-3);border-right:1px solid var(--t-line);background:color-mix(in srgb,var(--t-surface) 82%,transparent)}
.apv-brand{display:flex;align-items:center;gap:var(--sp-2);padding:0 var(--sp-1) var(--sp-3);margin-bottom:var(--sp-2);border-bottom:1px solid var(--t-line);color:var(--t-text-strong);font-size:var(--fs-tiny)}
.apv-brand-mark{display:grid;place-items:center;width:26px;height:26px;border-radius:var(--skin-r-sm,var(--r-sm));background:var(--t-accent-quiet);color:var(--t-accent-ink);font-size:var(--fs-micro);font-weight:700}
.apv-nav{position:relative;padding:var(--sp-2) var(--sp-3);border-radius:var(--skin-r-xs,var(--r-xs));color:var(--t-text-soft);font-size:var(--fs-micro);line-height:1.5}
.apv-nav.active{background:var(--t-accent-quiet);color:var(--t-accent-ink);font-weight:600}
.apv-nav.active::before{position:absolute;inset:6px auto 6px 0;width:2px;border-radius:var(--r-pill);background:var(--t-accent);content:""}
.apv-nav-rule{height:1px;margin:var(--sp-2) 2px;background:var(--t-line)}
.apv-main{min-width:0}
.apv-topbar{display:flex;justify-content:space-between;gap:var(--sp-3);padding:var(--sp-3) var(--sp-4);border-bottom:1px solid var(--t-line);color:var(--t-text-faint);font-size:var(--fs-micro)}
.apv-topbar span:last-child{color:var(--t-accent-ink)}
.apv-content{display:grid;gap:var(--sp-3);max-width:960px;margin:0 auto;padding:var(--pad-lg)}
.apv-heading{display:flex;align-items:center;gap:var(--sp-3)}
.apv-heading>span:first-child{display:grid;gap:var(--sp-1);min-width:0}
.apv-heading small{color:var(--t-text-faint);font-size:var(--fs-micro)}
.apv-heading strong{color:var(--t-text-strong);font-family:var(--skin-heading-font,inherit);font-size:var(--fs-head);font-weight:600}
.apv-tag{flex:none;margin-left:auto;padding:var(--sp-1) var(--sp-3);border-radius:var(--r-pill);background:var(--t-ok-quiet);color:var(--t-ok-ink);font-size:var(--fs-micro)}
.apv-card{display:grid;gap:var(--sp-2);min-width:0;padding:var(--pad);border:1px solid var(--t-line);border-radius:calc(var(--r-xs) * 1.2);background:var(--t-surface-raised);box-shadow:var(--t-shadow)}
.apv-head{display:flex;align-items:center;gap:var(--sp-2);min-width:0}
.apv-head strong{color:var(--t-text-strong);font-size:var(--fs-body);font-weight:600}
.apv-dot{width:8px;height:8px;flex:none;border-radius:var(--r-pill);background:var(--t-accent)}
.apv-status{margin-left:auto;color:var(--t-text-faint);font-size:var(--fs-micro);white-space:nowrap}
.apv-line{margin:0;color:var(--t-text-soft);font-size:var(--fs-body);line-height:1.65}
.apv-row{display:flex;flex-wrap:wrap;gap:var(--sp-1)}
.apv-chip{padding:3px var(--sp-2);border-radius:var(--r-xs);background:var(--t-accent-quiet);color:var(--t-accent-ink);font-size:var(--fs-micro)}
.apv-chip.quiet{background:var(--t-surface-sunken);color:var(--t-text-soft)}
.apv-actions{display:flex;justify-content:flex-start;gap:var(--sp-2);flex-wrap:wrap}
.apv-actions .button{margin:0}
.apv-actions .button.primary{border-color:var(--t-accent-solid);background:var(--t-accent-solid);color:var(--t-on-solid)}
.apv-actions .button.primary:hover{border-color:var(--t-accent-solid-hover);background:var(--t-accent-solid-hover)}
.apv-record-list{display:grid;gap:var(--sp-2);margin:0;padding:0;list-style:none}
.apv-record-list li{display:grid;grid-template-columns:48px minmax(0,1fr);gap:var(--sp-2);color:var(--t-text-soft);font-size:var(--fs-micro);line-height:1.5}
.apv-record-list time{color:var(--t-text-faint);font-variant-numeric:tabular-nums}
.apv-field{display:grid;gap:var(--sp-1)}
.apv-field label{color:var(--t-text-soft);font-size:var(--fs-tiny)}
.apv-field input{width:100%;padding:var(--sp-2) var(--sp-3);border:1px solid var(--t-line-firm);border-radius:var(--r-sm);background:var(--t-surface);color:var(--t-text);font-size:var(--fs-body)}
.ap-preview-note{margin:0;color:var(--t-text-faint);font-size:var(--fs-micro);line-height:1.6}
.ap-preview-note b{color:var(--t-text-soft);font-weight:600}

.ap-theme-panel{gap:var(--sp-3)}
.ap-count-badge{background:var(--t-ok-quiet);color:var(--t-ok-ink)}
.ap-theme-group{display:grid;gap:var(--sp-2)}
.ap-group-label{display:flex;align-items:baseline;gap:var(--sp-2);flex-wrap:wrap;color:var(--t-accent-ink);font-size:var(--fs-micro)}
.ap-group-label strong{font-weight:650}
.ap-group-label small{color:var(--t-text-faint);font-size:var(--fs-micro)}
