.shell-nav-group { display: flex; flex-direction: column; gap:calc(var(--sp-1) * .25); }
.shell-nav-group + .shell-nav-group {
  margin-top:var(--sp-3);
  padding-top:var(--sp-3);
  border-top: 1px solid var(--t-line);
}
.shell-nav-title {
  padding:0 var(--sp-2) var(--sp-1);
  font-size: var(--fs-micro);
  font-weight: 600;
  letter-spacing: 0;
  color: var(--t-text-faint);
  text-transform: uppercase;
}

.shell-nav-link {
  display: flex;
  align-items: center;
  gap:var(--sp-2);
  width: 100%;
  padding:var(--sp-2) var(--sp-2);
  border: 0;
  border-radius: var(--r-sm, var(--r-xs));
  background: transparent;
  color: var(--t-text-soft);
  font: inherit;
  font-size: var(--fs-body);
  min-height: 36px;
  line-height: 1.5;
  text-align: left;
  cursor: pointer;
  transition: background var(--dur-fast, .16s ease), color var(--dur-fast, .16s ease);
}
.shell-nav-link:hover { background: var(--t-surface-soft); color: var(--t-text); }
/* 褰撳墠椤电敤 aria-current 琛ㄨ揪锛堝畠鏈潵灏辨槸銆屽綋鍓嶉〉銆嶈涔夛紝涓嶆槸寮€鍏崇姸鎬侊級銆?   aria-pressed 浠嶇敱 app.js 鍚屾鍐欏叆锛屼緵鏃㈡湁鑴氭湰璇诲彇锛屼絾涓嶅啀鍐冲畾鏍峰紡銆?*/
.shell-nav-link[aria-current="page"],
.shell-nav-link[aria-pressed="true"] {
  background: var(--t-accent-quiet);
  color: var(--t-accent-ink);
  font-weight: 600;
}
/* 閫変腑椤瑰啀鍔犱竴閬?3px 绔栨爣锛屾壂瑙嗘椂涓嶅繀璇绘枃瀛椾篃鑳藉畾浣嶃€?*/
.shell-nav-link[aria-current="page"] {
  box-shadow: inset 3px 0 0 var(--t-accent);
}
@media (max-width: 760px) {
  .shell-nav-link[aria-current="page"] { box-shadow: inset 0 -3px 0 var(--t-accent); }
}
.shell-nav-link i { flex: none; width: 15px; height: 15px; opacity: .85; }

/* 宸︽爮搴曢儴锛氭悳绱笌鏄剧ず鍋忓ソ锛堝師鏈湪椤舵爮閲岋級銆?*/
.rail-foot {
  margin-top:auto;
  padding-top:var(--sp-3);
  border-top: 1px solid var(--t-line);
  display: flex;
  flex-direction: column;
  gap:calc(var(--sp-1) * .25);
}
.rail-foot .shell-nav-link { font-size: var(--fs-body); }
.rail-foot .rail-note {
  padding:var(--sp-2) var(--sp-2) 0;
  font-size: var(--fs-micro);
  line-height: 1.6;
  color: var(--t-text-faint);
}

/* === 涓讳綋 === */
.shell-body {
  grid-area: body;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(var(--shell-side), .3fr);
  grid-template-rows: auto auto;
  grid-template-areas:
    "stage side"
    "panel panel";
  gap:var(--shell-gap);
  padding:var(--shell-pad);
  align-items: start;
}

/* 绐勫睆锛氱姸鎬佸崱鐗囩Щ鍒板皬灞嬩笅闈紝宸︽爮鏀惰捣銆?*/
@media (max-width: 1120px) {
  #homeShell { grid-template-columns: var(--shell-rail-collapsed) minmax(0, 1fr); }
  .shell-body {
    grid-template-columns: minmax(0, 1fr) minmax(0, 0fr);
    grid-template-rows: auto auto auto;
