@container self-journal (max-width:380px){
  .journal-name-row h2{font-size:var(--fs-lead)}
  .journal-cover{padding:var(--sp-2)}
  .self-page .wb-journal .wb-actions :is(.button,.wb-save){flex-basis:100%;justify-content:center}
  .self-page .wb-journal .wb-number{gap:var(--sp-1)}
