  .role-profile-draft-knowledge-head{align-items:flex-start;flex-direction:column}
}
@media(prefers-reduced-motion:reduce){
  .role-profile-draft-dialog[open],.role-profile-draft-spinner{animation:none!important}
.role-profile-draft-dialog *, .role-profile-draft-dialog *::before,.role-profile-draft-dialog *::after{transition:none!important}
