:root:is([data-motion="low"],[data-motion="off"]) .role-profile-draft-dialog[open],
:root:is([data-motion="low"],[data-motion="off"]) .role-profile-draft-spinner,
body.reduce-motion .role-profile-draft-dialog[open],body.reduce-motion .role-profile-draft-spinner{animation:none}
:root:is([data-motion="low"],[data-motion="off"]) .role-profile-draft-dialog *,
:root:is([data-motion="low"],[data-motion="off"]) .role-profile-draft-dialog *::before,
:root:is([data-motion="low"],[data-motion="off"]) .role-profile-draft-dialog *::after,
body.reduce-motion .role-profile-draft-dialog *,body.reduce-motion .role-profile-draft-dialog *::before,
body.reduce-motion .role-profile-draft-dialog *::after{transition:none}

