/* theme-skins.css */
/* 主题的结构语言：页面基底、标题、导航、面板边界和常用控件共用一组皮肤令牌。 */
:root[data-theme="night"],:root[data-theme="walnut"]{color-scheme:dark}
:root[data-theme="courtyard"],:root[data-theme="dawn"],
:root[data-theme="dusk"],:root[data-theme="contrast"]{color-scheme:light}

body{background-color:var(--t-canvas)}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{
  outline-color:var(--t-accent);outline-offset:3px}
::selection{background:var(--t-accent-quiet);color:var(--t-accent-ink)}

.button{border-color:var(--t-line-firm);border-radius:var(--r-sm);background:var(--t-surface);
  color:var(--t-text);box-shadow:none}
.button:hover{border-color:var(--t-accent);background:var(--t-surface-raised);color:var(--t-accent-ink)}
.button.primary{border-color:var(--t-accent-solid);background:var(--t-accent-solid);
  color:var(--t-on-solid);box-shadow:var(--t-shadow)}
.button.primary:hover{border-color:var(--t-accent-solid-hover);background:var(--t-accent-solid-hover);color:var(--t-on-solid)}
.button.danger{border-color:var(--t-risk);background:var(--t-risk-quiet);color:var(--t-risk-ink)}
input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),textarea,select{
  border-color:var(--t-line-firm);border-radius:var(--r-sm);background-color:var(--t-surface);color:var(--t-text)}

#homeShell{background-color:var(--t-canvas);background-image:var(--skin-canvas-pattern,none);
  background-size:var(--skin-canvas-size,auto);background-attachment:fixed}
#homeShell .rail{background-color:var(--t-surface);background-image:var(--skin-canvas-pattern,none);
  background-size:var(--skin-canvas-size,auto);border-right-color:var(--t-line)}
#homeShell .shell-nav-link{border-radius:var(--skin-r-xs,var(--r-sm))}
#homeShell .shell-nav-link[aria-pressed="true"]{box-shadow:inset 3px 0 var(--t-accent)}
#homeShell .shell-panel{border-radius:var(--r-lg);box-shadow:var(--t-shadow-lift)}
#homeShell .shell-panel-head{background-color:var(--t-surface-soft);
  background-image:var(--skin-canvas-pattern,none);background-size:var(--skin-canvas-size,auto)}
#homeShell .page-heading h1,#homeShell .shell-panel-head h2,#homeShell .stage-bar h2,
#homeShell .ap-block-head h2{font-family:var(--skin-heading-font,inherit)}
#homeShell .stage-region .room-stage{background-color:var(--t-surface-soft);
  background-image:var(--skin-canvas-pattern,none);background-size:var(--skin-canvas-size,auto)}

@media(prefers-reduced-motion:reduce){
  *,*::before,*::after{scroll-behavior:auto!important}
}

/* page-motion.css */
/* 动效只补充呈现，尺寸与颜色继续由各页面及主题令牌负责。 */
:root {
  --ease-control: cubic-bezier(.22, .72, .24, 1);
  --control-hover-y: -2px;
  --control-press-y: 1px;
  --control-press-scale: .985;
  --control-icon-x: 2px;
}

#shellNav { position: relative; isolation: isolate; }
#homeShell #shellNav .shell-nav-link { position: relative; z-index: 1; }
.shell-nav-indicator {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  border-radius: var(--r-sm);
  background: var(--t-accent-quiet);
  box-shadow: inset 3px 0 var(--t-accent);
  transform-origin: top left;
  pointer-events: none;
}
#homeShell #shellNav[data-motion-nav] .shell-nav-link[aria-pressed="true"] {
  background: transparent;
  box-shadow: none;
}
#homeShell .shell-nav-link svg {
  transition: transform var(--dur-fast) var(--ease-control), opacity var(--dur-fast);
}

:where(#homeShell, #detailDialog, #searchDialog, #navigationDialog)
  :is(.button, .memory-button, .icon-button, .stage-overlay-button, .shell-nav-link,
      .stage-furniture-strip button, .home-side-action, [role="tab"], .ap-seg button) {
  transition-property: background-color, border-color, color, box-shadow, opacity, transform;
  transition-timing-function: var(--ease-control);
  transition-duration: var(--dur-fast) !important;
}
:where(#homeShell, #detailDialog, #searchDialog, #navigationDialog)
  :is(.button, .memory-button, .icon-button, .stage-overlay-button, .shell-nav-link,
      .stage-furniture-strip button, .home-side-action, [role="tab"], .ap-seg button):focus-visible {
  outline: 2px solid var(--t-focus, var(--t-accent));
  outline-offset: 3px;
}
:where(#homeShell, #detailDialog, #searchDialog, #navigationDialog)
  :is(.button, .memory-button, .icon-button, .stage-overlay-button, .shell-nav-link,
      .stage-furniture-strip button, .home-side-action, [role="tab"], .ap-seg button):is(:disabled, [aria-disabled="true"]) { cursor: default; }
:where(#homeShell, #detailDialog, #searchDialog, #navigationDialog)
  :is(.button, .memory-button, .icon-button, .stage-overlay-button, .shell-nav-link,
      .stage-furniture-strip button, .home-side-action, [role="tab"], .ap-seg button)[aria-busy="true"] { cursor: progress; }
:where(#homeShell, #detailDialog, #searchDialog, #navigationDialog)
  :is(.button, .memory-button, .icon-button, .stage-overlay-button, .shell-nav-link,
      .stage-furniture-strip button, .home-side-action, [role="tab"], .ap-seg button)[aria-disabled="true"] { opacity: .55; }
@media (hover: hover) and (pointer: fine) {
  #homeShell .shell-nav-link:hover:not(:disabled) svg { transform: translateX(var(--control-icon-x)); opacity: 1; }
  #homeShell .stage-furniture-strip button:hover:not(:disabled):not(:active),
  #homeShell .stage-overlay-button:hover:not(:disabled):not(:active) { transform: translateY(var(--control-hover-y)); box-shadow: var(--t-shadow); }
  :where(#homeShell, #detailDialog, #searchDialog)
    :is(.button, .memory-button):hover:not(:disabled):not(.primary):not(.danger) {
    border-color: var(--t-accent);
  }
}
:where(#homeShell, #detailDialog, #searchDialog, #navigationDialog)
  :is(.button, .memory-button, .icon-button, .stage-overlay-button, .shell-nav-link,
      .stage-furniture-strip button, .home-side-action, [role="tab"], .ap-seg button):active:not(:disabled):not([aria-disabled="true"]):not([aria-busy="true"]) {
  transform: translateY(var(--control-press-y)) scale(var(--control-press-scale));
  transition-duration: .08s !important;
}

#homeShell details > summary {
  transition: background-color var(--dur-fast), color var(--dur-fast);
  cursor: pointer;
}
#homeShell details > summary:focus-visible { outline: 2px solid var(--t-focus, var(--t-accent)); outline-offset: 2px; }
#homeShell details > summary > svg:last-child { transition: transform var(--dur) var(--ease-control); }
@supports (interpolate-size: allow-keywords) and selector(details::details-content) {
  #homeShell details::details-content {
    interpolate-size: allow-keywords;
    height: 0;
    overflow: clip;
    opacity: 0;
    content-visibility: hidden;
    transition: height var(--dur) var(--ease-control), opacity var(--dur-fast),
      content-visibility var(--dur) allow-discrete;
  }
  #homeShell details[open]::details-content { height: auto; opacity: 1; content-visibility: visible; }
}

:is(#detailDialog, #searchDialog, #navigationDialog) {
  opacity: 0;
  transform: translateY(10px) scale(.985);
  transition: opacity var(--dur-fast), transform var(--dur) var(--ease-control),
    display var(--dur) allow-discrete, overlay var(--dur) allow-discrete;
}
#detailDialog { transform: translateX(14px); }
:is(#detailDialog, #searchDialog, #navigationDialog)[open] { opacity: 1; transform: none; }
:is(#detailDialog, #searchDialog, #navigationDialog):not([open]),
:is(#detailDialog, #searchDialog, #navigationDialog):not([open])::backdrop { pointer-events: none; }
:is(#detailDialog, #searchDialog, #navigationDialog)::backdrop {
  opacity: 0;
  transition: opacity var(--dur), display var(--dur) allow-discrete, overlay var(--dur) allow-discrete;
}
:is(#detailDialog, #searchDialog, #navigationDialog)[open]::backdrop { opacity: 1; }
@starting-style {
  :is(#detailDialog, #searchDialog, #navigationDialog)[open] { opacity: 0; transform: translateY(10px) scale(.985); }
  #detailDialog[open] { transform: translateX(14px); }
  :is(#detailDialog, #searchDialog, #navigationDialog)[open]::backdrop { opacity: 0; }
}
@media (max-width: 760px) {
  #detailDialog { transform: translateY(16px); }
  #detailDialog[open] { transform: none; }
  @starting-style { #detailDialog[open] { transform: translateY(16px); } }
}

/* 减弱只保留短淡入；关闭或系统减少动效立即提交最终状态。 */
:root:is([data-motion="low"], [data-motion="off"]), body.reduce-motion {
  --control-hover-y: 0px;
  --control-press-y: 0px;
  --control-press-scale: 1;
  --control-icon-x: 0px;
}
:root[data-motion="low"] #homeShell :is(.shell-nav-link, .stage-overlay-button, .stage-furniture-strip button):is(:hover, :active),
:root[data-motion="low"] #homeShell .shell-nav-link:hover svg,
:root[data-motion="low"] :is(#detailDialog, #searchDialog, #navigationDialog) { transform: none; }
:root[data-motion="off"] :is(#homeShell, #detailDialog, #searchDialog, #navigationDialog) *,
body.reduce-motion :is(#homeShell, #detailDialog, #searchDialog, #navigationDialog) * {
  transition: none !important;
  animation: none !important;
}
:root:is([data-motion="low"], [data-motion="off"]) #homeShell details::details-content,
body.reduce-motion #homeShell details::details-content { transition: none; }
:root[data-motion="off"] :is(#detailDialog, #searchDialog, #navigationDialog),
body.reduce-motion :is(#detailDialog, #searchDialog, #navigationDialog) { transition: none !important; transform: none; }
:root[data-motion="off"] :is(#detailDialog, #searchDialog, #navigationDialog)::backdrop,
body.reduce-motion :is(#detailDialog, #searchDialog, #navigationDialog)::backdrop { transition: none !important; }
@media (prefers-reduced-motion: reduce) {
  :root { --control-hover-y: 0px; --control-press-y: 0px; --control-press-scale: 1; --control-icon-x: 0px; }
  :is(#homeShell, #detailDialog, #searchDialog, #navigationDialog) *,
  #homeShell details::details-content,
  :is(#detailDialog, #searchDialog, #navigationDialog),
  :is(#detailDialog, #searchDialog, #navigationDialog)::backdrop { transition: none !important; animation: none !important; }
  #homeShell :is(.shell-nav-link, .stage-overlay-button, .stage-furniture-strip button):is(:hover, :active),
  #homeShell .shell-nav-link:hover svg,
  :is(#detailDialog, #searchDialog, #navigationDialog) { transform: none; }
}

/* screen-observation.css */
.screen-observation-panel{margin-top:18px;padding:18px;border:1px solid var(--t-line);border-radius:14px;background:var(--t-surface);color:inherit}
.screen-observation-panel header{display:flex;align-items:center;justify-content:space-between;gap:12px}
.screen-observation-panel header small{display:block;margin-top:4px;opacity:.7}
.screen-observation-panel p{margin:12px 0;line-height:1.7;overflow-wrap:anywhere}
.screen-observation-meta{font-size:12px;opacity:.7}
.screen-observation-text{white-space:pre-wrap}
.screen-observation-media{display:block;max-width:100%;max-height:540px;margin-top:14px;border-radius:8px;object-fit:contain;background:var(--t-surface-sunken)}
@media(max-width:560px){.screen-observation-panel{padding:14px}.screen-observation-panel header{align-items:flex-start;flex-wrap:wrap}}
